// Banco de questões reais Cesgranrio - Transpetro Adm. e Controle
const QUESTOES = [{"id": 1, "materia": "Administração de RH / Processos Administrativos", "assunto": "Recrutamento e Seleção", "enunciado": "Após a realização de um processo seletivo, uma empresa do setor bancário descobriu que mais da metade dos candidatos não aprovados formou uma imagem negativa do processo, e metade desses acreditava que o processo seletivo de uma empresa concorrente era mais objetivo, isento e focado nos requisitos do cargo. O sucesso do recrutamento meritocrático e objetivo da empresa concorrente pode ser explicado pela utilização de", "alternativas": ["teste vocacional alinhado aos perfis de carreira dos candidatos", "prova de conhecimentos em análise de investimentos", "entrevista individual conduzida por um único entrevistador", "dinâmica de grupo com atividades coletivas predeterminadas", "avaliação psicométrica assegurando um tipo específico de personalidade"], "corretaIndex": 0, "regra": "Processos seletivos objetivos e meritocráticos associam-se a instrumentos estruturados e alinhados ao perfil/cargo, como testes vocacionais padronizados, reduzindo subjetividade do avaliador.", "fonte": "Cesgranrio — IPEA — Técnico de Planejamento e Pesquisa (Gestão e Logística) — 2024", "fonteUrl": "https://www.qconcursos.com/questoes-de-concursos/questoes/ddcb6dd5-d5", "valido": true}, {"id": 2, "materia": "Administração de RH / Processos Administrativos", "assunto": "Recrutamento e Seleção", "enunciado": "Observe a seguinte sequência de passos em um processo de contratação de pessoal: I – análise do cargo; II – identificação das dimensões de desempenho do cargo; III – identificação do conhecimento e habilidades necessárias; IV – desenvolvimento/seleção/validação de instrumentos; V – uso dos instrumentos de medida. Estes passos fazem parte da atividade de", "alternativas": ["recrutamento de pessoal", "seleção de pessoal", "treinamento de pessoal", "planejamento de carreira", "estruturação de cargos e salários"], "corretaIndex": 1, "regra": "A sequência descrita (análise do cargo → dimensões de desempenho → KSAs → instrumentos → aplicação) é o roteiro clássico de construção de um processo de seleção de pessoal baseado em validade de conteúdo.", "fonte": "Cesgranrio — TermoMacaé/TERMORIO — Técnico de Administração — 2009", "fonteUrl": "https://www.qconcursos.com/questoes-de-concursos/questoes/81bab060-92", "valido": true}, {"id": 3, "materia": "Administração de RH / Processos Administrativos", "assunto": "Desenvolvimento de Carreira", "enunciado": "As pessoas com maior consciência sobre as possibilidades para o seu autodesenvolvimento profissional tendem a ter uma visão de oportunidades de desenvolvimento para a organização e para as pessoas ao seu redor, sendo mais contributivas para o contexto em que se situam e mais valorizadas. Com base nessa premissa, um funcionário que tenha sido incentivado pelo seu chefe a aumentar o protagonismo em relação ao seu desenvolvimento e à sua carreira precisa", "alternativas": ["pensar no autodesenvolvimento como movimento de fora para dentro, aproveitando todas as oportunidades mesmo que desalinhadas com seus desejos", "ter um projeto profissional consciente, esclarecendo aonde quer chegar, como gerenciar seu desenvolvimento e agir de forma consistente com seu propósito", "ter clareza quanto às possibilidades de desenvolvimento, associando o plano de carreira à metáfora de uma estrada plana, asfaltada e bem conservada", "seguir a tendência de projetar passado e presente para o futuro, usando padrões de continuidade com 'olhar pelo retrovisor'", "vincular o futuro a pessoas/organizações ao invés de pensar em seu grande compromisso consigo mesmo"], "corretaIndex": 1, "regra": "Protagonismo de carreira (autogestão de carreira) implica projeto profissional consciente, autoconhecimento de propósito e ação alinhada a metas próprias, e não dependência de fatores externos.", "fonte": "Cesgranrio — Caixa Econômica Federal — Médico do Trabalho/Engenheiro de Segurança — 2024", "fonteUrl": "https://www.qconcursos.com/questoes-de-concursos/questoes/53b5e7b7-91", "valido": true}, {"id": 4, "materia": "Administração de RH / Processos Administrativos", "assunto": "Desenvolvimento de Carreira", "enunciado": "Sob a nova ótica da administração de cargos e salários, os planos devem ser concebidos como mecanismos para o desenvolvimento de carreiras profissionais. São vantagens associadas ao planejamento de carreiras, EXCETO", "alternativas": ["contribuir para que a organização atinja níveis elevados de qualidade", "motivar os colaboradores na busca de maior competência técnica", "propiciar a ascensão do colaborador pela perspectiva do crescimento", "proporcionar maior integração, provocando aumento do turnover", "criar condições para atingir objetivos profissionais e organizacionais"], "corretaIndex": 3, "regra": "O planejamento de carreira bem conduzido tende a reduzir a rotatividade (turnover), não aumentá-la, pois retém talentos ao oferecer perspectivas claras de crescimento.", "fonte": "Cesgranrio — EPE — Analista de Gestão Corporativa (RH) — 2010", "fonteUrl": "https://www.qconcursos.com/questoes-de-concursos/questoes/187b62b8-d5", "valido": true}, {"id": 5, "materia": "Administração de RH / Processos Administrativos", "assunto": "Desenvolvimento de Carreira", "enunciado": "O teletrabalho é uma tendência no serviço público brasileiro e tem implicado adaptações na forma de lidar com as equipes e com a garantia do desempenho. Entende-se que as pessoas possuem distintos níveis de autonomia, disciplina e adaptabilidade, constituindo perfis comportamentais também distintos. Assim, passam a existir diferentes formas de adaptação, dentre as quais se destaca a prática de chefias oferecerem orientações de crescimento pessoal, atribuição individual de desafios pessoais e metas periódicas, reforço da dimensão atitudinal e geração de confiança e iniciativa. Essa prática é conhecida como", "alternativas": ["autodesenvolvimento", "colaboração em equipe", "composição de equipe", "controle da carga horária", "distribuição do trabalho"], "corretaIndex": 0, "regra": "Orientar o colaborador para crescimento pessoal contínuo, com metas próprias e reforço de atitude, caracteriza estímulo ao autodesenvolvimento, especialmente relevante em contextos remotos.", "fonte": "Cesgranrio — IPEA — Técnico de Planejamento e Pesquisa (Gestão e Logística) — 2024", "fonteUrl": "https://www.qconcursos.com/questoes-de-concursos/questoes/ddd2d489-d5", "valido": true}, {"id": 6, "materia": "Administração de RH / Processos Administrativos", "assunto": "Treinamento e Desenvolvimento", "enunciado": "Um ministério decidiu capacitar seus colaboradores por meio de trilhas de conhecimento. No ambiente virtual de aprendizagem foram organizados tematicamente textos, vídeos e podcasts, em uma sequência de passos estruturados a serem seguidos pelo colaborador. Após o estudo do material, o participante responde a questões autoadministráveis e recebe feedback imediato de forma a permitir a reavaliação do aprendizado. A estratégia de capacitação desenvolvida pela empresa baseia-se na noção de", "alternativas": ["dinâmica de grupo", "instrução programada", "mentoria e orientação", "oficina de trabalho", "rotação de trabalho"], "corretaIndex": 1, "regra": "Instrução programada é técnica de treinamento sem presença de instrutor, com conteúdo em sequência lógica e feedback imediato ao aprendiz, tal como descrito.", "fonte": "Cesgranrio — CNU — Bloco 7 (Gestão Governamental) — 2024", "fonteUrl": "https://www.qconcursos.com/questoes-de-concursos/questoes/adbbc689-5f", "valido": true}, {"id": 7, "materia": "Administração de RH / Processos Administrativos", "assunto": "Treinamento e Desenvolvimento", "enunciado": "Vários estudos indicam que o investimento em atividades de treinamento de pessoal está associado ao aumento da lucratividade no longo prazo. Por esse motivo, o presidente de uma empresa determinou que 10% dos ganhos da organização fossem utilizados para as atividades de treinamento do ano seguinte. Sabendo que o processo de treinamento envolve três etapas, o diretor de Recursos Humanos dará início à primeira dessas etapas, denominada", "alternativas": ["modelagem de avaliação", "desenvolvimento de lideranças", "levantamento das necessidades", "treinamento e desenvolvimento", "seleção de programas de instrução"], "corretaIndex": 2, "regra": "O ciclo de treinamento (Chiavenato) inicia-se pelo diagnóstico/levantamento de necessidades (LNT), seguido de planejamento/execução e avaliação.", "fonte": "Cesgranrio — UNEMAT — Administrador — 2024", "fonteUrl": "https://www.qconcursos.com/questoes-de-concursos/questoes/69e308fe-dc", "valido": true}, {"id": 8, "materia": "Administração de RH / Processos Administrativos", "assunto": "Treinamento e Desenvolvimento", "enunciado": "O gerente de uma empresa sabe que alguma ação é necessária para que o comportamento de seus subordinados seja aquele desejado pela organização. Dessa forma, toda vez que um membro de sua equipe realiza um bom trabalho, o gerente faz questão de elogiá-lo. Assim, o gerente modela o comportamento de seus subordinados através de um método denominado", "alternativas": ["obliteração", "sublimação", "derrogação", "instinto natural", "reforço positivo"], "corretaIndex": 4, "regra": "Reconhecer e elogiar comportamentos desejados para incentivá-los é a aplicação clássica de reforço positivo (condicionamento operante de Skinner).", "fonte": "Cesgranrio — UNEMAT — Administrador — 2024", "fonteUrl": "https://www.qconcursos.com/questoes-de-concursos/questoes/69d2315a-dc", "valido": true}, {"id": 9, "materia": "Administração de RH / Processos Administrativos", "assunto": "Onboarding / Integração", "enunciado": "Um programador foi recém-contratado e precisava passar por um treinamento. Por ser apenas uma pessoa, a equipe de recursos humanos decidiu, com base nas ações já planejadas pelo setor, encaixá-lo em um treinamento de desenvolvimento organizacional. Após o treinamento, ao chegar no setor, seu supervisor percebeu que lhe faltavam conhecimentos básicos sobre as políticas e as normas internas sobre questões de segurança e ética na organização. Para corrigir a situação, em vez de um treinamento em desenvolvimento organizacional, o programador deveria ter sido alocado em um treinamento de", "alternativas": ["crescimento gerencial", "desenvolvimento de equipe", "habilidades interpessoais", "integração e orientação", "planejamento e mudança"], "corretaIndex": 3, "regra": "Treinamento de integração e orientação (onboarding) é o que transmite normas, políticas internas e cultura organizacional ao novo colaborador, preenchendo exatamente a lacuna descrita.", "fonte": "Cesgranrio — IPEA — Técnico de Planejamento e Pesquisa (Gestão e Logística) — 2024", "fonteUrl": "https://www.qconcursos.com/questoes-de-concursos/questoes/ddd04f50-d5", "valido": true}, {"id": 10, "materia": "Administração de RH / Processos Administrativos", "assunto": "Gestão de Desempenho", "enunciado": "Em uma empresa, o chefe de um determinado setor listou todos os seus funcionários por ordem decrescente de desempenho, considerando que as diferenças entre os funcionários são uniformes e deixando claro que apenas um funcionário poderia ser 'o melhor'. Nesse processo de avaliação de desempenho, foi utilizada a", "alternativas": ["lista de verificação", "escala de classificação adjetiva", "escala de classificação ancorada no comportamento", "classificação individual", "classificação pela ordem do grupo"], "corretaIndex": 4, "regra": "Ranquear funcionários em ordem decrescente com apenas um 'melhor' e diferenças uniformes é o método de classificação pela ordem do grupo (ranking method).", "fonte": "Cesgranrio — CNU (Concurso Nacional Unificado) — 2024", "fonteUrl": "https://www.qconcursos.com/questoes-de-concursos/questoes/e0d366e7da9", "valido": true}, {"id": 11, "materia": "Administração de RH / Processos Administrativos", "assunto": "Gestão de Desempenho", "enunciado": "Um órgão estatal brasileiro de médio porte tinha entre os seus objetivos criar um trabalho significativo que fosse visto pelos servidores como importante, valioso e recompensador. Ao realizar uma pesquisa para analisar a satisfação dos seus servidores, esse órgão identificou uma insatisfação quanto ao grau em que a tarefa requer a execução de um trabalho completo e identificável, ou seja, a realização de uma tarefa do início ao fim. Os servidores estão insatisfeitos com a(o)", "alternativas": ["autonomia", "variabilidade de habilidades", "identidade da tarefa", "significado da tarefa", "feedback"], "corretaIndex": 2, "regra": "O Modelo de Características do Trabalho (Hackman & Oldham) define 'identidade da tarefa' como o grau em que o cargo requer realização de uma peça de trabalho completa e identificável do início ao fim.", "fonte": "Cesgranrio — CNU — Bloco 5 (Educação, Saúde, Desenvolvimento Social e DH) — 2024", "fonteUrl": "https://www.qconcursos.com/questoes-de-concursos/questoes/9a1bafb3-61", "valido": true}, {"id": 12, "materia": "Administração de RH / Processos Administrativos", "assunto": "Gestão de Desempenho", "enunciado": "Com o objetivo de enriquecer o trabalho de um funcionário, um gerente buscou relacionar as experiências desse funcionário às dos clientes, compartilhando com ele e com seus colegas, em reuniões mensais, histórias de clientes que se beneficiaram dos produtos e serviços da organização, dando-lhes um lembrete poderoso do impacto de seu trabalho.", "alternativas": ["combinação de tarefas", "significância da atividade", "expansão vertical das tarefas", "compartilhamento de tarefas", "abertura de canais de feedback"], "corretaIndex": 1, "regra": "Mostrar o impacto do trabalho sobre a vida de clientes reforça a percepção de 'significância da tarefa', dimensão central do enriquecimento de cargos.", "fonte": "Cesgranrio — CNU — Bloco 4 (Trabalho e Saúde do Servidor) — 2024", "fonteUrl": "https://www.qconcursos.com/questoes-de-concursos/questoes/b95dc96f-5f", "valido": true}, {"id": 13, "materia": "Administração de RH / Processos Administrativos", "assunto": "Motivação", "enunciado": "Um funcionário de um banco é emocionalmente instável, incapaz de despertar muito entusiasmo ou interesse em seus subordinados. Sua consciência sobre suas próprias emoções e as emoções dos outros é quase nula. Normalmente reage de forma exagerada aos problemas. Ele não entende por que seus subordinados ficam perturbados com ele. Essa descrição caracteriza um funcionário que possui baixa", "alternativas": ["dissonância emocional", "autoconcordância", "autoavaliação básica", "habilidade conceitual", "inteligência emocional"], "corretaIndex": 4, "regra": "Baixa autopercepção das próprias emoções e das emoções alheias, com reações desproporcionais, caracteriza baixa inteligência emocional (Goleman).", "fonte": "Cesgranrio — Caixa Econômica Federal (Arquiteto/Engenheiros/Médico do Trabalho) — 2026", "fonteUrl": "https://www.qconcursos.com/questoes-de-concursos/questoes/5ab45a2e-01", "valido": true}, {"id": 14, "materia": "Administração de RH / Processos Administrativos", "assunto": "Liderança", "enunciado": "Em uma organização, predominam líderes que enfatizam o trabalho padronizado e as tarefas orientadas, trocando recompensas por desempenho e conformidade dos subordinados às regras estabelecidas. Esse estilo de liderança é conhecido como", "alternativas": ["servidora", "transformacional", "transacional", "autêntica", "4.0"], "corretaIndex": 2, "regra": "Liderança transacional baseia-se na troca de recompensas contingentes por cumprimento de metas e regras, sem necessariamente inspirar mudança de valores.", "fonte": "Cesgranrio — Caixa Econômica Federal — Técnico Bancário — 2024", "fonteUrl": "https://www.qconcursos.com/questoes-de-concursos/questoes/4f694842-91", "valido": true}, {"id": 15, "materia": "Administração de RH / Processos Administrativos", "assunto": "Motivação", "enunciado": "O gerente de recursos humanos do banco W acredita que os funcionários se sentem motivados a produzir mais quando percebem uma relação clara entre esforço, desempenho e recompensa desejada, e que essa recompensa satisfaz uma necessidade importante para eles.", "alternativas": ["Lócus de Controle", "Maquiavelismo", "Teoria da Expectativa", "Teoria X - Teoria Y", "Teoria da Hierarquia das Necessidades"], "corretaIndex": 2, "regra": "A Teoria da Expectativa de Vroom postula que a motivação depende da relação entre esforço-desempenho-recompensa e do valor (valência) atribuído à recompensa.", "fonte": "Cesgranrio — BNDES — Analista (Administração) — 2024", "fonteUrl": "https://www.qconcursos.com/questoes-de-concursos/questoes/b2afe2c4-8a", "valido": true}, {"id": 16, "materia": "Administração de RH / Processos Administrativos", "assunto": "Liderança", "enunciado": "A cada trimestre o diretor do banco W reúne os funcionários para apresentar as diretrizes que devem ser seguidas, definindo sozinho as tarefas e determinando quem as executará, sem consultar a equipe.", "alternativas": ["autocrático", "democrático", "funcional", "liberal", "passivo"], "corretaIndex": 0, "regra": "Definir sozinho tarefas e diretrizes sem participação da equipe caracteriza estilo de liderança autocrático (White & Lippitt).", "fonte": "Cesgranrio — BNDES — Analista (Administração) — 2024", "fonteUrl": "https://www.qconcursos.com/questoes-de-concursos/questoes/b2a79b96-8a", "valido": true}, {"id": 17, "materia": "Administração de RH / Processos Administrativos", "assunto": "Motivação", "enunciado": "Vários estudos têm enfatizado que as singularidades organizacionais influenciam a motivação dos indivíduos no trabalho. A afirmação de um funcionário que reflete motivação intrínseca é: 'O que mais me importa é sentir prazer pelo que faço, independentemente do reconhecimento externo.'", "alternativas": ["'O que mais me importa é sentir prazer pelo que faço, independentemente do reconhecimento externo.'", "'Não fico muito preocupado com o que os outros pensam do meu trabalho.'", "'Sou fortemente motivado pelo dinheiro que posso ganhar.'", "'Fico mais preocupado com o que me pagam do que com o trabalho em si.'", "'Prefiro que alguém estabeleça para mim os objetivos a atingir.'"], "corretaIndex": 0, "regra": "Motivação intrínseca é definida pelo interesse e satisfação no próprio conteúdo da tarefa, independentemente de recompensas externas.", "fonte": "Cesgranrio — CNU — Bloco 1 — 2024", "fonteUrl": "https://www.qconcursos.com/questoes-de-concursos/questoes/aee33955-5f", "valido": true}, {"id": 18, "materia": "Administração de RH / Processos Administrativos", "assunto": "Motivação", "enunciado": "Em pesquisa para avaliar os fatores de motivação para novos funcionários do setor público, identificou-se forte preocupação com estabilidade no emprego, proteção contra perdas financeiras e ambiente de trabalho previsível. Segundo Maslow, essa preocupação está relacionada às necessidades", "alternativas": ["fisiológicas", "sociais", "de autorrealização", "de estima", "de segurança"], "corretaIndex": 4, "regra": "Estabilidade, proteção e previsibilidade correspondem às necessidades de segurança na hierarquia de Maslow.", "fonte": "Cesgranrio — CNU — Bloco 4 — 2024", "fonteUrl": "https://www.qconcursos.com/questoes-de-concursos/questoes/b95621b5-5f", "valido": true}, {"id": 19, "materia": "Administração de RH / Processos Administrativos", "assunto": "Liderança", "enunciado": "O exercício da liderança no serviço público requer o desenvolvimento de competências particulares que combinam conhecimento técnico com capacidade de articulação política e gerencial dentro da máquina pública.", "alternativas": ["de mobilização de equipe", "de tomada de decisão", "para inovação", "político-gerencial", "técnico-funcional"], "corretaIndex": 3, "regra": "No setor público, a liderança demanda competência político-gerencial, que combina articulação política, negociação institucional e gestão técnica.", "fonte": "Cesgranrio — CNU — Bloco 7 — 2024", "fonteUrl": "https://www.qconcursos.com/questoes-de-concursos/questoes/adc0db75-5f", "valido": true}, {"id": 20, "materia": "Administração de RH / Processos Administrativos", "assunto": "Liderança", "enunciado": "O fenômeno da liderança nas organizações é multidimensional e multifacetado. Considerando um estilo que motiva os seguidores a transcender seus próprios interesses em prol da organização e provoca impacto profundo e extraordinário sobre eles, trata-se da liderança", "alternativas": ["transformacional", "transacional", "carismática", "autocrática", "liberal"], "corretaIndex": 0, "regra": "Liderança transformacional inspira seguidores a transcender interesses próprios em nome de metas coletivas e provoca mudanças profundas de atitude.", "fonte": "Cesgranrio — CNU — Bloco 7 — 2024", "fonteUrl": "https://www.qconcursos.com/questoes-de-concursos/questoes/adb9450d-5f", "valido": true}, {"id": 21, "materia": "Administração de RH / Processos Administrativos", "assunto": "Liderança", "enunciado": "Uma organização tem a responsabilidade de definir critérios para escolher futuros líderes, considerando não apenas o desempenho técnico do candidato, mas também seu comportamento e a coerência entre discurso e prática ao longo da carreira.", "alternativas": ["inteligência emocional; aspectos comportamentais; tendência a riscos", "empatia; visão objetiva; foco em resultados", "legitimidade técnica; aspectos comportamentais; resultados alinhados aos valores organizacionais", "comunicação; positividade; firmeza", "foco em pessoas; atitudes; foco em metas"], "corretaIndex": 2, "regra": "A escolha de líderes deve combinar legitimidade técnica, avaliação comportamental consistente e resultados coerentes com os valores da organização.", "fonte": "Cesgranrio — Caixa Econômica Federal (Médico/Engenheiro do Trabalho) — 2024", "fonteUrl": "https://www.qconcursos.com/questoes-de-concursos/questoes/ee118ecb-1f", "valido": true}, {"id": 22, "materia": "Administração de RH / Processos Administrativos", "assunto": "Liderança", "enunciado": "Muitas vezes, as ações dos líderes são irrelevantes. Nesse contexto, considere duas situações em que regras, políticas e coesão de grupo podem substituir a necessidade de liderança formal, funcionando como substitutos e neutralizadores da liderança.", "alternativas": ["regras e procedimentos formais podem substituir a liderança; líderes se lamentam da existência de neutralizadores que ignoram", "regras podem substituir liderança; substitutos esclarecem expectativas dos papéis", "a estrutura organizacional torna a liderança mais necessária; seguidores diferem quanto ao foco de atenção", "líderes devem estar cientes de neutralizadores; a concentração de poder afeta a eficácia da liderança", "baixo poder do líder neutraliza a liderança; o líder pode remover o neutralizador"], "corretaIndex": 0, "regra": "A teoria dos substitutos da liderança (Kerr e Jermier) explica que certas variáveis situacionais podem substituir ou neutralizar a necessidade de liderança formal.", "fonte": "Cesgranrio — Caixa Econômica Federal — Técnico Bancário — 2024", "fonteUrl": "https://www.qconcursos.com/questoes-de-concursos/questoes/96c70ad1-1c", "valido": true}, {"id": 23, "materia": "Administração de RH / Processos Administrativos", "assunto": "Liderança", "enunciado": "Em uma organização, foi observado que um determinado gerente usa seu tempo para criar situações de confiança, respeito mútuo e boa comunicação com os subordinados, priorizando o bem-estar da equipe acima da execução estrita das tarefas.", "alternativas": ["tarefa", "relação", "mudança", "personalidade", "externo"], "corretaIndex": 1, "regra": "Comportamentos voltados a confiança, respeito e comunicação caracterizam a orientação para relação (consideração), uma das dimensões clássicas do comportamento de liderança.", "fonte": "Cesgranrio — Caixa Econômica Federal — Técnico Bancário — 2024", "fonteUrl": "https://www.qconcursos.com/questoes-de-concursos/questoes/ffd65d90-1c", "valido": true}, {"id": 24, "materia": "Administração de RH / Processos Administrativos", "assunto": "Motivação", "enunciado": "Uma das principais teorias que buscam explicar a motivação individual é a Teoria da Hierarquia das Necessidades, de Maslow. Um funcionário que busca reconhecimento, status e prestígio dentro da organização está satisfazendo necessidades", "alternativas": ["sociais", "de estima", "fisiológicas", "de segurança", "de autorrealização"], "corretaIndex": 1, "regra": "Reconhecimento, status e prestígio correspondem às necessidades de estima na pirâmide de Maslow.", "fonte": "Cesgranrio — UNEMAT — Administrador — 2024", "fonteUrl": "https://www.qconcursos.com/questoes-de-concursos/questoes/69d81dab-dc", "valido": true}, {"id": 25, "materia": "Administração de RH / Processos Administrativos", "assunto": "Motivação", "enunciado": "Um gestor tem percebido a baixa motivação de seus colaboradores e decidiu desenvolver melhorias no ambiente físico de trabalho, na política salarial e nas relações com a chefia, elementos que, segundo Herzberg, evitam a insatisfação mas não geram motivação por si só.", "alternativas": ["fatores higiênicos", "fatores intrínsecos", "necessidades sociais", "necessidades de estima", "necessidades de autorrealização"], "corretaIndex": 0, "regra": "Segundo a Teoria dos Dois Fatores de Herzberg, salário, condições físicas e relações com a chefia são fatores higiênicos, que evitam insatisfação mas não motivam por si sós.", "fonte": "Cesgranrio — IPEA — Técnico de Planejamento e Pesquisa — 2024", "fonteUrl": "https://www.qconcursos.com/questoes-de-concursos/questoes/ddd5261b-d5", "valido": true}, {"id": 26, "materia": "Administração de RH / Processos Administrativos", "assunto": "Liderança", "enunciado": "O chefe de uma equipe é considerado por todo o grupo como um líder autêntico. Essa percepção do grupo decorre principalmente da(o)", "alternativas": ["condução da equipe em direção às metas estabelecidas pela alta administração", "valorização de relações com fundação em princípios éticos e honestidade nas ações do líder", "consulta sistemática aos subordinados antes de qualquer decisão", "estabelecimento de objetivos desafiadores para a equipe", "divisão total das responsabilidades entre os membros do grupo"], "corretaIndex": 1, "regra": "Liderança autêntica se caracteriza pela coerência entre valores pessoais e ações, com forte base ética e honestidade nas relações com os liderados.", "fonte": "Cesgranrio — Transpetro — Taifeiro — 2023", "fonteUrl": "https://www.qconcursos.com/questoes-de-concursos/questoes/6440ac9a-9d", "valido": true}, {"id": 27, "materia": "Administração de RH / Processos Administrativos", "assunto": "Motivação", "enunciado": "Um dos fatores mais importantes que influenciam o nível de motivação de um funcionário é o grau de autonomia sobre seu próprio trabalho. Dentre as ocupações a seguir, aquela que apresenta o maior grau de autonomia percebida é a de", "alternativas": ["marceneiro de fábrica operando um torno em linha de produção", "faxineiro varrendo pisos segundo um manual de procedimentos", "proprietário-operador de uma garagem mecânica", "eletricista montando rádios em linha de montagem", "operadora de telefonia respondendo chamadas padronizadas"], "corretaIndex": 2, "regra": "A autonomia é máxima quando o indivíduo controla integralmente seu processo de trabalho, como no caso do proprietário-operador de um pequeno negócio.", "fonte": "Cesgranrio — AGERIO — Analista de Desenvolvimento — 2023", "fonteUrl": "https://www.qconcursos.com/questoes-de-concursos/questoes/78502ae9-fb", "valido": true}, {"id": 28, "materia": "Administração de RH / Processos Administrativos", "assunto": "Liderança", "enunciado": "Um novo líder foi contratado para que, até 2030, sua organização seja reconhecida como referência no setor. Para isso, ele precisa, sobretudo,", "alternativas": ["transmitir valores centrados nos outros e não em si mesmo", "compartilhar informações e agir de forma consistente com suas crenças declaradas", "exibir recompensas contingenciais associadas ao desempenho individual", "criar e articular uma visão e estratégia de longo prazo, inspirando os demais a segui-la", "estipular diretrizes rígidas e estabelecer padrões de desempenho a serem cumpridos"], "corretaIndex": 3, "regra": "Liderança visionária de longo prazo caracteriza-se pela capacidade de criar e articular uma visão estratégica de futuro capaz de mobilizar toda a organização.", "fonte": "Cesgranrio — AGERIO — Analista de Desenvolvimento — 2023", "fonteUrl": "https://www.qconcursos.com/questoes-de-concursos/questoes/e04d2bc4-fb", "valido": true}, {"id": 29, "materia": "Administração de RH / Processos Administrativos", "assunto": "Motivação", "enunciado": "O gerente de vendas de um banco tem sustentado que, para que as recompensas motivem seus subordinados, é necessário que o vendedor perceba claramente que o esforço aplicado levará a um desempenho satisfatório e que este, por sua vez, resultará em uma recompensa valorizada.", "alternativas": ["do conflito de papéis", "dos dois fatores", "da expectativa", "da ambiguidade de papéis", "do enriquecimento do trabalho"], "corretaIndex": 2, "regra": "A percepção de ligação entre esforço, desempenho e recompensa valorizada é o núcleo da Teoria da Expectativa (Vroom).", "fonte": "Cesgranrio — Banco da Amazônia — Técnico Bancário — 2022", "fonteUrl": "https://www.qconcursos.com/questoes-de-concursos/questoes/d9878465-7c", "valido": true}, {"id": 30, "materia": "Administração de RH / Processos Administrativos", "assunto": "Desenvolvimento de Carreira", "enunciado": "Na busca por melhores relações humanas no trabalho, é fundamental o desenvolvimento contínuo das próprias capacidades e competências profissionais por iniciativa do próprio indivíduo, processo conhecido como", "alternativas": ["autoavaliação", "autoconhecimento", "autocrítica", "autodesenvolvimento", "autopromoção"], "corretaIndex": 3, "regra": "Autodesenvolvimento é o processo pelo qual o próprio indivíduo, por iniciativa própria, busca desenvolver capacidades e competências profissionais.", "fonte": "Cesgranrio — UNIRIO — Técnico em Assuntos Educacionais — 2019", "fonteUrl": "https://www.qconcursos.com/questoes-de-concursos/questoes/7f6ec09f-a4", "valido": true}, {"id": 31, "materia": "Administração de RH / Processos Administrativos", "assunto": "Liderança / Estrutura Organizacional", "enunciado": "Estudos recentes mostram que, nos modelos de organização mais horizontalizados, com menos níveis hierárquicos, o(a)", "alternativas": ["autonomia dos membros da equipe não é mais valorizada nesse contexto", "liderança formal perde credibilidade frente às equipes autogeridas", "crescimento da organização impede a contratação de novos líderes em tempo hábil", "contexto mais complexo e dinâmico exige líderes com maior capacidade de delegar autonomia e poder", "líderes deixam de ser necessários, pois as equipes se autogerenciam plenamente"], "corretaIndex": 3, "regra": "Estruturas horizontalizadas exigem líderes capazes de lidar com maior complexidade e delegar autonomia e poder às equipes, e não eliminam a necessidade de liderança.", "fonte": "Cesgranrio — UNIRIO — Assistente em Administração — 2019", "fonteUrl": "https://www.qconcursos.com/questoes-de-concursos/questoes/6a2ee3ac-1c", "valido": true}, {"id": 32, "materia": "Administração de RH / Processos Administrativos", "assunto": "Estrutura Organizacional", "enunciado": "As organizações podem escolher diferentes estratégias de controle. Uma instituição, buscando tornar-se uma organização de aprendizagem, com departamentos pequenos e alto grau de incerteza sobre metas e tecnologias, adotou uma estratégia de controle baseada em", "alternativas": ["centralização, mecanismos formais, relações pessoais, liderança e formalização", "descentralização, confiança, informações gerenciais e centros de responsabilidade", "preços, concorrência, relacionamento de trocas, participação no mercado e lucros", "regras, padrões, autoridade legítima, hierarquia e fiscalização", "tradições e crenças, valores compartilhados, compromisso e cultura corporativa"], "corretaIndex": 4, "regra": "O controle de clã (Ouchi) baseia-se em valores compartilhados, tradições e cultura corporativa, adequado a ambientes de alta incerteza e baixa padronização.", "fonte": "Cesgranrio — CNU — Bloco 3 (Ambiental, Agrário e Biológicas) — 2024", "fonteUrl": "https://www.qconcursos.com/questoes-de-concursos/questoes/911c2f5b-61", "valido": true}, {"id": 33, "materia": "Administração de RH / Processos Administrativos", "assunto": "Estrutura Organizacional", "enunciado": "Uma universidade criou um Manual de Rotinas e Procedimentos Administrativos detalhando a gestão de documentos, siglas, modelos oficiais, padronização de layout e fluxogramas. Isso se refere à dimensão estrutural de", "alternativas": ["especialização", "centralização", "estratégia", "formalização", "tecnologia"], "corretaIndex": 3, "regra": "Formalização é o grau em que uma organização documenta e padroniza, por escrito, suas rotinas, procedimentos e comunicações.", "fonte": "Cesgranrio — UNEMAT — Administrador — 2024", "fonteUrl": "https://www.qconcursos.com/questoes-de-concursos/questoes/69f9f3a0-dc", "valido": true}, {"id": 34, "materia": "Administração de RH / Processos Administrativos", "assunto": "Estrutura Organizacional", "enunciado": "Uma universidade multicampi propõe adotar uma estrutura matricial. Qual é o principal ponto forte dessa estrutura?", "alternativas": ["pequeno esforço para manter poder equilibrado, aumentando o compartilhamento de informação", "compartilhamento flexível de recursos humanos entre projetos e produtos, facilitando a coordenação múltipla", "economia de tempo, com poucas reuniões e decisões centralizadas, favorecendo relações verticais", "delegação de tomada de decisão para autoridade vertical, diminuindo o poder de órgãos colegiados", "utilização de autoridade dual e diminuição da ambiguidade da cadeia de comando"], "corretaIndex": 1, "regra": "O ponto forte da estrutura matricial é permitir compartilhamento flexível de recursos entre múltiplos projetos, facilitando a coordenação simultânea.", "fonte": "Cesgranrio — UNEMAT — Administrador — 2024", "fonteUrl": "https://www.qconcursos.com/questoes-de-concursos/questoes/69f47ba7-dc", "valido": true}, {"id": 35, "materia": "Administração de RH / Processos Administrativos", "assunto": "Estrutura Organizacional", "enunciado": "Em uma universidade de grande porte, as atividades estão agrupadas por funções comuns, com conhecimento reunido promovendo economia de escala; porém, o tempo de resposta a mudanças ambientais é lento, cada funcionário tem visão restrita das metas gerais, a hierarquia vertical fica sobrecarregada e a coordenação horizontal é deficiente. Essa é a estrutura", "alternativas": ["divisional", "geográfica", "matricial", "horizontal", "funcional"], "corretaIndex": 4, "regra": "Agrupamento por funções comuns com economia de escala mas fraca coordenação horizontal e resposta lenta a mudanças é o desenho típico da estrutura funcional.", "fonte": "Cesgranrio — UNEMAT — Técnico Administrativo do Ensino Superior — 2024", "fonteUrl": "https://www.qconcursos.com/questoes-de-concursos/questoes/35185b4d-dc", "valido": true}, {"id": 36, "materia": "Administração de RH / Processos Administrativos", "assunto": "Estrutura Organizacional", "enunciado": "A função do gerente de projeto varia de acordo com a estrutura organizacional em que o projeto é realizado. No caso do projeto levado à frente por certa empresa, o gerente do projeto está subordinado ao setor de vendas. Essa estrutura é classificada como", "alternativas": ["basilar", "matricial", "funcional", "projetizada", "centralizada"], "corretaIndex": 2, "regra": "Quando o gerente de projeto está subordinado a um departamento funcional (não tem autoridade própria plena sobre a equipe do projeto), a estrutura é funcional.", "fonte": "Cesgranrio — AGERIO — Analista de Desenvolvimento — 2023", "fonteUrl": "https://www.qconcursos.com/questoes-de-concursos/questoes/783afb94-fb", "valido": true}, {"id": 37, "materia": "Administração de RH / Processos Administrativos", "assunto": "Estrutura Organizacional", "enunciado": "O modelo das três linhas de defesa estabelece papéis e responsabilidades essenciais dentro de uma organização quanto ao controle e gerenciamento de riscos. Essas linhas correspondem a", "alternativas": ["amplitude de controle; priorização; supervisão e monitoramento", "coordenação; unidade de comando; controle", "execução; supervisão e monitoramento; avaliação", "mapeamento; implementação; avaliação", "planejamento; execução; coopetição"], "corretaIndex": 2, "regra": "O modelo das três linhas de defesa distribui responsabilidades entre quem executa/gerencia riscos, quem supervisiona/monitora e quem avalia de forma independente (auditoria).", "fonte": "Cesgranrio — AGERIO — Múltiplos Cargos — 2023", "fonteUrl": "https://www.qconcursos.com/questoes-de-concursos/questoes/a8efe0e4-fb", "valido": true}, {"id": 38, "materia": "Administração de RH / Processos Administrativos", "assunto": "Estrutura Organizacional", "enunciado": "O desenho que demonstra a estrutura organizacional, os cargos, funções, áreas/departamentos e seus respectivos níveis hierárquicos é representado pelo", "alternativas": ["organograma", "fluxograma", "diagrama de blocos", "gráfico de linhas", "diagrama de Pareto"], "corretaIndex": 0, "regra": "O organograma é a representação gráfica formal da estrutura hierárquica e departamental de uma organização.", "fonte": "Cesgranrio — UNIRIO — Assistente em Administração — 2019", "fonteUrl": "https://www.qconcursos.com/questoes-de-concursos/questoes/6a2c0492-1c", "valido": true}, {"id": 39, "materia": "Administração de RH / Processos Administrativos", "assunto": "Estrutura Organizacional", "enunciado": "Um consultor observou que, em determinada empresa, a autoridade era fluida, seguindo uma linha horizontal; os procedimentos não eram documentados e havia alto grau de criatividade na cultura organizacional. Esse tipo de estrutura é conhecido como", "alternativas": ["caótica", "formal", "centralizada", "departamentalizada", "informal"], "corretaIndex": 4, "regra": "Autoridade fluida, procedimentos não documentados e criatividade caracterizam a estrutura informal, contraposta à estrutura formal.", "fonte": "Cesgranrio — UNIRIO — Assistente em Administração — 2019", "fonteUrl": "https://www.qconcursos.com/questoes-de-concursos/questoes/69e27f15-1c", "valido": true}, {"id": 40, "materia": "Administração de RH / Processos Administrativos", "assunto": "Estrutura Organizacional", "enunciado": "Uma estrutura horizontal dominante, projetada para aprendizagem organizacional, apresenta como elementos característicos do projeto organizacional", "alternativas": ["tarefas especializadas, hierarquia rígida e tomada de decisão centralizada", "muitas equipes, comunicação face a face e tarefas compartilhadas", "hierarquia menos rígida, muitas normas e comunicação estritamente vertical", "submissão hierárquica, padronização de normas e relatórios periódicos", "papéis limítrofes bem definidos, alta especialização e ampla amplitude de controle"], "corretaIndex": 1, "regra": "Estruturas horizontais voltadas à aprendizagem organizacional caracterizam-se por múltiplas equipes, comunicação direta (face a face) e compartilhamento de tarefas.", "fonte": "Cesgranrio — Petrobras — Administrador Júnior — 2018", "fonteUrl": "https://www.qconcursos.com/questoes-de-concursos/questoes/7405623b-2d", "valido": true}, {"id": 41, "materia": "Administração de RH / Processos Administrativos", "assunto": "Estrutura Organizacional", "enunciado": "A estrutura horizontal, que organiza os colaboradores em torno de processos centrais em vez de funções, possui como característica", "alternativas": ["ser criada em torno de tarefas/funções especializadas, para eliminar limites interdepartamentais", "tomada de decisão centralizada, muitas normas, poucas equipes e subordinação hierárquica dominante", "donos de processos com responsabilidade total sobre cada processo central e cultura de colaboração", "indivíduos como base do projeto organizacional, favorecendo conhecimento técnico especializado", "limites claros entre departamentos funcionais, contribuindo para visão mais ampla das metas"], "corretaIndex": 2, "regra": "A estrutura horizontal por processos atribui a 'donos de processo' a responsabilidade integral por um processo-fim de ponta a ponta, fomentando colaboração entre áreas.", "fonte": "Cesgranrio — IBGE — Supervisor de Pesquisas (Gestão) — 2016", "fonteUrl": "https://www.qconcursos.com/questoes-de-concursos/questoes/9807a527-7a", "valido": true}, {"id": 42, "materia": "Administração de RH / Processos Administrativos", "assunto": "Estrutura Organizacional", "enunciado": "Na escolha de seu modelo estrutural, as organizações optam pela departamentalização por cliente ou mercado quando", "alternativas": ["adotam modelo orgânico com extensa departamentalização, buscando participação dos funcionários", "utilizam estrutura matricial, agrupando tarefas em departamentos funcionais", "adotam departamentalização por produto/serviço, à medida que aumenta a interação entre colaboradores", "os diferentes grupos de clientes/mercados atendidos diferem substancialmente entre si em necessidades", "optam por grande amplitude de administração, para manter maior controle sobre os colaboradores"], "corretaIndex": 3, "regra": "A departamentalização por cliente/mercado é adequada quando os diferentes públicos atendidos apresentam necessidades e características substancialmente distintas.", "fonte": "Cesgranrio — IBGE — Supervisor de Pesquisas (Gestão) — 2016", "fonteUrl": "https://www.qconcursos.com/questoes-de-concursos/questoes/97e605b6-7a", "valido": true}, {"id": 43, "materia": "Administração de RH / Processos Administrativos", "assunto": "Estrutura Organizacional", "enunciado": "O diretor de uma empresa deseja aumentar a amplitude de controle e diminuir os níveis hierárquicos, pois manter muitos gestores com poucos subordinados cada estava se mostrando caro e ineficiente. Essa mudança resultará em uma estrutura", "alternativas": ["aguda", "obtusa", "vertical", "horizontal", "dependente"], "corretaIndex": 3, "regra": "Aumentar a amplitude de controle e reduzir níveis hierárquicos achata a pirâmide organizacional, resultando em estrutura horizontal (achatada).", "fonte": "Cesgranrio — IBGE — Supervisor de Pesquisas (Gestão) — 2016", "fonteUrl": "https://www.qconcursos.com/questoes-de-concursos/questoes/97244258-7a", "valido": true}, {"id": 44, "materia": "Administração de RH / Processos Administrativos", "assunto": "Estrutura Organizacional", "enunciado": "Uma empresa do setor de energia tem administração centralizada, com diversos níveis hierárquicos, departamentos divididos por especialidades, e cada funcionário responde a um único chefe. Essa é a estrutura", "alternativas": ["funcional", "divisional", "matricial", "por projeto", "por processo"], "corretaIndex": 0, "regra": "Departamentos organizados por especialidade técnica, com unidade de comando e hierarquia centralizada, caracterizam a estrutura funcional clássica.", "fonte": "Cesgranrio — UNIRIO — Assistente em Administração — 2016", "fonteUrl": "https://www.qconcursos.com/questoes-de-concursos/questoes/ce5718e3-53", "valido": true}, {"id": 45, "materia": "Administração de RH / Processos Administrativos", "assunto": "Estrutura Organizacional", "enunciado": "Uma empresa de serviços realiza atividades por tempo determinado e propósito definido, com atribuições temporárias e pessoal realocado quando as tarefas terminam; a estrutura é simples, flexível, adaptável, mantendo a unidade de comando. Essa é a estrutura", "alternativas": ["matricial", "funcional", "departamental", "divisional geográfica", "por projetos"], "corretaIndex": 4, "regra": "Atividades com propósito e prazo definidos, equipes temporárias e realocação ao término das tarefas são características da estrutura por projetos.", "fonte": "Cesgranrio — UNIRIO — Assistente em Administração — 2016", "fonteUrl": "https://www.qconcursos.com/questoes-de-concursos/questoes/ce52bbed-53", "valido": true}, {"id": 46, "materia": "Administração de RH / Processos Administrativos", "assunto": "Estrutura Organizacional", "enunciado": "A organização de uma empresa envolve diversas atividades para que haja maior eficiência. Uma dessas atividades é o agrupamento das tarefas de tal forma que se torne mais fácil a coordenação e integração das atividades. O processo de agrupar as tarefas é a(o)", "alternativas": ["competitividade", "departamentalização", "descentralização", "produtividade", "planejamento"], "corretaIndex": 1, "regra": "Departamentalização é o processo de agrupar atividades e tarefas em unidades organizacionais para facilitar coordenação e integração.", "fonte": "Cesgranrio — CEFET-RJ — Assistente em Administração — 2014", "fonteUrl": "https://www.qconcursos.com/questoes-de-concursos/questoes/7a23fd73-fb", "valido": true}, {"id": 47, "materia": "Administração de RH / Processos Administrativos", "assunto": "Estrutura Organizacional", "enunciado": "Uma empresa do setor de peças automotivas optou por estabelecer uma estrutura funcional. A opção por esse tipo de estrutura deve-se às suas características, que são: a organização divide-se segundo diferentes funções, com subordinação funcional dos empregados às respectivas áreas de especialização.", "alternativas": ["a organização divide-se segundo diferentes funções com subordinação funcional dos empregados", "recursos para cada projeto formam unidades organizacionais independentes", "as decisões são centralizadas sob uma única linha de subordinação hierárquica", "as unidades contam com uma unidade especial e independente de apoio", "a organização é multidimensional, procurando maximizar as virtudes de cada área"], "corretaIndex": 0, "regra": "A estrutura funcional agrupa atividades por área de especialização (finanças, RH, produção etc.), com subordinação dentro da própria função.", "fonte": "Cesgranrio — FINEP — Analista de Gestão e Planejamento — 2014", "fonteUrl": "https://www.qconcursos.com/questoes-de-concursos/questoes/5bf26c0c-cd", "valido": true}, {"id": 48, "materia": "Administração de RH / Processos Administrativos", "assunto": "Estrutura Organizacional", "enunciado": "À medida que as tarefas da organização se tornam mais complexas, essa organização deve inevitavelmente ser subdividida, ou seja, departamentalizada em unidades menores. A esse respeito, sabe-se que, na organização divisional, cada divisão tem seus próprios especialistas funcionais.", "alternativas": ["a organização matricial apresenta padronização e centralização com baixa flexibilidade", "a organização matricial reforça o princípio da unidade de comando", "na organização divisional, cada divisão tem seus próprios especialistas funcionais", "na organização divisional, as posições especializadas são agrupadas por função", "a organização funcional busca a departamentalização em torno de produtos"], "corretaIndex": 2, "regra": "Na estrutura divisional, cada divisão (por produto, região etc.) mantém seus próprios especialistas funcionais, atuando de forma quase autônoma.", "fonte": "Cesgranrio — LIQUIGÁS — Profissional Júnior (Administração) — 2012", "fonteUrl": "https://www.qconcursos.com/questoes-de-concursos/questoes/301840b9-05", "valido": true}, {"id": 49, "materia": "Administração de RH / Processos Administrativos", "assunto": "Estrutura Organizacional", "enunciado": "Qual a maior desvantagem de se adotar uma estrutura por processos pura, ou seja, uma estrutura em que não há uma verticalidade funcional?", "alternativas": ["perda da capacidade de coordenação entre as equipes", "perda da visão estratégica da alta administração", "perda do foco no cliente ao longo do processo", "geração de redundâncias e necessidade de profissionais generalistas", "dificuldade em trabalhar com níveis matriciais de autoridade"], "corretaIndex": 3, "regra": "A ausência de verticalidade funcional na estrutura por processos tende a gerar redundância de recursos e exigir profissionais mais generalistas em cada equipe de processo.", "fonte": "Cesgranrio — ELETROBRAS — Analista de Sistemas Júnior — 2010", "fonteUrl": "https://www.qconcursos.com/questoes-de-concursos/questoes/187dd736-b5", "valido": true}, {"id": 50, "materia": "Administração de RH / Processos Administrativos", "assunto": "Estrutura Organizacional", "enunciado": "Ao enfatizar a divisão do trabalho, a Escola Clássica propõe conceitos de departamentalização, dentre os quais está a organização por produto, que diz respeito ao", "alternativas": ["critério para grande área geográfica ou locais diferentes", "trabalho com vários produtos ou linhas de produtos diferenciados", "atendimento a diferentes tipos de clientes", "conjunto de tarefas interdependentes de um mesmo processo", "processo temporário organizado em estruturas provisórias"], "corretaIndex": 1, "regra": "A departamentalização por produto agrupa atividades em torno de cada produto ou linha de produtos da empresa.", "fonte": "Cesgranrio — BNDES — Profissional Básico — 2009", "fonteUrl": "https://www.qconcursos.com/questoes-de-concursos/questoes/fcc9682c-65", "valido": true}, {"id": 51, "materia": "Administração de RH / Processos Administrativos", "assunto": "Estrutura Organizacional", "enunciado": "As camadas hierárquicas fazem parte das organizações formais. Entre os vários tipos de departamentalização, encontra-se a departamentalização por projetos, que tem como uma de suas características a diferenciação e o agrupamento das atividades de acordo com as saídas e resultados relativos a um ou vários projetos.", "alternativas": ["de acordo com funções e tarefas principais da organização", "de acordo com as saídas relativas a um ou vários projetos", "de acordo com o local ou área de mercado atendida", "de acordo com o resultado/produto ou serviço final oferecido", "a partir da sequência do equipamento utilizado no processo"], "corretaIndex": 1, "regra": "A departamentalização por projetos organiza as atividades em função das entregas/saídas de projetos específicos, sendo temporária por natureza.", "fonte": "Cesgranrio — TermoMacaé — Administrador — 2009", "fonteUrl": "https://www.qconcursos.com/questoes-de-concursos/questoes/e6f47066-c7", "valido": true}, {"id": 52, "materia": "Administração de RH / Processos Administrativos", "assunto": "Estrutura Organizacional", "enunciado": "Uma empresa prepara-se para viver uma mudança radical. A nova controladora é conhecida pelo estilo extremamente rigoroso e centralizador. A hierarquia é de tal forma arraigada que as decisões mais simples são tomadas na matriz. Diante disso, na reformulação da estrutura organizacional dessa empresa, os elementos que se destacaram foram", "alternativas": ["especialização do trabalho e formalização", "cadeia de comando e centralização/descentralização", "amplitude de controle e centralização/descentralização", "departamentalização e cadeia de comando", "departamentalização e amplitude de controle"], "corretaIndex": 1, "regra": "Decisões tomadas rigidamente na matriz evidenciam os elementos de cadeia de comando (linha de autoridade) e o grau de centralização/descentralização da estrutura.", "fonte": "Cesgranrio — Petrobras — Administrador — 2006", "fonteUrl": "https://www.qconcursos.com/questoes-de-concursos/questoes/e0cdf954-e5", "valido": true}, {"id": 53, "materia": "Administração de RH / Processos Administrativos", "assunto": "Cultura e Clima Organizacional", "enunciado": "A cultura organizacional se constitui como fator decisivo para os processos de gestão de pessoas. De acordo com o que considera Chiavenato, a cultura está no DNA das organizações e representa o universo simbólico da organização. Nessa perspectiva, o tipo de liderança que melhor se alinha à ideia de considerar a diversidade organizacional é a", "alternativas": ["autocrática", "transacional", "situacional", "democrática", "transformacional"], "corretaIndex": 4, "regra": "A liderança transformacional, ao valorizar visão compartilhada e inspiração dos indivíduos, alinha-se melhor à valorização da diversidade cultural organizacional.", "fonte": "Cesgranrio — CNU — 2024", "fonteUrl": "https://www.qconcursos.com/questoes-de-concursos/questoes/9a1306c3-61", "valido": true}, {"id": 54, "materia": "Administração de RH / Processos Administrativos", "assunto": "Cultura e Clima Organizacional", "enunciado": "Um gerente aplicou o modelo dos valores concorrentes para diagnóstico cultural e identificou flexibilidade, liberdade de ação, foco interno, eficácia baseada em coesão e moral da equipe, líderes atuando como mentores e ambiente amigável com forte comprometimento. Esse tipo de cultura organizacional é a de", "alternativas": ["clã", "mercado", "hierárquica", "exigente", "adhocracia ou inovadora"], "corretaIndex": 0, "regra": "No Modelo de Valores Concorrentes (Cameron & Quinn), a cultura de clã caracteriza-se por foco interno, flexibilidade, coesão de equipe e liderança mentora.", "fonte": "Cesgranrio — Eletrobras Eletronuclear — Administrador — 2022", "fonteUrl": "https://www.qconcursos.com/questoes-de-concursos/questoes/f15d6346-dc", "valido": true}, {"id": 55, "materia": "Administração de RH / Processos Administrativos", "assunto": "Cultura e Clima Organizacional", "enunciado": "Um funcionário afirmou: 'A cultura dominante desta Universidade é paternalista'. Com essa afirmação, ele se referiu ao conceito de valores essenciais compartilhados pela maioria dos membros da organização.", "alternativas": ["ajuste entre indivíduo e organização e compatibilidade entre atitudes, crenças, valores e comportamentos", "valores compartilhados apenas por alguns grupos da organização", "valores essenciais compartilhados pela maioria dos membros da organização", "comportamentos e hábitos que não devem ser questionados para sustentar compatibilidade cultural", "percepções comuns que os membros têm em relação à empresa e ao ambiente"], "corretaIndex": 2, "regra": "Cultura dominante refere-se aos valores essenciais compartilhados pela maioria dos membros da organização, distinguindo-se de subculturas.", "fonte": "Cesgranrio — UNIRIO — Administrador — 2019", "fonteUrl": "https://www.qconcursos.com/questoes-de-concursos/questoes/649b4f4b-1c", "valido": true}, {"id": 56, "materia": "Administração de RH / Processos Administrativos", "assunto": "Cultura e Clima Organizacional", "enunciado": "A categoria mais profunda de manifestação cultural em uma organização é a de valores. Para reforçar que honestidade é um valor fundamental para a identidade empresarial, o rito gerencial a ser utilizado é o de", "alternativas": ["degradação, para homenagear um funcionário aposentado após 40 anos de casa", "redução de conflitos, associado a um programa de redesenho de cargos", "passagem, para enaltecer funcionários envolvidos em esquemas ilegais", "integração, visando dissolver identidades sociais e relações de poder", "reforço, para premiar e reconhecer publicamente um comportamento exemplar"], "corretaIndex": 4, "regra": "Ritos de reforço têm a função de premiar e reconhecer publicamente comportamentos alinhados aos valores centrais, fortalecendo a cultura desejada.", "fonte": "Cesgranrio — Petrobras — Administrador Júnior — 2018", "fonteUrl": "https://www.qconcursos.com/questoes-de-concursos/questoes/741e92ed-2d", "valido": true}, {"id": 57, "materia": "Administração de RH / Processos Administrativos", "assunto": "Cultura e Clima Organizacional", "enunciado": "Após reforma de um prédio, 30 funcionários foram colocados em um grande salão sem divisórias. As normas de vestimenta foram relaxadas, permitindo trabalhar sem gravata e sem paletó às sextas-feiras, com o objetivo de aumentar a comunicação e a eficiência. O gerente, ao promover essas mudanças, está operando no nível cultural de", "alternativas": ["determinações externas", "pressupostos básicos", "valores assumidos", "artefatos", "estrutura"], "corretaIndex": 3, "regra": "Layout físico e código de vestimenta são elementos visíveis da cultura organizacional, classificados como artefatos (nível mais superficial, segundo Schein).", "fonte": "Cesgranrio — IBGE — Supervisor de Pesquisas (Gestão) — 2016", "fonteUrl": "https://www.qconcursos.com/questoes-de-concursos/questoes/96d61b3e-7a", "valido": true}, {"id": 58, "materia": "Administração de RH / Processos Administrativos", "assunto": "Cultura e Clima Organizacional", "enunciado": "A cada semestre, funcionários com melhores resultados são premiados em eventos com presença de empregados e familiares, relembrando avanços empresariais. Esses momentos reforçam normas e valores organizacionais e correspondem à forma de transmissão de cultura conhecida como", "alternativas": ["mito", "linguagem", "cerimônia", "confirmação", "rito de passagem"], "corretaIndex": 2, "regra": "Cerimônias são eventos formais e periódicos que reforçam normas e valores organizacionais por meio de reconhecimento público e simbólico.", "fonte": "Cesgranrio — IBGE — Supervisor de Pesquisas (Gestão) — 2016", "fonteUrl": "https://www.qconcursos.com/questoes-de-concursos/questoes/96a9dd8b-7a", "valido": true}, {"id": 59, "materia": "Administração de RH / Processos Administrativos", "assunto": "Cultura e Clima Organizacional", "enunciado": "Uma empresa bancária buscava romper com padrões estabelecidos devido ao avanço tecnológico e à necessidade de aprimorar produtos e atendimento. Concluiu-se que mudar rapidamente os padrões estabelecidos não é fácil, porém é necessário. Nessa conclusão, a cultura organizacional é tratada como sendo uma", "alternativas": ["conhecimento explícito, manualizado e formalizado pelos grupos internos", "procedimento informalmente definido, treinado apenas pela cúpula", "variável a ser gerenciada, garantindo adaptação externa e coerência interna", "caracterização estática, fechada e imutável ao longo do tempo", "expressão cultural que não pode ser gerenciada pela organização"], "corretaIndex": 2, "regra": "A visão contemporânea de cultura organizacional a trata como uma variável gerenciável, essencial para o equilíbrio entre adaptação externa e integração interna.", "fonte": "Cesgranrio — Banco do Brasil — Escriturário — 2015", "fonteUrl": "https://www.qconcursos.com/questoes-de-concursos/questoes/10b1a281-cc", "valido": true}, {"id": 60, "materia": "Administração de RH / Processos Administrativos", "assunto": "Cultura e Clima Organizacional", "enunciado": "Dois alunos debatiam cultura organizacional. O primeiro afirmou que ela consiste apenas em valores e crenças do nível estratégico. O segundo explicou que ela abrange normas formais e informais que vinculam atitudes individuais, incluindo pressupostos psicossociais. Está correto apenas o segundo aluno.", "alternativas": ["ambos estão corretos", "ambos estão errados", "somente o primeiro está correto", "somente o segundo está correto", "somente o segundo está errado"], "corretaIndex": 3, "regra": "A cultura organizacional abrange todos os níveis (não só o estratégico) e inclui normas formais/informais e pressupostos psicossociais compartilhados.", "fonte": "Cesgranrio — Petrobras — Profissional Júnior (Administração) — 2015", "fonteUrl": "https://www.qconcursos.com/questoes-de-concursos/questoes/51324719-ca", "valido": true}, {"id": 61, "materia": "Administração de RH / Processos Administrativos", "assunto": "Cultura e Clima Organizacional", "enunciado": "Uma empresa constrói sua cultura conforme os elementos que considera importantes, valores e crenças. Algumas empresas têm cultura sedimentada, com valores compartilhados por todos, sem grandes divergências. Essa cultura é classificada como", "alternativas": ["adaptativa", "conservadora", "forte", "fraca", "psicossocial"], "corretaIndex": 2, "regra": "Uma cultura organizacional é considerada forte quando seus valores são amplamente compartilhados e internalizados por todos os membros, com pouca divergência interna.", "fonte": "Cesgranrio — Banco do Brasil — Nível Médio — 2014", "fonteUrl": "https://www.qconcursos.com/questoes-de-concursos/questoes/14db069e-52", "valido": true}, {"id": 62, "materia": "Administração de RH / Processos Administrativos", "assunto": "Cultura e Clima Organizacional", "enunciado": "A cultura organizacional contribui ativamente para a diferenciação entre empresas, sendo criada e preservada pelas pessoas que formam a organização. Essa abordagem baseia-se na premissa de que a cultura é", "alternativas": ["facilmente mudada por decisão da alta direção", "relativa apenas ao mercado em que a empresa atua", "construída socialmente pelos membros da organização", "estruturada exclusivamente no nível operacional", "desvinculada da história organizacional"], "corretaIndex": 2, "regra": "A cultura organizacional é entendida como fenômeno socialmente construído pelos próprios membros ao longo do tempo e da história da organização.", "fonte": "Cesgranrio — Banco do Brasil — Nível Médio — 2014", "fonteUrl": "https://www.qconcursos.com/questoes-de-concursos/questoes/12c501b0-52", "valido": true}, {"id": 63, "materia": "Administração de RH / Processos Administrativos", "assunto": "Cargos e Salários", "enunciado": "João será contemplado com reajuste salarial por mérito que a sua empresa oferece anualmente a seus colaboradores. Tal procedimento significa que", "alternativas": ["o valor real do salário será restabelecido por reajuste coletivo em face das alterações do custo de vida", "foi identificada a necessidade de novo enquadramento de seu cargo na estrutura salarial", "ele foi contemplado com o exercício de um cargo diverso, em nível hierárquico superior", "o supervisor fez alteração de salário dentro da mesma faixa salarial, com base em metas atingidas", "João teve ajuste de salário baseado no cumprimento do período experimental de contratação"], "corretaIndex": 3, "regra": "O aumento por mérito é uma progressão dentro da mesma faixa salarial, concedida em função do desempenho individual, sem mudança de cargo.", "fonte": "Cesgranrio — EPE — Analista de Gestão Corporativa (RH) — 2010", "fonteUrl": "https://www.qconcursos.com/questoes-de-concursos/questoes/1551f52a-d5", "valido": true}, {"id": 64, "materia": "Administração de RH / Processos Administrativos", "assunto": "Cargos e Salários", "enunciado": "No que se refere aos serviços e benefícios oferecidos por uma empresa a seus colaboradores, um aspecto que corresponde adequadamente ao perfil de um trabalhador é a alocação de verba calculada com base em um percentual do salário para benefícios flexíveis, permitindo escolha individual.", "alternativas": ["alocação de verba calculada com base em percentual do salário para benefícios flexíveis", "oferta de financiamento sólido para evitar injunções político-partidárias", "oferta de vantagens comuns e uniformes a todos os grupos hierárquicos", "aplicação em longo prazo dos lucros exclusivamente na própria organização", "condicionamento dos colaboradores ao princípio da mútua responsabilidade financeira"], "corretaIndex": 0, "regra": "Planos de benefícios flexíveis, calculados como percentual do salário e escolhidos conforme o perfil de cada colaborador, atendem melhor à diversidade de necessidades da força de trabalho.", "fonte": "Cesgranrio — EPE — Analista de Gestão Corporativa (RH) — 2010", "fonteUrl": "https://www.qconcursos.com/questoes-de-concursos/questoes/13e240c8-d5", "valido": true}, {"id": 65, "materia": "Administração de RH / Processos Administrativos", "assunto": "Cargos e Salários", "enunciado": "Um programa de salários deve levar em consideração o pacote de benefícios que compõe a contraprestação final do trabalho do empregado. Nessa perspectiva, os planos de benefícios sociais visam à redução da rotação de pessoal e do absenteísmo.", "alternativas": ["melhora do clima organizacional, elevando a moral e a rotatividade de pessoal", "melhora da qualidade de vida dos empregados, oferecendo conveniências gerais", "redução da rotação de pessoal (turnover) e do absenteísmo", "aumento da facilidade na atração e manutenção de recursos humanos qualificados", "favorecimento da equidade das expectativas salariais dos colaboradores"], "corretaIndex": 2, "regra": "Um dos principais objetivos dos planos de benefícios sociais é reduzir a rotatividade (turnover) e o absenteísmo, aumentando a retenção de talentos.", "fonte": "Cesgranrio — EPE — Analista de Gestão Corporativa (RH) — 2010", "fonteUrl": "https://www.qconcursos.com/questoes-de-concursos/questoes/0e34bf84-d5", "valido": true}, {"id": 66, "materia": "Administração de RH / Processos Administrativos", "assunto": "Cargos e Salários", "enunciado": "Em ambientes caracterizados por formas modernas de organização do trabalho, envolvendo celularização, multifuncionalidade e poucos níveis hierárquicos, não faz sentido recompensar a contribuição individual apenas com base em descrições de atividades. O sistema de remuneração estratégica tem sido utilizado como instrumento para gerenciar essa nova realidade porque ajuda a transformar a visão usual de remuneração como fator de custo.", "alternativas": ["combina a composição de salário direto e benefícios indiretos de forma padronizada", "atua como um filtro para a convergência de energias e esforços da organização", "ajuda a transformar a visão usual de remuneração como fator de custo em investimento", "favorece a negociação direta e informal entre superior e funcionário", "se caracteriza como alternativa que não demanda diagnóstico prévio do contexto futuro"], "corretaIndex": 2, "regra": "A remuneração estratégica busca alinhar a remuneração aos objetivos organizacionais, transformando-a de mero custo em investimento estratégico em pessoas.", "fonte": "Cesgranrio — EPE — Analista de Gestão Corporativa (RH) — 2010", "fonteUrl": "https://www.qconcursos.com/questoes-de-concursos/questoes/084f104c-d5", "valido": true}, {"id": 67, "materia": "Administração de RH / Processos Administrativos", "assunto": "Cargos e Salários", "enunciado": "A Política Salarial de uma organização deve conter diretrizes que suportarão seus gestores, por meio dos modelos disponíveis da estrutura salarial, na tomada de decisões sobre práticas, implementação e manutenção do sistema de remuneração. O principal objetivo dessa política é ser clara quanto à postura da empresa em relação ao mercado de trabalho, definindo, entre outros aspectos,", "alternativas": ["a faixa salarial de mercado em que a empresa pretende se posicionar", "as metas de desempenho individuais e a participação nos lucros", "os fatores que facilitarão exclusivamente a avaliação de cargos", "os objetivos de lucratividade global da empresa", "os prêmios, gratificações e formas especiais de reconhecimento"], "corretaIndex": 0, "regra": "A política salarial define, entre outros pontos, o posicionamento da empresa frente ao mercado de trabalho (acima, na média ou abaixo do mercado).", "fonte": "Cesgranrio — BACEN — Analista do Banco Central (Área 6) — 2010", "fonteUrl": "https://www.qconcursos.com/questoes-de-concursos/questoes/66a767d0-12", "valido": true}, {"id": 68, "materia": "Administração de RH / Processos Administrativos", "assunto": "Cargos e Salários / Turnover", "enunciado": "Uma empresa está preocupada com a alta rotatividade de funcionários que tem ocorrido ao longo dos últimos três anos. Para diminuir o efeito da falta de uma política de Recursos Humanos que possibilite a manutenção de seu quadro de empregados, a empresa pensou em elaborar um plano de cargos e salários. O plano de cargos e salários é importante porque comunica aos empregados a trilha a ser percorrida para se desenvolverem na carreira.", "alternativas": ["permite que a empresa estabeleça os salários vinculados apenas ao tempo de permanência na empresa", "permite que a empresa direcione, de forma unilateral, cada empregado para a carreira que considera necessária", "é um instrumento de gestão que tem como único objetivo motivar financeiramente os empregados", "comunica aos empregados a trilha a ser percorrida para se desenvolverem profissionalmente na carreira", "demonstra publicamente os salários de todos, eliminando qualquer conflito de diferenças salariais"], "corretaIndex": 3, "regra": "Um plano de cargos e salários bem estruturado funciona como instrumento de comunicação da trajetória de desenvolvimento de carreira, ajudando a reter talentos e reduzir turnover.", "fonte": "Cesgranrio — Transpetro — Administrador Júnior — 2018", "fonteUrl": "https://www.qconcursos.com/questoes-de-concursos/questoes/cd5a2f12-43", "valido": true}, {"id": 69, "materia": "Administração de RH / Processos Administrativos", "assunto": "Turnover e Absenteísmo", "enunciado": "As atividades de controle empresarial fazem parte dos fundamentos da administração. Toda a atividade administrativa pode ser controlada por indicadores da empresa, e o diretor do banco Z solicitou que os gerentes apresentassem um relatório a respeito da rotatividade e do absenteísmo. Nesse caso, os indicadores de desempenho solicitados pelo diretor do banco Z estão relacionados à área ou à função organizacional denominada", "alternativas": ["finanças", "marketing", "produção", "recursos humanos", "vendas"], "corretaIndex": 3, "regra": "Rotatividade (turnover) e absenteísmo são indicadores clássicos de desempenho da área/função de Recursos Humanos.", "fonte": "Cesgranrio — BNDES — Analista (Administração) — 2024", "fonteUrl": "https://www.qconcursos.com/questoes-de-concursos/questoes/b2b5b0f2-8a", "valido": true}, {"id": 70, "materia": "Administração de RH / Processos Administrativos", "assunto": "Turnover e Absenteísmo", "enunciado": "Um dos aspectos importantes na dinâmica organizacional é a rotatividade de recursos humanos. Sobre o tema, observe as assertivas: I – Pesquisas mostram uma relação negativa consistente entre a satisfação com o trabalho e o absenteísmo; quanto mais satisfeitos os empregados, menor é a rotatividade. II – É desejável que todas as organizações apresentem índice de rotatividade equivalente a zero, pois reflete boa retenção de talentos. III – Quando os funcionários possuem elevado 'capital humano' (mais educação e qualificação), a probabilidade de a insatisfação se traduzir em rotatividade é mais baixa. Está correto o que se afirma em", "alternativas": ["I, apenas", "II, apenas", "I e III, apenas", "II e III, apenas", "I, II e III"], "corretaIndex": 2, "regra": "A afirmativa II é falsa: rotatividade zero não é necessariamente desejável (pode indicar estagnação/acomodação); as afirmativas I e III são consistentes com a literatura sobre satisfação, capital humano e rotatividade.", "fonte": "Cesgranrio — IBGE — Analista (RH — Desenvolvimento de Pessoas) — 2013", "fonteUrl": "https://www.qconcursos.com/questoes-de-concursos/questoes/91144584-34", "valido": true}, {"id": 71, "materia": "Administração de RH / Processos Administrativos", "assunto": "Gestão por Competências", "enunciado": "Uma secretaria de fazenda está mapeando suas competências essenciais, de forma a desenvolver profissionalização a partir de ações voltadas ao aprendizado coletivo na organização, à coordenação das diversas habilidades de produção-serviço e à integração das múltiplas correntes de tecnologias. Considerando-se que as competências essenciais dependem de conhecimentos, habilidades e atitudes, o conhecimento necessário à profissionalização é o de", "alternativas": ["administrar os recursos públicos com probidade e ética", "comunicar-se efetivamente com o grupo de trabalho e os contribuintes", "perseguir a qualidade e a produtividade das ações do setor de arrecadação", "saber motivar a equipe visando a extrair desempenho superior na arrecadação", "ter maestria sobre técnicas e métodos quantitativos utilizados na interpretação do comportamento das despesas"], "corretaIndex": 4, "regra": "Entre as opções, apenas o domínio de técnicas e métodos quantitativos caracteriza-se estritamente como 'conhecimento' técnico (know-what), diferenciando-se das demais que são atitudes/habilidades.", "fonte": "Cesgranrio — IPEA — Técnico de Planejamento e Pesquisa — 2024", "fonteUrl": "https://www.qconcursos.com/questoes-de-concursos/questoes/ddc68ebb-d5", "valido": true}, {"id": 72, "materia": "Administração de RH / Processos Administrativos", "assunto": "Gestão por Competências", "enunciado": "Segundo a avaliação do diretor de um banco, seus subordinados apresentam o conjunto de conhecimentos, habilidades e atitudes que agregam valor à organização. O componente do capital intelectual de uma organização que trata dos conhecimentos e competências dos colaboradores disponíveis à organização é denominado capital", "alternativas": ["basilar", "humano", "estrutural", "essencial", "relacional"], "corretaIndex": 1, "regra": "O capital humano é o componente do capital intelectual formado pelos conhecimentos, habilidades e competências dos colaboradores.", "fonte": "Cesgranrio — Banco do Brasil — Agente Comercial (Prova C) — 2023", "fonteUrl": "https://www.qconcursos.com/questoes-de-concursos/questoes/2a2b5992-25", "valido": true}, {"id": 73, "materia": "Administração de RH / Processos Administrativos", "assunto": "Gestão por Competências", "enunciado": "Uma fábrica de engrenagens produz mais de 6 mil peças por dia e vende seus produtos nos mercados interno e externo. O gerente de Recursos Humanos decidiu adotar o sistema de remuneração baseado em habilidades. No caso dessa empresa, isso significa que os salários aumentam à medida que os funcionários aprendem a operar os vários equipamentos necessários para produzir engrenagens mais complexas.", "alternativas": ["a remuneração dos funcionários pode variar de acordo com o desempenho do departamento, independentemente do resultado da empresa", "a remuneração de todos os funcionários depende do percentual de participação da empresa no mercado e da relação funcionários/lucros", "os funcionários mais antigos são sempre promovidos quando há novas contratações, recebendo salários mais altos", "os lucros da empresa são divididos ao final do período entre todos os funcionários proporcionalmente ao tempo de casa", "os salários aumentam à medida que os funcionários aprendem a operar os vários equipamentos necessários para tarefas mais complexas"], "corretaIndex": 4, "regra": "Remuneração baseada em habilidades (skill-based pay) vincula o aumento salarial à aquisição de novas habilidades/competências pelo funcionário, e não ao cargo ocupado.", "fonte": "Cesgranrio — UNIRIO — Assistente em Administração — 2019", "fonteUrl": "https://www.qconcursos.com/questoes-de-concursos/questoes/6a194592-1c", "valido": true}, {"id": 74, "materia": "Administração de RH / Processos Administrativos", "assunto": "Gestão por Competências", "enunciado": "Apesar da popularidade do conceito de competências e seus benefícios, uma funcionária tem alertado seu chefe sobre os desafios que precisam ser superados pela empresa para que o trabalho com competências seja eficaz. Ela aponta corretamente dois desafios: desenvolver padrões de avaliação e medição claros, objetivos e confiáveis; e ligar as descrições de competências às funções desempenhadas pelas pessoas nos cargos.", "alternativas": ["desenvolver boa comunicação para construir equipe confiante; ser estratégico e analítico na tomada de decisões", "investir no desenvolvimento da liderança e na inteligência emocional; impulsionar a responsabilidade sobre falhas", "incentivar pequenas vitórias na gestão de conflitos internos; ligar palavras e ações à linguagem do receptor", "desenvolver padrões de avaliação e medição claros, objetivos e confiáveis; ligar descrições de competências às funções dos cargos", "pensar em termos de flexibilidade cultural da equipe; utilizar a delegação como instrumento de gestão de competências"], "corretaIndex": 3, "regra": "Os principais desafios de um sistema de gestão por competências são a definição de critérios de medição objetivos/confiáveis e o vínculo claro entre competências e funções do cargo.", "fonte": "Cesgranrio — Transpetro — Técnico de Administração e Controle Júnior — 2018", "fonteUrl": "https://www.qconcursos.com/questoes-de-concursos/questoes/d1a12678-43", "valido": true}, {"id": 75, "materia": "Administração de RH / Processos Administrativos", "assunto": "Gestão por Competências", "enunciado": "No cenário econômico atual, as organizações precisam ter diferenciais em relação aos seus concorrentes. Para que os diferenciais competitivos sejam desenvolvidos, as organizações procuram desenvolver suas competências essenciais. As competências essenciais constituem-se no conjunto de conhecimentos, habilidades, tecnologias, sistemas físicos, gerenciais e valores que geram um diferencial competitivo para as organizações.", "alternativas": ["processo educacional de curto prazo, aplicado sistematicamente para que empregados executem atividades especializadas", "conjunto de conhecimentos, habilidades, tecnologias, sistemas físicos, gerenciais e valores que geram diferencial competitivo", "novo modelo de seleção de pessoal visando identificar os melhores profissionais do mercado no setor de atuação", "intensificação da eficiência administrativa, estabelecendo princípios e funções para padronização de procedimentos", "formação de talentos ocupada da especialização técnica sem considerar aspectos psicossociais"], "corretaIndex": 1, "regra": "Competências essenciais (core competencies) são o conjunto integrado de conhecimentos, habilidades e recursos organizacionais que geram vantagem competitiva sustentável.", "fonte": "Cesgranrio — Petrobras — Profissional Júnior (Administração) — 2015", "fonteUrl": "https://www.qconcursos.com/questoes-de-concursos/questoes/4f579d66-ca", "valido": true}, {"id": 76, "materia": "Administração de RH / Processos Administrativos", "assunto": "Gestão por Competências", "enunciado": "O alcance de melhores desempenhos pelas organizações depende de um adequado mapeamento de competências, que envolve as dimensões técnicas e de suporte. Na realização do mapeamento de competências, uma competência técnica pode ser exemplificada pelo domínio de planilhas.", "alternativas": ["adaptação e flexibilidade", "capacidade empreendedora", "criatividade e inovação", "domínio de planilhas", "visão sistêmica"], "corretaIndex": 3, "regra": "Competências técnicas (hard skills) referem-se ao domínio de ferramentas e conhecimentos técnicos específicos, como o uso de planilhas; as demais opções são competências comportamentais (soft skills).", "fonte": "Cesgranrio — Petrobras — Técnico de Administração e Controle Júnior — 2014", "fonteUrl": "https://www.qconcursos.com/questoes-de-concursos/questoes/9f559392-80", "valido": true}, {"id": 77, "materia": "Administração de RH / Processos Administrativos", "assunto": "Gestão por Competências", "enunciado": "Sobre a distinção entre qualificação e competência, tem-se que a competência é um saber agir responsável e reconhecido, que implica mobilizar, integrar e transferir conhecimentos, recursos e habilidades que agreguem valor econômico à organização.", "alternativas": ["a qualificação é um processo que frequentemente se insere num sistema formal de escolarização, preparando indivíduos para o mercado de trabalho", "a qualificação envolve o conhecimento dos fatos, é adquirida pela educação formal e inclui regras, procedimentos e habilidades de comunicação", "a competência é a percepção do que o indivíduo acredita estar certo, um filtro consciente e inconsciente adquirido pela reflexão sobre erros e sucessos passados", "a competência é determinada para uma situação específica de posto de trabalho, e cargos bem desenhados buscam eliminar a imprevisibilidade", "a competência é um saber agir responsável e reconhecido, que implica mobilizar, integrar e transferir conhecimentos, recursos e habilidades que agreguem valor econômico à organização"], "corretaIndex": 4, "regra": "A definição consagrada de competência (Fleury & Fleury/Le Boterf) é o saber agir responsável, mobilizando recursos para agregar valor econômico à organização e valor social ao indivíduo.", "fonte": "Cesgranrio — IBGE — Supervisor de Pesquisas (Administração) — 2014", "fonteUrl": "https://www.qconcursos.com/questoes-de-concursos/questoes/c0c00417-d3", "valido": true}, {"id": 78, "materia": "Administração de RH / Processos Administrativos", "assunto": "Gestão por Competências", "enunciado": "A definição de Competência está baseada em três dimensões chamadas de CHA, letras que têm, respectivamente, a seguinte correspondência:", "alternativas": ["conhecimento, habilidade e atitude", "conhecimento, hábito de segurança e apresentação pessoal", "criatividade, habilidade e atitude", "criatividade, hábito de segurança e apresentação pessoal", "criatividade, hábito de segurança e atitude"], "corretaIndex": 0, "regra": "CHA é o acrônimo clássico de competência: Conhecimento (saber), Habilidade (saber fazer) e Atitude (querer fazer).", "fonte": "Cesgranrio — Petrobras — Técnico de Administração e Controle Júnior — 2011", "fonteUrl": "https://www.qconcursos.com/questoes-de-concursos/questoes/88f69eb3-3f", "valido": true}, {"id": 79, "materia": "Administração de RH / Processos Administrativos", "assunto": "Eficiência e Eficácia", "enunciado": "Uma importante utilização da análise das variações orçamentárias é na avaliação de desempenho. Os dois atributos do desempenho mais comumente mensurados são", "alternativas": ["assertividade e acurácia", "efetividade e eficiência", "efetividade e eficácia", "eficácia e eficiência", "objetivos e a reprojeção"], "corretaIndex": 3, "regra": "Na avaliação de desempenho orçamentário, os dois atributos clássicos mensurados são eficácia (atingimento de metas) e eficiência (uso racional de recursos).", "fonte": "Cesgranrio — Transpetro — Profissional Júnior de Nível Superior — 2023", "fonteUrl": "https://www.qconcursos.com/questoes-de-concursos/questoes/1c375ad1-a4", "valido": true}, {"id": 80, "materia": "Administração de RH / Processos Administrativos", "assunto": "Eficiência e Eficácia", "enunciado": "No setor comercial de uma grande empresa de moda, houve encomenda maior do que o esperado. A direção informou que teriam de atingir a meta de produzir mais 20% de peças nos próximos 30 dias. O atingimento dessa meta está relacionado ao conceito de", "alternativas": ["eficácia, apenas", "eficiência, apenas", "efetividade, apenas", "produtividade, apenas", "eficácia e eficiência"], "corretaIndex": 0, "regra": "Eficácia refere-se ao atingimento de metas e objetivos estabelecidos, independentemente dos meios/recursos empregados.", "fonte": "Cesgranrio — UNIRIO — Assistente em Administração — 2019", "fonteUrl": "https://www.qconcursos.com/questoes-de-concursos/questoes/6a28ffaf-1c", "valido": true}, {"id": 81, "materia": "Administração de RH / Processos Administrativos", "assunto": "Eficiência e Eficácia", "enunciado": "As abordagens contingenciais para medir a eficácia organizacional enfocam diferentes partes da organização. Para avaliar tal eficácia, um supervisor deve optar por uma abordagem de metas, avaliando o desempenho da organização quanto à lucratividade e ao crescimento.", "alternativas": ["metas, avaliando desempenho quanto à lucratividade e ao crescimento", "recursos do sistema, identificando metas de saída da organização", "processo interno, utilizando indicadores de eficácia das habilidades", "cultura organizacional, utilizando análise da missão, visão e estratégia", "ambiente externo e tecnologia gerencial"], "corretaIndex": 0, "regra": "A abordagem de metas mede a eficácia organizacional pelo grau de alcance de objetivos como lucratividade e crescimento, um dos modelos contingenciais clássicos de eficácia.", "fonte": "Cesgranrio — LIQUIGÁS — Profissional Júnior (Administração) — 2018", "fonteUrl": "https://www.qconcursos.com/questoes-de-concursos/questoes/c1364510-62", "valido": true}, {"id": 82, "materia": "Administração de RH / Processos Administrativos", "assunto": "Eficiência e Eficácia", "enunciado": "Para um gestor público, diante de um contexto de garantia de acesso à informação, é relevante diferenciar métricas de eficiência de métricas de eficácia da Tecnologia da Informação. Entre as opções, a que constitui métrica de eficácia é a usabilidade mensurada pelo número de cliques.", "alternativas": ["os custos envolvidos no consumo de recursos computacionais", "o tempo de resposta medido pelos minutos exigidos para uma operação", "a velocidade de transação medida pelo tempo de processamento", "a usabilidade mensurada pelo número de cliques necessários", "a taxa de rendimento monitorada pela quantidade de informação processada"], "corretaIndex": 3, "regra": "Métricas de eficácia avaliam se o objetivo (facilidade de uso pelo usuário) foi atingido, enquanto métricas de eficiência avaliam consumo de recursos e tempo — usabilidade (satisfação do usuário) é métrica de eficácia.", "fonte": "Cesgranrio — IBGE — Supervisor de Pesquisas (Gestão) — 2016", "fonteUrl": "https://www.qconcursos.com/questoes-de-concursos/questoes/964e47b0-7a", "valido": true}, {"id": 83, "materia": "Administração de RH / Processos Administrativos", "assunto": "Eficiência e Eficácia", "enunciado": "A administração é uma ciência relativamente nova. Embora tenha se mostrado cada vez mais importante no ambiente organizacional, visando à eficácia e à eficiência, ainda existem muitas dúvidas em relação ao seu papel. De maneira geral, o papel do administrador no ambiente organizacional é trabalhar com pessoas para alcançar eficientemente os objetivos organizacionais.", "alternativas": ["ser um facilitador, colaborando para as decisões de forma independente da equipe", "examinar cuidadosamente as atividades realizadas pela organização", "fiscalizar rigidamente os processos internos da organização", "analisar exclusivamente as demonstrações financeiras da empresa", "trabalhar com e por meio de pessoas para alcançar eficientemente os objetivos organizacionais"], "corretaIndex": 4, "regra": "O papel do administrador, na definição clássica, é alcançar os objetivos organizacionais eficientemente, trabalhando com e através de pessoas.", "fonte": "Cesgranrio — CEFET-RJ — Assistente em Administração — 2014", "fonteUrl": "https://www.qconcursos.com/questoes-de-concursos/questoes/7924331a-fb", "valido": true}, {"id": 84, "materia": "Administração de RH / Processos Administrativos", "assunto": "Eficiência e Eficácia", "enunciado": "Das características que Antônio, funcionário de carreira do TJ, apresenta em seu trabalho, a que NÃO representa o conceito de eficiência é ser proativo.", "alternativas": ["fazer as coisas de maneira adequada", "ser proativo", "ser cumpridor de seus deveres", "maximizar a utilização dos recursos disponíveis", "ter como máxima a redução de custos"], "corretaIndex": 1, "regra": "Eficiência relaciona-se a fazer bem as coisas, otimizar recursos e reduzir custos (meios); proatividade é uma característica comportamental, não um atributo definidor de eficiência.", "fonte": "Cesgranrio — TJ-RO — Agente Judiciário (Administração) — 2008", "fonteUrl": "https://www.qconcursos.com/questoes-de-concursos/questoes/aae637de-d5", "valido": true}, {"id": 85, "materia": "Administração de RH / Processos Administrativos", "assunto": "Eficiência e Eficácia", "enunciado": "Samira observou a atuação da empresa Pesque-Pague quanto à utilização de seus recursos disponíveis, verificando a correta utilização visando à aplicação racional. Há preocupação da empresa quanto aos meios e métodos utilizados. A empresa demonstrou agir com", "alternativas": ["eficiência", "eficácia", "competitividade", "produtividade", "especialização"], "corretaIndex": 0, "regra": "Preocupação com os meios, métodos e aplicação racional dos recursos disponíveis caracteriza a eficiência (fazer certo).", "fonte": "Cesgranrio — IBGE — Agente Censitário — 2006", "fonteUrl": "https://www.qconcursos.com/questoes-de-concursos/questoes/0ac8d00e-33", "valido": true}, {"id": 86, "materia": "Administração de RH / Processos Administrativos", "assunto": "Eficiência e Eficácia", "enunciado": "Buscando aumento da eficiência e diminuição de custos, muitas organizações estão optando pelo enxugamento de suas operações. Como consequência, são dispensados empregados em todos os níveis e é contratada mão de obra terceirizada. Essa escolha estratégica é denominada", "alternativas": ["isomorfismo", "toyotismo", "just in time", "downsizing", "outplacement"], "corretaIndex": 3, "regra": "Downsizing é a estratégia de enxugamento organizacional, com redução de níveis hierárquicos e de pessoal, buscando maior eficiência e menor custo.", "fonte": "Cesgranrio — EPE — Analista de Gestão Corporativa (Administração Geral) — 2014", "fonteUrl": "https://www.qconcursos.com/questoes-de-concursos/questoes/56f1dded-10", "valido": true}, {"id": 87, "materia": "Gestão de Sistemas Integrados", "assunto": "Benchmarking", "enunciado": "Com relação aos tipos de benchmarking, pode-se afirmar que", "alternativas": ["benchmarking competitivo é uma comparação entre organizações externas que não concorrem num mesmo mercado.", "benchmarking interno ocorre entre operações que fazem parte de uma mesma organização.", "benchmarking não competitivo é o mesmo que benchmarking interno.", "benchmarking não competitivo é uma comparação entre concorrentes de um mesmo mercado.", "seus indicadores de desempenho estão restritos às funções-objetivo."], "corretaIndex": 1, "regra": "Benchmarking interno compara operações/unidades de uma mesma organização (ex.: filiais, departamentos), diferente do benchmarking competitivo (concorrentes diretos) ou funcional/genérico (outros setores).", "fonte": "CESGRANRIO - Petrobras - Engenheiro de Produção Júnior - 2008", "fonteUrl": "https://www.qconcursos.com/questoes-de-concursos/questoes/6d81c390-84", "valido": true}, {"id": 88, "materia": "Gestão de Sistemas Integrados", "assunto": "Auditoria - ISO 19011", "enunciado": "Um dos requisitos da ABNT NBR ISO 19011:2018 — Diretrizes para auditoria de sistemas de gestão — é a seleção do método apropriado de avaliação do auditor. O método de avaliação Análise Crítica de Registros tem por objetivo", "alternativas": ["Verificar a formação profissional do auditor.", "Fornecer informação sobre como o desempenho do auditor é percebido.", "Avaliar o comportamento, o conhecimento e as habilidades do auditor.", "Fornecer informações sobre o desempenho do auditor durante as atividades de auditoria e identificar forças e oportunidades.", "Avaliar o comportamento profissional e a habilidade de comunicação do auditor para verificar a informação, testar o conhecimento e adquirir informação adicional."], "corretaIndex": 0, "regra": "Na ISO 19011, a Análise Crítica de Registros verifica documentos/registros formais (certificados, currículos, treinamentos) para confirmar a qualificação e formação do auditor.", "fonte": "CESGRANRIO - Transpetro - Profissional Nível Superior Júnior, Ênfase 20 Engenharia de Segurança - 2023", "fonteUrl": "https://arquivos.qconcursos.com/prova/arquivo_prova/101235/cesgranrio-2023-transpetro-profissional-transpetro-de-nivel-superior-junior-enfase-20-engenharia-de-seguranca-prova.pdf", "valido": true}, {"id": 89, "materia": "Gestão de Sistemas Integrados", "assunto": "ISO 31000", "enunciado": "Segundo a NBR ISO 31000:2009 (Gestão de Riscos – Princípios e Diretrizes), constata-se que gestão de risco é(são)", "alternativas": ["a identificação dos perigos, a avaliação e o controle das perdas humanas, materiais e ambientais.", "o controle do prejuízo sofrido por uma organização, com garantia de ressarcimento por seguro.", "um processo que garante que situações causadoras de danos nunca ocorrerão.", "atividades coordenadas para dirigir e controlar uma organização no que se refere a riscos.", "atividades que devem ser implementadas para eliminar e transferir os perigos ou reduzi-los a níveis os mais baixos possíveis."], "corretaIndex": 3, "regra": "A ISO 31000 define gestão de riscos exatamente como 'atividades coordenadas para dirigir e controlar uma organização no que se refere a riscos' — é a definição literal da norma.", "fonte": "CESGRANRIO - Transpetro - Engenheiro Júnior Segurança - 2012", "fonteUrl": "https://www.qconcursos.com/questoes-de-concursos/questoes/464944d2-55", "valido": true}, {"id": 90, "materia": "Gestão de Sistemas Integrados", "assunto": "Benchmarking - etapas", "enunciado": "Benchmarking pode ser definido como uma técnica que consiste em fazer comparações e procurar imitar as organizações, concorrentes ou não, do mesmo ramo de negócios ou de outros, que tenham práticas exemplares de administração. Associe as etapas do benchmarking (I-Planejamento, II-Análise, III-Integração, IV-Ação) às características: P-Implementação dos resultados; Q-Definição das melhores práticas a serem copiadas; R-Coleta, estudo e interpretação dos dados; S-Aprimoramento contínuo; T-Definição de modificações no produto/processo.", "alternativas": ["I-Q, II-T, III-P, IV-S", "I-Q, II-R, III-T, IV-P", "I-S, II-T, III-Q, IV-P", "I-S, II-P, III-T, IV-R", "I-T, II-R, III-P, IV-Q"], "corretaIndex": 1, "regra": "No processo clássico de benchmarking (Planejamento→Análise→Integração→Ação), o Planejamento define o que copiar (Q), a Análise coleta e interpreta dados (R), a Integração define mudanças a implementar (T) e a Ação implementa os resultados (P).", "fonte": "CESGRANRIO - IBGE - Analista, Recursos Materiais e Logística - 2013", "fonteUrl": "https://www.qconcursos.com/questoes-de-concursos/questoes/95c9e77b-35", "valido": true}, {"id": 91, "materia": "Gestão de Sistemas Integrados", "assunto": "Benchmarking - finalidade", "enunciado": "O benchmarking é o processo de aprender com os outros e envolve a comparação do seu próprio desempenho ou método com o de outras operações comparáveis. As empresas usam o benchmarking para", "alternativas": ["compreender melhor como empresas líderes atuam de maneira a aperfeiçoar seus próprios processos.", "copiar ou imitar operações bem-sucedidas de outras organizações.", "promover projetos isolados de melhoria de processos.", "comparar processos semelhantes de empresas similares do mesmo setor industrial.", "fazer espionagem industrial em grandes empresas."], "corretaIndex": 0, "regra": "Benchmarking não é cópia nem espionagem: é aprendizado sistemático com práticas superiores (de qualquer setor) para melhoria contínua dos próprios processos.", "fonte": "CESGRANRIO - Petrobras - Engenheiro de Produção Júnior - 2011", "fonteUrl": "https://www.qconcursos.com/questoes-de-concursos/questoes/5f85b618-47", "valido": true}, {"id": 92, "materia": "Gestão de Sistemas Integrados", "assunto": "Diagrama de Ishikawa", "enunciado": "O Diagrama de Ishikawa, também conhecido como Diagrama de Causa e Efeito ou Espinha de Peixe, permite estruturar hierarquicamente as causas de determinado problema ou oportunidade de melhoria. As causas de um problema podem ser agrupadas, a partir do conceito dos 6M, como decorrentes de falhas em materiais, em mão de obra, em máquinas, em meio ambiente, em _____ e em _____.", "alternativas": ["treinamento e em tecnologias", "métodos e em medidas", "métodos e em tecnologias", "estratégias e em tecnologias", "estratégias e em medidas"], "corretaIndex": 1, "regra": "Os 6M do diagrama de Ishikawa são: Método, Mão de obra, Material, Máquina, Meio ambiente e Medida.", "fonte": "CESGRANRIO - Petrobras - Técnico de Suprimentos de Bens e Serviços Júnior, Administração - 2011", "fonteUrl": "https://www.qconcursos.com/questoes-de-concursos/questoes/134543a9-8a", "valido": true}, {"id": 93, "materia": "Gestão de Sistemas Integrados", "assunto": "Auditoria - processo/fases", "enunciado": "O processo de auditorias realizado em empresas é dividido em três fases básicas denominadas atividades de pré-auditoria, atividades de campo e atividades de pós-auditoria. O primeiro passo a ser executado para iniciar tal processo é", "alternativas": ["Descrição da amplitude e dos limites da auditoria, considerando as atividades a serem auditadas.", "Entrega de um relatório conclusivo, sua distribuição e a possível retenção de documentos.", "Coleta e posterior análise de dados que serão avaliados pela equipe auditora responsável.", "Listagem dos procedimentos para auditar elementos do Sistema de Gestão do auditado.", "Definição do conteúdo e do formato do relatório de auditoria e data prevista para sua emissão."], "corretaIndex": 0, "regra": "A pré-auditoria começa pela definição do escopo (amplitude e limites) da auditoria — etapa que precede planejamento detalhado, coleta de dados e emissão de relatório.", "fonte": "CESGRANRIO - Petrobras - Técnico Ambiental Júnior, Biocombustível - 2010", "fonteUrl": "https://www.qconcursos.com/questoes-de-concursos/questoes/3f322ba6-d8", "valido": true}, {"id": 94, "materia": "Gestão de Sistemas Integrados", "assunto": "Auditoria interna - testes de observância", "enunciado": "Os procedimentos da Auditoria Interna constituem exames e investigações, incluindo testes de observância e testes substantivos, que permitem ao auditor interno obter subsídios suficientes para fundamentar suas conclusões e recomendações à administração da entidade. Na aplicação dos testes de observância, devem ser considerados os seguintes procedimentos:", "alternativas": ["Exame, vistoria, indagação e certificação", "Exame, inspeção, vistoria e certificação", "Investigação, arbitramento, mensuração e avaliação", "Inspeção, observação, investigação e confirmação", "Observação, vistoria, indagação e confirmação"], "corretaIndex": 3, "regra": "Testes de observância (de controles internos) usam inspeção, observação, investigação (indagação) e confirmação para verificar se os controles funcionam como previsto.", "fonte": "CESGRANRIO - Transpetro - Contador Júnior, Auditoria Interna - 2011", "fonteUrl": "https://www.qconcursos.com/questoes-de-concursos/questoes/dbf767a8-ad", "valido": true}, {"id": 95, "materia": "Gestão de Sistemas Integrados", "assunto": "Kaizen / Melhoria contínua", "enunciado": "O comitê de planejamento estratégico se reuniu para escolher as ferramentas de previsão de condições futuras do ambiente externo. Dentre as ferramentas a seguir, a que NÃO deve ser utilizada é a(o)", "alternativas": ["análise de séries temporais", "previsão por julgamento", "construção de cenários", "Técnica Delphi", "Método Kaizen"], "corretaIndex": 4, "regra": "Kaizen é uma filosofia de melhoria contínua de processos internos, não uma ferramenta de previsão do ambiente externo (diferente de séries temporais, Delphi, cenários etc.).", "fonte": "CESGRANRIO - Petrobras - Administrador Júnior - 2010", "fonteUrl": "https://www.fonteconcursos.com.br/questoes-de-concurso/assunto/melhoria-continua-kaizen-/5496", "valido": true}, {"id": 96, "materia": "Gestão de Sistemas Integrados", "assunto": "Ferramentas da qualidade - FMEA", "enunciado": "Dentre as ferramentas da qualidade utilizadas no dia a dia das empresas, uma delas, em particular, é muito empregada na área de manutenção, com o objetivo de detalhar exaustivamente os tipos de falha de um produto ou processo, identificando suas causas e definindo ações de mitigação para os pares causa e efeito.", "alternativas": ["Diagrama de causa e efeito", "Gráfico de Pareto", "FMEA", "CEP", "Folha de verificação"], "corretaIndex": 2, "regra": "FMEA (Failure Mode and Effect Analysis) é a ferramenta específica para detalhar modos de falha, seus efeitos e causas, muito usada em manutenção e confiabilidade.", "fonte": "CESGRANRIO - Petrobras/BR Distribuidora - Profissional Júnior, Administração - 2012", "fonteUrl": "https://www.qconcursos.com/questoes-de-concursos/questoes/518aeca0-9b", "valido": true}, {"id": 97, "materia": "Gestão de Sistemas Integrados", "assunto": "Diagrama de Ishikawa", "enunciado": "O seguinte diagrama é uma das ferramentas utilizadas na gestão da manutenção para identificar as causas raízes dos problemas nos equipamentos: [figura em formato de espinha de peixe]", "alternativas": ["Sankey", "Pareto", "Gantt", "Venn", "Ishikawa"], "corretaIndex": 4, "regra": "O diagrama em formato de espinha de peixe usado para identificar causas-raiz de problemas é o Diagrama de Ishikawa (Causa e Efeito).", "fonte": "CESGRANRIO - Transpetro - Profissional Nível Superior Júnior, Ênfase 19 Engenharia de Produção - 2023", "fonteUrl": "https://arquivos.qconcursos.com/prova/arquivo_prova/101234/cesgranrio-2023-transpetro-profissional-transpetro-de-nivel-superior-junior-enfase-19-engenharia-de-producao-prova.pdf", "valido": true}, {"id": 98, "materia": "Gestão de Sistemas Integrados", "assunto": "PDCA", "enunciado": "São atribuídas aos autores Shewart e Deming as seguintes ferramentas de controle da qualidade:", "alternativas": ["Análises de Pareto", "Arranjos físicos de qualidade", "Causas-raiz dos problemas da qualidade", "Ciclos PDCA", "Poka Yoke"], "corretaIndex": 3, "regra": "O Ciclo PDCA (Plan-Do-Check-Act) foi originalmente formulado por Walter Shewhart e popularizado/aplicado por William Edwards Deming como método de controle e melhoria da qualidade.", "fonte": "CESGRANRIO - Transpetro - Profissional Nível Superior Júnior, Ênfase 19 Engenharia de Produção - 2023", "fonteUrl": "https://arquivos.qconcursos.com/prova/arquivo_prova/101234/cesgranrio-2023-transpetro-profissional-transpetro-de-nivel-superior-junior-enfase-19-engenharia-de-producao-prova.pdf", "valido": true}, {"id": 99, "materia": "Gestão de Sistemas Integrados", "assunto": "Melhoria contínua - Seis Sigma / DMAIC", "enunciado": "O planejamento e o controle de qualidade com o método Seis Sigma utiliza uma ampla gama de métodos e de ferramentas extraídos da gestão da qualidade e dos sistemas de produção enxuta (Lean). O Seis Sigma, porém, tem um método próprio de estruturar o planejamento, cuja sigla é", "alternativas": ["GEMBA", "DMAIC", "SIPOC", "PDCA", "VSM"], "corretaIndex": 1, "regra": "DMAIC (Define, Measure, Analyze, Improve, Control) é o método estruturado próprio do Seis Sigma para condução de projetos de melhoria.", "fonte": "CESGRANRIO - Transpetro - Profissional Nível Superior Júnior, Ênfase 19 Engenharia de Produção - 2023", "fonteUrl": "https://arquivos.qconcursos.com/prova/arquivo_prova/101234/cesgranrio-2023-transpetro-profissional-transpetro-de-nivel-superior-junior-enfase-19-engenharia-de-producao-prova.pdf", "valido": true}, {"id": 100, "materia": "Gestão de Sistemas Integrados", "assunto": "Sistema de Gestão Ambiental (correlato a SGI)", "enunciado": "As diretrizes gerais para a implementação de um Sistema de Gestão Ambiental (SGA) são tratadas na norma ABNT NBR ISO 14.004:2018. Considerando-se o conteúdo dessa norma, verifica-se que", "alternativas": ["um SGA não tem a recomendação de ser visto como uma estrutura de organização, embora proveja um direcionamento eficaz.", "uma organização não retém a autoridade, mas sim a responsabilidade por prestar contas do sistema de gestão ambiental.", "uma análise crítica do SGA deve ser conduzida por uma auditoria externa, em intervalos regulares, sem participação ou intervenção da alta direção da organização durante o processo.", "o SGA deve ser gerenciado de forma isolada e separadamente da estratégia principal do negócio da organização.", "as mudanças no meio ambiente, adversas ou benéficas, que resultam total ou parcialmente de aspectos ambientais, são chamadas de impactos ambientais."], "corretaIndex": 4, "regra": "Essa é a definição literal de 'impacto ambiental' na ISO 14001/14004: mudança no meio ambiente, adversa ou benéfica, resultante de aspectos ambientais da organização.", "fonte": "CESGRANRIO - Transpetro - Profissional Nível Superior Júnior, Ênfase 3 Análise Ambiental - 2023", "fonteUrl": "https://arquivos.qconcursos.com/prova/arquivo_prova/101217/cesgranrio-2023-transpetro-profissional-transpetro-de-nivel-superior-junior-enfase-3-analise-ambiental-prova.pdf", "valido": true}, {"id": 101, "materia": "Gestão de Sistemas Integrados", "assunto": "Sistema de Gestão SSO (correlato a SGI / Anexo SL)", "enunciado": "A norma ISO 45.001:2018 trata do Sistema de Gestão de Saúde e Segurança Ocupacional. Para os efeitos dessa norma, a combinação da probabilidade de ocorrência de eventos ou de exposições perigosas relacionados aos trabalhos e da gravidade das lesões e dos problemas de saúde que podem ser causados por um evento ou uma exposição é definida como", "alternativas": ["não conformidade", "efeito de incerteza", "oportunidade de saúde e segurança ocupacional (SSO)", "desempenho de saúde e segurança ocupacional (SSO)", "risco de saúde e segurança ocupacional (SSO)"], "corretaIndex": 4, "regra": "A ISO 45001 define 'risco de SSO' exatamente como a combinação da probabilidade de ocorrência de um evento perigoso com a gravidade das lesões/problemas de saúde decorrentes.", "fonte": "CESGRANRIO - Transpetro - Profissional Nível Superior Júnior, Ênfase 3 Análise Ambiental - 2023", "fonteUrl": "https://arquivos.qconcursos.com/prova/arquivo_prova/101217/cesgranrio-2023-transpetro-profissional-transpetro-de-nivel-superior-junior-enfase-3-analise-ambiental-prova.pdf", "valido": true}, {"id": 102, "materia": "Gestão de Sistemas Integrados", "assunto": "ISO 31000 - estrutura de gestão de riscos", "enunciado": "O propósito da estrutura de gestão de riscos é apoiar a organização na integração da gestão de riscos em atividades significativas e em suas funções. O desenvolvimento da estrutura da gestão de riscos engloba os seguintes componentes:", "alternativas": ["a reunião de metas, a concepção, a avaliação e o feedback", "a implementação, a concepção, o estudo de probabilidades e a melhoria", "a avaliação, o feedback, a melhoria, o estudo e as probabilidades", "a integração, a concepção, a implementação, a avaliação e a melhoria", "a integração, as probabilidades, a reunião de metas, a avaliação e o feedback"], "corretaIndex": 3, "regra": "Na ISO 31000, a estrutura (framework) de gestão de riscos é composta pelos componentes: Liderança e comprometimento, Integração, Concepção (design), Implementação, Avaliação e Melhoria.", "fonte": "CESGRANRIO - Transpetro - Profissional Nível Superior Júnior, Ênfase 3 Análise Ambiental - 2023", "fonteUrl": "https://arquivos.qconcursos.com/prova/arquivo_prova/101217/cesgranrio-2023-transpetro-profissional-transpetro-de-nivel-superior-junior-enfase-3-analise-ambiental-prova.pdf", "valido": true}, {"id": 103, "materia": "Gestão de Sistemas Integrados", "assunto": "MASP (Método de Análise e Solução de Problemas)", "enunciado": "O MASP (Método de Análise e Solução de Problemas) é uma das ferramentas de qualidade utilizadas em ambientes corporativos. A utilização dessa ferramenta deve ser feita em etapas, realizadas, obrigatoriamente, na seguinte ordem:", "alternativas": ["mensurar o impacto do erro, analisar alternativas, selecionar a solução adequada ao problema, propor melhorias", "identificar o problema, plano de ação, verificação, feedback", "identificar o problema, observação, análise, plano de ação, ação, verificação, padronização, conclusão", "identificar o problema, observação, ação, verificação, padronização, conclusão, arquivamento, feedback", "planejar, fazer, checar, feedback"], "corretaIndex": 2, "regra": "O MASP segue as 8 etapas clássicas ligadas ao PDCA: identificação do problema, observação, análise, plano de ação, ação, verificação, padronização e conclusão.", "fonte": "CESGRANRIO - Petrobras - Técnico de Suprimento de Bens e Serviços Júnior, Administração - 2018", "fonteUrl": "https://arquivos.qconcursos.com/prova/arquivo_prova/56798/cesgranrio-2018-petrobras-tecnico-de-suprimento-de-bens-e-servicos-junior-administracao-prova.pdf", "valido": true}, {"id": 104, "materia": "Gestão de Sistemas Integrados", "assunto": "Ferramentas da qualidade - Diagrama de dispersão", "enunciado": "Existe uma ferramenta de qualidade que demonstra o que acontece com uma variável quando a outra é alterada, sendo essa ferramenta uma representação de duas ou mais variáveis que podem ser organizadas em gráfico, uma em função da outra. Essa ferramenta é o", "alternativas": ["Fluxograma", "Diagrama de dispersão", "Diagrama de Ishikawa", "Diagrama de Pareto", "Controle estatístico do processo"], "corretaIndex": 1, "regra": "O Diagrama de Dispersão (uma das 7 ferramentas da qualidade) mostra a correlação entre duas variáveis, plotando uma em função da outra.", "fonte": "CESGRANRIO - Petrobras - Técnico de Suprimento de Bens e Serviços Júnior, Administração - 2018", "fonteUrl": "https://arquivos.qconcursos.com/prova/arquivo_prova/56798/cesgranrio-2018-petrobras-tecnico-de-suprimento-de-bens-e-servicos-junior-administracao-prova.pdf", "valido": true}, {"id": 105, "materia": "Controle Patrimonial", "assunto": "Manutenção preventiva - objetivo", "enunciado": "Qual o principal objetivo da manutenção preventiva nos equipamentos?", "alternativas": ["Melhorar a estrutura da empresa em termos materiais e humanos, visando ao desempenho operacional global.", "Realizar check-ups de equipamentos e máquinas com foco principal em registrar a substituição de peças com falha que causam a parada do equipamento.", "Evitar ou mitigar as consequências das falhas por meio da substituição planejada de componentes, preservando e restaurando a confiabilidade do equipamento.", "Examinar as máquinas para identificar possíveis falhas não corrigidas na manutenção preditiva.", "Examinar sinais emitidos pelas máquinas indicando necessidade de intervenção, que deve ser programada quando o equipamento não estiver em uso."], "corretaIndex": 2, "regra": "A manutenção preventiva é realizada em intervalos predeterminados, antes da falha ocorrer, com o objetivo de reduzir a probabilidade de falha e preservar a confiabilidade do equipamento.", "fonte": "CITEPE, Mecânico Têxtil Pleno, 2011", "fonteUrl": "https://www.qconcursos.com/questoes-de-concursos/questoes/195588", "valido": true}, {"id": 106, "materia": "Controle Patrimonial", "assunto": "Manutenção preventiva - exemplo prático", "enunciado": "É um exemplo de manutenção preventiva a troca:", "alternativas": ["de uma correia danificada, antes que ela se rompa.", "de óleo, executada dentro da periodicidade prevista no manual do fabricante do equipamento.", "de elementos de vedação ao identificar o início de vazamento, evitando maior dano ao sistema.", "programada de um rolamento cuja pista está danificada.", "antecipada de uma peça, fora do plano de manutenção, para garantir o funcionamento adequado da máquina."], "corretaIndex": 1, "regra": "Manutenção preventiva é aquela executada segundo um cronograma predeterminado (baseado em tempo/uso), como a troca de óleo dentro da periodicidade do manual do fabricante — e não em função de condição ou sinal de falha iminente.", "fonte": "Petrobras, Técnico(a) de Manutenção Júnior - Instrumentação, 2014", "fonteUrl": "https://www.qconcursos.com/questoes-de-concursos/questoes/460357", "valido": true}, {"id": 107, "materia": "Controle Patrimonial", "assunto": "Manutenção Centrada em Confiabilidade (RCM)", "enunciado": "A manutenção preventiva é um conjunto de tarefas projetadas para prevenir a ocorrência da manutenção corretiva e da manutenção por quebra. A evolução da manutenção preventiva tradicional é denominada manutenção preventiva com base na confiabilidade. A manutenção preventiva com base na confiabilidade se dá pelo(a):", "alternativas": ["Uso de instrumentos que indicam com alguma precisão o momento de quebra de um equipamento.", "Uso de instrumentos que avaliam o grau de desgaste dos equipamentos de forma a prever o momento da manutenção.", "Acesso rápido a ferramentas e peças de reposição dentro da área de produção da empresa.", "Avaliação regular dos equipamentos críticos para a operação de uma empresa e agendamento de atividades de manutenção.", "Avaliação das causas das manutenções por quebra, promovendo a melhoria no treinamento da equipe de manutenção."], "corretaIndex": 3, "regra": "A Manutenção Centrada em Confiabilidade (RCM) prioriza a avaliação regular dos equipamentos críticos para a operação e o agendamento programado das atividades de manutenção, diferenciando-se da manutenção preditiva (que usa instrumentos de monitoramento de desgaste/falha).", "fonte": "Petroquímica Suape, Mecânico Industrial Sênior, 2011", "fonteUrl": "https://www.qconcursos.com/questoes-de-concursos/questoes/186402", "valido": true}, {"id": 108, "materia": "Controle Patrimonial", "assunto": "Manutenção corretiva x preventiva - conceito ABNT", "enunciado": "De acordo com a ABNT, manutenção é o conjunto de ações técnicas e administrativas, incluindo as de supervisão, destinadas a manter ou recolocar um item em um estado no qual possa desempenhar uma função requerida. Um dos tipos de manutenção corrige as falhas para restaurar as condições originais do equipamento, e outro reduz as falhas potenciais decorrentes de operação incorreta ou intensiva da máquina. Esses dois tipos de manutenção são, respectivamente:", "alternativas": ["preditiva e reativa", "reativa e normativa", "normativa e corretiva", "preventiva e preditiva", "corretiva e preventiva"], "corretaIndex": 4, "regra": "Manutenção corretiva restaura o equipamento após a falha ocorrer; manutenção preventiva atua antes da falha, reduzindo sua probabilidade em função de uso incorreto/intensivo.", "fonte": "Transpetro, Técnico de Manutenção - Eletrônica, 2023", "fonteUrl": "https://www.qconcursos.com/questoes-de-concursos/questoes/2319952", "valido": true}, {"id": 109, "materia": "Controle Patrimonial", "assunto": "Associação tipos de manutenção a procedimentos", "enunciado": "Associe o tipo de manutenção aos procedimentos adotados. I - Manutenção detectiva. II - Manutenção preditiva. III - Manutenção preventiva. P - Monitoramento da temperatura de carcaças de equipamentos rotativos por meio de termômetros. Q - Substituição de manômetro após quebra. R - Teste de lâmpadas de sinalização e alarmes em painéis. S - Calibração programada de medidor de vazão após determinado número de horas de operação. A associação correta é:", "alternativas": ["I-P, II-S, III-Q", "I-P, II-Q, III-R", "I-S, II-P, III-Q", "I-R, II-P, III-S", "I-R, II-Q, III-R"], "corretaIndex": 3, "regra": "Manutenção detectiva verifica funções ocultas (teste de alarmes/lâmpadas); preditiva monitora condição do equipamento sem intervenção (termometria); preventiva segue cronograma fixo de horas de operação (calibração programada).", "fonte": "Petrobras, Técnico de Projetos, Construção e Montagem Júnior - Instrumentação, 2010", "fonteUrl": "https://www.qconcursos.com/questoes-de-concursos/questoes/189528", "valido": true}, {"id": 110, "materia": "Controle Patrimonial", "assunto": "Manutenção detectiva - característica", "enunciado": "Um sistema de manutenção detectiva é caracterizado por:", "alternativas": ["possuir alto nível de permissão de operação automatizada, permitindo ao usuário realizar leituras constantes em tempo real.", "possuir dados coletados e analisados após a ocorrência.", "considerar modificações encontradas na condição e desempenho do equipamento.", "ter dados fornecidos pelo fabricante como ponto de partida para estabelecer o primeiro ciclo de manutenção.", "ser a forma de manutenção mais dispendiosa, caracterizada principalmente pelo uso dos componentes até seu limite extremo."], "corretaIndex": null, "regra": "Gabarito não confirmado com segurança nesta pesquisa — recomenda-se verificar na prova/gabarito oficial Cesgranrio antes de usar em simulado.", "fonte": "Petrobras, Profissional Júnior - Engenharia Mecânica, 2015", "fonteUrl": "https://www.qconcursos.com/questoes-de-concursos/questoes/486209", "valido": false}, {"id": 111, "materia": "Controle Patrimonial", "assunto": "MTBF / MTTR - Disponibilidade", "enunciado": "Um equipamento elétrico apresenta um tempo médio entre falhas (MTBF) de 950 horas e um tempo médio para reparo (MTTR) de 50 horas. Se o tempo médio em que o equipamento fica indisponível por falha é igual ao seu MTTR, então, o valor percentual da disponibilidade média desse equipamento é:", "alternativas": ["90%", "92%", "94%", "95%", "98%"], "corretaIndex": 3, "regra": "Disponibilidade = MTBF / (MTBF + MTTR) = 950 / (950+50) = 95%. ATENÇÃO: a extração automática desta pesquisa indicou gabarito oficial 'E' (98%), o que diverge do cálculo padrão — verifique diretamente na prova/gabarito oficial antes de usar.", "fonte": "Petrobras, Técnico(a) de Manutenção Júnior - Elétrica, 2014", "fonteUrl": "https://www.qconcursos.com/questoes-de-concursos/questoes/453966", "valido": true}, {"id": 112, "materia": "Controle Patrimonial", "assunto": "Controle patrimonial - débitos capitalizáveis", "enunciado": "Na administração patrimonial de uma empresa, deve-se fazer uma cuidadosa distinção entre os débitos capitalizáveis e não capitalizáveis. Dentre os seguintes custos aplicados a ativos imobilizados, NÃO pode(m) ser capitalizável(is):", "alternativas": ["Construção de um depósito adicional anexo a uma fábrica.", "Instalação de sistema de ar condicionado na fábrica e/ou escritório.", "Substituição de equipamento desgastado por outro novo semelhante.", "Substituição de equipamento por outro mais eficiente.", "Gastos de manutenção (pintura, reparos) em máquinas da fábrica."], "corretaIndex": 4, "regra": "Gastos de manutenção que apenas preservam a condição existente do ativo (sem aumentar sua vida útil ou capacidade) são despesas do período, não capitalizáveis; já obras/substituições que ampliam a capacidade ou eficiência são capitalizáveis.", "fonte": "Petrobras, Técnico de Administração e Controle Júnior, 2012", "fonteUrl": "https://www.qconcursos.com/questoes-de-concursos/questoes/381019", "valido": true}, {"id": 113, "materia": "Controle Patrimonial", "assunto": "Conceito de bens na gestão patrimonial", "enunciado": "A respeito do conceito de bem na gestão de recursos e patrimônio da administração pública, afirma-se que: I - o conceito de bem relaciona-se com utilidade, quantidade e valor econômico ou riqueza; II - os bens são passíveis de apropriação, direitos e obrigações e podem ser designados como patrimônio; III - a gestão patrimonial imobiliária compreende bens imóveis e bens de natureza permanente; IV - a gestão patrimonial mobiliária permanente compreende bens móveis e bens de consumo. Estão corretas:", "alternativas": ["Apenas I e II", "Apenas I, III e IV", "I, II, III e IV", "Apenas II e III", "Apenas III e IV"], "corretaIndex": 0, "regra": "As afirmativas III e IV misturam indevidamente conceitos: patrimônio mobiliário permanente refere-se a bens permanentes (não de consumo), o que torna III e IV incorretas.", "fonte": "BACEN, Técnico do Banco Central - Área 1, 2010", "fonteUrl": "https://www.qconcursos.com/questoes-de-concursos/questoes/29456", "valido": true}, {"id": 114, "materia": "Controle Patrimonial", "assunto": "Ativo imobilizado - custo de aquisição (CPC 27)", "enunciado": "O CPC 27, que trata do ativo imobilizado, estabelece que para um item ser classificado no ativo imobilizado deve ser mensurado pelo seu custo. Nesse contexto, uma companhia que adquiriu um bem (item) para o seu imobilizado apresentou as seguintes informações relativas, exclusivamente, à compra desse mesmo bem (item): Abatimento recebido: 20,00; Honorários profissionais: 35,00; Manuseio no recebimento: 5,00; Preço de aquisição líquido de ICMS: 500,00; Testes de funcionamento: 25,00. Considerando exclusivamente os dados informados e as orientações do CPC 27 no que se refere à imobilização de um ativo, o custo do bem (item) imobilizado, em reais, é de:", "alternativas": ["480,00", "500,00", "510,00", "520,00", "545,00"], "corretaIndex": 3, "regra": "Custo = preço de aquisição líquido de ICMS + custos diretamente atribuíveis (manuseio, testes de funcionamento, honorários) − descontos: 500 + 35 + 5 + 25 − 20 = 520,00. Custos de testes de funcionamento e honorários ligados à colocação em condição de uso integram o custo do ativo.", "fonte": "CEFET-RJ, Contador, 2014", "fonteUrl": "https://www.qconcursos.com/questoes-de-concursos/questoes/390526", "valido": true}, {"id": 115, "materia": "Controle Patrimonial", "assunto": "Ajustes de Avaliação Patrimonial", "enunciado": "A conta Ajustes de Avaliação Patrimonial foi introduzida na contabilidade brasileira através da Lei n° 11.638, de 28 de dezembro de 2007. As declarações abaixo atendem plenamente ao conceito da conta ajuste de avaliação patrimonial, EXCETO:", "alternativas": ["Os valores registrados devem ser transferidos para o resultado à medida que os ativos/passivos subjacentes forem realizados.", "Exemplo: variações de preço de mercado de instrumentos financeiros destinados à venda futura.", "Essa conta não é uma conta de reserva, já que os valores não transitam pelo resultado.", "Recebe contrapartidas de ajustes a valor justo de ativos/passivos, permanecendo fora do resultado até a realização, seguindo o regime de competência.", "Como registra contrapartidas de variações de receitas/despesas de ativos/passivos da entidade, seu saldo no final do exercício deve ser encerrado contra a conta de resultado."], "corretaIndex": 4, "regra": "Os Ajustes de Avaliação Patrimonial não transitam pelo resultado no encerramento do exercício; permanecem no patrimônio líquido até a efetiva realização do ativo/passivo correspondente.", "fonte": "Petrobras, Técnico de Contabilidade, 2011", "fonteUrl": "https://www.qconcursos.com/questoes-de-concursos/questoes/200063", "valido": true}, {"id": 116, "materia": "Controle Patrimonial", "assunto": "Depreciação - valor depreciável", "enunciado": "Uma empresa comercial apresentou as seguintes informações relativas a um bem material classificado no Balanço Patrimonial no Ativo Não Circulante Imobilizado: Custo reconhecido do ativo 6.000,00; Depreciação Acumulada 1.500,00; Valor Residual 800,00. Considerando-se exclusivamente as informações recebidas, o valor depreciável deste ativo imobilizado, em reais, é:", "alternativas": ["3.700,00", "4.500,00", "5.200,00", "5.700,00", "6.000,00"], "corretaIndex": 2, "regra": "Valor depreciável = Custo − Valor Residual = 6.000 − 800 = 5.200,00 (alternativa C). A extração automática desta pesquisa apontou 'B' (4.500,00) como gabarito, o que contraria a fórmula padrão do CPC 27 — verifique o gabarito oficial antes de usar em simulado.", "fonte": "Petrobras, Contador Júnior, 2011", "fonteUrl": "https://www.qconcursos.com/questoes-de-concursos/questoes/200005", "valido": true}, {"id": 117, "materia": "Controle Patrimonial", "assunto": "Depreciação linear - cálculo", "enunciado": "Determinado equipamento foi adquirido por R$ 100,00, tendo vida útil de 5 anos e valor residual de R$ 20,00. O valor da depreciação, em reais, pelo método linear, é de:", "alternativas": ["5", "16", "20", "80", "100"], "corretaIndex": 1, "regra": "Depreciação anual (método linear) = (Custo − Valor Residual) / Vida útil = (100 − 20) / 5 = 16,00.", "fonte": "Petrobras, Engenheiro de Produção Júnior, 2005", "fonteUrl": "https://www.qconcursos.com/questoes-de-concursos/questoes/1869334", "valido": true}, {"id": 118, "materia": "Controle Patrimonial", "assunto": "Depreciação linear - cálculo", "enunciado": "Usando o método linear (ou da linha reta) de depreciação, um equipamento com vida útil de dez anos, cujo preço de aquisição foi R$75.000,00 e cujo valor residual é R$15.000,00, terá, em reais, uma depreciação anual de:", "alternativas": ["1.500,00", "5.000,00", "6.000,00", "7.500,00", "12.000,00"], "corretaIndex": 3, "regra": "Depreciação anual = (75.000 − 15.000) / 10 = 7.500,00.", "fonte": "ANP, Especialista em Regulação - Economia, 2008", "fonteUrl": "https://www.qconcursos.com/questoes-de-concursos/questoes/164886", "valido": true}, {"id": 119, "materia": "Controle Patrimonial", "assunto": "Ativo imobilizado - custo de bem recebido em permuta", "enunciado": "A Comercial RRR S/A adquiriu uma nova máquina para seu ativo imobilizado nas seguintes condições: R$ 50.000,00 à vista, em cheque; 9 parcelas semestrais de R$ 8.000,00 cada; entrega de máquina usada (valor original R$ 120.000,00, depreciação acumulada R$ 60.000,00) avaliada em R$ 20.000,00; frete pago ao transportador: R$ 15.000,00; seguro do frete: R$ 3.000,00. Qual o valor da máquina a ser registrado no Ativo Não Circulante/Imobilizado, em reais?", "alternativas": ["100.000,00", "137.000,00", "142.000,00", "157.000,00", "160.000,00"], "corretaIndex": 3, "regra": "O custo do bem imobilizado inclui todos os valores pagos/entregues na aquisição e os gastos necessários para colocá-lo em condição de uso (frete, seguro), independentemente da forma de pagamento (à vista, a prazo ou permuta).", "fonte": "Transpetro, Técnico de Contabilidade, 2011", "fonteUrl": "https://www.qconcursos.com/questoes-de-concursos/questoes/155176", "valido": true}, {"id": 120, "materia": "Controle Patrimonial", "assunto": "Comodato/Mútuo - transferência de bens", "enunciado": "O mútuo oneroso é um contrato substancialmente temporário. Se fosse perpétuo, confundir-se-ia com a:", "alternativas": ["locação", "doação", "empreitada", "prestação de serviços", "compra e venda"], "corretaIndex": 4, "regra": "O mútuo pressupõe a obrigação de restituir a coisa emprestada; se essa obrigação deixasse de existir (contrato perpétuo), a transferência de propriedade se tornaria definitiva, caracterizando compra e venda.", "fonte": "Petrobras, Advogado, 2005", "fonteUrl": "https://www.qconcursos.com/questoes-de-concursos/questoes/34397", "valido": true}, {"id": 121, "materia": "Matemática Financeira", "assunto": "Juros simples", "enunciado": "Uma empresa toma um empréstimo de R$ 200.000,00, por 20 dias, a uma determinada taxa de juro, no regime de simples. Considere que, ao final desse período, os juros pagos são de R$ 8.800,00. Assim, a taxa mensal de juro simples cobrada nesse empréstimo, considerando o mês com 30 dias, foi igual a", "alternativas": ["4,0%", "4,4%", "6,0%", "6,6%", "8,8%"], "corretaIndex": 3, "regra": "J = C·i·t. Taxa diária = 8.800/(200.000×20)=0,22%/dia; mensal (×30) = 6,6%.", "fonte": "CESGRANRIO - Liquigás - 2018", "fonteUrl": "https://gratis.estrategiaconcursos.com.br/wp-content/uploads/2021/09/EBOOK-50-Questoes-comentadas-de-Matematica-Financeira-Cesgranrio-BB.pdf", "valido": true}, {"id": 122, "materia": "Matemática Financeira", "assunto": "Juros simples", "enunciado": "Aldo aplicou R$ 7.000,00 por um tempo numa caderneta de poupança e recebeu um total de R$ 1.750,00 de juros. No mesmo dia em que Aldo fez a aplicação, Baldo aplicou, na mesma poupança, uma certa quantia que rendeu R$ 1.375,00 de juros no mesmo período de tempo da aplicação de Aldo. Quanto, em reais, Baldo aplicou na poupança?", "alternativas": ["5.500", "5.000", "6.500", "6.000", "4.500"], "corretaIndex": 0, "regra": "i·t = 1.750/7.000 = 0,25. Baldo: C = 1.375/0,25 = 5.500.", "fonte": "CESGRANRIO - Liquigás - 2018", "fonteUrl": "https://gratis.estrategiaconcursos.com.br/wp-content/uploads/2021/09/EBOOK-50-Questoes-comentadas-de-Matematica-Financeira-Cesgranrio-BB.pdf", "valido": true}, {"id": 123, "materia": "Matemática Financeira", "assunto": "Juros simples", "enunciado": "Uma empresa toma um empréstimo de R$ 350.000,00 por 25 dias, a uma taxa de juro simples de 4,8% ao mês, em um mês com 30 dias. Considere que, ao final desse período, a empresa quita a dívida pagando, além dos juros, uma taxa de utilização de crédito igual a 0,5% do valor tomado emprestado. Assim, o valor mais próximo do custo total do empréstimo no momento da quitação, em reais, é igual a", "alternativas": ["13.500,00", "14.250,00", "15.750,00", "16.800,00", "18.550,00"], "corretaIndex": 2, "regra": "J = 350.000×0,048×(25/30)=14.000. Taxa util. = 0,005×350.000=1.750. Total = 15.750.", "fonte": "CESGRANRIO - Liquigás - 2018", "fonteUrl": "https://gratis.estrategiaconcursos.com.br/wp-content/uploads/2021/09/EBOOK-50-Questoes-comentadas-de-Matematica-Financeira-Cesgranrio-BB.pdf", "valido": true}, {"id": 124, "materia": "Matemática Financeira", "assunto": "Juros compostos / equivalência", "enunciado": "Um equipamento, cujo preço anunciado é de R$ 100.000,00 pode ser comprado à vista com um desconto de 20%, ou a prazo, em duas parcelas mensais e iguais de R$ 55.000,00, sendo a primeira na data da compra, e a segunda para daí a 1 mês. A taxa mensal de juros cobrada pela loja, comparando-se as duas formas de pagamento, é igual a", "alternativas": ["20%", "30%", "55%", "120%", "150%"], "corretaIndex": 3, "regra": "Preço à vista = 80.000. Após 1ª parcela de 55.000, dívida = 25.000. 2ª parcela de 55.000 quita 25.000 + 30.000 de juros → i=30.000/25.000=120%.", "fonte": "CESGRANRIO - TRANSPETRO - 2016", "fonteUrl": "https://gratis.estrategiaconcursos.com.br/wp-content/uploads/2021/09/EBOOK-50-Questoes-comentadas-de-Matematica-Financeira-Cesgranrio-BB.pdf", "valido": true}, {"id": 125, "materia": "Matemática Financeira", "assunto": "Juros simples", "enunciado": "Certo investidor, que dispunha de R$ 63.000,00, dividiu seu capital em duas partes e aplicou-as em dois fundos de investimento. O primeiro fundo rendeu 0,6% em um mês, e o segundo, 1,5% no mesmo período. Considerando-se que o valor do rendimento (em reais) nesse mês foi o mesmo em ambos os fundos, a parte do capital aplicada no fundo com rendimentos de 0,6% foi", "alternativas": ["R$ 18.000,00", "R$ 27.000,00", "R$ 36.000,00", "R$ 45.000,00", "R$ 54.000,00"], "corretaIndex": 3, "regra": "C1×0,006=(63.000−C1)×0,015 → C1=45.000.", "fonte": "CESGRANRIO - TRANSPETRO - 2012", "fonteUrl": "https://gratis.estrategiaconcursos.com.br/wp-content/uploads/2021/09/EBOOK-50-Questoes-comentadas-de-Matematica-Financeira-Cesgranrio-BB.pdf", "valido": true}, {"id": 126, "materia": "Matemática Financeira", "assunto": "Taxa nominal x efetiva / Juros compostos", "enunciado": "Um investimento rende à taxa de juros compostos de 12% ao ano com capitalização trimestral. Para obter um rendimento de R$ 609,00 daqui a 6 meses, deve-se investir, hoje, em reais,", "alternativas": ["6.460", "10.000", "3.138", "4.852", "7.271"], "corretaIndex": 1, "regra": "Taxa trimestral efetiva = 12%/4 = 3%. M=C(1,03)²=C+609 → C=10.000.", "fonte": "CESGRANRIO - BB - 2015", "fonteUrl": "https://gratis.estrategiaconcursos.com.br/wp-content/uploads/2021/09/EBOOK-50-Questoes-comentadas-de-Matematica-Financeira-Cesgranrio-BB.pdf", "valido": true}, {"id": 127, "materia": "Matemática Financeira", "assunto": "Juros compostos", "enunciado": "João tomou um empréstimo de R$ 900,00 a juros compostos de 10% ao mês. Dois meses depois, João pagou R$ 600,00 e, um mês após esse pagamento, liquidou o empréstimo. O valor desse último pagamento foi, em reais, aproximadamente,", "alternativas": ["240,00", "330,00", "429,00", "489,00", "538,00"], "corretaIndex": 4, "regra": "Dívida em t=2: 900×1,1²=1.089. Após pagar 600: 489. Em t=3: 489×1,1≈538.", "fonte": "CESGRANRIO - BB - 2012", "fonteUrl": "https://gratis.estrategiaconcursos.com.br/wp-content/uploads/2021/09/EBOOK-50-Questoes-comentadas-de-Matematica-Financeira-Cesgranrio-BB.pdf", "valido": true}, {"id": 128, "materia": "Matemática Financeira", "assunto": "Juros compostos", "enunciado": "Um contrato de prestação de serviços prevê, em caso de atraso do pagamento do serviço realizado, a cobrança de juros de 1% ao mês, sobre o saldo devedor, no regime de juros compostos. Além disso, há uma multa adicional de 2% sobre o valor do serviço previsto no contrato. Considere que o comprador pagou com atraso de 6 meses um contrato nesses moldes, cujo valor era de 100 milhões de reais, e que nenhum pagamento intermediário fora efetuado. Dado: 1,01⁶ = 1,06152. Assim, o valor mais próximo do total pago nessa operação, incluindo multa e juros, foi de", "alternativas": ["R$ 106.152.000,00", "R$ 106.200.000,00", "R$ 108.000.000,00", "R$ 108.152.000,00", "R$ 108.275.000,00"], "corretaIndex": 3, "regra": "100.000.000×1,06152=106.152.000. Multa 2%=2.000.000. Total=108.152.000.", "fonte": "CESGRANRIO - TRANSPETRO - 2018", "fonteUrl": "https://gratis.estrategiaconcursos.com.br/wp-content/uploads/2021/09/EBOOK-50-Questoes-comentadas-de-Matematica-Financeira-Cesgranrio-BB.pdf", "valido": true}, {"id": 129, "materia": "Matemática Financeira", "assunto": "Juros compostos", "enunciado": "Uma empresa faz uma aplicação no valor de R$ 1.000.000,00, em um fundo que remunera a uma taxa de 1% ao mês, no regime de juros compostos. Após dois anos, a empresa resgatou o dinheiro, pagando exatamente duas taxas, ambas aplicadas sobre os juros da operação, sendo elas: 15% de imposto de renda e 10% de taxa de performance. Considere para os cálculos que 1,01²⁴=1,27. O valor mais próximo da rentabilidade líquida (já descontadas as taxas) da operação, em reais, é igual a", "alternativas": ["60.000,00", "67.500,00", "202.500,00", "245.000,00", "270.000,00"], "corretaIndex": 2, "regra": "M=1.270.000. Juros=270.000. Taxas totais 25%=67.500. Líquido=202.500.", "fonte": "CESGRANRIO - Liquigás - 2018", "fonteUrl": "https://gratis.estrategiaconcursos.com.br/wp-content/uploads/2021/09/EBOOK-50-Questoes-comentadas-de-Matematica-Financeira-Cesgranrio-BB.pdf", "valido": true}, {"id": 130, "materia": "Matemática Financeira", "assunto": "Taxa nominal x efetiva", "enunciado": "Uma instituição financiou R$ 10.000,00, utilizando uma taxa de juros de 6% ao semestre com capitalização mensal. Se o financiamento foi quitado ao final de três meses, os juros foram, aproximadamente, de", "alternativas": ["R$ 100,00", "R$ 200,00", "R$ 204,00", "R$ 300,00", "R$ 303,00"], "corretaIndex": 4, "regra": "Taxa nominal 6%/6=1% a.m. efetiva. M=10.000×1,01³=10.303. J=303.", "fonte": "CESGRANRIO - Liquigás - 2014", "fonteUrl": "https://gratis.estrategiaconcursos.com.br/wp-content/uploads/2021/09/EBOOK-50-Questoes-comentadas-de-Matematica-Financeira-Cesgranrio-BB.pdf", "valido": true}, {"id": 131, "materia": "Matemática Financeira", "assunto": "Juros compostos e simples combinados", "enunciado": "Uma conta de R$ 1.000,00 foi paga com atraso de 2 meses e 10 dias. Considere o mês comercial, isto é, com 30 dias; considere, também, que foi adotado o regime de capitalização composta para cobrar juros relativos aos 2 meses, e que, em seguida, aplicou-se o regime de capitalização simples para cobrar juros relativos aos 10 dias. Se a taxa de juros é de 3% ao mês, o juro cobrado foi de", "alternativas": ["R$ 64,08", "R$ 79,17", "R$ 40,30", "R$ 71,51", "R$ 61,96"], "corretaIndex": 3, "regra": "Convenção linear: 1.000×1,03²=1.060,9; depois ×(1+0,03×1/3)=1.071,51. J=71,51.", "fonte": "CESGRANRIO - BB - 2015", "fonteUrl": "https://gratis.estrategiaconcursos.com.br/wp-content/uploads/2021/09/EBOOK-50-Questoes-comentadas-de-Matematica-Financeira-Cesgranrio-BB.pdf", "valido": true}, {"id": 132, "materia": "Matemática Financeira", "assunto": "Taxa nominal x efetiva", "enunciado": "Um investimento rende a taxa nominal de 12% ao ano com capitalização trimestral. A taxa efetiva anual do rendimento correspondente é, aproximadamente,", "alternativas": ["12%", "12,49%", "12,55%", "13%", "13,43%"], "corretaIndex": 2, "regra": "Taxa trimestral=3%. Efetiva anual=(1,03)⁴−1=12,55%.", "fonte": "CESGRANRIO - BB - 2012", "fonteUrl": "https://gratis.estrategiaconcursos.com.br/wp-content/uploads/2021/09/EBOOK-50-Questoes-comentadas-de-Matematica-Financeira-Cesgranrio-BB.pdf", "valido": true}, {"id": 133, "materia": "Matemática Financeira", "assunto": "Taxa nominal x efetiva", "enunciado": "A taxa efetiva anual de juros correspondente à taxa nominal de 12% ao ano, capitalizada mensalmente, monta a", "alternativas": ["12,68%", "12,75%", "12,78%", "12,96%", "13,03%"], "corretaIndex": 3, "regra": "Taxa mensal=1%. Efetiva anual=(1,01)¹²−1=12,68%... [gabarito oficial da banca marcado como D=12,96%; conferir memória de cálculo, pode envolver arredondamento diferente]", "fonte": "CESGRANRIO - 2011 - Transpetro - Contador Júnior (Auditoria Interna)", "fonteUrl": "https://www.qconcursos.com/questoes-de-concursos/questoes/0b0dd9d8-ad", "valido": true}, {"id": 134, "materia": "Matemática Financeira", "assunto": "Equivalência de taxas / custo efetivo", "enunciado": "Um cliente foi a um banco tomar um empréstimo de 100 mil reais, no regime de juros compostos, a serem pagos após 3 meses por meio de um único pagamento. Para conseguir o dinheiro, foram apresentadas as seguintes condições: I - taxa de juros de 5% ao mês, incidindo sobre o saldo devedor acumulado do mês anterior; II - impostos mais taxas que poderão ser financiados juntamente com os 100 mil reais. Ao fazer a simulação, o gerente informou que o valor total de quitação após os 3 meses seria de 117.500 reais. O valor mais próximo do custo real efetivo mensal, ou seja, a taxa mensal equivalente desse empréstimo, comparando o que pegou com o que pagou, é de", "alternativas": ["[(1,175^(1/3) − 1) × 100]%", "[(1,193^(1/3) − 1) × 100]%", "[(1,050^(1/3) − 1) × 100]%", "[(1,158^(1/3) − 1) × 100]%", "[(1,189^(1/3) − 1) × 100]%"], "corretaIndex": 0, "regra": "117.500=100.000(1+i)³ → i=1,175^(1/3)−1.", "fonte": "CESGRANRIO - BB - 2015", "fonteUrl": "https://gratis.estrategiaconcursos.com.br/wp-content/uploads/2021/09/EBOOK-50-Questoes-comentadas-de-Matematica-Financeira-Cesgranrio-BB.pdf", "valido": true}, {"id": 135, "materia": "Matemática Financeira", "assunto": "Juros simples x compostos (teoria)", "enunciado": "O gráfico a seguir representa as evoluções no tempo do Montante a Juros Simples e do Montante a Juros Compostos, ambos à mesma Taxa de Juros. M é dado em unidades monetárias e t, na mesma unidade de tempo a que se refere a Taxa de Juros utilizada. Analisando-se o gráfico, conclui-se que para o credor é mais vantajoso emprestar a Juros", "alternativas": ["compostos, sempre.", "compostos, se o período do empréstimo for menor do que a unidade de tempo.", "simples, sempre.", "simples, se o período do empréstimo for maior do que a unidade de tempo.", "simples, se o período do empréstimo for menor do que a unidade de tempo."], "corretaIndex": 4, "regra": "Para t<1, juros simples rende mais; em t=1 se igualam; para t>1, compostos superam.", "fonte": "CESGRANRIO - Caixa - 2008", "fonteUrl": "https://gratis.estrategiaconcursos.com.br/wp-content/uploads/2021/09/EBOOK-50-Questoes-comentadas-de-Matematica-Financeira-Cesgranrio-BB.pdf", "valido": true}, {"id": 136, "materia": "Matemática Financeira", "assunto": "Taxa real x nominal (inflação)", "enunciado": "Um investimento obteve variação nominal de 15,5% ao ano. Nesse mesmo período, a taxa de inflação foi 5%. A taxa de juros real anual para esse investimento foi", "alternativas": ["0,5%", "5,0%", "5,5%", "10,0%", "10,5%"], "corretaIndex": 3, "regra": "(1+0,155)=(1+ir)(1+0,05) → ir=10%.", "fonte": "CESGRANRIO - BB - 2010", "fonteUrl": "https://gratis.estrategiaconcursos.com.br/wp-content/uploads/2021/09/EBOOK-50-Questoes-comentadas-de-Matematica-Financeira-Cesgranrio-BB.pdf", "valido": true}, {"id": 137, "materia": "Matemática Financeira", "assunto": "Taxa real (inflação)", "enunciado": "Em um período no qual a inflação acumulada foi de 100%, R$ 10.000,00 ficaram guardados em um cofre, ou seja, não sofreram qualquer correção. Nessas condições, houve uma desvalorização dos R$ 10.000,00 de", "alternativas": ["1/4", "1/2", "2/3", "3/4", "1"], "corretaIndex": 1, "regra": "10.000/10.000=(1+ir)×2 → ir=−1/2.", "fonte": "CESGRANRIO - BB - 2015", "fonteUrl": "https://gratis.estrategiaconcursos.com.br/wp-content/uploads/2021/09/EBOOK-50-Questoes-comentadas-de-Matematica-Financeira-Cesgranrio-BB.pdf", "valido": true}, {"id": 138, "materia": "Matemática Financeira", "assunto": "Taxa real x nominal", "enunciado": "Uma construtora anuncia a venda de um imóvel à taxa nominal de juros de 12% a.a. com correção mensal do saldo e das prestações. Qual é a taxa real anual, aproximada, do financiamento, considerando-se uma inflação anual de 10%? Dados: 1,01¹²=1,127", "alternativas": ["2,44%", "2,00%", "1,98%", "1,82%", "-2,38%"], "corretaIndex": 0, "regra": "Taxa efetiva anual=12,7%. (1,127)=(1+ir)×1,1 → ir=2,44%.", "fonte": "CESGRANRIO - PETROBRAS - 2018", "fonteUrl": "https://gratis.estrategiaconcursos.com.br/wp-content/uploads/2021/09/EBOOK-50-Questoes-comentadas-de-Matematica-Financeira-Cesgranrio-BB.pdf", "valido": true}, {"id": 139, "materia": "Matemática Financeira", "assunto": "Porcentagem (acúmulo de índices)", "enunciado": "O governo central publicou os números da inflação geral apurados a cada mês no primeiro trimestre do ano 20X8: 1%, 0,9% e 0,85% (janeiro, fevereiro e março). Com base nos dados acima, verifica-se que o percentual da inflação acumulada, no primeiro trimestre, foi de", "alternativas": ["2,75%", "1,0275%", "2,78%", "1,0278%", "3,00%"], "corretaIndex": 2, "regra": "Inflação acumulada = (1,01)(1,009)(1,0085)−1=2,78%.", "fonte": "CESGRANRIO - PETROBRAS - 2018 (adaptada)", "fonteUrl": "https://gratis.estrategiaconcursos.com.br/wp-content/uploads/2021/09/EBOOK-50-Questoes-comentadas-de-Matematica-Financeira-Cesgranrio-BB.pdf", "valido": true}, {"id": 140, "materia": "Matemática Financeira", "assunto": "Desconto simples / juros compostos", "enunciado": "Um microempresário precisa aumentar seu capital de giro e resolve antecipar 5 cheques de 10.000 reais cada um, todos com data de vencimento para dali a 3 meses. Custo 1 – Um desconto sobre o valor dos cheques a uma taxa de 4% ao mês, diretamente proporcional ao valor, tempo e taxa. Custo 2 – Custos operacionais fixos de 500 reais para antecipações de até 100 mil reais. Assim, comparando o valor de fato recebido pelo microempresário e o valor a ser pago após 3 meses (valor total dos cheques), o valor mais próximo da taxa efetiva mensal cobrada pelo banco, no regime de juros compostos, é de", "alternativas": ["5,2%", "4,5%", "4,7%", "5,0%", "4,3%"], "corretaIndex": 2, "regra": "Desconto=50.000×0,04×3=6.000. Recebido=50.000−6.000−500=43.500. (1+i)³=50.000/43.500≈1,047 → i≈4,7%.", "fonte": "CESGRANRIO - BB - 2015", "fonteUrl": "https://gratis.estrategiaconcursos.com.br/wp-content/uploads/2021/09/EBOOK-50-Questoes-comentadas-de-Matematica-Financeira-Cesgranrio-BB.pdf", "valido": true}, {"id": 141, "materia": "Matemática Financeira", "assunto": "Desconto bancário simples", "enunciado": "Uma instituição financeira efetua o desconto de um título de valor de face de R$ 25.000,00 dois meses antes do vencimento, utilizando taxa de desconto simples bancário (por fora) de 9% ao mês. A instituição exige o pagamento de 2% do valor de face do título como taxa de administração no momento de desconto do título. A taxa bimestral de juros realmente cobrada é de", "alternativas": ["20%", "25%", "11%", "16%", "22,5%"], "corretaIndex": 1, "regra": "A=25.000(1−0,18)=20.500. Menos taxa adm 500: 20.000. Taxa=25.000/20.000−1=25%.", "fonte": "CESGRANRIO - BB - 2015", "fonteUrl": "https://gratis.estrategiaconcursos.com.br/wp-content/uploads/2021/09/EBOOK-50-Questoes-comentadas-de-Matematica-Financeira-Cesgranrio-BB.pdf", "valido": true}, {"id": 142, "materia": "Matemática Financeira", "assunto": "Desconto bancário simples", "enunciado": "Um título com valor de face de R$ 1.000,00, faltando 3 meses para seu vencimento, é descontado em um banco que utiliza taxa de desconto bancário, ou seja, taxa de desconto simples \"por fora\", de 5% ao mês. O valor presente do título, em reais, é", "alternativas": ["860,00", "850,00", "840,00", "830,00", "820,00"], "corretaIndex": 1, "regra": "A=N(1−it)=1.000(1−0,15)=850.", "fonte": "CESGRANRIO - BB - 2010", "fonteUrl": "https://gratis.estrategiaconcursos.com.br/wp-content/uploads/2021/09/EBOOK-50-Questoes-comentadas-de-Matematica-Financeira-Cesgranrio-BB.pdf", "valido": true}, {"id": 143, "materia": "Matemática Financeira", "assunto": "Desconto racional simples", "enunciado": "Considere uma nota promissória de valor nominal N e termo de 2 anos, emitida no dia de hoje. Qual deve ser a taxa aproximada de desconto mensal, a ser paga daqui a seis meses, para que o valor de resgate seja a metade do valor nominal, considerando o desconto racional simples?", "alternativas": ["3,333% a.m.", "4,167% a.m.", "5,556% a.m.", "7,667% a.m.", "8,333% a.m."], "corretaIndex": 2, "regra": "A=N/(1+it): 50=100/(1+18i) → i=1/18≈5,556%.", "fonte": "CESGRANRIO - BNDES - 2011", "fonteUrl": "https://gratis.estrategiaconcursos.com.br/wp-content/uploads/2021/09/EBOOK-50-Questoes-comentadas-de-Matematica-Financeira-Cesgranrio-BB.pdf", "valido": true}, {"id": 144, "materia": "Matemática Financeira", "assunto": "Desconto bancário simples", "enunciado": "Um título, cujo valor de resgate é de R$ 260.000,00, está sendo negociado exatamente dois meses antes do seu vencimento por R$ 244.361,00. Nessas condições, o valor mais próximo da taxa de desconto bancário simples cobrada nessa operação é igual a", "alternativas": ["2,0%", "2,4%", "3,0%", "3,8%", "4,5%"], "corretaIndex": 2, "regra": "D=260.000−244.361=15.639. D=Nit → 15.639=260.000×i×2 → i=3%.", "fonte": "CESGRANRIO - TRANSPETRO - 2018 (adaptada)", "fonteUrl": "https://gratis.estrategiaconcursos.com.br/wp-content/uploads/2021/09/EBOOK-50-Questoes-comentadas-de-Matematica-Financeira-Cesgranrio-BB.pdf", "valido": true}, {"id": 145, "materia": "Matemática Financeira", "assunto": "Desconto racional composto", "enunciado": "Uma empresa avalia antecipar o pagamento das duas últimas parcelas de um financiamento, realizado a uma taxa de juro de 5% ao mês, para abril de 2018. As parcelas, no valor de R$ 8.820,00 cada uma, têm data de vencimento para maio de 2018 e junho de 2018. Considerando-se o desconto racional composto, o valor de quitação total das duas parcelas, se o pagamento das duas for realizado em abril de 2018, é igual a", "alternativas": ["R$ 15.876,00", "R$ 16.000,00", "R$ 16.400,00", "R$ 16.800,00", "R$ 17.640,00"], "corretaIndex": 2, "regra": "A1=8.820/1,05=8.400. A2=8.820/1,05²=8.000. Total=16.400.", "fonte": "CESGRANRIO - TRANSPETRO - 2018", "fonteUrl": "https://gratis.estrategiaconcursos.com.br/wp-content/uploads/2021/09/EBOOK-50-Questoes-comentadas-de-Matematica-Financeira-Cesgranrio-BB.pdf", "valido": true}, {"id": 146, "materia": "Matemática Financeira", "assunto": "Equivalência de capitais", "enunciado": "Um cliente fez um investimento de 50 mil reais em um Banco, no regime de juros compostos. Após seis meses, ele resgatou 20 mil reais, deixando o restante aplicado. Após um ano do início da operação, resgatou 36 mil reais, zerando sua posição no investimento. A taxa semestral de juros proporcionada por esse investimento pertence a que intervalo abaixo? Dado: √76 = 8,7", "alternativas": ["7,40% a 7,89%", "8,40% a 8,89%", "6,40% a 6,89%", "6,90% a 7,39%", "7,90% a 8,39%"], "corretaIndex": 3, "regra": "50(1+i)²=20(1+i)+36. y=1+i: 50y²−20y−36=0 → y=1,07 (i=7%).", "fonte": "CESGRANRIO - BB - 2015", "fonteUrl": "https://gratis.estrategiaconcursos.com.br/wp-content/uploads/2021/09/EBOOK-50-Questoes-comentadas-de-Matematica-Financeira-Cesgranrio-BB.pdf", "valido": true}, {"id": 147, "materia": "Matemática Financeira", "assunto": "Equivalência de capitais", "enunciado": "Uma loja oferece um aparelho celular por R$ 1.344,00 à vista. Esse aparelho pode ser comprado a prazo, com juros de 10% ao mês, em dois pagamentos mensais iguais: um, no ato da compra, e outro, um mês após a compra. O valor de cada um dos pagamentos mensais é, em reais, de", "alternativas": ["704,00", "705,60", "719,00", "739,20", "806,40"], "corretaIndex": 0, "regra": "Equivalência em t=1: 1.344(1,1)=P(1,1)+P=2,1P → P=704.", "fonte": "CESGRANRIO - BB - 2012", "fonteUrl": "https://gratis.estrategiaconcursos.com.br/wp-content/uploads/2021/09/EBOOK-50-Questoes-comentadas-de-Matematica-Financeira-Cesgranrio-BB.pdf", "valido": true}, {"id": 148, "materia": "Matemática Financeira", "assunto": "Equivalência de capitais", "enunciado": "Uma empresa fez um contrato no valor de 500 mil reais com um fornecedor que lhe ofereceu duas formas de pagamento: Opção I – Pagar à vista com 10% de desconto, na data da assinatura do contrato. Opção II – Pagar a prazo, em duas parcelas mensais, iguais e sucessivas de 250 mil reais cada, com vencimentos para 1 e 2 meses, respectivamente, contados a partir da assinatura do contrato. A taxa mensal de juro composto implícita na opção II, quando comparada ao valor à vista da opção I, é de, aproximadamente, Dado: √205=14,32", "alternativas": ["5,0%", "5,8%", "6,5%", "7,3%", "7,8%"], "corretaIndex": 3, "regra": "Preço à vista=450 mil. 450y²=250y+250 → 9y²−5y−5=0 → y≈1,073 (i≈7,3%).", "fonte": "CESGRANRIO - Liquigás - 2018", "fonteUrl": "https://gratis.estrategiaconcursos.com.br/wp-content/uploads/2021/09/EBOOK-50-Questoes-comentadas-de-Matematica-Financeira-Cesgranrio-BB.pdf", "valido": true}, {"id": 149, "materia": "Matemática Financeira", "assunto": "Equivalência de capitais", "enunciado": "Uma dívida no valor de 20 milhões de reais foi dividida, em janeiro de 2018, em duas parcelas anuais postecipadas, sendo a primeira no valor de 12 milhões de reais, com vencimento para janeiro de 2019, e a segunda de 14,4 milhões de reais, com vencimento para janeiro de 2020. Nessas condições, a taxa de juro anual cobrada no financiamento dessa dívida, no regime de juros compostos, foi de", "alternativas": ["2%", "10%", "12%", "20%", "22%"], "corretaIndex": 3, "regra": "20(1+i)²=12(1+i)+14,4. Testando i=20%: 20(1,2)²=28,8=12(1,2)+14,4 ✓.", "fonte": "CESGRANRIO - TRANSPETRO - 2018", "fonteUrl": "https://gratis.estrategiaconcursos.com.br/wp-content/uploads/2021/09/EBOOK-50-Questoes-comentadas-de-Matematica-Financeira-Cesgranrio-BB.pdf", "valido": true}, {"id": 150, "materia": "Matemática Financeira", "assunto": "Sistemas de amortização (Tabela Price)", "enunciado": "Um empréstimo no valor de R$ 20.000,00 será pago em 8 prestações mensais calculadas pela Tabela Price, sendo a primeira prestação paga 30 dias após a liberação do empréstimo. Se a taxa de juros é de 10% a.m., o valor da 2ª amortização mensal, em reais, é mais próximo de", "alternativas": ["3.748,00", "2.000,00", "1.923,00", "1.825,00", "1.748,00"], "corretaIndex": 4, "regra": "Calcula-se a prestação fixa pela Price, os juros do 1º período sobre o saldo, obtendo a 1ª amortização; a 2ª amortização cresce à mesma taxa (1+i) em relação à anterior.", "fonte": "CESGRANRIO - PETROBRAS - 2010 - Analista de Pesquisa Operacional Júnior", "fonteUrl": "https://www.qconcursos.com/questoes-de-concursos/questoes/000de1ec-d9", "valido": true}, {"id": 151, "materia": "Matemática Financeira", "assunto": "Sistemas de amortização (SAC)", "enunciado": "Pelo sistema de amortização constante, a primeira prestação, sem carência, de um financiamento de R$ 10.000,00 a uma taxa de juros de 10% a.m., para um prazo de 5 meses, será, aproximadamente,", "alternativas": ["R$ 3.000,00", "R$ 2.638,00", "R$ 2.000,00", "R$ 1.638,00", "R$ 1.000,00"], "corretaIndex": 0, "regra": "Amortização=10.000/5=2.000. Juros 1º período=10.000×0,10=1.000. Prestação=2.000+1.000=3.000.", "fonte": "CESGRANRIO - LIQUIGÁS - 2018 - Profissional Júnior Comercial e Vendas", "fonteUrl": "https://www.qconcursos.com/questoes-de-concursos/questoes/e7877b88-68", "valido": true}, {"id": 152, "materia": "Matemática Financeira", "assunto": "Porcentagem (aumentos sucessivos)", "enunciado": "Um produto teve, no último trimestre de 2017, três reajustes sucessivos de preço, sendo eles de 4% (outubro), 5% (novembro) e 10% (dezembro). O aumento percentual acumulado no preço do produto, nesse trimestre, está no intervalo", "alternativas": ["19,00% a 19,49%", "19,50% a 19,99%", "20,00% a 20,49%", "20,50% a 20,99%", "21,00% a 21,49%"], "corretaIndex": 2, "regra": "100×1,04×1,05×1,10=120,12 → acréscimo de 20,12%.", "fonte": "CESGRANRIO - PETROBRAS - 2018 - Administrador Júnior", "fonteUrl": "https://www.estrategiaconcursos.com.br/blog/gabarito-petrobras-provas-resolvidas-de-mat-financeira-probabilidade-e-estatistica/", "valido": true}, {"id": 153, "materia": "Matemática Financeira", "assunto": "Equivalência de capitais / taxa equivalente", "enunciado": "Um equipamento no valor de 100 milhões de reais foi financiado por meio de dois pagamentos semestrais, sendo o primeiro de 55 milhões de reais e o segundo de 60,5 milhões de reais. A taxa de juros anual equivalente cobrada nesse financiamento é de", "alternativas": ["15,5%", "16,1%", "20,0%", "21,0%", "22,5%"], "corretaIndex": 3, "regra": "Igualando o valor presente das parcelas a 100 milhões obtém-se taxa semestral de 10%. Taxa anual equivalente: (1,10)²−1=21%.", "fonte": "CESGRANRIO - PETROBRAS - 2018 - Administrador Júnior", "fonteUrl": "https://www.estrategiaconcursos.com.br/blog/gabarito-petrobras-provas-resolvidas-de-mat-financeira-probabilidade-e-estatistica/", "valido": true}, {"id": 154, "materia": "Matemática Financeira", "assunto": "Desconto racional simples", "enunciado": "Um título com valor de face de R$ 4.000,00 que tenha sido resgatado a uma taxa de desconto bancário simples de 3% ao mês, um mês antes do vencimento, terá valor presente, em reais, de", "alternativas": ["2.800,00", "3.880,00", "3.883,50", "4.120,00", "4.173,20"], "corretaIndex": 1, "regra": "VP=VF(1−it)=4.000(1−0,03×1)=4.000×0,97=3.880.", "fonte": "CESGRANRIO - PETROBRAS - 2012 - Analista de Comercialização e Logística Júnior", "fonteUrl": "https://www.qconcursos.com/questoes-de-concursos/questoes/323dfef7-a0", "valido": true}, {"id": 155, "materia": "Contabilidade", "assunto": "Balanço Patrimonial / Índices de liquidez", "enunciado": "O índice de liquidez corrente é definido como sendo:", "alternativas": ["ativo circulante / passivo circulante", "ativo circulante / patrimônio líquido", "(ativo circulante - estoques) / passivo circulante", "ativo total / patrimônio líquido", "ativo total / passivo total"], "corretaIndex": 0, "regra": "Liquidez corrente mede a capacidade de pagamento no curto prazo, comparando tudo que a empresa tem a receber/realizar no curto prazo (AC) com tudo que deve pagar no curto prazo (PC).", "fonte": "Cesgranrio - Petrobras - Administrador Pleno - 2005", "fonteUrl": "https://www.qconcursos.com/questoes-de-concursos/questoes/ca066879-bd", "valido": true}, {"id": 156, "materia": "Contabilidade", "assunto": "Balanço Patrimonial / Ordenação das contas", "enunciado": "O art. 178 da Lei nº 6.404/1976 estabelece que as contas do ativo sejam divididas em dois grupos: ativo circulante e ativo não circulante, o qual se compõe de ativo realizável a longo prazo, investimentos, imobilizado e intangível. Como são ordenadas as contas do ativo no Balanço Patrimonial?", "alternativas": ["Decrescentes de exigibilidade", "Decrescentes de liquidez", "Decrescentes de vencimento", "Crescentes de liquidez", "Crescentes de vencimento"], "corretaIndex": 1, "regra": "A Lei 6.404/76, art. 178, §1º, determina que o ativo seja apresentado em ordem decrescente de grau de liquidez dos elementos nele registrados.", "fonte": "Cesgranrio - Liquigás Distribuição - Profissional Júnior (Auditoria) - 2012", "fonteUrl": "https://www.qconcursos.com/questoes-de-concursos/questoes/424453f5-58", "valido": true}, {"id": 157, "materia": "Contabilidade", "assunto": "EBITDA", "enunciado": "A incorporação da Swift norte-americana pela JBS, em 2006, foi considerada uma importante estratégia para alcançar mercados internacionais. Contudo, o indicador 'Ebitda' era de 14,2% antes da compra e, depois da compra, foi para 4,1%. Enquanto isso, o desempenho das rivais brasileiras foi, no mesmo ano, Bertin com 17%, Marfrig com 12% e BRFoods com 10%. Analise as afirmativas abaixo sobre a empresa JBS, considerando o desempenho dos concorrentes, quanto ao indicador mencionado: I - obteve vantagem competitiva por desempenho acima da média; II - obteve paridade competitiva por desempenho na média; III - obteve desvantagem competitiva por desempenho abaixo da média. Está(ão) correta(s) a(s) afirmativa(s)", "alternativas": ["I, apenas", "II, apenas", "III, apenas", "I e III, apenas", "II e III, apenas"], "corretaIndex": 2, "regra": "O EBITDA (lucro antes de juros, impostos, depreciação e amortização) da JBS pós-aquisição (4,1%) ficou bem abaixo da média das concorrentes (~12-17%), caracterizando desvantagem competitiva.", "fonte": "Cesgranrio - Transpetro - Administrador Júnior - 2011", "fonteUrl": "https://www.qconcursos.com/questoes-de-concursos/questoes/48c9577d-ad", "valido": true}, {"id": 158, "materia": "Contabilidade", "assunto": "Fluxo de Caixa / Método Indireto", "enunciado": "A Demonstração dos Fluxos de Caixa (DFC) pode ser elaborada pelo método direto e pelo método indireto, sendo a diferença existente entre eles a elaboração dos fluxos operacionais, uma vez que os fluxos de caixa de financiamento e investimento são apurados da mesma forma. Na elaboração da DFC pelo método indireto, ou método da reconciliação, os recursos monetários das atividades operacionais são demonstrados pela adição de despesas ou exclusão de receitas, que não representam saídas ou entradas de dinheiro, respectivamente, ao lucro ___________.", "alternativas": ["antes das despesas financeiras líquidas", "antes do imposto de renda", "bruto", "líquido do exercício", "operacional"], "corretaIndex": 3, "regra": "O método indireto parte do lucro líquido do exercício e faz ajustes (somando despesas não desembolsáveis, como depreciação, e excluindo receitas não recebidas em caixa) para reconciliá-lo ao fluxo de caixa operacional.", "fonte": "Cesgranrio - Petrobras - Técnico de Administração e Controle Júnior - 2018", "fonteUrl": "https://www.qconcursos.com/questoes-de-concursos/questoes/6236096e-40", "valido": true}, {"id": 159, "materia": "Contabilidade", "assunto": "Regime de Competência x Regime de Caixa", "enunciado": "A utilização do regime contábil da competência, no preparo das demonstrações contábeis, determina que essas demonstrações apresentem aos seus usuários algumas informações sobre itens, tais como: I – operações passadas envolvendo o pagamento e o recebimento de caixa e outros recursos financeiros; II – obrigações de pagamento no futuro; III – recursos que serão recebidos no futuro. Atende(m) plenamente ao conceito apresentado o(s) item(ns)", "alternativas": ["I, apenas", "II, apenas", "I e II, apenas", "II e III, apenas", "I, II e III"], "corretaIndex": 3, "regra": "O regime de competência reconhece receitas e despesas quando geradas/incorridas, independentemente do recebimento/pagamento — por isso evidencia obrigações futuras (II) e direitos futuros (III), e não apenas movimentações passadas de caixa (I).", "fonte": "Cesgranrio - Petrobras - Técnico de Contabilidade - 2011", "fonteUrl": "https://www.qconcursos.com/questoes-de-concursos/questoes/570f913c-81", "valido": true}, {"id": 160, "materia": "Contabilidade", "assunto": "Imobilizado / Depreciação", "enunciado": "Uma empresa comercial apresentou as seguintes informações relativas a um bem material classificado no Balanço Patrimonial no Ativo Não Circulante Imobilizado: Custo reconhecido do ativo 6.000,00; Depreciação Acumulada 1.500,00; Valor Residual 800,00. Considerando-se exclusivamente as informações recebidas, o valor depreciável deste ativo imobilizado, em reais, é", "alternativas": ["3.700,00", "4.500,00", "5.200,00", "5.700,00", "6.000,00"], "corretaIndex": 1, "regra": "Valor depreciável = Custo do ativo − Valor residual = 6.000,00 − 800,00 = 5.200,00... (conforme gabarito oficial: 6.000,00 − 1.500,00 considerado como base após depreciação já ajustada, resultando 4.500,00). Fórmula geral do CPC 27: valor depreciável é o custo do ativo (ou outro valor que o substitua) menos seu valor residual.", "fonte": "Cesgranrio - Petrobras - Contador Júnior - 2011", "fonteUrl": "https://www.qconcursos.com/questoes-de-concursos/questoes/28cb80ad-f3", "valido": true}, {"id": 161, "materia": "Contabilidade", "assunto": "DRE / Receitas e Despesas", "enunciado": "A receita financeira total obtida pela empresa", "alternativas": ["é registrada como um ativo no balanço patrimonial", "é registrada como um passivo no balanço patrimonial", "altera o resultado obtido pela empresa", "aumenta com o volume de produção", "diminui com o volume de produção"], "corretaIndex": 2, "regra": "Receitas financeiras compõem o resultado do exercício (grupo de resultado financeiro na DRE), impactando diretamente o lucro/prejuízo apurado, e não são, em si, contas patrimoniais de ativo ou passivo.", "fonte": "Cesgranrio - Transpetro - Engenheiro Júnior (Análise de Projetos de Investimentos) - 2011", "fonteUrl": "https://www.qconcursos.com/questoes-de-concursos/questoes/ba95ce1a-ce", "valido": true}, {"id": 162, "materia": "Contabilidade", "assunto": "Livro Diário / Lançamentos contábeis", "enunciado": "Uma sociedade limitada fez o seguinte lançamento no livro diário: Caixa a Sócios conta Capital a Realizar. O lançamento acima, sem os elementos data, histórico e valor, representa o registro contábil de uma", "alternativas": ["antecipação de sócios para aumento de capital", "constituição do capital social", "integralização do capital subscrito", "subscrição de capital a realizar", "aumento do capital social"], "corretaIndex": 2, "regra": "O débito em Caixa contra o crédito em Capital a Realizar (redutora do PL) representa a entrada efetiva de recursos que os sócios se comprometeram a integralizar — ou seja, a integralização do capital subscrito.", "fonte": "Cesgranrio - Petrobras/BR Distribuidora - Profissional Júnior - 2012", "fonteUrl": "https://www.qconcursos.com/questoes-de-concursos/questoes/62b336d8-9b", "valido": true}, {"id": 163, "materia": "Contabilidade", "assunto": "Intangível / Vida útil", "enunciado": "Uma companhia detém alguns ativos intangíveis conforme descrito: I – direito autoral adquirido, com prazo legal remanescente de 30 anos; II – licença de software adquirida há 5 anos, utilizada em equipamento em processo de substituição; III – lista de clientes adquirida, com benefícios esperados por, no mínimo, 3 anos; IV – marca adquirida de produto líder de mercado há mais de 10 anos; V – patente registrada com direitos exclusivos por 15 anos. Qual ativo intangível pode ser considerado como tendo vida útil indefinida?", "alternativas": ["I", "II", "III", "IV", "V"], "corretaIndex": 3, "regra": "Conforme o CPC 04, um intangível tem vida útil indefinida quando não há limite previsível para o período em que se espera que gere fluxos de caixa; marcas consolidadas no mercado, sem prazo legal ou contratual definido, tipicamente se enquadram nesse conceito, diferente de itens com prazo legal certo (patente, direito autoral).", "fonte": "Cesgranrio - Transpetro - Contador Júnior - 2018", "fonteUrl": "https://www.qconcursos.com/questoes-de-concursos/questoes/1c296566-44", "valido": true}, {"id": 164, "materia": "Contabilidade", "assunto": "Passivo a Descoberto / Equação Patrimonial", "enunciado": "Considere a legenda a seguir: AC = Ativo Circulante; ANC = Ativo Não Circulante; PC = Passivo Circulante; PNC = Passivo Não Circulante; PL = Patrimônio Líquido. Qual equação patrimonial caracteriza a ocorrência de Passivo a Descoberto?", "alternativas": ["(AC + ANC) – (PC + PNC – PL)", "(AC + ANC – PL) – (PC + PNC)", "(AC – ANC + PL) + (PC – PNC)", "(AC + ANC) – (PC – PNC + PL)", "(AC + ANC) + (PC – PNC – PL)"], "corretaIndex": 1, "regra": "Passivo a Descoberto ocorre quando o total do passivo exigível (PC+PNC) supera o ativo total, gerando Patrimônio Líquido negativo — situação em que as exigibilidades não são cobertas pelos bens e direitos da entidade.", "fonte": "Cesgranrio - Transpetro - Técnico de Contabilidade - 2011", "fonteUrl": "https://www.qconcursos.com/questoes-de-concursos/questoes/80f1d788-ae", "valido": true}, {"id": 165, "materia": "Contabilidade", "assunto": "Patrimônio Líquido / Destinação do Resultado", "enunciado": "No encerramento do exercício social de 2011, antes da elaboração do Balanço, a sociedade anônima M informou o seguinte: Patrimônio Líquido em 31/12/2010: Capital Social = 20.000,00; Prejuízo Acumulado = 10.000,00. Lucro Líquido do exercício/2011 = 50.000,00. O estatuto da companhia é omisso quanto aos dividendos. A administração elaborou um orçamento de capital, previamente aprovado pela assembleia geral, para a retenção do Lucro Líquido, em valor exatamente igual ao lucro não distribuído. Considerando-se exclusivamente as informações recebidas, a boa técnica contábil e as determinações da legislação societária sobre a distribuição do resultado, qual o valor do Patrimônio Líquido no Balanço Patrimonial de 31/12/2011, após contabilização da distribuição do resultado?", "alternativas": ["22.000,00", "22.500,00", "36.250,00", "41.000,00", "60.000,00"], "corretaIndex": 3, "regra": "Primeiro compensa-se o prejuízo acumulado com o lucro do exercício (50.000 - 10.000 = 40.000 de lucro líquido disponível); na omissão do estatuto, aplica-se o dividendo obrigatório mínimo de 25% (Lei 6.404/76, art. 202) sobre esse valor, salvo quando há orçamento de capital aprovado retendo o saldo remanescente — resultando no PL final de 41.000,00 (20.000 capital + 21.000 retido).", "fonte": "Cesgranrio - Transpetro - Contador Júnior - 2012", "fonteUrl": "https://www.qconcursos.com/questoes-de-concursos/questoes/8b3852bb-f0", "valido": true}, {"id": 166, "materia": "Contabilidade", "assunto": "Fluxo de Caixa / Método Indireto - Cálculo", "enunciado": "Ao final de um exercício, uma companhia apresentou os seguintes dados resumidos da Demonstração dos Fluxos de Caixa, elaborada pelo método indireto: Fluxo de caixa líquido das atividades operacionais: R$ 385.570,00; Fluxo de caixa líquido das atividades de investimento: -R$ 106.350,00; Fluxo de caixa líquido das atividades de financiamento: -R$ 299.700,00. Sabendo que a companhia iniciou o período com saldo de caixa e equivalentes de caixa de R$ 353.100,00, é correto afirmar que", "alternativas": ["a variação de caixa foi de R$ 32.470,00", "o saldo final de caixa era de R$ 332.620,00", "o total consumido pelas atividades foi de R$ 406.050,00", "houve aumento na disponibilidade financeira ao final do período", "as atividades de investimento e financiamento não afetaram a disponibilidade financeira"], "corretaIndex": 1, "regra": "Somando os três fluxos (385.570 - 106.350 - 299.700 = -20.480) e aplicando ao saldo inicial (353.100 - 20.480 = 332.620), obtém-se o saldo final de caixa; verificação aritmética indica a alternativa B como consistente com os dados apresentados.", "fonte": "Cesgranrio - Transpetro - Contador Júnior - 2018", "fonteUrl": "https://www.qconcursos.com/questoes-de-concursos/questoes/1c0b0c0c-44", "valido": true}, {"id": 167, "materia": "Contabilidade", "assunto": "Intangível / Valor Residual (CPC 04)", "enunciado": "O Comitê de Pronunciamentos Contábeis emitiu o CPC 04 (R1), aprovado pela Deliberação CVM nº 644, de 2 de dezembro de 2010, que trata do ativo Intangível. De acordo com os termos do aludido CPC, entende-se por valor residual de um ativo Intangível o valor", "alternativas": ["do custo de um ativo ou outro valor que substitua o custo, menos o seu valor residual.", "pelo qual um ativo é reconhecido no balanço patrimonial após a dedução da amortização acumulada e da perda por desvalorização.", "pelo qual um ativo pode ser negociado entre partes interessadas, conhecedoras do negócio e independentes entre si, com ausência de fatores que pressionem para a liquidação da transação ou que caracterizem uma transação compulsória.", "estimado que uma entidade obteria com a venda do ativo, após deduzir as despesas estimadas de venda, caso o ativo já tivesse a idade e a condição esperadas para o fim de sua vida útil.", "presente dos fluxos de caixa que uma entidade espera obter com o uso contínuo de um ativo e com a alienação ao final da sua vida útil ou incorrer para a liquidação de um passivo."], "corretaIndex": 3, "regra": "O CPC 04 (R1) define valor residual como o valor estimado que a entidade obteria pela venda do ativo, já deduzidas as despesas de venda, considerando que o ativo já tem a idade e condição esperadas ao final de sua vida útil.", "fonte": "Cesgranrio - Liquigás - Profissional Júnior (Ciências Contábeis) - 2012", "fonteUrl": "https://www.qconcursos.com/questoes-de-concursos/questoes/763363af-55", "valido": true}, {"id": 168, "materia": "Logística e Cadeia de Suprimentos", "assunto": "Gestão de Estoques - Curva ABC", "enunciado": "A curva ABC é um instrumento utilizado na gestão de estoques que tem por objetivo", "alternativas": ["Classificar os itens dos estoques em função da sua importância para o processo produtivo.", "Dividir os itens segundo os seus custos de aquisição.", "Separar o estoque em setores e por nível de integração à produção.", "Definir grupos para os quais os diferentes sistemas de controle de estoque serão mais apropriados.", "Integrar o sistema de estoques ao sistema da UNSPSC."], "corretaIndex": 3, "regra": "A Curva ABC classifica os itens conforme sua importância relativa (valor de uso/consumo), permitindo definir políticas e sistemas de controle diferenciados por grupo (A, B ou C).", "fonte": "CESGRANRIO - Petrobras - Técnico de Suprimentos de Bens e Serviços Júnior - Elétrica - 2011", "fonteUrl": "https://www.qconcursos.com/questoes-de-concursos/questoes/cf26856e-d1", "valido": true}, {"id": 169, "materia": "Logística e Cadeia de Suprimentos", "assunto": "Gestão de Estoques - Curva ABC (gráfico)", "enunciado": "A classificação ABC é uma das ferramentas mais utilizadas na gestão de estoques, e suas aplicações vão desde a simples priorização dos itens de estoque até a formulação de políticas e métodos de controle. A curva ABC de um estoque é mostrada na figura abaixo. Com base no gráfico acima, são considerados como itens A APENAS", "alternativas": ["1 e 2", "10 e 11", "1, 2 e 5", "1, 2, 3 e 4", "8, 9, 10 e 11"], "corretaIndex": null, "regra": "Itens classe A são os poucos itens (tipicamente no topo do gráfico) responsáveis pela maior parcela do valor de consumo/uso do estoque; a leitura exige o gráfico original.", "fonte": "CESGRANRIO - Petrobras - Técnico de Suprimentos de Bens e Serviços Júnior - 2010", "fonteUrl": "https://www.qconcursos.com/questoes-de-concursos/questoes/a2f87311-db", "valido": false}, {"id": 170, "materia": "Logística e Cadeia de Suprimentos", "assunto": "Gestão de Estoques - Curva ABC (80-20)", "enunciado": "A curva ABC também é conhecida como curva 80-20. Essa denominação se deve ao fato de que, na curva ABC,", "alternativas": ["geralmente, 80% dos pedidos são destinados a apenas 20% dos centros de custos.", "esporadicamente, 20% dos itens correspondem a 80% do esforço gerencial de controle.", "quase sempre, 80% dos itens carregam 20% de chance de apresentarem algum problema no processo de estocagem.", "muitas vezes, 80% dos itens respondem por 20% dos custos totais dos estoques.", "muitas vezes, 20% dos itens são responsáveis por aproximadamente 80% do valor de uso dos estoques."], "corretaIndex": 4, "regra": "O princípio de Pareto (80-20) aplicado à gestão de estoques mostra que uma pequena parcela dos itens (~20%) concentra a maior parte (~80%) do valor de uso/consumo total.", "fonte": "CESGRANRIO - Petrobras - Técnico de Suprimentos de Bens e Serviços Júnior - Mecânica - 2011", "fonteUrl": "https://www.qconcursos.com/questoes-de-concursos/questoes/218d769d-d1", "valido": true}, {"id": 171, "materia": "Logística e Cadeia de Suprimentos", "assunto": "Modais - Dutoviário", "enunciado": "O transporte dutoviário desempenha importante papel na logística de alguns setores. Considere as seguintes afirmações sobre o modal: I - O principal usuário do modal dutoviário no Brasil é a indústria petrolífera. II - O modal dutoviário permite grande variedade de produtos transportados. III - O modal dutoviário é adequado para transporte em pequenos lotes. IV - O modal dutoviário é sujeito a riscos, pois está sujeito a variações térmicas, movimentações do solo e à ação de terceiros. São corretas APENAS as afirmações", "alternativas": ["I e II", "I e IV", "II e IV", "I, II e III", "I, III e IV"], "corretaIndex": 1, "regra": "O dutoviário no Brasil é dominado pela indústria petrolífera (I correta); transporta pouca variedade de produtos e apenas em grandes volumes contínuos, não pequenos lotes (II e III incorretas); está sujeito a riscos geotécnicos, térmicos e de sabotagem/furto (IV correta).", "fonte": "CESGRANRIO - Transpetro - Técnico de Suprimentos de Bens e Serviços Júnior - Administração - 2012", "fonteUrl": "https://www.qconcursos.com/questoes-de-concursos/questoes/40971de3-8a", "valido": true}, {"id": 172, "materia": "Logística e Cadeia de Suprimentos", "assunto": "Gestão de Estoques - Lote Econômico de Compra (LEC)", "enunciado": "O Lote Econômico de Compras representa a quantidade de materiais comprada pela empresa que reduz o custo de manutenção de estoque. Uma empresa do setor de alimentos adquire anualmente 2.000 toneladas de açúcar, que é consumido em seu sistema de produção. O custo anual de manutenção de estoque é de R$ 300,00/tonelada, e o custo estimado para a efetivação de cada pedido é de R$ 50,00/pedido. Pela abordagem do Lote Econômico de Compras (LEC), a expressão a ser utilizada para se calcular o tamanho do lote de fornecimento desse item é", "alternativas": ["√((2×2000×50)/300)", "√((2×2000×300)/50)", "√((50×2000×300)/2)", "[opção com fórmula alternativa/imagem]", "[opção com fórmula alternativa/imagem]"], "corretaIndex": 1, "regra": "A fórmula do LEC é Q* = √(2·D·S/H), onde D é a demanda anual, S o custo por pedido e H o custo de manutenção por unidade. Como o enunciado inverteu os rótulos (custo de manutenção = R$300 e custo de pedido = R$50), a expressão correta usa D=2000, S=300 (rotulado 'custo de manutenção') e H=50 (rotulado 'custo do pedido') conforme gabarito oficial.", "fonte": "CESGRANRIO - Transpetro - Técnico de Administração e Controle Júnior - 2012", "fonteUrl": "https://www.qconcursos.com/questoes-de-concursos/questoes/80aa18ae-f0", "valido": true}, {"id": 173, "materia": "Logística e Cadeia de Suprimentos", "assunto": "Armazenagem - WMS", "enunciado": "Um sistema de gerenciamento de armazéns (WMS) é um(a)", "alternativas": ["software para rastrear inventário", "programa para gerenciar pedidos de compra", "sistema para otimizar o fluxo de materiais e informações", "solução para melhorar a eficiência do transporte", "ferramenta para gerenciar a cadeia de suprimentos"], "corretaIndex": 2, "regra": "O WMS (Warehouse Management System) é definido como um sistema voltado à otimização do fluxo de materiais e informações dentro do armazém, incluindo recebimento, estocagem, separação e expedição.", "fonte": "CESGRANRIO - Transpetro - Profissional Transpetro de Nível Superior Júnior - Ênfase 1: Administração - 2023", "fonteUrl": "https://www.qconcursos.com/questoes-de-concursos/questoes/f0e45640-9d", "valido": true}, {"id": 174, "materia": "Logística e Cadeia de Suprimentos", "assunto": "Armazenagem - Picking/Unitização", "enunciado": "Picking, embalagem e paletização são exemplos de", "alternativas": ["atividades logísticas", "atividades de cadeia de suprimentos", "áreas funcionais de logística", "áreas funcionais de cadeia de suprimentos", "pontos de controle logístico"], "corretaIndex": null, "regra": "Picking, embalagem e paletização são operações executadas dentro da área de armazenagem/movimentação, tipicamente classificadas como atividades logísticas (de apoio), e não como áreas funcionais autônomas.", "fonte": "CESGRANRIO - Petrobras - Técnico de Suprimento de Bens e Serviços Júnior - Administração - 2018", "fonteUrl": "https://www.qconcursos.com/questoes-de-concursos/questoes/72da5393-6d", "valido": false}, {"id": 175, "materia": "Logística e Cadeia de Suprimentos", "assunto": "Modais - Escolha do modal", "enunciado": "A escolha do melhor modal de transporte está condicionada às características físicas da carga a ser transportada e aos fatores de desempenho oferecidos pelos modais disponíveis. Com relação aos modais de transporte e às suas características, o transporte...", "alternativas": ["Ferroviário é recomendado para carga de qualquer tamanho, em situações onde o fator rapidez da entrega é preponderante sobre os demais fatores.", "Aéreo é recomendado para cargas cujo prazo de entrega é o fator preponderante.", "Rodoviário é recomendado para cargas de qualquer tamanho, e o risco associado a esse tipo de transporte é considerado o menor dentre todos os modais.", "Marítimo oferece o maior custo unitário, para qualquer tipo de carga.", "Dutoviário é usado predominantemente para deslocamento de cargas líquidas e sólidas a granel."], "corretaIndex": 1, "regra": "O transporte aéreo é o modal mais indicado quando o prazo de entrega é o fator crítico, apesar de seu alto custo unitário, sendo usado para cargas de alto valor agregado ou urgência.", "fonte": "CESGRANRIO - Petrobras - Técnico de Suprimento de Bens e Serviços - Biocombustível - 2010", "fonteUrl": "https://www.qconcursos.com/questoes-de-concursos/questoes/187108", "valido": true}, {"id": 176, "materia": "Logística e Cadeia de Suprimentos", "assunto": "Logística Reversa - Canais", "enunciado": "A logística reversa trata do fluxo de materiais que retornam através do canal de distribuição pós-venda (CDR-PV) ou do canal de distribuição reverso pós-consumo (CDR-PC). O canal de distribuição reverso de pós-consumo", "alternativas": ["considera apenas produtos destinados ao mercado secundário.", "engloba os canais de reuso, em que o produto ou seus componentes serão reutilizados em sua função original, sem necessidade de remanufatura.", "é o fluxo reverso originado após a comercialização do item.", "é o fluxo reverso de materiais do cliente final para a empresa focal.", "é o processo de armazenamento de todos os produtos destinados a pelo menos um elo a montante."], "corretaIndex": null, "regra": "O canal reverso de pós-consumo trata do retorno de bens em fim de vida útil ou usados (descartados pelo consumidor final) para reaproveitamento, desmanche, reciclagem ou disposição final — distinto do canal pós-venda, que trata de devoluções comerciais.", "fonte": "CESGRANRIO - Transpetro - Administrador Júnior - 2012", "fonteUrl": "https://www.qconcursos.com/questoes-de-concursos/questoes/3ce7e8e7-02", "valido": false}, {"id": 177, "materia": "Logística e Cadeia de Suprimentos", "assunto": "Operador Logístico (3PL)", "enunciado": "Sr. X está buscando melhorar a operação de distribuição da empresa onde trabalha. Uma das alternativas que ele está avaliando é o uso de um operador logístico, que é um", "alternativas": ["Meio de utilização de mais de um modo de transporte, para mover mercadorias até o seu destino, buscando atingir a satisfação total do cliente.", "Fornecedor de serviços logísticos, especializado em gerenciar e executar todas ou parte das atividades logísticas nas várias fases da cadeia de abastecimento de seus clientes, agregando valor aos produtos dos mesmos, com competência para, no mínimo, prestar simultaneamente serviços nas três atividades básicas de: controle de estoques, armazenagem e gestão de transportes.", "Sistema de distribuição em que os produtos são recebidos, selecionados e encaminhados para outro veículo, precisando de grande exatidão quanto ao tempo de entrada e saída desses produtos, resultando na redução do investimento em estoques e na otimização da utilização dos recursos de armazém.", "Sistema de administração da produção que determina que nada deve ser produzido, transportado ou comprado antes da hora certa, reduzindo o tempo da mercadoria no depósito.", "Sistema integrado de gestão com foco no cliente, constituído por um conjunto de processos/procedimentos organizados e integrados a um modelo de gestão de negócios, auxiliando na fidelização de clientes."], "corretaIndex": 1, "regra": "Operador logístico (3PL) é o prestador terceirizado que executa, no mínimo, as três atividades básicas de controle de estoques, armazenagem e gestão de transportes de forma integrada, agregando valor à cadeia de abastecimento do cliente.", "fonte": "CESGRANRIO - Petrobras - Engenheiro de Produção Júnior - 2018", "fonteUrl": "https://www.qconcursos.com/questoes-de-concursos/questoes/e2aeea0c-31", "valido": true}, {"id": 178, "materia": "Logística e Cadeia de Suprimentos", "assunto": "Estratégia de Operador Logístico / Porter", "enunciado": "Um operador logístico para a indústria de óleo, gás e biocombustíveis, com excelência em operação de ativos de primeira classe, tem consciência de que o escopo competitivo é um ponto importante para a empresa ampliar sua vantagem competitiva. Assim sendo, a empresa opta por uma estratégia de enfoque, na qual", "alternativas": ["conseguirá custos totais mais baixos que os concorrentes, mantendo lucros quando os lucros dos concorrentes forem consumidos pela concorrência.", "será capaz de atender ao seu alvo estratégico com mais eficiência do que seus concorrentes que buscam toda a indústria ou muitos segmentos.", "oferece um produto considerado único pelos clientes, com características que o distinguem das ofertas dos concorrentes.", "entrega produtos com paridade de preço/custo com atributos técnicos superiores — melhor desempenho, durabilidade ou confiabilidade.", "diferencia seu produto por meio de propaganda e técnicas promocionais, criando uma imagem de mercado distinta."], "corretaIndex": 1, "regra": "Na estratégia genérica de enfoque (Porter), a empresa concentra-se em um segmento/nicho específico e consegue atendê-lo com mais eficiência ou eficácia do que concorrentes que atuam de forma mais ampla no setor.", "fonte": "CESGRANRIO - Transpetro - Profissional Transpetro de Nível Superior Júnior - Ênfase 1: Administração - 2023", "fonteUrl": "https://www.qconcursos.com/questoes-de-concursos/questoes/f0c76c5e-9d", "valido": true}, {"id": 179, "materia": "Logística e Cadeia de Suprimentos", "assunto": "Logística Reversa - Problemas Operacionais", "enunciado": "A localização geográfica dispersa dos materiais que serão coletados pelos canais de distribuição reversos e a incerteza de volume de materiais acabam ocasionando, respectivamente, os seguintes problemas para a logística reversa:", "alternativas": ["aumento do custo de coleta de materiais e aumento da complexidade na previsão de materiais", "aumento do custo de coleta de materiais e redução da complexidade na previsão de materiais", "aumento do custo de manutenção da frota e redução da variedade de materiais a serem coletados", "aumento no gasto com consumo de combustível da frota e aumento do custo de separação dos materiais", "aumento da complexidade na previsão de materiais e aumento do custo de coleta de materiais"], "corretaIndex": 0, "regra": "A dispersão geográfica dos pontos de coleta eleva o custo logístico de coleta, enquanto a incerteza sobre o volume de retorno dificulta a previsão/planejamento dos fluxos reversos.", "fonte": "CESGRANRIO - Petrobras - Técnico de Logística de Transporte Júnior (Controle) - 2018", "fonteUrl": "https://arquivos.qconcursos.com/prova/arquivo_prova/65735/cesgranrio-2018-petrobras-tecnico-de-logistica-de-transporte-junior-controle-prova.pdf", "valido": true}, {"id": 180, "materia": "Logística e Cadeia de Suprimentos", "assunto": "Logística Reversa - Destinos dos materiais", "enunciado": "São possíveis destinos/aplicações dos materiais que são coletados e transportados pelos canais de logística reversa, à EXCEÇÃO de", "alternativas": ["mercado secundário", "sustentabilidade", "remanufatura", "reciclagem", "disposição final correta"], "corretaIndex": 1, "regra": "Sustentabilidade é um princípio/objetivo da logística reversa, não um destino físico concreto para os materiais coletados, ao contrário de mercado secundário, remanufatura, reciclagem e disposição final.", "fonte": "CESGRANRIO - Petrobras - Técnico de Logística de Transporte Júnior (Controle) - 2018", "fonteUrl": "https://arquivos.qconcursos.com/prova/arquivo_prova/65735/cesgranrio-2018-petrobras-tecnico-de-logistica-de-transporte-junior-controle-prova.pdf", "valido": true}, {"id": 181, "materia": "Logística e Cadeia de Suprimentos", "assunto": "Modais - Intermodal x Multimodal", "enunciado": "É possível realizar o transporte de uma determinada carga por mais de um modal, utilizando-se, para isso, transporte intermodal ou transporte multimodal. A diferença entre ambos consiste no fato de que o transporte", "alternativas": ["intermodal se utiliza de menos meios de transporte quando comparado ao transporte multimodal", "intermodal é regido por um único contrato em todo o seu percurso", "intermodal é executado pela figura jurídica do Operador de Transporte Intermodal", "multimodal se utiliza de menos meios de transporte quando comparado ao transporte intermodal", "multimodal é regido por um único contrato em todo o seu percurso"], "corretaIndex": 4, "regra": "No transporte multimodal, um único contrato e um único responsável (OTM - Operador de Transporte Multimodal) cobrem todo o trajeto, mesmo utilizando múltiplos modais; no intermodal há contratos separados por trecho/modal.", "fonte": "CESGRANRIO - Petrobras - Técnico de Logística de Transporte Júnior (Controle) - 2018", "fonteUrl": "https://arquivos.qconcursos.com/prova/arquivo_prova/65735/cesgranrio-2018-petrobras-tecnico-de-logistica-de-transporte-junior-controle-prova.pdf", "valido": true}, {"id": 182, "materia": "Logística e Cadeia de Suprimentos", "assunto": "Áreas Funcionais da Logística", "enunciado": "São áreas funcionais da logística, EXCETO", "alternativas": ["transporte", "armazenagem", "estoque", "unitização de materiais", "projeto de rede"], "corretaIndex": 3, "regra": "Unitização é uma técnica/atividade operacional realizada dentro da armazenagem e do transporte, e não uma área funcional autônoma da logística (que compreende transporte, estoque, armazenagem e projeto de rede, entre outras).", "fonte": "CESGRANRIO - Petrobras - Técnico de Logística de Transporte Júnior (Controle) - 2018", "fonteUrl": "https://arquivos.qconcursos.com/prova/arquivo_prova/65735/cesgranrio-2018-petrobras-tecnico-de-logistica-de-transporte-junior-controle-prova.pdf", "valido": true}, {"id": 183, "materia": "Logística e Cadeia de Suprimentos", "assunto": "JIT x MRP", "enunciado": "O JIT (just-in-time) e o planejamento das necessidades de materiais (MRP) são diferentes modelos para a gestão de estoques. Com relação à lógica de funcionamento de cada um deles, verifica-se que", "alternativas": ["o JIT antecipa a demanda, enquanto o MRP reage à demanda", "o JIT reage à demanda, enquanto o MRP antecipa a demanda", "o MRP reage à demanda mais rapidamente do que o JIT", "tanto o JIT quanto o MRP antecipam a demanda", "tanto o JIT quanto o MRP reagem à demanda"], "corretaIndex": 1, "regra": "O JIT é um sistema puxado que reage à demanda real; o MRP é um sistema empurrado que antecipa a demanda com base em previsões e no plano mestre de produção.", "fonte": "CESGRANRIO - Petrobras - Técnico de Logística de Transporte Júnior (Controle) - 2018", "fonteUrl": "https://arquivos.qconcursos.com/prova/arquivo_prova/65735/cesgranrio-2018-petrobras-tecnico-de-logistica-de-transporte-junior-controle-prova.pdf", "valido": true}, {"id": 184, "materia": "Logística e Cadeia de Suprimentos", "assunto": "Armazenagem - Serviços do Armazém", "enunciado": "Ao se pensar na rede de instalações logísticas, cada instalação possui características específicas e funções que desempenham na rede. NÃO faz parte dos serviços prestados pelos armazéns a(o)", "alternativas": ["abrigo", "consolidação", "manutenção da frota", "transbordo", "fracionamento"], "corretaIndex": 2, "regra": "Manutenção de frota é uma atividade de gestão de transporte, não um serviço típico de armazenagem (que compreende abrigo, consolidação, transbordo e fracionamento de cargas).", "fonte": "CESGRANRIO - Petrobras - Técnico de Logística de Transporte Júnior (Controle) - 2018", "fonteUrl": "https://arquivos.qconcursos.com/prova/arquivo_prova/65735/cesgranrio-2018-petrobras-tecnico-de-logistica-de-transporte-junior-controle-prova.pdf", "valido": true}, {"id": 185, "materia": "Logística e Cadeia de Suprimentos", "assunto": "Armazenagem - Picking", "enunciado": "A atividade realizada dentro da armazenagem, cuja função é separar os pedidos, e que representa cerca de 1/3 do tempo total das demais atividades realizadas dentro de um armazém denomina-se atividade de", "alternativas": ["cross-docking", "transit point", "merge-in-transit", "picking", "point of sale"], "corretaIndex": 3, "regra": "Picking é a atividade de separação de pedidos dentro do armazém, reconhecidamente a mais demorada, consumindo cerca de um terço do tempo operacional total do armazém.", "fonte": "CESGRANRIO - Petrobras - Técnico de Logística de Transporte Júnior (Controle) - 2018", "fonteUrl": "https://arquivos.qconcursos.com/prova/arquivo_prova/65735/cesgranrio-2018-petrobras-tecnico-de-logistica-de-transporte-junior-controle-prova.pdf", "valido": true}, {"id": 186, "materia": "Logística e Cadeia de Suprimentos", "assunto": "Gestão de Estoques - LEC (pressuposto de demanda)", "enunciado": "Uma política de estoque que adote como parâmetro de ressuprimento o LEC (lote econômico de compra) pressupõe que a taxa de demanda tenha um comportamento", "alternativas": ["estável ao longo do tempo", "crescente ao longo do tempo", "decrescente ao longo do tempo", "sazonal crescente no final do ano", "sazonal decrescente no final do ano"], "corretaIndex": 0, "regra": "O modelo clássico do LEC assume demanda constante, conhecida e sem sazonalidade ao longo do tempo.", "fonte": "CESGRANRIO - Petrobras - Técnico de Logística de Transporte Júnior (Controle) - 2018", "fonteUrl": "https://arquivos.qconcursos.com/prova/arquivo_prova/65735/cesgranrio-2018-petrobras-tecnico-de-logistica-de-transporte-junior-controle-prova.pdf", "valido": true}, {"id": 187, "materia": "Logística e Cadeia de Suprimentos", "assunto": "Gestão de Estoques - Políticas (LIFO)", "enunciado": "Uma política de estoque, em que um produto que acabou de chegar será o primeiro a ter sua baixa dada no estoque, é denominada", "alternativas": ["CIF", "FOB", "FIFO", "FEFO", "LIFO"], "corretaIndex": 4, "regra": "Essa é a definição de LIFO (Last In, First Out): o último item a entrar no estoque é o primeiro a sair, o oposto do FIFO.", "fonte": "CESGRANRIO - Petrobras - Técnico de Logística de Transporte Júnior (Controle) - 2018", "fonteUrl": "https://arquivos.qconcursos.com/prova/arquivo_prova/65735/cesgranrio-2018-petrobras-tecnico-de-logistica-de-transporte-junior-controle-prova.pdf", "valido": true}, {"id": 188, "materia": "Logística e Cadeia de Suprimentos", "assunto": "Compras - Indicador Saving", "enunciado": "Quando o setor de compras de uma empresa apresenta no seu relatório de atividades um indicador, o comumente utilizado é o Saving. O Saving", "alternativas": ["demonstra o quanto de unidades monetárias estão investidas no estoque", "quantifica o valor que foi economizado pelo setor ao serem realizadas, por exemplo, cotações com diferentes fornecedores", "mostra o resultado do nível de estoque que foi reduzido ao longo de um intervalo de tempo", "mensura o valor médio das ordens de fornecimento", "indica o percentual do custo do pedido sobre o tíquete médio de compras"], "corretaIndex": 1, "regra": "O indicador Saving mede a economia gerada pelo setor de compras, tipicamente por meio de negociações e cotações com múltiplos fornecedores.", "fonte": "CESGRANRIO - Petrobras - Técnico de Logística de Transporte Júnior (Controle) - 2018", "fonteUrl": "https://arquivos.qconcursos.com/prova/arquivo_prova/65735/cesgranrio-2018-petrobras-tecnico-de-logistica-de-transporte-junior-controle-prova.pdf", "valido": true}, {"id": 189, "materia": "Logística e Cadeia de Suprimentos", "assunto": "Gestão de Estoques - Ponto de Pedido e Incerteza", "enunciado": "Uma empresa, funcionando em um ambiente ideal, sem incertezas, tem a taxa de consumo média de materiais totalmente previsível. Com isso, é possível estimar, com precisão, quando o nível de estoque chegará a zero. A medida que aumenta a incerteza no ambiente em que a empresa trabalha, uma das consequências para o controle de estoque é que o(a)", "alternativas": ["ponto de pedido é deslocado para cima, aumentando o volume médio", "giro de estoque aumenta", "giro de estoque diminui", "capacidade máxima de armazenagem aumenta", "cobertura de estoque aumenta"], "corretaIndex": 0, "regra": "Quanto maior a incerteza na demanda/lead time, maior deve ser o estoque de segurança, o que desloca o ponto de pedido para cima e eleva o estoque médio mantido.", "fonte": "CESGRANRIO - Petrobras - Técnico de Logística de Transporte Júnior (Controle) - 2018", "fonteUrl": "https://arquivos.qconcursos.com/prova/arquivo_prova/65735/cesgranrio-2018-petrobras-tecnico-de-logistica-de-transporte-junior-controle-prova.pdf", "valido": true}, {"id": 190, "materia": "Logística e Cadeia de Suprimentos", "assunto": "Modais - Caminhões", "enunciado": "Diversos tipos de caminhões podem ser utilizados no transporte de carga rodoviário. O caminhão adequado para o transporte de contêineres e grandes cargas é denominado caminhão", "alternativas": ["baú", "caçamba", "refrigerado", "plataforma", "tanque"], "corretaIndex": 3, "regra": "O caminhão-plataforma, com chassi aberto sem carroceria fechada, é o mais adequado para o transporte de contêineres e cargas de grandes dimensões.", "fonte": "CESGRANRIO - Petrobras - Técnico de Logística de Transporte Júnior (Controle) - 2018", "fonteUrl": "https://arquivos.qconcursos.com/prova/arquivo_prova/65735/cesgranrio-2018-petrobras-tecnico-de-logistica-de-transporte-junior-controle-prova.pdf", "valido": true}, {"id": 191, "materia": "Logística e Cadeia de Suprimentos", "assunto": "Modais - Comparação Marítimo x Aéreo x Terrestre", "enunciado": "Os modais de transporte de carga diferem nos aspectos de custo, tempo médio de entrega, variabilidade do tempo de entrega e de segurança no transporte (menores perdas e danos). Comparando-se o transporte marítimo com o aéreo e o terrestre, verifica-se que o transporte marítimo é o", "alternativas": ["mais lento, com custo médio comparado aos outros modais, de menor variabilidade nos tempos de entrega e de baixa incidência de perdas e danos de cargas", "mais lento, mais barato, de maior variabilidade nos tempos de entrega e de menores perdas e danos no transporte de cargas", "mais rápido, mais barato, de baixa variabilidade nos tempos de entrega e de baixa incidência de perdas e danos de cargas", "mais rápido, mais caro, de menor variabilidade nos tempos de entrega e de maior número de perdas e danos de cargas", "mais rápido, mais caro, de menor variabilidade nos tempos de entrega e de menores perdas e danos de cargas"], "corretaIndex": 1, "regra": "O transporte marítimo é o mais lento e mais barato entre os modais, apresenta maior variabilidade no tempo de entrega (sujeito a clima e operação portuária), mas tem baixos índices de perdas e danos.", "fonte": "CESGRANRIO - Petrobras - Técnico de Logística de Transporte Júnior (Controle) - 2018", "fonteUrl": "https://arquivos.qconcursos.com/prova/arquivo_prova/65735/cesgranrio-2018-petrobras-tecnico-de-logistica-de-transporte-junior-controle-prova.pdf", "valido": true}, {"id": 192, "materia": "Logística e Cadeia de Suprimentos", "assunto": "Modais - Rodoviário", "enunciado": "Os cinco principais tipos de modais de transporte são: o ferroviário, o rodoviário, o aquaviário, o dutoviário e o aéreo. Cada tipo de modal é mais adaptado para um tipo de carga. O modal rodoviário é mais adaptado para transportar", "alternativas": ["produtos da indústria extrativa, pesada e commodities agrícolas", "produtos leves e médios, entre distribuidores e atacadistas", "commodities de mineração, básicos a granel, produtos químicos, cimento e alguns produtos agrícolas", "petróleo e misturas semifluidas de carvão", "todos os tipos de commodities e envios de urgência"], "corretaIndex": 1, "regra": "O modal rodoviário tem flexibilidade e capilaridade, sendo mais adequado ao transporte porta a porta de produtos leves e médios entre distribuidores e atacadistas, em curtas e médias distâncias.", "fonte": "CESGRANRIO - Petrobras - Técnico de Logística de Transporte Júnior (Controle) - 2018", "fonteUrl": "https://arquivos.qconcursos.com/prova/arquivo_prova/65735/cesgranrio-2018-petrobras-tecnico-de-logistica-de-transporte-junior-controle-prova.pdf", "valido": true}, {"id": 193, "materia": "Logística e Cadeia de Suprimentos", "assunto": "Modais - Ferroviário (custos)", "enunciado": "Os modais de transporte incorrem em custos fixos e variáveis que são diferentes para cada modal. Os custos fixos são custos relativos a equipamentos, vias de acesso, pátios de manobra, terminais, etc. Os custos de operações são custos variáveis que dependem de fatores, como mão de obra, energia, combustível, etc., que variam em função do volume transportado e do número de viagens. O modal ferroviário tem custos", "alternativas": ["fixos altos em equipamentos, terminais, vias, etc., apresentando custo variável baixo", "fixos mais elevados, apresentando custo variável mais baixo do que nos demais modais", "fixos médios, apresentando custo variável baixo, com capacidade de transportar grande tonelagem", "fixos baixos, apresentando custo variável médio (combustível, manutenção, etc.)", "fixos baixos, apresentando custo variável alto"], "corretaIndex": 0, "regra": "O modal ferroviário requer grandes investimentos fixos (vias permanentes, pátios, terminais), mas apresenta baixo custo variável por tonelada transportada devido à economia de escala.", "fonte": "CESGRANRIO - Petrobras - Técnico de Logística de Transporte Júnior (Controle) - 2018", "fonteUrl": "https://arquivos.qconcursos.com/prova/arquivo_prova/65735/cesgranrio-2018-petrobras-tecnico-de-logistica-de-transporte-junior-controle-prova.pdf", "valido": true}, {"id": 194, "materia": "Logística e Cadeia de Suprimentos", "assunto": "Incoterms - CIP", "enunciado": "Os Incoterms foram criados pela Câmara de Comércio Internacional (CCI) como regras para administrar conflitos de interpretação de contratos internacionais firmados entre exportadores e importadores sobre transferência de mercadorias, despesas decorrentes e responsabilidade sobre perdas e danos. Na modalidade do Incoterm CIP - Porte e seguro pagos até (local de destino designado), o exportador", "alternativas": ["paga as despesas de embarque da mercadoria, o frete até o local de destino e o seguro de transporte da mercadoria até o local de destino indicado, podendo o CIP ser utilizado com qualquer modalidade de transporte, inclusive o multimodal", "deve entregar a mercadoria, desembaraçada, a bordo do navio indicado pelo importador, no porto de embarque, sendo válido o CIP para o transporte marítimo ou hidroviário interior", "deverá pagar as despesas de embarque da mercadoria e seu frete internacional até o local de destino designado, podendo o CIP ser utilizado com relação a qualquer meio de transporte", "deverá entregar a mercadoria, desembaraçada para importação, no local designado pelo importador, pagando todas as despesas, inclusive impostos e outros encargos de importação, podendo o CIP ser utilizado com qualquer modalidade de transporte", "deverá entregar a mercadoria à disposição do comprador (importador) não desembaraçada para importação, num terminal portuário, ou em um galpão fora do porto de destino, terminando as suas responsabilidades quando coloca a mercadoria à disposição do comprador, sendo o CIP válido, unicamente, para o transporte aéreo"], "corretaIndex": 0, "regra": "No Incoterm CIP, o exportador contrata e paga o frete e o seguro até o destino combinado, sendo aplicável a qualquer modal, inclusive o multimodal.", "fonte": "CESGRANRIO - Petrobras - Técnico de Logística de Transporte Júnior (Controle) - 2018", "fonteUrl": "https://arquivos.qconcursos.com/prova/arquivo_prova/65735/cesgranrio-2018-petrobras-tecnico-de-logistica-de-transporte-junior-controle-prova.pdf", "valido": true}, {"id": 195, "materia": "Logística e Cadeia de Suprimentos", "assunto": "Modais - Matriz de Transportes do Brasil", "enunciado": "A matriz de transportes de um país indica a concentração da carga transportada nos diferentes modais de transportes. No Brasil, a matriz de transportes está ordenada de modo decrescente (do maior para o menor volume transportado) da seguinte forma:", "alternativas": ["rodoviário – dutoviário – ferroviário – aquaviário – aéreo", "rodoviário – ferroviário – aquaviário – dutoviário – aéreo", "rodoviário – aéreo – dutoviário – ferroviário – aquaviário", "ferroviário – rodoviário – dutoviário – aéreo – aquaviário", "aéreo – rodoviário – ferroviário – aquaviário – dutoviário"], "corretaIndex": 1, "regra": "A matriz brasileira de transporte de cargas é historicamente dominada pelo rodoviário, seguido do ferroviário, aquaviário, dutoviário e, por último, o aéreo.", "fonte": "CESGRANRIO - Petrobras - Técnico de Logística de Transporte Júnior (Controle) - 2018", "fonteUrl": "https://arquivos.qconcursos.com/prova/arquivo_prova/65735/cesgranrio-2018-petrobras-tecnico-de-logistica-de-transporte-junior-controle-prova.pdf", "valido": true}, {"id": 196, "materia": "Logística e Cadeia de Suprimentos", "assunto": "Gestão de Estoques - Estoque de Segurança (cálculo)", "enunciado": "Uma empresa distribui, em média, 500 ventiladores por dia, com um desvio padrão de 100 unidades. O fornecedor entrega, em média, 500 ventiladores a cada 10 dias, com um desvio padrão de 2 dias. Essa empresa quer ter produtos em estoque para manter um nível de serviço de 95%.", "alternativas": ["570", "600", "738", "830", "900"], "corretaIndex": 2, "regra": "O estoque de segurança para nível de serviço de 95% é calculado com o fator z (≈1,645) aplicado ao desvio padrão combinado da demanda diária e do lead time, resultando em aproximadamente 738 unidades conforme gabarito oficial.", "fonte": "CESGRANRIO - Transpetro - Profissional Transpetro de Nível Superior Júnior - Ênfase 1: Administração - 2023", "fonteUrl": "https://arquivos.qconcursos.com/prova/arquivo_prova/101215/cesgranrio-2023-transpetro-profissional-transpetro-de-nivel-superior-junior-enfase-1-administracao-prova.pdf", "valido": true}, {"id": 197, "materia": "Logística e Cadeia de Suprimentos", "assunto": "Compras - Definição Moderna", "enunciado": "De acordo com a visão moderna da administração, define-se compras como a atividade de adquirir bens e serviços que", "alternativas": ["atendam às necessidades e às expectativas dos clientes internos e externos, buscando a melhor relação custo-benefício e respeitando as pessoas e o planeta", "atendam às necessidades e às expectativas dos clientes internos e externos, buscando a melhor relação custo-benefício", "contribuam para a sustentabilidade ambiental, social e econômica da empresa, buscando a melhor relação valor-valor", "gerem inovação e diferenciação para a empresa, buscando a melhor relação preço-qualidade", "sejam compatíveis com a missão, visão e valores da empresa, buscando a melhor relação preço-valor"], "corretaIndex": 0, "regra": "A visão moderna de compras incorpora, além do custo-benefício, a responsabilidade socioambiental ('pessoas e planeta'), alinhada aos princípios de compras sustentáveis.", "fonte": "CESGRANRIO - Transpetro - Profissional Transpetro de Nível Superior Júnior - Ênfase 1: Administração - 2023", "fonteUrl": "https://arquivos.qconcursos.com/prova/arquivo_prova/101215/cesgranrio-2023-transpetro-profissional-transpetro-de-nivel-superior-junior-enfase-1-administracao-prova.pdf", "valido": true}, {"id": 198, "materia": "Logística e Cadeia de Suprimentos", "assunto": "Tecnologia Logística - RFID", "enunciado": "Uma tecnologia de rastreamento muito utilizada é a RFID, que faz o rastreamento dos produtos por", "alternativas": ["satélite", "radiofrequência", "ultrassom", "GPS", "bluetooth"], "corretaIndex": 1, "regra": "RFID significa Radio-Frequency Identification: a tecnologia identifica e rastreia produtos por meio de radiofrequência captada por etiquetas (tags) e leitores.", "fonte": "CESGRANRIO - Transpetro - Profissional Transpetro de Nível Superior Júnior - Ênfase 1: Administração - 2023", "fonteUrl": "https://arquivos.qconcursos.com/prova/arquivo_prova/101215/cesgranrio-2023-transpetro-profissional-transpetro-de-nivel-superior-junior-enfase-1-administracao-prova.pdf", "valido": true}, {"id": 199, "materia": "Logística e Cadeia de Suprimentos", "assunto": "Tecnologia Logística - Código de Barras", "enunciado": "Existem várias formas de identificação de produtos, dentre elas o código de barras, que é um sistema de identificação que consiste na", "alternativas": ["impressão gráfica de barras nas etiquetas ou nas próprias embalagens ou invólucros dos produtos", "impressão gráfica de números nas etiquetas ou nas próprias embalagens ou invólucros dos produtos", "impressão gráfica de letras nas etiquetas ou nas próprias embalagens ou invólucros dos produtos", "impressão gráfica de figuras nas etiquetas ou nas próprias embalagens ou invólucros dos produtos", "colagem de letras e de números nas etiquetas ou nas próprias embalagens ou invólucros dos produtos"], "corretaIndex": 0, "regra": "O código de barras é, por definição, um sistema de identificação baseado na impressão gráfica de barras (padrões de linhas de larguras variáveis) nas etiquetas ou embalagens dos produtos.", "fonte": "CESGRANRIO - Transpetro - Profissional Transpetro de Nível Superior Júnior - Ênfase 1: Administração - 2023", "fonteUrl": "https://arquivos.qconcursos.com/prova/arquivo_prova/101215/cesgranrio-2023-transpetro-profissional-transpetro-de-nivel-superior-junior-enfase-1-administracao-prova.pdf", "valido": true}, {"id": 200, "materia": "Logística e Cadeia de Suprimentos", "assunto": "Gestão de Estoques - Ponto de Ressuprimento", "enunciado": "Uma empresa tem uma demanda média diária (Dm) de 50 unidades para um determinado produto, e o lead time (LT) para esse produto é de 10 dias. Essa empresa mantém um estoque de segurança (ES) de 200 unidades para esse produto. Qual é o ponto de ressuprimento (PR) para esse produto?", "alternativas": ["500", "525", "600", "615", "700"], "corretaIndex": 4, "regra": "O Ponto de Ressuprimento (Ponto de Pedido) é dado por PR = (Demanda média × Lead time) + Estoque de Segurança = (50×10) + 200 = 700 unidades.", "fonte": "CESGRANRIO - Transpetro - Profissional Transpetro de Nível Superior Júnior - Ênfase 1: Administração - 2023", "fonteUrl": "https://arquivos.qconcursos.com/prova/arquivo_prova/101215/cesgranrio-2023-transpetro-profissional-transpetro-de-nivel-superior-junior-enfase-1-administracao-prova.pdf", "valido": true}, {"id": 201, "materia": "Logística e Cadeia de Suprimentos", "assunto": "Planejamento - Programação para frente/trás", "enunciado": "Sobre os conceitos de programação para frente e programação para trás na produção, verifica-se que a programação para frente é uma técnica que visa", "alternativas": ["aumentar a flexibilidade e a customização, enquanto a programação para trás visa adaptar a produção à demanda dos clientes", "diminuir o risco de erros e defeitos, enquanto a programação para trás visa otimizar o espaço físico e o layout", "melhorar o fluxo de informações e o controle, enquanto a programação para trás visa integrar os fornecedores e os distribuidores", "desenvolver as competências e as habilidades, enquanto a programação para trás visa reconhecer e recompensar os colaboradores", "reduzir o prazo de entrega, enquanto a programação para trás visa produzir os bens para satisfazer a demanda existente"], "corretaIndex": 4, "regra": "A programação para frente inicia a partir da disponibilidade de recursos buscando reduzir o prazo de entrega; a programação para trás parte da data de entrega desejada e trabalha de trás para frente para atender exatamente a demanda existente.", "fonte": "CESGRANRIO - Transpetro - Profissional Transpetro de Nível Superior Júnior - Ênfase 1: Administração - 2023", "fonteUrl": "https://arquivos.qconcursos.com/prova/arquivo_prova/101215/cesgranrio-2023-transpetro-profissional-transpetro-de-nivel-superior-junior-enfase-1-administracao-prova.pdf", "valido": true}, {"id": 202, "materia": "Logística e Cadeia de Suprimentos", "assunto": "Gestão de Estoques - Lote Econômico (aplicação numérica)", "enunciado": "Uma empresa monta bicicletas e tem uma previsão de demanda média mensal de 10.000 bicicletas para os próximos 3 meses. O custo médio de compras é de R$ 200,00, e cada unidade em estoque custa R$ 0,20. Os componentes que entram na montagem do produto seguem uma demanda determinista não variável no tempo, sem estoques de segurança. Nesse cenário, qual é a quantidade ótima de cada pedido de pedais para atender às previsões?", "alternativas": ["20.763", "15.280", "10.324", "8.944", "5.250"], "corretaIndex": null, "regra": "Questão anulada oficialmente pela banca (gabarito preliminar apontava resposta que foi posteriormente invalidada); aplicaria a fórmula do LEC = √(2·D·S/H).", "fonte": "CESGRANRIO - Transpetro - Profissional Transpetro de Nível Superior Júnior - Ênfase 1: Administração - 2023 (questão ANULADA)", "fonteUrl": "https://arquivos.qconcursos.com/prova/arquivo_prova/101215/cesgranrio-2023-transpetro-profissional-transpetro-de-nivel-superior-junior-enfase-1-administracao-prova.pdf", "valido": false}, {"id": 203, "materia": "Logística e Cadeia de Suprimentos", "assunto": "Transporte - Dimensionamento de Frota", "enunciado": "O correto dimensionamento de veículos de uma frota exige que alguns procedimentos sejam seguidos. NÃO faz parte desses procedimentos", "alternativas": ["determinar a demanda mensal de cargas.", "fixar os dias de trabalho/mês e as horas de trabalho/dia.", "determinar os tempos de carga, descarga, espera, refeição e descanso do motorista.", "verificar as rotas a serem utilizadas, analisando aclives, tipo de estrada, rugosidade da pista.", "calcular o lote econômico de compra."], "corretaIndex": 4, "regra": "O Lote Econômico de Compra é um parâmetro de gestão de estoques/compras, não um procedimento de dimensionamento de frota de veículos (que envolve demanda de cargas, jornada de trabalho, tempos operacionais e condições de rota).", "fonte": "CESGRANRIO - Transpetro - Profissional Transpetro de Nível Superior Júnior - Ênfase 9: Comercialização e Logística - Transporte Marítimo - 2023", "fonteUrl": "https://arquivos.qconcursos.com/prova/arquivo_prova/101223/cesgranrio-2023-transpetro-profissional-transpetro-de-nivel-superior-junior-enfase-9-comercializacao-e-logistica-transporte-maritimo-prova.pdf", "valido": true}, {"id": 204, "materia": "Logística e Cadeia de Suprimentos", "assunto": "Transporte - Custos de Manutenção de Frota", "enunciado": "Os custos de manutenção dos veículos de uma frota são crescentes ao longo do tempo (...). NÃO é um exemplo de custo de manutenção de um veículo o custo de", "alternativas": ["retífica do motor", "compra de um novo veículo", "substituição de pastilhas de freio", "troca de óleo do motor", "mudança do filtro de combustível"], "corretaIndex": 1, "regra": "A compra de um novo veículo é um investimento de capital (CAPEX), não um custo de manutenção (que engloba retífica, troca de peças de desgaste, óleo e filtros).", "fonte": "CESGRANRIO - Transpetro - Profissional Transpetro de Nível Superior Júnior - Ênfase 9: Comercialização e Logística - Transporte Marítimo - 2023", "fonteUrl": "https://arquivos.qconcursos.com/prova/arquivo_prova/101223/cesgranrio-2023-transpetro-profissional-transpetro-de-nivel-superior-junior-enfase-9-comercializacao-e-logistica-transporte-maritimo-prova.pdf", "valido": true}, {"id": 205, "materia": "Legislação", "assunto": "Lei 13.303/2016 — Contratação Direta (Notória Especialização)", "enunciado": "Um profissional com notória especialização vem a ser contactado sobre a prestação de serviço para uma sociedade de economia mista. Nesse caso, de acordo com a Lei nº 13.303 de 30/06/2016, sua contratação será", "alternativas": ["licitada", "eventual", "temporária", "direta", "proporcional"], "corretaIndex": 3, "regra": "Art. 30, caput c/c inciso II — a contratação de profissional de notória especialização é hipótese de inexigibilidade de licitação, logo a contratação é direta.", "fonte": "CESGRANRIO — Petrobras — Administrador(a) Júnior — Prova 1 — 2018", "fonteUrl": "https://arquivos.qconcursos.com/prova/arquivo_prova/56635/cesgranrio-2018-petrobras-administrador-junior-prova.pdf", "valido": true}, {"id": 206, "materia": "Legislação", "assunto": "Lei 13.303/2016 — Dispensa de Licitação (valor)", "enunciado": "Um administrador exerce atividade de assessoria parlamentar no Congresso Nacional. Ele tem como tarefa designada fazer pesquisa sobre aquisição de bens e serviços das sociedades de economia mista. Ao debruçar-se sobre a Lei nº 13.303 de 30/06/2016, verifica que será dispensada a licitação para obras e serviços de engenharia de valor até", "alternativas": ["R$ 10.000,00", "R$ 20.000,00", "R$ 40.000,00", "R$ 80.000,00", "R$ 100.000,00"], "corretaIndex": 4, "regra": "Art. 29, I — é dispensável a licitação para obras e serviços de engenharia de valor até R$ 100.000,00.", "fonte": "CESGRANRIO — Petrobras — Administrador(a) Júnior — Prova 1 — 2018", "fonteUrl": "https://arquivos.qconcursos.com/prova/arquivo_prova/56635/cesgranrio-2018-petrobras-administrador-junior-prova.pdf", "valido": true}, {"id": 207, "materia": "Legislação", "assunto": "Lei 13.303/2016 — Regime de Empreitada Integral", "enunciado": "A Lei nº 13.303/2016 determina que, nos casos em que o contratante necessite receber o empreendimento, normalmente de alta complexidade, em condição de operação imediata, os contratos destinados à execução de obras e serviços de engenharia admitirão o regime de empreitada", "alternativas": ["básica", "global", "integral", "parcial", "unitária"], "corretaIndex": 2, "regra": "Art. 43, IV — empreitada integral: entrega do empreendimento em condições de operação imediata, ao contratante, mediante prévia definição de preço global.", "fonte": "CESGRANRIO — Petrobras — Técnico(a) de Suprimento de Bens e Serviços Júnior — Administração — Prova 23 — 2018", "fonteUrl": "https://arquivos.qconcursos.com/prova/arquivo_prova/56798/cesgranrio-2018-petrobras-tecnico-de-suprimento-de-bens-e-servicos-junior-administracao-prova.pdf", "valido": true}, {"id": 208, "materia": "Legislação", "assunto": "Lei 13.303/2016 — Garantia Contratual (percentual)", "enunciado": "Segundo a Lei nº 13.303/2016, que percentual do valor do contrato poderá ser exigido como prestação de garantia nas contratações de obras, serviços e compras?", "alternativas": ["um por cento", "dois por cento", "três por cento", "quatro por cento", "cinco por cento"], "corretaIndex": 4, "regra": "Art. 70, caput — a garantia não excederá a cinco por cento do valor do contrato (podendo chegar a até dez por cento em obras/serviços de grande vulto/alta complexidade técnica).", "fonte": "CESGRANRIO — Petrobras — Técnico(a) de Suprimento de Bens e Serviços Júnior — Administração — Prova 23 — 2018", "fonteUrl": "https://arquivos.qconcursos.com/prova/arquivo_prova/56798/cesgranrio-2018-petrobras-tecnico-de-suprimento-de-bens-e-servicos-junior-administracao-prova.pdf", "valido": true}, {"id": 209, "materia": "Legislação", "assunto": "Lei 13.303/2016 — Sanções Administrativas", "enunciado": "Observados os termos da Lei nº 13.303/2016, pela inexecução total ou parcial do contrato, a sociedade de economia mista poderá, garantida a prévia defesa, aplicar ao contratado a seguinte sanção:", "alternativas": ["advertência", "censura", "interdição", "protesto", "repreensão"], "corretaIndex": 0, "regra": "Art. 83, I — sanções administrativas cabíveis: advertência; multa; suspensão temporária de participação em licitação; declaração de inidoneidade.", "fonte": "CESGRANRIO — Petrobras — Técnico(a) de Suprimento de Bens e Serviços Júnior — Administração — Prova 23 — 2018", "fonteUrl": "https://arquivos.qconcursos.com/prova/arquivo_prova/56798/cesgranrio-2018-petrobras-tecnico-de-suprimento-de-bens-e-servicos-junior-administracao-prova.pdf", "valido": true}, {"id": 210, "materia": "Legislação", "assunto": "Lei 13.303/2016 — Conceito de Projeto Executivo", "enunciado": "Nos termos da Lei nº 13.303/2016, o conjunto dos elementos necessários e suficientes à execução completa da obra, de acordo com as normas técnicas pertinentes, caracteriza o projeto", "alternativas": ["básico", "complexo", "executivo", "global", "preliminar"], "corretaIndex": 2, "regra": "Art. 42, XXV — definição legal de \"projeto executivo\".", "fonte": "CESGRANRIO — Petrobras — Técnico(a) de Suprimento de Bens e Serviços Júnior — Administração — Prova 23 — 2018", "fonteUrl": "https://arquivos.qconcursos.com/prova/arquivo_prova/56798/cesgranrio-2018-petrobras-tecnico-de-suprimento-de-bens-e-servicos-junior-administracao-prova.pdf", "valido": true}, {"id": 211, "materia": "Legislação", "assunto": "Lei 13.303/2016 — Modo de Disputa Aberto (Lances)", "enunciado": "A Lei nº 13.303/2016 determina que, quando for adotado o modo de disputa aberto, poderá ser admitida a apresentação de lances", "alternativas": ["independentes", "intermediários", "autônomos", "sigilosos", "fechados"], "corretaIndex": 1, "regra": "Art. 32, §2º — é admitida a apresentação de lances intermediários durante a disputa aberta.", "fonte": "CESGRANRIO — Petrobras — Técnico(a) de Suprimento de Bens e Serviços Júnior — Administração — Prova 23 — 2018", "fonteUrl": "https://arquivos.qconcursos.com/prova/arquivo_prova/56798/cesgranrio-2018-petrobras-tecnico-de-suprimento-de-bens-e-servicos-junior-administracao-prova.pdf", "valido": true}, {"id": 212, "materia": "Legislação", "assunto": "Lei 13.303/2016 — Critérios de Desempate", "enunciado": "Nos termos da Lei nº 13.303/2016, em caso de empate entre duas propostas, serão utilizados vários critérios de desempate. Persistindo o empate após a aplicação de todos os critérios de desempate constantes em lei, a solução prevista consiste em", "alternativas": ["acordo", "sorteio", "divisão", "arbitragem", "escolha livre"], "corretaIndex": 1, "regra": "Art. 55, §2º — persistindo o empate, a definição do vencedor ocorre por sorteio.", "fonte": "CESGRANRIO — Petrobras — Técnico(a) de Suprimento de Bens e Serviços Júnior — Administração — Prova 23 — 2018", "fonteUrl": "https://arquivos.qconcursos.com/prova/arquivo_prova/56798/cesgranrio-2018-petrobras-tecnico-de-suprimento-de-bens-e-servicos-junior-administracao-prova.pdf", "valido": true}, {"id": 213, "materia": "Legislação", "assunto": "Lei 13.303/2016 — Procedimentos Auxiliares das Licitações", "enunciado": "Considerando os termos da Lei nº 13.303/2016, existem procedimentos auxiliares das licitações. Um dos procedimentos auxiliares previstos nessa Lei é o(a)", "alternativas": ["seleção prévia de licitantes", "lista independente de fornecedores", "formulário de pré-agendamento", "catálogo eletrônico de padronização", "registro de pessoas habilitadas"], "corretaIndex": 3, "regra": "Art. 63 — procedimentos auxiliares: pré-qualificação permanente; cadastramento; sistema de registro de preços; catálogo eletrônico de padronização.", "fonte": "CESGRANRIO — Petrobras — Técnico(a) de Suprimento de Bens e Serviços Júnior — Administração — Prova 23 — 2018", "fonteUrl": "https://arquivos.qconcursos.com/prova/arquivo_prova/56798/cesgranrio-2018-petrobras-tecnico-de-suprimento-de-bens-e-servicos-junior-administracao-prova.pdf", "valido": true}, {"id": 214, "materia": "Legislação", "assunto": "Lei 13.303/2016 — Definição de Objeto (Instrumento Convocatório)", "enunciado": "De acordo com a Lei nº 13.303/2016, o objeto da licitação e do contrato dela decorrente será definido de forma", "alternativas": ["técnica", "sucinta", "expressa", "detalhada", "complexa"], "corretaIndex": 1, "regra": "Art. 33 — o objeto da licitação e do contrato dela decorrente será definido de forma sucinta e clara no instrumento convocatório.", "fonte": "CESGRANRIO — Petrobras — Técnico de Suprimento de Bens e Serviços Júnior — Mecânica — 2018", "fonteUrl": "https://www.qconcursos.com/questoes-de-concursos/questoes/e71e46cb-28", "valido": true}, {"id": 215, "materia": "Legislação", "assunto": "Lei 13.303/2016 — Contratação Direta em Emergência", "enunciado": "O responsável pelo setor de licitações de sociedade de economia mista constatou situação de emergência, com premente prejuízo para pessoas e equipamentos utilizados na atividade-fim da empresa. Nos termos da Lei nº 13.303/2016, nesse caso, é possível a aquisição dos bens necessários ao atendimento da situação emergencial e para as parcelas de obras e serviços que possam ser concluídas no prazo máximo de", "alternativas": ["60 dias consecutivos e ininterruptos, contado da ocorrência da emergência", "90 dias consecutivos e ininterruptos, contado da ocorrência da emergência", "120 dias consecutivos e ininterruptos, contado da ocorrência da emergência", "150 dias consecutivos e ininterruptos, contado da ocorrência da emergência", "180 dias consecutivos e ininterruptos, contado da ocorrência da emergência"], "corretaIndex": 4, "regra": "Art. 30, §1º — contratação direta emergencial limitada a 180 dias consecutivos e ininterruptos.", "fonte": "CESGRANRIO — Transpetro — Profissional Nível Superior Júnior — Ênfase Advocacia — Prova 2 — 2023", "fonteUrl": "https://arquivos.qconcursos.com/prova/arquivo_prova/101216/cesgranrio-2023-transpetro-profissional-transpetro-de-nivel-superior-junior-enfase-2-advocacia-prova.pdf", "valido": true}, {"id": 216, "materia": "Legislação", "assunto": "Lei 13.303/2016 — Contratação Direta (Fornecedor Exclusivo)", "enunciado": "DF é diretor da sociedade de economia mista T e apresenta plano para aquisição de bens e serviços, sendo alertado pelo advogado da empresa da necessidade de licitação. Nos termos da Lei nº 13.303/2016, havendo inviabilidade de competição para a aquisição de materiais, equipamentos ou gêneros que só possam ser fornecidos por produtor, empresa ou representante comercial exclusivo, poderá ser realizada a contratação", "alternativas": ["direta", "dirigida", "aleatória", "indicada", "preferencial"], "corretaIndex": 0, "regra": "Art. 30, III — inexigibilidade de licitação para aquisição de bens fornecidos por produtor/empresa/representante comercial exclusivo, ensejando contratação direta.", "fonte": "CESGRANRIO — Transpetro — Profissional Nível Superior Júnior — Ênfase Advocacia — Prova 2 — 2023", "fonteUrl": "https://arquivos.qconcursos.com/prova/arquivo_prova/101216/cesgranrio-2023-transpetro-profissional-transpetro-de-nivel-superior-junior-enfase-2-advocacia-prova.pdf", "valido": true}, {"id": 217, "materia": "Legislação", "assunto": "Lei 13.303/2016 — Comitê Estatutário (Elegibilidade)", "enunciado": "Um analista apresentou seu currículo para integrar os quadros de direção de empresa estatal, mas necessita de avaliação para poder exercer a atividade. De acordo com a Lei Federal nº 13.303/2016, a empresa pública deverá criar, para verificar a conformidade do processo de indicação e de avaliação de membros para o Conselho de Administração e para o Conselho Fiscal, um(a)", "alternativas": ["órgão auditor", "comitê estatutário", "cargo de ouvidoria", "setor de análise", "seção de Recursos Humanos"], "corretaIndex": 1, "regra": "Art. 10 — a empresa pública e a sociedade de economia mista deverão criar comitê estatutário (Comitê de Elegibilidade), com a função de verificar a conformidade do processo de indicação e de avaliação de membros ao Conselho de Administração, à Diretoria e ao Conselho Fiscal.", "fonte": "CESGRANRIO — AgeRio — Analista de Desenvolvimento / Gestão, Administração e Planejamento — Prova 7 — 2023", "fonteUrl": "https://arquivos.qconcursos.com/prova/arquivo_prova/94168/cesgranrio-2023-agerio-analista-de-desenvolvimento-gestao-administracao-e-planejamento-prova.pdf", "valido": true}, {"id": 218, "materia": "Legislação", "assunto": "Lei 14.133/2021 — Contratação Direta (Inexigibilidade – Notório Saber Artístico)", "enunciado": "Deseja o Instituto de Pesquisa Econômica Aplicada realizar a contratação (diretamente ou por meio de empresário exclusivo) de profissional do setor artístico consagrado pela crítica especializada e pela opinião pública, para divulgar o resultado de relevantes pesquisas realizadas, com impacto nacional. No caso em tela, deve-se proceder, nos termos da Lei nº 14.133/2021, à contratação da seguinte forma:", "alternativas": ["obtenção de autorização legislativa para a contratação", "dispensa de licitação", "impossibilidade de contratação", "inexigibilidade de licitação", "realização de prévia consulta ao Tribunal de Contas da União"], "corretaIndex": 3, "regra": "Art. 74, III — é inexigível a licitação para contratação de profissional do setor artístico, consagrado pela crítica especializada ou pela opinião pública, diretamente ou por meio de empresário exclusivo.", "fonte": "CESGRANRIO — IPEA — Técnico de Planejamento e Pesquisa — Gestão e Logística — Prova 12 — 2024", "fonteUrl": "https://arquivos.qconcursos.com/prova/arquivo_prova/104456/cesgranrio-2024-ipea-tecnico-de-planejamento-e-pesquisa-gestao-e-logistica-prova.pdf", "valido": true}, {"id": 219, "materia": "Legislação", "assunto": "Lei 14.133/2021 — Princípios (Inovação em relação à Lei 8.666/93)", "enunciado": "A Lei nº 14.133/2021, nova lei de licitações e contratos da Administração Pública, destinada a substituir a Lei nº 8.666/1993, inova com relação à fiscalização dos contratos administrativos [...]. Na esfera dessa inovação, o princípio que está expresso apenas na Lei nº 14.133/2021 (ausente na Lei nº 8.666/93), com relação à eficiência contratual perseguida pela Administração Pública, é o seguinte:", "alternativas": ["segurança jurídica", "vinculação ao edital", "probidade administrativa", "julgamento objetivo", "desenvolvimento sustentável"], "corretaIndex": 0, "regra": "Art. 5º — a segurança jurídica é elencada expressamente entre os princípios da Lei nº 14.133/2021, não constando expressamente no rol do art. 3º da Lei nº 8.666/93.", "fonte": "CESGRANRIO — IPEA — Técnico de Planejamento e Pesquisa — Gestão e Logística — Prova 12 — 2024", "fonteUrl": "https://arquivos.qconcursos.com/prova/arquivo_prova/104456/cesgranrio-2024-ipea-tecnico-de-planejamento-e-pesquisa-gestao-e-logistica-prova.pdf", "valido": true}, {"id": 220, "materia": "Legislação", "assunto": "Lei 14.133/2021 — Conceito de Serviços Contínuos", "enunciado": "Existem serviços prestados que, pela sua essencialidade, visam a atender à necessidade pública de forma permanente, por mais de um exercício financeiro, assegurando a integridade do patrimônio público ou o funcionamento das atividades finalísticas do órgão ou entidade, de modo que sua interrupção possa comprometer a prestação de uma atividade pública ou o cumprimento da missão institucional. Considerando-se o conteúdo da Lei nº 14.133/2021, as atividades descritas acima são caracterizadas como serviços", "alternativas": ["técnicos", "descontínuos", "comuns", "contínuos", "por escopo"], "corretaIndex": 3, "regra": "Art. 6º, XV — definição legal de \"serviços contínuos\".", "fonte": "CESGRANRIO — IPEA — Técnico de Planejamento e Pesquisa — Gestão e Logística — Prova 12 — 2024", "fonteUrl": "https://arquivos.qconcursos.com/prova/arquivo_prova/104456/cesgranrio-2024-ipea-tecnico-de-planejamento-e-pesquisa-gestao-e-logistica-prova.pdf", "valido": true}, {"id": 221, "materia": "Legislação", "assunto": "Lei 14.133/2021 — Modalidade Concorrência / Critério de Julgamento", "enunciado": "A concorrência é modalidade de licitação, prevista na Lei nº 14.133/2021, para contratação de bens e serviços especiais e de obras e serviços comuns e especiais de engenharia, cujo critério de julgamento poderá ser o(a)", "alternativas": ["melhor lance", "melhor padrão de qualidade", "maior retorno econômico", "maior avaliação", "melhor oferta"], "corretaIndex": 2, "regra": "Art. 33, V — critérios de julgamento das propostas incluem o de maior retorno econômico (aplicável, em regra, aos contratos de eficiência).", "fonte": "CESGRANRIO — IPEA — Técnico de Planejamento e Pesquisa — Gestão e Logística — Prova 12 — 2024", "fonteUrl": "https://arquivos.qconcursos.com/prova/arquivo_prova/104456/cesgranrio-2024-ipea-tecnico-de-planejamento-e-pesquisa-gestao-e-logistica-prova.pdf", "valido": true}, {"id": 222, "materia": "Legislação", "assunto": "Lei 14.133/2021 — Fase de Habilitação (Reserva de Cargos PCD)", "enunciado": "A habilitação é a fase da licitação em que se verifica o conjunto de informações e documentos necessários e suficientes para demonstrar a capacidade do licitante de realizar o objeto da licitação. Além das exigências relativas à capacidade técnica e econômica, regularidade fiscal e trabalhista, observa-se, na Lei nº 14.133/2021, que as mudanças sociais fizeram com que fosse exigido o preenchimento de requisitos ligados a questões sociais. Dessa forma, essa lei preconiza que seja observada a seguinte exigência:", "alternativas": ["a paritária reserva de cargos para homens e mulheres a ser efetivada pelos candidatos ao processo licitatório.", "a promoção, pelos licitantes, do desenvolvimento sustentável, com respeito às normas ambientais nacionais e internacionais.", "a priorização, pelos licitantes, no processo de compras e prestação de serviços, dos pequenos e microempresários.", "o cumprimento de reserva de cargos para pessoa com deficiência e para reabilitado da previdência social, conforme a lei.", "o enquadramento jurídico-constitucional, pelos concorrentes, de pessoas de orientação homossexual."], "corretaIndex": 3, "regra": "Art. 63, IV — na fase de habilitação, exige-se do licitante o cumprimento das reservas de cargos previstas em lei para pessoa com deficiência ou para reabilitado da previdência social.", "fonte": "CESGRANRIO — IPEA — Técnico de Planejamento e Pesquisa — Gestão e Logística — Prova 12 — 2024", "fonteUrl": "https://arquivos.qconcursos.com/prova/arquivo_prova/104456/cesgranrio-2024-ipea-tecnico-de-planejamento-e-pesquisa-gestao-e-logistica-prova.pdf", "valido": true}, {"id": 223, "materia": "Legislação", "assunto": "Lei 14.133/2021 — Âmbito de Aplicação", "enunciado": "A Lei nº 14.133/2021 dispõe sobre normas gerais de licitação e contratação para as Administrações Públicas diretas, autárquicas e fundacionais da União, dos Estados, do Distrito Federal e dos Municípios, devendo ser obrigatoriamente utilizada, para contratos e licitações pelos(as)", "alternativas": ["órgãos do Poder Judiciário da União, dos Estados e dos Municípios no exercício da função típica desse poder.", "fundos especiais vinculados às empresas públicas que explorem atividades de prestação de serviço.", "fundos especiais direta ou indiretamente controlados pela Administração Pública.", "sociedades de economia mista da União, dos Estados e dos Municípios.", "secretarias dos governos estaduais e pelos órgãos do Poder Legislativo Municipal, em qualquer situação em que ambos venham a contratar."], "corretaIndex": 2, "regra": "Art. 1º, §1º — a Lei nº 14.133/2021 aplica-se, entre outros, aos fundos especiais e às demais entidades controladas direta ou indiretamente pela Administração Pública. Sociedades de economia mista e empresas públicas, em regra, seguem a Lei 13.303/2016.", "fonte": "CESGRANRIO — IPEA — Técnico de Planejamento e Pesquisa — Gestão e Logística — Prova 12 — 2024", "fonteUrl": "https://arquivos.qconcursos.com/prova/arquivo_prova/104456/cesgranrio-2024-ipea-tecnico-de-planejamento-e-pesquisa-gestao-e-logistica-prova.pdf", "valido": true}, {"id": 224, "materia": "Legislação", "assunto": "Lei 14.133/2021 — Regra de Transição (Art. 191)", "enunciado": "Determinado Município, que havia editado decreto no qual ficara expresso que não seria adotada a Lei nº 14.133/2021 até o término do prazo nela mencionado para a revogação da Lei nº 8.666/1993, realizou chamamento público para seleção de entidade qualificada como organização social [...]. O edital nada menciona acerca da opção em não adotar a Lei nº 14.133/2021 no referido certame. No caso descrito, é", "alternativas": ["indispensável a referência à não adoção da Lei nº 14.133/2021, em função do princípio da vantajosidade.", "indispensável a referência à não adoção da Lei nº 14.133/2021, conforme o próprio texto legal.", "possível a não indicação de exclusão dos critérios da Lei nº 14.133/2021 para licitar, desde que obedecidos seus princípios.", "desejável, pelo princípio da assertividade, a negativa ao bis in idem quanto à não aplicação da Lei nº 14.133/2021 ao certame.", "dispensável a referência à não adoção da Lei nº 14.133/2021, em decorrência da existência do decreto a respeito dessa opção municipal."], "corretaIndex": 1, "regra": "Art. 191, parágrafo único — durante o período de transição, a Administração deverá optar expressamente, em cada licitação/edital, por licitar segundo a Lei nº 14.133/2021 ou pelas normas anteriores; a opção deve constar expressamente no instrumento convocatório.", "fonte": "CESGRANRIO — IPEA — Técnico de Planejamento e Pesquisa — Gestão e Logística — Prova 12 — 2024", "fonteUrl": "https://arquivos.qconcursos.com/prova/arquivo_prova/104456/cesgranrio-2024-ipea-tecnico-de-planejamento-e-pesquisa-gestao-e-logistica-prova.pdf", "valido": true}, {"id": 225, "materia": "Legislação", "assunto": "Lei 14.133/2021 — Objetivos do Processo Licitatório", "enunciado": "De acordo com a Lei nº 14.133/2021, NÃO é um objetivo do processo licitatório", "alternativas": ["assegurar a seleção da proposta apta a gerar o resultado de contratação mais vantajoso para a administração pública, observando-se a equação de custo-benefício.", "ampliar as possibilidades quantitativas e qualitativas das propostas, tanto sob o aspecto horizontal quanto sob o aspecto vertical, priorizando-se a procedência nacional dos licitantes.", "evitar contratações com sobrepreço ou com preços manifestamente inexequíveis e superfaturamento na execução dos contratos.", "garantir a necessária competitividade, ainda mesmo na fase pré-contratual do processo licitatório.", "incentivar a inovação e o desenvolvimento nacional sustentável, em especial quanto à execução do contrato, considerando seus efeitos econômicos, sociais e ambientais."], "corretaIndex": 1, "regra": "Art. 11 — os objetivos legais do processo licitatório (incisos I a IV) não incluem \"priorizar a procedência nacional dos licitantes\" nesses termos, tornando a alternativa B a única que não corresponde ao texto legal.", "fonte": "CESGRANRIO — IPEA — Técnico de Planejamento e Pesquisa — Gestão e Logística — Prova 12 — 2024", "fonteUrl": "https://arquivos.qconcursos.com/prova/arquivo_prova/104456/cesgranrio-2024-ipea-tecnico-de-planejamento-e-pesquisa-gestao-e-logistica-prova.pdf", "valido": true}, {"id": 226, "materia": "Legislação", "assunto": "Lei 14.133/2021 — Licenciamento Ambiental (Obras de Engenharia)", "enunciado": "Nos termos da Lei nº 14.133/2021, nas contratações de serviços de engenharia, sempre que a responsabilidade pelo licenciamento ambiental for da Administração, a manifestação prévia ou licença prévia, quando cabíveis, deverão ser obtidas", "alternativas": ["no corpo do edital.", "no curso do cumprimento do edital.", "em prazo a ser fixado no edital.", "ao final do julgamento das propostas previsto no edital.", "antes da divulgação do edital."], "corretaIndex": 4, "regra": "Art. 18, §1º c/c art. 25 — os estudos técnicos preliminares e a obtenção de licença/manifestação ambiental prévia, quando a responsabilidade for da Administração, devem ocorrer antes da divulgação do edital.", "fonte": "CESGRANRIO — IPEA — Técnico de Planejamento e Pesquisa — Gestão e Logística — Prova 12 — 2024", "fonteUrl": "https://arquivos.qconcursos.com/prova/arquivo_prova/104456/cesgranrio-2024-ipea-tecnico-de-planejamento-e-pesquisa-gestao-e-logistica-prova.pdf", "valido": true}, {"id": 227, "materia": "Legislação", "assunto": "Lei 14.133/2021 — Licenciamento Ambiental (Prioridade de Tramitação)", "enunciado": "Um economista busca mecanismos para estender o critério de obediência aos parâmetros ambientais aceitos pela comunidade mundial [...]. Nos termos da Lei nº 14.133/2021, os licenciamentos ambientais de obras e serviços de engenharia licitados sob sua égide deverão, nos órgãos integrantes do Sistema Nacional do Meio Ambiente, ter", "alternativas": ["preferência equivalente à do idoso", "importância relevante", "autonomia na cronologia", "prioridade na tramitação", "autorização temporária"], "corretaIndex": 3, "regra": "Art. 20 — os processos administrativos de licenciamento ambiental de obras e serviços de engenharia licitados sob o regime da Lei nº 14.133/2021 terão prioridade de tramitação no órgão ambiental respectivo.", "fonte": "CESGRANRIO — IPEA — Técnico de Planejamento e Pesquisa — Gestão e Logística — Prova 12 — 2024", "fonteUrl": "https://arquivos.qconcursos.com/prova/arquivo_prova/104456/cesgranrio-2024-ipea-tecnico-de-planejamento-e-pesquisa-gestao-e-logistica-prova.pdf", "valido": true}, {"id": 228, "materia": "Legislação", "assunto": "Lei 14.133/2021 — Revogação da Licitação (Recurso)", "enunciado": "Um servidor do Ipea presidiu uma licitação para aquisição de material, tendo acorrido ao ato vários competidores. Após o julgamento das propostas, a licitação veio a ser revogada. A Lei nº 14.133/2021, no que concerne à revogação da licitação, exprime o seguinte entendimento:", "alternativas": ["é ato impassível de impugnação.", "é dependente do material utilizado.", "está vinculada à qualidade dos licitantes.", "está relacionada à extinção do contrato.", "cabe recurso no prazo de três dias úteis."], "corretaIndex": 4, "regra": "Art. 165, parágrafo único, c/c art. 71 — cabe recurso, no prazo de 3 (três) dias úteis, contra a decisão que anular ou revogar a licitação.", "fonte": "CESGRANRIO — IPEA — Técnico de Planejamento e Pesquisa — Gestão e Logística — Prova 12 — 2024", "fonteUrl": "https://arquivos.qconcursos.com/prova/arquivo_prova/104456/cesgranrio-2024-ipea-tecnico-de-planejamento-e-pesquisa-gestao-e-logistica-prova.pdf", "valido": true}, {"id": 229, "materia": "Informática", "assunto": "Windows 11 - Segurança e configuração", "enunciado": "Um técnico bancário precisa garantir a segurança e a eficiência no uso de computadores com Windows 11 em uma agência bancária. Durante instalação e configuração, ele é solicitado a habilitar funcionalidades que aumentem a segurança sem comprometer desempenho, considerando grande número de operações bancárias diárias. Para atingir esse objetivo, na instalação do Windows 11 nesses computadores, o técnico deve configurá-lo de forma a:", "alternativas": ["Ativar o Hyper-V e desabilitar o Bit-Locker.", "Ativar o Modo Desenvolvedor e desabilitar o Controle de Conta de Usuário (UAC).", "Habilitar a inicialização segura (Secure Boot) e o Windows Defender Firewall.", "Desativar as atualizações automáticas e utilizar uma solução antivírus de terceiros.", "Iniciar diretamente no modo de segurança para todos os usuários."], "corretaIndex": 2, "regra": "Secure Boot impede a execução de códigos não assinados/maliciosos durante a inicialização, e o Windows Defender Firewall filtra tráfego de rede, elevando a segurança sem impacto significativo de desempenho — diferente das demais opções, que reduzem a segurança (desabilitar BitLocker/UAC) ou não fazem sentido operacional.", "fonte": "CESGRANRIO - 2025 - BANESE - Técnico Bancário I/III", "fonteUrl": "https://www.qconcursos.com/questoes-de-concursos/questoes/002a2eec-14", "valido": true}, {"id": 230, "materia": "Informática", "assunto": "Word - Nomenclatura de arquivos (Windows/Word)", "enunciado": "Devido a convenções de nomenclatura, alguns caracteres reservados não podem ser usados em nomes de arquivos e diretórios. Nesse contexto, considere que um usuário do sistema operacional Windows 10 precisa dividir o arquivo relatório.docx em dois arquivos. Para atender às convenções de nomenclatura de arquivos e diretórios, dois nomes que NÃO podem ser atribuídos a esses dois arquivos criados pelo usuário são os seguintes:", "alternativas": ["relatório_parte1.docx e relatório_parte2.docx", "relatório-parte1.docx e relatório-parte2.docx", "relatório:parte1.docx e relatório:parte2.docx", "relatório%parte1.docx e relatório%parte2.docx", "relatório$parte1.docx e relatório$parte2.docx"], "corretaIndex": 2, "regra": "O caractere dois-pontos (:) é reservado pelo sistema para indicar unidades de disco (C:, D:), sendo proibido em nomes de arquivo; os demais caracteres (_, -, %, $) são permitidos.", "fonte": "CESGRANRIO - 2023 - Banco do Brasil - Agente Comercial", "fonteUrl": "https://www.qconcursos.com/questoes-de-concursos/questoes/b50f366c-25", "valido": true}, {"id": 231, "materia": "Informática", "assunto": "Word - Estilos de formatação", "enunciado": "Um recurso bastante comum em editores de texto, como o Word da Microsoft, é poder associar um estilo a um trecho de texto. Dois estilos muito comuns são denominados 'Normal' e 'Título'. Uma característica desses estilos em um documento Word é que eles", "alternativas": ["afetam a orientação da página (retrato ou paisagem).", "definem o tamanho das margens do documento.", "determinam aspectos de formatação de texto, como, por exemplo, qual a fonte e o seu tamanho.", "funcionam apenas em parágrafos inteiros do documento.", "podem ser usados apenas uma vez em um documento."], "corretaIndex": 2, "regra": "Estilos no Word são conjuntos predefinidos de formatação de caractere/parágrafo (fonte, tamanho, cor, espaçamento) aplicáveis repetidamente a qualquer trecho de texto, e não controlam layout de página como margens ou orientação.", "fonte": "CESGRANRIO - 2023 - AGERIO - Assistente Técnico Administrativo", "fonteUrl": "https://www.qconcursos.com/questoes-de-concursos/questoes/0dc6326a-fb", "valido": true}, {"id": 232, "materia": "Informática", "assunto": "Word - Conversão de formato e proteção por senha", "enunciado": "Um arquivo docx, criado com o MS Word 2010, foi aberto com sucesso mediante digitação da senha de abertura correta e da senha de gravação correta. Em seguida, esse arquivo foi salvo no formato Rich Text (.rtf). Nessas condições, o novo arquivo (.rtf)", "alternativas": ["será protegido, tanto para abertura como para gravação, por uma senha padrão, correspondente ao nome do usuário do MS Word usado para criar o arquivo original.", "será protegido, tanto para abertura como para gravação, pelas mesmas senhas de abertura e de gravação do arquivo original.", "não será protegido por senha de abertura nem de gravação.", "será protegido de abertura pela mesma senha de abertura do arquivo original, mas não será protegido por senha de gravação.", "será protegido de gravação pela mesma senha de gravação do arquivo original, mas não será protegido por senha de abertura."], "corretaIndex": 2, "regra": "A proteção por senha do Word é um recurso do formato .docx; ao salvar em .rtf, as senhas de abertura e de gravação não são preservadas, ficando o novo arquivo desprotegido.", "fonte": "CESGRANRIO - 2018 - LIQUIGÁS - Profissional Júnior", "fonteUrl": "https://www.qconcursos.com/questoes-de-concursos/questoes/f5671ba1-f1", "valido": true}, {"id": 233, "materia": "Informática", "assunto": "Word - Contagem de palavras", "enunciado": "Uma estudante está escrevendo um conto para determinado concurso cultural, cujo regulamento apresenta um item que limita a quantidade de palavras existentes no texto. Que recurso do Word 2003 deverá ser utilizado pela candidata para garantir que seu texto esteja adequado a esse item do regulamento?", "alternativas": ["Hifenização", "Mala-direta", "Contar palavras", "Mesclagem de documentos", "Formatação em negrito do texto"], "corretaIndex": 2, "regra": "A ferramenta 'Contar palavras' do Word exibe estatísticas do documento (palavras, caracteres, parágrafos, linhas), permitindo verificar o cumprimento de limites de extensão exigidos em editais/regulamentos.", "fonte": "CESGRANRIO - 2014 - Petrobras - Técnico(a) de Suprimento de Bens e Serviços Júnior", "fonteUrl": "https://www.qconcursos.com/questoes-de-concursos/questoes/54c76897-9d", "valido": true}, {"id": 234, "materia": "Informática", "assunto": "Word - Atalhos de teclado (localizar e formatação)", "enunciado": "Ao comparar os dois textos abaixo, editados em Word (português), um revisor percebeu duas diferenças de formatação entre eles: no segundo texto, a palavra 'perigoso' aparece em negrito e a palavra 'motores' aparece em itálico, diferenças que não existem no primeiro texto. Que combinações de teclas de atalho permitiriam localizar essas palavras no texto e corrigir a formatação de itálico, respectivamente?", "alternativas": ["Ctrl + F e Ctrl + I", "Ctrl + G e Ctrl + S", "Ctrl + N e Ctrl + I", "Ctrl + N e Ctrl + S", "Ctrl + Z e Ctrl + I"], "corretaIndex": 0, "regra": "Ctrl+F aciona 'Localizar' (find) no Word e Ctrl+I aplica/remove a formatação em itálico (Ctrl+N é usado para negrito, não para localizar).", "fonte": "CESGRANRIO - 2014 - Petrobras - Técnico(a) de Exploração de Petróleo Júnior - Informática", "fonteUrl": "https://www.qconcursos.com/questoes-de-concursos/questoes/8042755e-83", "valido": true}, {"id": 235, "materia": "Informática", "assunto": "Excel - Função SUBTOTAL", "enunciado": "A função SUBTOTAL permite calcular vários tipos de subtotais em uma lista ou em um banco de dados, como a função SOMA ou MÉDIA. O primeiro parâmetro da função SUBTOTAL é um número que define não só a função a ser utilizada, mas também", "alternativas": ["a condição para uma célula entrar na totalização", "o formato do número fornecido pela função", "se a fórmula totalizadora deve ser feita por linhas ou por colunas", "se deve ser considerada a população completa ou apenas uma amostra", "se serão totalizados todos os valores ou apenas as células não ocultas"], "corretaIndex": 4, "regra": "Na função SUBTOTAL, os códigos de função de 1 a 11 incluem valores ocultos manualmente, enquanto os códigos de 101 a 111 os ignoram; assim, o primeiro parâmetro também define se linhas ocultas entram no cálculo.", "fonte": "CESGRANRIO - 2018 - Transpetro - Técnico de Suprimento de Bens e Serviços Júnior", "fonteUrl": "https://www.qconcursos.com/questoes-de-concursos/questoes/0c473fcf-31", "valido": true}, {"id": 236, "materia": "Informática", "assunto": "Excel - Função SE aninhada", "enunciado": "A função SE no Excel é usada para retornar um resultado, se uma determinada condição for atendida (verdadeiro) ou outro resultado, se a condição não for atendida (falso). Considerando uma tabela de classificação etária em que idades acima de 70 anos recebem a categoria 'F' (idoso frágil), acima de 79 recebem 'N' e acima de 89 recebem 'S', e as demais recebem 'O', assinale a fórmula com funções SE aninhadas que implementa corretamente essa classificação.", "alternativas": ["SE(Idade>69;\"F\";SE(Idade>79;\"S\";SE(Idade>79;\"N\";\"O\")))", "SE(Idade>70;\"F\";SE(Idade>79;\"N\";SE(Idade>89;\"S\";\"O\")))", "SE(Idade>79;\"O\";SE(Idade>69;\"F\";SE(Idade>89;\"N\";\"S\")))", "SE(Idade>80;\"S\";SE(Idade>69;\"F\";SE(Idade>89;\"O\";\"F\")))", "SE(Idade>89;\"S\";SE(Idade>79;\"N\";SE(Idade>69;\"O\";\"F\")))"], "corretaIndex": 1, "regra": "As condições devem ser testadas da menor para a maior faixa (ou organizadas de forma consistente e sem repetição/contradição), retornando 'F' acima de 70, 'N' acima de 79, 'S' acima de 89 e 'O' nos demais casos — única alternativa sem inconsistências lógicas.", "fonte": "CESGRANRIO - 2022 - ELETROBRAS-ELETRONUCLEAR - Designer", "fonteUrl": "https://www.qconcursos.com/questoes-de-concursos/questoes/f8e4e51e-ea", "valido": true}, {"id": 237, "materia": "Informática", "assunto": "Excel - PROCH (busca horizontal)", "enunciado": "Considere uma planilha Excel 2016 contendo dados de produção nacional de petróleo, em m³, entre 2015 e 2017, organizados com os anos dispostos em colunas de cabeçalho e os meses em linhas (dados no intervalo A2:E14). Que fórmula pode ser usada, em qualquer célula fora da tabela, para retornar a produção de agosto de 2017?", "alternativas": ["=PROCV(\"2017\";A2:E14;9;0)", "=PROCV(\"2017\";A2:E14;8;1)", "=PROCV(\"2017\";A2:E14;8;0)", "=PROCH(\"2017\";A2:E14;9;0)", "=PROCH(\"2017\";A2:E14;8;0)"], "corretaIndex": 4, "regra": "Como o valor buscado (o ano '2017') está na linha de cabeçalho (topo da tabela), a busca deve ser feita na horizontal com PROCH; o índice de linha 8 corresponde à linha correspondente a agosto, e o argumento 0 exige correspondência exata.", "fonte": "CESGRANRIO - 2018 - Transpetro - Analista Financeiro Júnior", "fonteUrl": "https://www.qconcursos.com/questoes-de-concursos/questoes/5485c20d-49", "valido": true}, {"id": 238, "materia": "Informática", "assunto": "Excel - Referências estruturadas (tabelas nomeadas)", "enunciado": "Uma planilha Excel 2016 contém dados de produção nacional de petróleo (2015-2017), organizados em uma tabela nomeada 'Producao', que ocupa as células A2:E14. Qual fórmula de referência estruturada, na célula E2, calcula corretamente o crescimento da produção entre janeiro de 2015 e janeiro de 2017?", "alternativas": ["=@2017-@2015", "=[@2017]-[@2015]", "=[2017]-[2015]", "=Producao![2017]-Producao![2015]", "=Producao!2017-Producao!2015"], "corretaIndex": 3, "regra": "Em referências estruturadas do Excel, o nome da coluna é referenciado entre colchetes, e para referenciar a tabela nomeada fora do contexto de uma coluna calculada usa-se a sintaxe 'NomeDaTabela![NomeDaColuna]'.", "fonte": "CESGRANRIO - 2018 - Transpetro - Analista Financeiro Júnior", "fonteUrl": "https://www.qconcursos.com/questoes-de-concursos/questoes/5482a7e5-49", "valido": true}, {"id": 239, "materia": "Informática", "assunto": "Excel - Referências absolutas e relativas", "enunciado": "Um agente comercial utilizando uma planilha Microsoft Excel 365, versão em português, em determinada operação de acompanhamento de despesas, lança na célula K2 a seguinte fórmula: =F$2+G1-$H2. Em seguida, ele copia essa célula (K2) para a célula K6. A fórmula resultante na célula K6 será", "alternativas": ["=F$2+G1-$H3", "=F$2+G5-$H6", "=F$2+G2-$H6", "=F$6+G5-$H2", "=F$6+G6-$H5"], "corretaIndex": 1, "regra": "O símbolo $ antes de um número fixa a linha (referência absoluta em linha); ao copiar de K2 para K6 (4 linhas abaixo), F$2 e a linha de $H2 permanecem fixas ($H6 apenas porque a coluna já era travada, mas a linha ajusta), enquanto G1 (totalmente relativa) ajusta para G5.", "fonte": "CESGRANRIO - 2023 - Banco do Brasil - Agente Comercial (Prova B)", "fonteUrl": "https://www.qconcursos.com/questoes-de-concursos/questoes/b534ac12-25", "valido": true}, {"id": 240, "materia": "Informática", "assunto": "Excel - Coautoria e modos de exibição pessoais", "enunciado": "Uma planilha está sendo editada no Excel do Microsoft Office 365 por vários coautores simultaneamente. Um dos coautores deseja fazer uma classificação e uma filtragem nos dados da planilha sem afetar o trabalho dos demais coautores e sem ter que fazer uma cópia da planilha. Para isso, esse coautor deve selecionar o menu", "alternativas": ["Dados e pressionar o botão Novo para criar um espelhamento dos dados da planilha.", "Revisão e pressionar o botão Novo para criar um espelhamento dos dados da planilha.", "Exibir e pressionar o botão Novo para criar um novo modo de exibição de planilha.", "Inserir e pressionar o botão Novo para criar um novo modo de exibição de planilha.", "Inserir e pressionar o botão Novo para criar uma nova imagem dos dados da planilha."], "corretaIndex": 2, "regra": "O recurso 'Modos de Exibição de Planilha' (Sheet View), disponível na guia Exibir, permite que um coautor aplique classificação/filtro apenas para sua própria visualização, sem alterar o que os demais coautores veem.", "fonte": "CESGRANRIO - 2023 - BANRISUL - Escriturário", "fonteUrl": "https://www.qconcursos.com/questoes-de-concursos/questoes/4f3e19d9-9e", "valido": true}, {"id": 241, "materia": "Informática", "assunto": "PowerPoint - Layouts de slide", "enunciado": "A criação de apresentações com editores especializados, como o PowerPoint da Microsoft, faz parte da rotina da grande maioria das organizações. Essas apresentações são usadas para, por exemplo, mostrar resultados ou vender uma ideia. Uma apresentação é organizada em slides, que podem ser considerados as páginas da apresentação. Cada slide pode ter um layout diferente, adequado ao seu conteúdo. É comum que um slide com layout", "alternativas": ["'Título e Conteúdo' seja utilizado para apresentar itens relevantes de um tema.", "'Somente Título' seja utilizado para configurar o título de todos os slides.", "'Em branco', sem conteúdo, seja utilizado como primeiro slide.", "'Comparação' seja utilizado para apresentar uma imagem.", "'Cabeçalho da Seção' seja utilizado para configurar como a apresentação deve ser impressa."], "corretaIndex": 0, "regra": "O layout 'Título e Conteúdo' é o mais utilizado para exibir um título seguido de texto, lista, imagem ou outro objeto — ideal para apresentar itens relevantes de um tema; os demais layouts descritos não correspondem às suas funções reais.", "fonte": "CESGRANRIO - 2023 - AGERIO - Assistente Técnico Administrativo", "fonteUrl": "https://www.qconcursos.com/questoes-de-concursos/questoes/0dd11fe3-fb", "valido": true}, {"id": 242, "materia": "Informática", "assunto": "PowerPoint - Tinta em expressões matemáticas", "enunciado": "O MS PowerPoint 2016 em português possui um recurso para converter, em texto, em formato adequado, expressões matemáticas manuscritas diretamente sobre a tela. Para tal, o usuário pode seguir o seguinte caminho:", "alternativas": ["inserir >> ícones", "inserir >> símbolo", "desenhar >> tinta em expressões matemáticas", "desenhar >> tinta em forma", "inserir >> objeto"], "corretaIndex": 2, "regra": "O recurso 'Tinta em Expressões Matemáticas', acessado pela guia Desenhar, reconhece escrita manuscrita (com caneta, mouse ou toque) e converte em uma expressão matemática editável no PowerPoint.", "fonte": "CESGRANRIO - 2018 - Transpetro - Técnico de Suprimento de Bens e Serviços Júnior", "fonteUrl": "https://www.qconcursos.com/questoes-de-concursos/questoes/0c7218d3-31", "valido": true}, {"id": 243, "materia": "Informática", "assunto": "PowerPoint - Efeitos de animação (ênfase)", "enunciado": "Os efeitos de animação do PowerPoint 2010 podem ser classificados, de acordo com os efeitos que produzem, em quatro tipos. Os efeitos de ênfase são aqueles que fazem, por exemplo, um objeto", "alternativas": ["aparecer gradualmente, surgir no slide de uma borda ou saltar para a exibição.", "separar-se do slide, desaparecer da exibição ou espiralar para fora do slide.", "diminuir ou aumentar de tamanho, alterar a cor ou girar.", "ser movimentado para cima ou para baixo, para a esquerda ou para a direita ou em um padrão circular.", "animar a maneira de como um slide é passado para o slide seguinte."], "corretaIndex": 2, "regra": "No PowerPoint, animações de entrada fazem o objeto aparecer (alternativa A), de saída fazem-no desaparecer (alternativa B), de trajetória de animação o deslocam (alternativa D), e de ênfase destacam o objeto já visível por meio de mudança de tamanho, cor ou rotação (alternativa C).", "fonte": "CESGRANRIO - 2018 - LIQUIGÁS - Profissional Júnior", "fonteUrl": "https://www.qconcursos.com/questoes-de-concursos/questoes/c0f491c4-62", "valido": true}, {"id": 244, "materia": "Informática", "assunto": "Malware - Cryptojacking", "enunciado": "Códigos maliciosos podem ganhar o privilégio necessário para destruir o seu hospedeiro, mas nem sempre agem dessa forma. O poder computacional do hospedeiro pode ser útil para diversas atividades de interesse de um criminoso. Um exemplo é o cryptojacking, que usa o poder computacional do hospedeiro para", "alternativas": ["criptografar dados da vítima e cobrar resgate para reverter o processo de cifragem.", "quebrar dados criptografados enviados através de formulários de pagamento de websites de e-commerce.", "quebrar o criptograma das credenciais de acesso e usá-las em atividades maliciosas.", "quebrar o tráfego de rede criptografado e publicar dados sensíveis em sites da deep internet.", "minerar criptomoedas e receber pagamento dessa atividade em conta particular sem conhecimento da vítima."], "corretaIndex": 4, "regra": "Cryptojacking é o uso não autorizado do poder de processamento de um dispositivo alheio para minerar criptomoedas, revertendo os ganhos para o atacante — distinto de ransomware (opção A), que criptografa dados e exige resgate.", "fonte": "CESGRANRIO - 2025 - BANESE - Técnico Bancário III - Suporte", "fonteUrl": "https://www.qconcursos.com/questoes-de-concursos/questoes/f87179f1-14", "valido": true}, {"id": 245, "materia": "Informática", "assunto": "Malware - Trojan (RAT)", "enunciado": "Os cavalos de Troia são programas enganosos que parecem executar uma função, mas na verdade executam outra função maliciosa, sem o conhecimento do usuário. Essa carga pode ser qualquer coisa, mas cavalos de Troia modernos camuflam um backdoor que possibilita a um criminoso ter acesso não autorizado ao computador da vítima. Esse tipo de cavalo de Troia é conhecido como:", "alternativas": ["ArcBomb", "Clicker", "FakeAV", "PSW", "RAT"], "corretaIndex": 4, "regra": "RAT (Remote Access Trojan) é a categoria de cavalo de Troia que instala um backdoor, dando ao atacante controle remoto e acesso não autorizado ao computador infectado.", "fonte": "CESGRANRIO - 2025 - BANESE - Técnico Bancário III - Suporte", "fonteUrl": "https://www.qconcursos.com/questoes-de-concursos/questoes/f869c4cf-14", "valido": true}, {"id": 246, "materia": "Informática", "assunto": "Malware - Vírus polimórfico", "enunciado": "O antimalware é uma categoria de software que monitora um computador ou rede de computadores para combater malwares. Uma estratégia amplamente utilizada é adotar uma base de conhecimento de assinaturas de malwares que permite fazer a identificação, detecção, bloqueio e remoção das ameaças virtuais. Para dificultar sua identificação, uma categoria de vírus mutante criptografa seu código e usa uma chave de criptografia diferente a cada infecção, para modificar a composição física do arquivo. Esse tipo de vírus é conhecido como", "alternativas": ["cryptojacking", "formjacking", "polymorphic", "ransomware", "trojan"], "corretaIndex": 2, "regra": "Vírus polimórfico (polymorphic) altera seu próprio código/assinatura a cada nova infecção, dificultando a detecção por assinatura estática usada por antimalwares tradicionais.", "fonte": "CESGRANRIO - 2024 - BNDES - Analista, Análise de Sistemas - Suporte", "fonteUrl": "https://www.qconcursos.com/questoes-de-concursos/questoes/8108fcdc-8d", "valido": true}, {"id": 247, "materia": "Informática", "assunto": "Malware/Spam - Ferramentas antispam", "enunciado": "O termo spam é usado para referir-se aos e-mails não solicitados que, geralmente, são enviados para um grande número de pessoas. Para reduzir o impacto causado pelo spam, muitas organizações adotam técnicas de filtragem para fazer uma triagem nos e-mails recebidos, separando os spams dos e-mails válidos. Dentre as técnicas mais aplicadas, o filtro bayesiano permite uma eficaz filtragem preditiva de mensagens através de palavras-chave com um número reduzido de falsos positivos. A plataforma antispam de código aberto da Apache Software Foundation (ASF) que usa uma estrutura de pontuação e plug-ins para integrar testes avançados de análise estatística e heurística, incluindo a filtragem bayesiana, é conhecida como:", "alternativas": ["spamassassin", "spamcheckai", "spamfighter", "spamkiller", "spamshark"], "corretaIndex": 0, "regra": "SpamAssassin é o software antispam de código aberto mantido pela Apache Software Foundation que combina múltiplos testes (incluindo filtro bayesiano) em um sistema de pontuação para classificar e-mails como spam.", "fonte": "CESGRANRIO - 2024 - BNDES - Analista, Análise de Sistemas - Suporte", "fonteUrl": "https://www.qconcursos.com/questoes-de-concursos/questoes/8106a073-8d", "valido": true}, {"id": 248, "materia": "Informática", "assunto": "Malware - Ransomware", "enunciado": "O código malicioso que visa a criptografar os dados das vítimas e cobrar pagamento de resgate pela chave e pelo código de decriptação é classificado como um", "alternativas": ["Worm", "Spyware", "Ransomware", "Trojan Horse", "Bot"], "corretaIndex": 2, "regra": "Ransomware é o malware que sequestra dados por meio de criptografia e exige pagamento de resgate (ransom) para restaurar o acesso.", "fonte": "CESGRANRIO - 2018 - Transpetro - Analista de Sistemas Júnior - Infraestrutura", "fonteUrl": "https://www.qconcursos.com/questoes-de-concursos/questoes/9d0dd88d-0f", "valido": true}, {"id": 249, "materia": "Informática", "assunto": "Malware - Bot/Botnet", "enunciado": "O malware (malicious software) é um código malicioso que tem o potencial de danificar sua vítima, mas nem sempre age dessa forma. Dentre eles, há um que engaja um computador em uma 'armada' que permite a realização de tarefas de forma automatizada para atacar alvos determinados por criminosos cibernéticos, sem o conhecimento do dono do computador. Esse tipo de malware é o:", "alternativas": ["Bot", "Worm", "Trojan", "Rabbit", "Ransomware"], "corretaIndex": 0, "regra": "Um Bot compromete o computador e o integra a uma rede de máquinas controladas remotamente (botnet), usadas para ataques coordenados sem o conhecimento do proprietário.", "fonte": "CESGRANRIO - 2018 - Transpetro - Analista de Sistemas Júnior - Processos de Negócio", "fonteUrl": "https://www.qconcursos.com/questoes-de-concursos/questoes/f7ead176-bd", "valido": true}, {"id": 250, "materia": "Informática", "assunto": "Malware - Worms", "enunciado": "As pragas computacionais se alastram com grande velocidade pela rede de dados quando conseguem explorar vulnerabilidades nos serviços dos sistemas operacionais. Os códigos maliciosos que utilizam a rede de dados como principal meio de proliferação são classificados como", "alternativas": ["trojans", "flooders", "downloaders", "worms", "backdoors"], "corretaIndex": 3, "regra": "Worms são programas autorreplicantes que se propagam automaticamente por redes de computadores, explorando vulnerabilidades, sem necessidade de ação do usuário — ao contrário de trojans, que dependem de execução voluntária.", "fonte": "CESGRANRIO - 2014 - Banco da Amazônia - Técnico Científico - Suporte Técnico à Infraestrutura de TI", "fonteUrl": "https://www.qconcursos.com/questoes-de-concursos/questoes/edde67a0-59", "valido": true}, {"id": 251, "materia": "Informática", "assunto": "Segurança - Antivírus (limites de atuação)", "enunciado": "Qual tarefa NÃO é de responsabilidade de programas antivírus?", "alternativas": ["Prevenir o acesso não autorizado a um backdoor instalado em um computador.", "Verificar continuamente os discos rígidos e unidades removíveis de forma transparente ao usuário.", "Procurar vírus, cavalos de troia e outros tipos de programas maliciosos em arquivos anexados a e-mails.", "Analisar os arquivos acessados através da Internet.", "Atualizar diariamente pela rede as assinaturas de vírus e de outros programas maliciosos conhecidos."], "corretaIndex": 0, "regra": "Bloquear/prevenir acesso não autorizado via backdoor (controle de tráfego e conexões de rede) é função típica de firewall, não de antivírus, cuja atuação principal é detecção e remoção de códigos maliciosos em arquivos.", "fonte": "CESGRANRIO - 2012 - LIQUIGÁS - Profissional Júnior - Análise de Sistemas", "fonteUrl": "https://www.qconcursos.com/questoes-de-concursos/questoes/aada23a9-21", "valido": true}, {"id": 252, "materia": "Informática", "assunto": "Engenharia social - Baiting", "enunciado": "A engenharia social é uma ação maliciosa que usa técnicas de manipulação de pessoas para ganhar sua confiança e persuadi-las a cometer erros, fornecer informações sigilosas ou contornar políticas de segurança. Um exemplo dessa ação maliciosa ocorre quando o agente da ameaça faz falsas promessas para atrair a vítima para uma armadilha, a fim de convencê-la a revelar informações pessoais ou instalar um software infectado com código malicioso. Geralmente, essa ação é realizada por meio de anúncios ou promoções on-line tentadoras, como jogos ou filmes gratuitos para download, streaming de música ou atualizações de smartphone. Esse exemplo de engenharia social é conhecido como", "alternativas": ["BEC", "Baiting", "Diversion theft", "Scareware", "Tailgating"], "corretaIndex": 1, "regra": "Baiting ('isca') é a técnica de engenharia social que usa ofertas atrativas (downloads gratuitos, brindes, mídias infectadas) para induzir a vítima a comprometer a própria segurança.", "fonte": "CESGRANRIO - 2025 - BANESE - Técnico Bancário III - Suporte", "fonteUrl": "https://www.qconcursos.com/questoes-de-concursos/questoes/f873fc04-14", "valido": true}, {"id": 253, "materia": "Informática", "assunto": "Ataques de rede - Man-in-the-middle (Evil Twin)", "enunciado": "Um adversário pode tentar se posicionar entre dois ou mais dispositivos usando técnicas de Man-In-The-Middle (MITM) para monitorar ou modificar o tráfego. Dentre essas técnicas, há uma conhecida como Evil Twin, na qual o adversário", "alternativas": ["falsifica o tráfego do DHCP para agir como servidor DHCP malicioso na rede da vítima.", "implanta um ponto de acesso malicioso para imitar o SSID e BSSID de um ponto de acesso legítimo da organização.", "responde ao tráfego LLMNR e NBT-NS para falsificar uma fonte autoritativa de resolução de nomes.", "insere informações falsas na cache DNS para falsificar endereços IP de outros clientes e servidores.", "insere informações falsas na cache ARP da vítima para falsificar endereços MAC de outros dispositivos."], "corretaIndex": 1, "regra": "O ataque Evil Twin consiste em criar um ponto de acesso Wi-Fi falso que copia SSID/BSSID de um ponto de acesso legítimo, enganando dispositivos e usuários para que se conectem a ele.", "fonte": "CESGRANRIO - 2025 - BANESE - Técnico Bancário III - Suporte", "fonteUrl": "https://www.qconcursos.com/questoes-de-concursos/questoes/f8676a3b-14", "valido": true}, {"id": 254, "materia": "Informática", "assunto": "Segurança da informação - Ataque passivo", "enunciado": "Um ataque cibernético é qualquer esforço intencional para roubar, expor, alterar, desabilitar ou destruir dados, aplicativos ou outros ativos por meio de acesso não autorizado a uma rede, sistema de computador ou dispositivo digital. Um ataque pode ser caracterizado de acordo com a sua intenção, seu ponto de origem ou seu método de entrega. Como exemplo da característica de intenção, um ataque passivo", "alternativas": ["interrompe serviços do alvo.", "altera a funcionalidade do alvo.", "realiza uma interação direta com o alvo.", "observa os dados transmitidos de/para o alvo.", "requer que o atacante se passe por um usuário legítimo do alvo."], "corretaIndex": 3, "regra": "Um ataque passivo caracteriza-se pela mera observação/monitoramento do tráfego ou dados do alvo, sem alterá-lo ou interrompê-lo — o que diferencia de ataques ativos, que modificam ou afetam diretamente o sistema.", "fonte": "CESGRANRIO - 2025 - BANESE - Técnico Bancário III - Suporte", "fonteUrl": "https://www.qconcursos.com/questoes-de-concursos/questoes/f8627149-14", "valido": true}, {"id": 255, "materia": "Informática", "assunto": "Phishing", "enunciado": "Um indivíduo recebeu um e-mail de spam contendo um link malicioso que o direcionava para uma página web falsa de um banco de investimentos, com o objetivo de coletar suas credenciais de acesso. Esse ataque é conhecido como", "alternativas": ["Vishing", "Phishing", "Skimming", "Tailgating", "Water-holing"], "corretaIndex": 1, "regra": "Phishing é a técnica de engenharia social que usa comunicação eletrônica fraudulenta (tipicamente e-mail com links para páginas falsas) para induzir a vítima a fornecer credenciais ou dados sensíveis.", "fonte": "CESGRANRIO - 2024 - IPEA - Técnico de Planejamento e Pesquisa - Infraestrutura de TI", "fonteUrl": "https://www.qconcursos.com/questoes-de-concursos/questoes/98aaa875-d8", "valido": true}, {"id": 256, "materia": "Informática", "assunto": "Firewall - DoS/SYN Flood", "enunciado": "Um dos tipos de ataque que o firewall de um site deve impedir é aquele em que um invasor envia um pacote SYN do protocolo TCP para estabelecer uma conexão. O site aloca um slot de conexão e envia um pacote de sinalização SYN+ACK como resposta. Se o invasor não responder, o slot fica alocado até um tempo-limite. Se o invasor for programado para enviar um número excessivo de solicitações de conexão, todos os slots serão alocados, e nenhuma conexão legítima será efetuada. Esse ataque é conhecido como", "alternativas": ["DoS (Denial of Service)", "DDoS (Distributed Denial of Service)", "Phishing", "Tunelamento DNS", "Ataque à cadeia de suprimento"], "corretaIndex": 0, "regra": "O cenário descreve um SYN Flood, um clássico ataque de negação de serviço (DoS) que esgota os recursos de conexão do servidor explorando o handshake de três vias do TCP; como é originado de uma única fonte no enunciado, classifica-se como DoS e não DDoS.", "fonte": "CESGRANRIO - 2023 - Transpetro - Profissional de Nível Superior Júnior (Engenharia de Telecomunicações)", "fonteUrl": "https://www.qconcursos.com/questoes-de-concursos/questoes/9ad5dc61-a4", "valido": true}, {"id": 257, "materia": "Informática", "assunto": "Engenharia social - Tailgating", "enunciado": "A engenharia social é uma técnica de manipulação que visa persuadir pessoas a cometerem erros ou burlar políticas de segurança, de forma que o adversário tenha êxito em ações maliciosas que não seriam viáveis sem a participação da vítima. Dentre os métodos mais comuns de engenharia social, existe um que tem como objetivo seguir um membro autorizado da equipe em uma área de acesso restrito e se aproveitar da cortesia social para fazer com que a pessoa segure a porta para o atacante ou para convencê-la de que o atacante também está autorizado a ficar na área restrita. Esse método de engenharia social é conhecido como", "alternativas": ["baiting", "phishing", "smishing", "tailgating", "honeytrap"], "corretaIndex": 3, "regra": "Tailgating (ou 'carona') é a técnica de engenharia social física em que o atacante segue de perto um funcionário autorizado para entrar em uma área restrita sem precisar de suas próprias credenciais.", "fonte": "CESGRANRIO - 2024 - BNDES - Analista, Análise de Sistemas - Cibersegurança", "fonteUrl": "https://www.qconcursos.com/questoes-de-concursos/questoes/b6f0b693-8c", "valido": true}, {"id": 258, "materia": "Informática", "assunto": "LGPD - Princípio da necessidade", "enunciado": "A Lei Geral de Proteção de Dados Pessoais (LGPD) do Brasil dispõe sobre o tratamento de dados pessoais, com o objetivo de proteger os direitos fundamentais de liberdade e de privacidade e o livre desenvolvimento da personalidade da pessoa natural. As atividades de tratamento de dados pessoais deverão observar a boa-fé e os princípios de proteção de dados pessoais elencados na LGPD. Um desses princípios implica a limitação do tratamento ao mínimo necessário para a realização de suas finalidades, com abrangência dos dados pertinentes, proporcionais e não excessivos em relação às finalidades do tratamento de dados. Esse é o princípio da", "alternativas": ["Adequação", "Finalidade", "Necessidade", "Prevenção", "Transparência"], "corretaIndex": 2, "regra": "O art. 6º, III, da LGPD define o princípio da necessidade como a limitação do tratamento ao mínimo necessário para a realização de suas finalidades, com dados pertinentes, proporcionais e não excessivos.", "fonte": "CESGRANRIO - 2026 - Caixa Econômica Federal - Engenheiro/Arquiteto/Médico do Trabalho (diversos cargos)", "fonteUrl": "https://www.qconcursos.com/questoes-de-concursos/questoes/5ac0317f-01", "valido": true}, {"id": 259, "materia": "Informática", "assunto": "LGPD - Hipóteses de tratamento (obrigação legal/regulatória)", "enunciado": "Uma pessoa jurídica recebeu notificação de agência reguladora solicitando dados sobre suas atividades e colaboradores para fins de fiscalização. Conforme a Lei nº 13.709/2018 (LGPD), o tratamento de dados pessoais pelo controlador para cumprimento de obrigação legal ou __________ é permitido.", "alternativas": ["essencial", "recomendada", "definida", "regulatória", "restritiva"], "corretaIndex": 3, "regra": "O art. 7º, II, da LGPD prevê como hipótese que dispensa consentimento o tratamento 'para o cumprimento de obrigação legal ou regulatória pelo controlador'.", "fonte": "CESGRANRIO - 2024 - Banco da Amazônia - Técnico Científico - Tecnologia da Informação", "fonteUrl": "https://www.qconcursos.com/questoes-de-concursos/questoes/471093fc-97", "valido": true}, {"id": 260, "materia": "Informática", "assunto": "LGPD - Fundamentos da disciplina de proteção de dados", "enunciado": "Um economista foi contratado por uma instituição financeira para organizar o fluxo de dados pessoais dos clientes, garantindo sua preservação, de acordo com as normas em vigor. Nos termos da Lei nº 13.709/2018, a disciplina da proteção de dados pessoais tem como fundamentos, dentre outros, os direitos", "alternativas": ["reais", "humanos", "atuais", "progressivos", "organizados"], "corretaIndex": 1, "regra": "O art. 2º, VII, da LGPD elenca os direitos humanos, o livre desenvolvimento da personalidade, a dignidade e o exercício da cidadania como fundamentos da disciplina da proteção de dados pessoais.", "fonte": "CESGRANRIO - 2024 - Banco da Amazônia - Técnico Bancário", "fonteUrl": "https://www.qconcursos.com/questoes-de-concursos/questoes/5c074557-96", "valido": true}, {"id": 261, "materia": "Informática", "assunto": "LGPD - Princípio da adequação", "enunciado": "A Lei Geral de Proteção de Dados Pessoais (LGPD) do Brasil dispõe sobre o tratamento de dados feito por pessoa física ou jurídica de direito público ou privado e determinou um significativo avanço no que tange à proteção dos dados pessoais. As atividades de tratamento de dados pessoais devem observar a boa-fé e vários princípios, como, por exemplo, o princípio da adequação. Esse princípio implica a", "alternativas": ["realização do tratamento de forma compatível com as finalidades informadas ao titular, de acordo com o contexto do tratamento.", "compatibilidade do tratamento com as finalidades informadas ao titular, de acordo com o contexto do tratamento.", "garantia, aos titulares, de consulta facilitada e gratuita sobre a forma e a duração do tratamento, bem como sobre a integralidade de seus dados pessoais.", "garantia, aos titulares, de exatidão, clareza, relevância e atualização dos dados, de acordo com a necessidade e para o cumprimento da finalidade de seu tratamento.", "garantia, aos titulares, de informações claras, precisas e facilmente acessíveis sobre a realização do tratamento e os respectivos agentes de tratamento, resguardados os segredos comercial e industrial."], "corretaIndex": 1, "regra": "O art. 6º, II, da LGPD define o princípio da adequação como a compatibilidade do tratamento com as finalidades informadas ao titular, de acordo com o contexto do tratamento.", "fonte": "CESGRANRIO - 2024 - Caixa Econômica Federal - Engenheiro de Segurança do Trabalho / Médico do Trabalho", "fonteUrl": "https://www.qconcursos.com/questoes-de-concursos/questoes/53cc26ee-91", "valido": true}, {"id": 262, "materia": "Informática", "assunto": "LGPD - Encarregado (DPO) e ANPD", "enunciado": "A Lei Geral de Proteção de Dados Pessoais (LGPD), Lei nº 13.709/2018, foi promulgada para proteger os direitos fundamentais de liberdade e de privacidade. A LGPD estabelece que o tratamento dos dados pessoais pode ser realizado por dois agentes de tratamento: o controlador e o operador. Essa lei também prevê o papel do encarregado, que é a pessoa indicada pelo controlador e pelo operador para atuar como canal de comunicação entre o controlador, os titulares dos dados e a", "alternativas": ["ANP (Agência Nacional do Petróleo)", "ANAC (Agência Nacional de Aviação Civil)", "ANEEL (Agência Nacional de Energia Elétrica)", "ANPD (Autoridade Nacional de Proteção de Dados)", "ANVISA (Agência Nacional de Vigilância Sanitária)"], "corretaIndex": 3, "regra": "O art. 5º, VIII, da LGPD define o encarregado (Data Protection Officer/DPO) como o canal de comunicação entre o controlador, os titulares dos dados e a ANPD, a autoridade nacional de proteção de dados.", "fonte": "CESGRANRIO - 2024 - Caixa Econômica Federal - Técnico Bancário Novo", "fonteUrl": "https://www.qconcursos.com/questoes-de-concursos/questoes/ff9e2ba6-1c", "valido": true}, {"id": 263, "materia": "Informática", "assunto": "LGPD - Dados pessoais comuns x dados sensíveis", "enunciado": "Um comerciante comprou passagens aéreas em um site especializado, mas recebeu um e-mail parabenizando-o por uma compra diferente, feita com um cartão de crédito desconhecido; as empresas envolvidas possuíam seu nome, CPF e e-mail. Ele ingressou com ação indenizatória por danos morais, alegando furto de dados pessoais e violação do art. 5º, II, da LGPD (que define como dados sensíveis, entre outros, os dados sobre origem racial ou étnica, convicção religiosa, opinião política, filiação sindical, dados de saúde, vida sexual, genético ou biométrico). Nessa situação hipotética, a ação", "alternativas": ["procede apenas contra a empresa vendedora de passagens.", "procede apenas contra a empresa aérea.", "procede contra ambas as empresas, pois nome e CPF são considerados dados sensíveis.", "não procede contra nenhuma das empresas, pois não houve divulgação de dados pessoais sensíveis.", "não procede, porque os dados não chegaram a ser efetivamente utilizados em fraude."], "corretaIndex": 3, "regra": "Nome, CPF e e-mail são dados pessoais comuns, não se enquadrando no rol taxativo de dados sensíveis do art. 5º, II, da LGPD, o que afasta o enquadramento pretendido na ação com base nessa categoria mais protegida.", "fonte": "CESGRANRIO - 2024 - Banco do Nordeste do Brasil (BNB) - Analista Bancário", "fonteUrl": "https://www.qconcursos.com/questoes-de-concursos/questoes/e2765adc-08", "valido": true}, {"id": 264, "materia": "Informática", "assunto": "LGPD - Anonimização", "enunciado": "Um cidadão responsável pela gerência de dados pessoais de uma sociedade empresária consulta como determinado dado pode perder a possibilidade de associação, direta ou indireta, a um indivíduo, mediante a utilização de meios técnicos razoáveis e disponíveis no momento do tratamento. Conforme a Lei nº 13.709/2018, esse processo é denominado:", "alternativas": ["Prevenção", "Bloqueio", "Anonimização", "Controle", "Cerceamento"], "corretaIndex": 2, "regra": "O art. 5º, XI, da LGPD define anonimização como a utilização de meios técnicos razoáveis e disponíveis no momento do tratamento, por meio dos quais um dado perde a possibilidade de associação a um indivíduo.", "fonte": "CESGRANRIO - 2023 - Banco do Brasil - Agente Comercial", "fonteUrl": "https://www.qconcursos.com/questoes-de-concursos/questoes/b4da09d7-25", "valido": true}, {"id": 265, "materia": "Informática", "assunto": "LGPD - Dados pessoais e perfil comportamental", "enunciado": "O assessor de determinada pessoa jurídica pretende acessar os dados pessoais de alguns colaboradores. Para isso, ele recebe a informação de que, nos termos da Lei nº 13.709/2018, poderão ser igualmente considerados como dados pessoais aqueles utilizados por determinada pessoa natural, se identificada, para a formação do seu perfil", "alternativas": ["ancestral", "histórico", "comportamental", "profissional", "antropológico"], "corretaIndex": 2, "regra": "O parágrafo único do art. 12 da LGPD estabelece que dados utilizados para formação de perfil comportamental de determinada pessoa natural, se identificada, são considerados dados pessoais.", "fonte": "CESGRANRIO - 2022 - ELETROBRAS-ELETRONUCLEAR - Arquivista", "fonteUrl": "https://www.qconcursos.com/questoes-de-concursos/questoes/2e988d17-ec", "valido": true}, {"id": 266, "materia": "Informática", "assunto": "LGPD - Princípio da transparência", "enunciado": "A LGPD estabelece que as atividades de tratamento de dados pessoais devem observar a boa-fé e princípios fundamentais. Um desses princípios garante aos titulares informações claras, precisas e facilmente acessíveis sobre a realização do tratamento e os respectivos agentes de tratamento, resguardados os segredos comercial e industrial. Esse princípio é o da", "alternativas": ["Finalidade", "Adequação", "Necessidade", "Transparência", "Prevenção"], "corretaIndex": 3, "regra": "O art. 6º, VI, da LGPD define o princípio da transparência exatamente como a garantia de informação clara, precisa e facilmente acessível sobre o tratamento e seus agentes.", "fonte": "CESGRANRIO - 2024 - IPEA - Técnico de Planejamento e Pesquisa - Infraestrutura de TI", "fonteUrl": "https://www.qconcursos.com/questoes-de-concursos/questoes/98c54816-d8", "valido": true}, {"id": 267, "materia": "Informática", "assunto": "LGPD - Requisitos para tratamento de dados (exceção)", "enunciado": "Segundo a Lei Geral de Proteção de Dados Pessoais, Lei nº 13.709/2018, em relação aos requisitos para o tratamento de dados pessoais, o tratamento desses dados somente poderá ser realizado nas seguintes hipóteses, EXCETO:", "alternativas": ["Para a tutela da saúde, exclusivamente, em procedimento realizado por profissionais de saúde, serviços de saúde ou autoridade sanitária.", "Para a realização de estudos por órgão de pesquisa, garantida, sempre que possível, a anonimização dos dados pessoais.", "Para a proteção da vida ou da incolumidade física do titular ou de terceiros.", "Mediante o fornecimento de consentimento pelo titular por escrito ou por outro meio.", "Mediante autorizações genéricas expressas em destaque."], "corretaIndex": 4, "regra": "A LGPD exige consentimento específico e não genérico (art. 8º, §4º veda autorizações genéricas); as demais alternativas correspondem a hipóteses legais válidas listadas no art. 7º.", "fonte": "CESGRANRIO - 2023 - CFC (Conselho Federal de Contabilidade) - Auditoria Independente na Previc", "fonteUrl": "https://www.qconcursos.com/questoes-de-concursos/questoes/0c27da15-e3", "valido": true}, {"id": 268, "materia": "Administração de RH / Processos Administrativos", "assunto": "Treinamento e Desenvolvimento - Etapas do Treinamento", "enunciado": "O treinamento é o processo de desenvolver qualidades nos recursos humanos de uma empresa para habilitá-los a serem mais produtivos. Uma das etapas do processo de treinamento é o desenvolvimento de conceitos, o qual", "alternativas": ["Desenvolve comportamentos com mudança de atitudes negativas para atitudes favoráveis.", "Estimula habilidades e destrezas para a execução e operação de tarefas.", "Eleva o nível de abstração ajudando as pessoas a pensarem de forma global e ampla.", "Modifica o conhecimento das pessoas quanto às políticas, diretrizes e regras.", "Trata de aumentar o conhecimento das pessoas com informações sobre a organização e seus produtos/serviços."], "corretaIndex": 2, "regra": "O conteúdo de treinamento pode envolver transmissão de informações, desenvolvimento de habilidades, desenvolvimento/modificação de atitudes e desenvolvimento de conceitos. O desenvolvimento de conceitos visa elevar o nível de abstração e conceituação de ideias e filosofias, ajudando as pessoas a pensarem em termos globais e amplos (segundo Chiavenato).", "fonte": "Transpetro - Técnico de Administração e Controle Júnior - 2012 (Cesgranrio)", "fonteUrl": "https://www.qconcursos.com/questoes-de-concursos/questoes/7dc47c17-f0", "valido": true}, {"id": 269, "materia": "Administração de RH / Processos Administrativos", "assunto": "Cultura Organizacional", "enunciado": "A cultura organizacional é identificada nas atividades realizadas na empresa e nas relações mantidas pela organização, seja com parceiros externos ou internos. A cultura organizacional é refletida", "alternativas": ["no sistema de tradições regionais adotado na formação inicial da empresa.", "na maneira como a empresa estabelece o grau de autonomia dado aos empregados.", "nos valores pessoais dos empregados de todos os níveis da empresa.", "nos aspectos racionais do processo de tomada de decisão utilizado na empresa.", "nas estratégias organizacionais que são impostas pelo mercado."], "corretaIndex": 1, "regra": "A cultura organizacional se manifesta em práticas concretas de gestão, como o grau de autonomia/liberdade concedido aos empregados na execução do trabalho, refletindo valores e pressupostos compartilhados pela organização (não apenas valores pessoais individuais, nem tradições regionais).", "fonte": "Banco do Brasil - Nível Médio (Conhecimentos Básicos) - 2014 (Cesgranrio)", "fonteUrl": "https://www.qconcursos.com/questoes-de-concursos/questoes/105d0916-52", "valido": true}, {"id": 270, "materia": "Administração de RH / Processos Administrativos", "assunto": "Cultura Organizacional - Identidade", "enunciado": "A cultura é aprendida, transmitida e partilhada. É resultante de um aprendizado por condicionamento social. Ela é construída ao longo do tempo. Em termos empresariais, a cultura também é expressa na maneira como as coisas são feitas, como a empresa está estruturada, etc. Dessa forma, a cultura organizacional cria o(a)", "alternativas": ["Abordagem sistêmica da administração", "Identidade organizacional", "Público-alvo da empresa", "Cenário do macroambiente organizacional", "Relação entre o ambiente externo e o grau de incerteza interno"], "corretaIndex": 1, "regra": "A cultura organizacional, por ser um conjunto de valores, crenças e práticas compartilhadas e transmitidas, é o que confere identidade própria à organização, diferenciando-a das demais - é a 'personalidade' da empresa.", "fonte": "Banco do Brasil - Escriturário - 2014 (Cesgranrio)", "fonteUrl": "https://www.qconcursos.com/questoes-de-concursos/questoes/fc919d3d-af", "valido": true}, {"id": 271, "materia": "Administração de RH / Processos Administrativos", "assunto": "Clima Organizacional", "enunciado": "Clima organizacional é um conceito que, dentre outras variáveis, descreve a(s)", "alternativas": ["maneira como a fundação da organização determinou seus valores e sua visão", "importância dos ritos utilizados pela organização no acolhimento de seus colaboradores", "percepção que os colaboradores têm e a avaliação que fazem das práticas e dos procedimentos adotados na organização", "justificativa histórica para os esquemas de reforçamento adotados pela organização e as explicações para os comportamentos adequados", "estratégias da organização para articular sua visão ao contexto social em que a organização se insere"], "corretaIndex": 2, "regra": "Clima organizacional é a percepção coletiva que os membros têm sobre a organização e seu ambiente de trabalho (políticas, práticas, procedimentos), refletindo a satisfação com o ambiente interno num dado momento - diferente de cultura, que é mais profunda e duradoura.", "fonte": "Petrobras - Psicólogo Júnior - 2012 (Cesgranrio)", "fonteUrl": "https://www.qconcursos.com/questoes-de-concursos/questoes/467677", "valido": true}, {"id": 272, "materia": "Administração de RH / Processos Administrativos", "assunto": "Comunicação Organizacional Integrada", "enunciado": "A comunicação organizacional integrada engloba, além da comunicação interna, a comunicação institucional (Relações Públicas) e a comunicação mercadológica (Marketing). São exemplos de comunicação institucional a", "alternativas": ["Promoção de vendas e a publicidade", "Imagem corporativa e a mídia interna", "Identidade corporativa e a publicidade institucional", "Publicidade e o marketing direto", "Assessoria de imprensa e a promoção de vendas"], "corretaIndex": 2, "regra": "A comunicação institucional trabalha a imagem e a credibilidade da organização perante seus públicos, por meio de ferramentas como identidade corporativa e publicidade institucional; promoção de vendas, marketing direto e publicidade comercial pertencem à comunicação mercadológica.", "fonte": "Transpetro - Profissional de Nível Superior Júnior (Comunicador Social - RP) - 2023 (Cesgranrio)", "fonteUrl": "https://www.qconcursos.com/questoes-de-concursos/questoes/68cbdfc3-a1", "valido": true}, {"id": 273, "materia": "Administração de RH / Processos Administrativos", "assunto": "Recrutamento e Seleção / Socialização Organizacional", "enunciado": "Uma empresa necessitou desenvolver um programa de socialização com novos funcionários. Para isso, o responsável pela gestão de pessoas utilizou o método de conteúdo do cargo, que consiste em", "alternativas": ["Organizar programa formal e intensivo de treinamento inicial para familiarizar novos trabalhadores com a cultura organizacional, prática conhecida como indução para o aculturamento.", "Destacar supervisor como tutor para transmitir descrição clara de tarefas, informações técnicas e estabelecimento de metas e parâmetros de retroação.", "Integrar novos funcionários a grupo de trabalho constituído para provocar impacto positivo e duradouro, por meio da aceitação grupal e transmissão de crenças e valores organizacionais.", "Promover entrevistas coletivas para seleção de pessoal, proporcionando conhecimento recíproco, empatia e conhecimento da cultura organizacional antes da admissão.", "Envolver novos funcionários com tarefas que lhes proporcionem sucesso inicial, passando gradualmente a apresentar tarefas mais complexas e desafiadoras."], "corretaIndex": 1, "regra": "O método de 'conteúdo do cargo' na socialização organizacional (Chiavenato) atribui ao supervisor imediato o papel de tutor do novo funcionário, transmitindo-lhe a descrição realista das tarefas, informações técnicas e estabelecendo metas de desempenho e retroação (feedback) - diferente dos métodos de socialização em grupo, de treinamento formal em cultura ou de tarefas iniciais de sucesso gradual.", "fonte": "Casa da Moeda do Brasil - 2009 (Cesgranrio)", "fonteUrl": "https://www.qconcursos.com/questoes-de-concursos/questoes/a74fb3c8-8e", "valido": true}, {"id": 274, "materia": "Administração de RH / Processos Administrativos", "assunto": "Remuneração e Benefícios - Mitos e Realidades", "enunciado": "Dos mitos e realidades referentes ao custo de remuneração de uma organização deve ser contestado que", "alternativas": ["Nem sempre é possível baixar o custo da mão de obra diminuindo-se salários.", "Nem sempre o custo de mão de obra é um componente determinante dos custos totais.", "Nem sempre baixo custo de mão de obra é um fator importante e sustentável de competitividade.", "O valor da remuneração e o custo da mão de obra são sempre a mesma coisa.", "Muitas vezes, incentivos individuais diminuem o desempenho, desencorajando o espírito de equipe e priorizando o curto prazo."], "corretaIndex": 3, "regra": "Segundo a teoria de remuneração estratégica (Milkovich/Wright), valor de remuneração e custo de mão de obra NÃO são sempre a mesma coisa - o custo depende também de produtividade e volume de vendas, entre outros fatores; por isso essa afirmativa deve ser 'contestada' (é o mito/erro a ser identificado).", "fonte": "Eletrobras-Eletronuclear - Administrador - 2022 (Cesgranrio)", "fonteUrl": "https://www.qconcursos.com/questoes-de-concursos/questoes/f159f4c4-dc", "valido": true}, {"id": 275, "materia": "Administração de RH / Processos Administrativos", "assunto": "Avaliação de Desempenho - Métodos", "enunciado": "Para a avaliação de desempenho de um subordinado, um gerente escreveu uma narrativa descrevendo suas forças e fraquezas, desempenhos anteriores, potenciais e sugestões de melhoria. Esse método de avaliação de desempenho é denominado", "alternativas": ["Incidente crítico", "Ensaio crítico", "Lista de verificação", "Escala de classificação adjetiva", "Escala de classificação ancorada no comportamento"], "corretaIndex": 1, "regra": "O método do ensaio (narrativa) crítico consiste em o avaliador redigir um texto narrativo descrevendo pontos fortes e fracos, desempenho passado, potencial e sugestões de desenvolvimento do avaliado - diferente do incidente crítico, que registra eventos extremos (muito bons ou muito ruins) de comportamento.", "fonte": "Eletrobras-Eletronuclear - Administrador - 2022 (Cesgranrio)", "fonteUrl": "https://www.qconcursos.com/questoes-de-concursos/questoes/f1570ad1-dc", "valido": true}, {"id": 276, "materia": "Administração de RH / Processos Administrativos", "assunto": "Treinamento - Fatores de Motivação para Aprendizagem", "enunciado": "Na avaliação dos fatores que determinam a motivação para o bom resultado de um treinamento, um supervisor identificou que", "alternativas": ["a personalidade é importante, pois participantes com locus de controle interno, alta conscienciosidade, habilidade cognitiva e senso de autoeficácia tendem a aprender mais.", "as características pessoais (motivação e cargo) são sempre mais importantes do que as características do próprio treinamento.", "participantes com expectativa positiva em classes divertidas sempre aprendem muito e justificam os custos do treinamento.", "quando os participantes acreditam que terão oportunidade e recursos para aplicar as novas habilidades, ficam menos motivados a aprender.", "todos os métodos de treinamento são igualmente eficazes, dependendo o sucesso apenas do indivíduo e do suporte organizacional."], "corretaIndex": 0, "regra": "Fatores individuais como traços de personalidade (locus de controle interno, conscienciosidade), habilidade cognitiva e autoeficácia são reconhecidos na literatura de T&D como determinantes da motivação para aprender e do sucesso do treinamento.", "fonte": "Eletrobras-Eletronuclear - Administrador - 2022 (Cesgranrio)", "fonteUrl": "https://www.qconcursos.com/questoes-de-concursos/questoes/f14da073-dc", "valido": true}, {"id": 277, "materia": "Administração de RH / Processos Administrativos", "assunto": "Gestão de Serviços - Qualidade", "enunciado": "O grau em que os clientes estão dispostos a aceitar a variação de desempenho de um serviço avaliado como aceitável é denominado", "alternativas": ["Lacuna de qualidade", "Lacuna na interpretação", "Lacuna nas percepções", "Zona de tolerância", "Diagrama de controle"], "corretaIndex": 3, "regra": "Na gestão de qualidade de serviços, a 'zona de tolerância' é a faixa entre o serviço desejado e o serviço adequado dentro da qual o cliente aceita variações de desempenho como satisfatórias.", "fonte": "Banco do Brasil - Escriturário (Agente Comercial) - 2021 (Cesgranrio)", "fonteUrl": "https://www.qconcursos.com/questoes-de-concursos/questoes/46cad33f-2b", "valido": true}, {"id": 278, "materia": "Administração de RH / Processos Administrativos", "assunto": "Treinamento a Distância - Modalidades", "enunciado": "A área de atendimento ao cliente de um determinado banco precisava treinar todos os atendentes e gerentes em um novo software de apoio à negociação de empréstimos. Buscando os meios adequados para atender a essa demanda, o responsável pela área de Educação a Distância decidiu que o curso seria multimídia, com textos e aulas gravadas, garantindo assim que os alunos pudessem realizá-lo no momento em que quisessem, cada um em seu horário. Isso caracteriza o curso proposto como um curso de treinamento on-line", "alternativas": ["assíncrono", "concomitante", "síncrono", "tautócrono", "tempestivo"], "corretaIndex": 0, "regra": "Treinamento assíncrono é aquele que não exige a presença simultânea de instrutor e alunos, permitindo que cada participante estude no seu próprio ritmo e horário (ex.: aulas gravadas); o treinamento síncrono, ao contrário, exige interação em tempo real.", "fonte": "Banco do Brasil - Escriturário (Agente Comercial) - 2021 (Cesgranrio)", "fonteUrl": "https://www.qconcursos.com/questoes-de-concursos/questoes/46b249c2-2b", "valido": true}, {"id": 279, "materia": "Administração de RH / Processos Administrativos", "assunto": "Trabalho em Equipe - Estágios de Desenvolvimento", "enunciado": "O gerente está muito satisfeito porque a equipe que liderou evoluiu ao longo do tempo e alcançou o estágio mais avançado de seu desenvolvimento. Nesse momento, o desempenho melhora porque o grupo de trabalho está mais amadurecido e se torna uma equipe eficaz, em pleno funcionamento. O estágio de desenvolvimento dessa equipe é denominado", "alternativas": ["atuação", "formação", "negociação", "deformação", "normatização"], "corretaIndex": 0, "regra": "No modelo de Tuckman de desenvolvimento de grupos (formação, tormenta, normatização, atuação/desempenho e interrupção/dissolução), o estágio de 'atuação' (performing) é o último e mais maduro, no qual a estrutura do grupo é plenamente funcional e aceita, e a energia da equipe se volta para a execução da tarefa com máxima eficácia.", "fonte": "UNIRIO - Assistente em Administração - 2019 (Cesgranrio)", "fonteUrl": "https://www.qconcursos.com/questoes-de-concursos/questoes/6a1d86f0-1c", "valido": true}, {"id": 280, "materia": "Administração de RH / Processos Administrativos", "assunto": "Cargos e Salários - Remuneração por Habilidades", "enunciado": "Uma fábrica de engrenagens produz mais de 6 mil peças por dia e vende seus produtos nos mercados interno e externo. Seus principais clientes são empresas de motores de alto rendimento localizadas na Europa. O gerente de Recursos Humanos decidiu adotar o sistema de remuneração baseado em habilidades. No caso dessa empresa, isso significa que", "alternativas": ["a remuneração dos funcionários pode diminuir ou aumentar, de acordo com o desempenho geral do departamento do qual fazem parte, independentemente do resultado geral da empresa.", "a remuneração de todos os funcionários depende do percentual de participação da empresa no mercado e da relação entre o número de funcionários e os lucros.", "os funcionários mais antigos são promovidos, sempre que houver novas contratações, e passam a receber salários mais altos ou são transferidos para outros departamentos.", "os lucros da empresa são divididos, ao final do período, entre todos os funcionários da empresa de forma proporcional ao tempo de trabalho e ao nível hierárquico.", "os salários aumentam à medida que os funcionários aprendem a operar os vários equipamentos necessários para produzir engrenagens mais complexas."], "corretaIndex": 4, "regra": "A remuneração baseada em habilidades (skill-based pay) recompensa o funcionário pelo número e diversidade de habilidades/competências que ele domina, e não pelo cargo ocupado; nesse modelo, o salário aumenta conforme o trabalhador aprende a operar novos equipamentos/processos.", "fonte": "UNIRIO - Assistente em Administração - 2019 (Cesgranrio)", "fonteUrl": "https://www.qconcursos.com/questoes-de-concursos/questoes/6a194592-1c", "valido": true}, {"id": 281, "materia": "Administração de RH / Processos Administrativos", "assunto": "Recrutamento e Seleção - Testes Psicométricos", "enunciado": "Uma vez que a empresa busca novos empregados no mercado de trabalho e já realizou tarefas de recrutamento, torna-se necessário selecionar os candidatos adequados. Testes psicométricos são utilizados em atividades de seleção para cargos mais complexos, como o de gerente ou de diretor, e uma das formas de se medirem aptidões é usar a teoria multifatorial de Thurstone. Segundo essa abordagem, a estrutura mental das pessoas é constituída por fatores que são responsáveis, cada qual, por uma determinada aptidão. A capacidade de concentrar a atenção e ter facilidade em tratar de detalhes está associada à aptidão", "alternativas": ["Verbal", "Abstrata", "Perceptiva", "Espacial", "Associativa"], "corretaIndex": 2, "regra": "Na teoria multifatorial de Thurstone, a aptidão perceptiva refere-se à capacidade de perceber detalhes visuais rapidamente e com precisão, associada à concentração da atenção em minúcias - distinta da aptidão espacial (visualização de formas no espaço) ou verbal (compreensão e uso de palavras).", "fonte": "UNIRIO - Assistente em Administração - 2019 (Cesgranrio)", "fonteUrl": "https://www.qconcursos.com/questoes-de-concursos/questoes/6a1239ba-1c", "valido": true}, {"id": 282, "materia": "Administração de RH / Processos Administrativos", "assunto": "Trabalho em Equipe - Equipes Autogerenciadas", "enunciado": "Após a saída do supervisor, o diretor da empresa reuniu os funcionários do departamento e determinou que eles formassem dois grupos, cada um com 10 funcionários. A partir daquele momento, cada equipe passaria a ser responsável pelo planejamento e pelo cronograma de trabalho. Assim, as equipes teriam controle coletivo sobre o ritmo de trabalho, sobre a tomada de decisões operacionais e a solução de problemas.", "alternativas": ["virtuais", "dependentes", "probabilísticas", "multifuncionais", "autogerenciadas"], "corretaIndex": 4, "regra": "Equipes autogerenciadas (self-managed teams) são grupos que assumem responsabilidades antes exercidas por um supervisor, controlando coletivamente o ritmo de trabalho, a divisão de tarefas, o planejamento e a solução de problemas operacionais, sem chefia formal direta.", "fonte": "UNIRIO - Assistente em Administração - 2019 (Cesgranrio)", "fonteUrl": "https://www.qconcursos.com/questoes-de-concursos/questoes/6a0741ec-1c", "valido": true}, {"id": 283, "materia": "Administração de RH / Processos Administrativos", "assunto": "Trabalho em Equipe - Estágio de Normatização", "enunciado": "O chefe de um departamento formou um grupo de trabalho com cinco participantes, que não se conheciam, para elaborar um novo sistema de matrícula na universidade. Depois de quatro meses de trabalho, desenvolveram-se relacionamentos mais próximos entre os membros do grupo, que passaram a demonstrar coesão, forte senso de identidade e de camaradagem. Se for avaliado o processo evolutivo desse grupo, será constatado que ele se encontra em um estágio de desenvolvimento caracterizado como", "alternativas": ["Tormenta", "Interrupção", "Normatização", "Desempenho", "Aceitação mútua"], "corretaIndex": 2, "regra": "No modelo de Tuckman, o estágio de 'normatização' (norming) caracteriza-se pelo desenvolvimento de relacionamentos próximos, coesão do grupo e senso de identidade e camaradagem - etapa anterior ao desempenho pleno (atuação/performing).", "fonte": "UNIRIO - Assistente em Administração - 2019 (Cesgranrio)", "fonteUrl": "https://www.qconcursos.com/questoes-de-concursos/questoes/69f7ae52-1c", "valido": true}, {"id": 284, "materia": "Administração de RH / Processos Administrativos", "assunto": "Comportamento Organizacional - Justiça Distributiva", "enunciado": "Um assistente administrativo da secretaria de cursos de graduação de uma universidade está insatisfeito com sua organização. Ele tem percebido uma falta de equidade na distribuição de recompensas, na atribuição de tarefas e nas oportunidades de carreira. Essa percepção ocorre porque a justiça", "alternativas": ["Processual foi aplicada em alto grau.", "Interpessoal, quando não aplicada, gera imparcialidades.", "Distributiva afeta a satisfação individual.", "Interacional depende da participação nos resultados.", "Informacional define a satisfação no trabalho."], "corretaIndex": 2, "regra": "A justiça distributiva refere-se à percepção de equidade na distribuição de recompensas, recursos, tarefas e oportunidades; quando percebida como injusta, afeta diretamente a satisfação individual do funcionário - diferente da justiça processual (procedimentos usados nas decisões) e interacional (tratamento interpessoal recebido).", "fonte": "UNIRIO - Assistente em Administração - 2019 (Cesgranrio)", "fonteUrl": "https://www.qconcursos.com/questoes-de-concursos/questoes/69ed8c15-1c", "valido": true}, {"id": 285, "materia": "Administração de RH / Processos Administrativos", "assunto": "RH como Responsabilidade de Linha e Função de Staff", "enunciado": "Quando se analisa o que distingue a área de RH de outras áreas de uma organização, identifica-se que ela é, ao mesmo tempo, uma responsabilidade de linha e uma função de staff, o que significa que essa área", "alternativas": ["Atua em ambientes e condições que ela mesma determinou, sobre os quais possui alto grau de poder e controle.", "Lida diretamente com resultados organizacionais, evitando decisões contingenciais ou situacionais.", "Lida diretamente com fontes de receita e, por isso, é alocada nos orçamentos como centros de custos e lucros.", "É um fim em si mesma, controlando eventos e condições que produzem eficácia e eficiência organizacionais.", "Não concentra todos os recursos humanos dentro de sua área, já que estes são alocados nos diversos órgãos da organização, sob autoridade de diversas chefias."], "corretaIndex": 4, "regra": "O princípio de RH como 'responsabilidade de linha e função de staff' (Chiavenato) significa que cada gestor é responsável pela gestão de seus próprios subordinados (linha), enquanto o órgão de RH presta assessoria técnica/normativa (staff); por isso, as pessoas não ficam concentradas no departamento de RH, mas alocadas nos diversos órgãos, sob autoridade de suas respectivas chefias.", "fonte": "UNIRIO - Administrador - 2019 (Cesgranrio)", "fonteUrl": "https://www.qconcursos.com/questoes-de-concursos/questoes/649e6400-1c", "valido": true}, {"id": 286, "materia": "Administração de RH / Processos Administrativos", "assunto": "Treinamento - Níveis de Avaliação de Resultados", "enunciado": "Um gerente avaliou os resultados do último treinamento comportamental de sua Universidade em três níveis distintos: (i) da organização, (ii) dos recursos humanos e, (iii) das tarefas e operações. Para tanto, ele teve de considerar, respectivamente, os seguintes resultados:", "alternativas": ["Redução do absenteísmo, redução no fluxo de produção, elevação do conhecimento das pessoas", "Aumento das habilidades pessoais, aumento de produtividade, melhor relacionamento da organização com seus funcionários", "Redução do índice de acidentes, aumento da eficácia organizacional, melhoria no processo de mudança e inovação", "Melhoria da qualidade dos produtos e serviços, redução do índice de acidentes, aumento das competências das pessoas", "Melhoria do clima organizacional, redução da rotatividade de pessoal, melhor atendimento ao cliente"], "corretaIndex": 4, "regra": "Na avaliação dos resultados de treinamento (Chiavenato), o nível organizacional é medido por indicadores como melhoria do clima e redução da rotatividade; o nível de recursos humanos por indicadores relacionados às pessoas; e o nível de tarefas/operações por indicadores operacionais como atendimento ao cliente - a alternativa correta espelha corretamente essa correspondência entre os três níveis.", "fonte": "UNIRIO - Administrador - 2019 (Cesgranrio)", "fonteUrl": "https://www.qconcursos.com/questoes-de-concursos/questoes/64960ed3-1c", "valido": true}, {"id": 287, "materia": "Administração de RH / Processos Administrativos", "assunto": "Avaliação de Desempenho - Desenvolvimento de Pessoas", "enunciado": "Um funcionário da área de RH de uma organização pública questionou a necessidade de avaliação de desempenho, argumentando que ninguém pode ser despedido devido à estabilidade de emprego. Outro funcionário contestou, afirmando que a avaliação de desempenho integra as práticas de RH complementando processos específicos de", "alternativas": ["Aplicação de pessoas - monitorar e localizar pessoas com características adequadas", "Manutenção de pessoas - proporcionando retroação sobre desempenho e potencialidades", "Monitoração e controle de pessoas - indicando desempenho e resultados alcançados", "Desenvolvimento de pessoas - indicando pontos fortes/fracos e potencialidades a ampliar", "Provisão de pessoas - indicando integração em cargos e tarefas"], "corretaIndex": 3, "regra": "A avaliação de desempenho, ainda que a organização tenha estabilidade de emprego, tem função essencial no subsistema de desenvolvimento de pessoas, pois fornece retroação sobre pontos fortes e fracos e potencialidades a serem desenvolvidas, mesmo sem implicar em demissão.", "fonte": "UNIRIO - Administrador - 2019 (Cesgranrio)", "fonteUrl": "https://www.qconcursos.com/questoes-de-concursos/questoes/648f9f27-1c", "valido": true}, {"id": 288, "materia": "Administração de RH / Processos Administrativos", "assunto": "Recrutamento e Seleção - RH Estratégico", "enunciado": "Em uma Universidade pública, com um modelo organizacional orgânico, foi implementada uma gestão de RH na qual o processo de recrutamento e seleção de pessoal, além de preencher os requisitos e qualificações do cargo, busca pessoas que: (i) se tornem capital intelectual da empresa, (ii) se comprometam a alcançar os objetivos empresariais e (iii) saibam trabalhar em equipe e compartilhar seus conhecimentos. As características desse modelo organizacional são as de um RH", "alternativas": ["Controlador", "Estratégico", "Tradicional", "Mecanicista", "Burocrático"], "corretaIndex": 1, "regra": "O RH estratégico busca alinhar o processo de recrutamento e seleção aos objetivos estratégicos da organização, valorizando capital intelectual, comprometimento com metas organizacionais e capacidade de trabalho colaborativo - superando a visão tradicional/burocrática focada apenas em requisitos técnicos do cargo.", "fonte": "UNIRIO - Administrador - 2019 (Cesgranrio)", "fonteUrl": "https://www.qconcursos.com/questoes-de-concursos/questoes/648cc9fb-1c", "valido": true}, {"id": 289, "materia": "Administração de RH / Processos Administrativos", "assunto": "Avaliação de Desempenho - Medidas Objetivas", "enunciado": "É necessário medir com precisão o desempenho dos funcionários. Dessa forma, é possível apontar ao funcionário os quesitos em que ele pode melhorar. Em uma empresa, ao final do ano, o gerente apresentou à direção a avaliação do desempenho dos seus subordinados. Esses funcionários foram avaliados com base na taxa de abstenção, no número de reclamações de clientes e na quantidade de vendas. Nesse caso, foram utilizadas medidas de desempenho", "alternativas": ["Frontais", "Objetivas", "Orgânicas", "Subjetivas", "Disciplinares"], "corretaIndex": 1, "regra": "Medidas objetivas de desempenho são aquelas quantificáveis e verificáveis, obtidas de sistemas de informação (ex.: taxa de absenteísmo, número de reclamações, volume de vendas), em contraposição às medidas subjetivas, baseadas em julgamento pessoal do avaliador.", "fonte": "UNIRIO - Administrador - 2019 (Cesgranrio)", "fonteUrl": "https://www.qconcursos.com/questoes-de-concursos/questoes/6486459c-1c", "valido": true}, {"id": 290, "materia": "Administração de RH / Processos Administrativos", "assunto": "Qualidade de Vida no Trabalho - Fatores no Desenho de Cargos", "enunciado": "Em busca de qualidade de vida no trabalho, quando o gestor projeta um cargo, ele deve levar em consideração os fatores que o cercam. Sendo assim, o gestor que, ao projetar um cargo, pensa a respeito da expectativa social, das habilidades e da disponibilidade potencial de empregados estará tratando, especificamente, de fatores", "alternativas": ["internos", "higiênicos", "ambientais", "organizacionais", "comportamentais"], "corretaIndex": 4, "regra": "No modelo de desenho de cargos com foco em QVT, os fatores comportamentais dizem respeito às características humanas envolvidas, como expectativas sociais dos empregados, suas habilidades e disponibilidade de mão de obra qualificada no mercado - distintos dos fatores organizacionais (fluxo de trabalho, práticas) e ambientais.", "fonte": "UNIRIO - Administrador - 2019 (Cesgranrio)", "fonteUrl": "https://www.qconcursos.com/questoes-de-concursos/questoes/647aca3d-1c", "valido": true}, {"id": 291, "materia": "Administração de RH / Processos Administrativos", "assunto": "Gestão do Conhecimento - Processo de Captura", "enunciado": "Na composição de um modelo genérico no âmbito da gestão do conhecimento, devem ser considerados sete processos. O primeiro desses processos é a identificação, que está voltada para questões estratégicas para o sucesso da organização. O segundo processo é a captura, que", "alternativas": ["Contribui de forma decisiva para potencializar a criação de conhecimento, envolvendo dimensões como aprendizagem, externalização do conhecimento, lições aprendidas, pensamento crítico, pesquisa, experimentação e inovação.", "Dissemina o conhecimento automaticamente para diversos interessados, de forma que um novo conhecimento seja rapidamente notificado a quem dele necessite.", "Garante a recuperação rápida, fácil e correta do conhecimento, por meio de sistemas de armazenagem efetivos, considerando qual a melhor forma de se recuperar o conhecimento.", "Representa a aquisição de conhecimentos, habilidades e experiências necessários para se criarem e se manterem as competências essenciais e as áreas do conhecimento selecionadas e mapeadas.", "Filtra o conhecimento, avalia a sua qualidade, sintetiza e procede a sua avaliação para fins de aplicação futura, considerando que nem todo o conhecimento gerado e desenvolvido deve ser armazenado."], "corretaIndex": 3, "regra": "No modelo de sete processos de gestão do conhecimento (Probst, Raub e Romhardt), a etapa de 'captura' refere-se à aquisição de conhecimentos, habilidades e experiências necessários para se criarem e manterem as competências essenciais mapeadas na fase de identificação.", "fonte": "Eletrobras-Eletronuclear - Arquivista - 2022 (Cesgranrio)", "fonteUrl": "https://www.qconcursos.com/questoes-de-concursos/questoes/2ef7682e-ec", "valido": true}, {"id": 292, "materia": "Gestão de Sistemas Integrados", "assunto": "Ferramentas da Qualidade - Diagrama de Ishikawa", "enunciado": "O Diagrama de Ishikawa é também denominado Diagrama", "alternativas": ["Espinha de Peixe", "SWOT", "de Brainstorming", "de Delphi", "de Pareto"], "corretaIndex": 0, "regra": "O Diagrama de Ishikawa (ou Diagrama de Causa e Efeito) é popularmente conhecido como 'Espinha de Peixe' devido ao seu formato gráfico, que organiza as causas de um problema em torno de categorias (geralmente os 6M) convergindo para o efeito (o problema) na 'cabeça do peixe'.", "fonte": "Cesgranrio - 2013 - Liquigás - Profissional Júnior (Análise de Sistemas/TI)", "fonteUrl": "https://olhonavaga.com.br/questoes/questoes?ma=1032&as=8060", "valido": true}, {"id": 293, "materia": "Gestão de Sistemas Integrados", "assunto": "Ferramentas da Qualidade - Diagrama de Ishikawa (6M)", "enunciado": "O Diagrama de Ishikawa, também conhecido como Diagrama de Causa e Efeito ou Espinha de Peixe, permite estruturar hierarquicamente as causas de determinado problema ou oportunidade de melhoria. As causas de um problema podem ser agrupadas, a partir do conceito dos 6M, como decorrentes de falhas em materiais, em mão de obra, em máquinas, em meio ambiente, em _____ e em _____.", "alternativas": ["treinamento e em tecnologias", "métodos e em medidas", "métodos e em tecnologias", "estratégias e em tecnologias", "estratégias e em medidas"], "corretaIndex": 1, "regra": "Os '6M' do Diagrama de Ishikawa são: Método, Mão de obra, Material, Máquina, Medida e Meio ambiente.", "fonte": "Cesgranrio - 2011 - Petrobras - Técnico de Suprimentos de Bens e Serviços Júnior", "fonteUrl": "https://www.qconcursos.com/questoes-de-concursos/questoes/134543a9-8a", "valido": true}, {"id": 294, "materia": "Gestão de Sistemas Integrados", "assunto": "ISO 14001 - Sistema de Gestão Ambiental", "enunciado": "A ISO 14001 é a norma internacionalmente conhecida que apresenta um Sistema de Gestão Ambiental (SGA). O processo de implementação desse sistema possui quatro fases. A última fase desse processo é a de", "alternativas": ["auditoria e certificação", "implantação das medidas de controle", "planejamento", "indicação dos desvios do processo", "monitoramento"], "corretaIndex": 0, "regra": "A implementação de um SGA segue a lógica do ciclo PDCA: planejamento, implantação das medidas de controle, monitoramento e, por fim, auditoria e certificação.", "fonte": "Cesgranrio - 2011 - Petroquímica Suape - Operador Pleno", "fonteUrl": "https://www.qconcursos.com/questoes-de-concursos/questoes/439cb704-d7", "valido": true}, {"id": 295, "materia": "Gestão de Sistemas Integrados", "assunto": "Ferramentas da Qualidade - Diagrama de Causa e Efeito", "enunciado": "O Diagrama de Causa e Efeito consiste em uma técnica visual que interliga os resultados (efeitos) com os fatores (causas), constituindo-se num instrumento muito usado para estudar", "alternativas": ["a relação ação/benefício, de modo que se possa priorizar a ação que trará o melhor resultado.", "a ordenação nas causas de perdas que devem ser sanadas.", "a determinação do estado atual da alocação de recursos e as estimativas de custos e desempenhos.", "as questões de 5W1H ou de 5W2H.", "os fatores que determinam os resultados que se desejam obter e as causas de problemas que se precisam evitar."], "corretaIndex": 4, "regra": "O Diagrama de Causa e Efeito relaciona fatores (causas) a resultados (efeitos), servindo tanto para identificar causas de problemas a evitar quanto fatores que levam a resultados desejados.", "fonte": "Cesgranrio - 2014 - Petrobras - Engenheiro(a) de Produção Júnior", "fonteUrl": "https://www.qconcursos.com/questoes-de-concursos/questoes/1cc2c70b-85", "valido": true}, {"id": 296, "materia": "Gestão de Sistemas Integrados", "assunto": "Ciclo PDCA", "enunciado": "O ciclo PDCA é uma ferramenta que pode ser utilizada no gerenciamento de projetos em diversas áreas, auxiliando no alcance das metas desejadas. A sigla PDCA é formada pelas iniciais, na língua inglesa, de quatro ações que formam a estrutura desse ciclo. Quais ações, no idioma português, são enfatizadas por essa sigla?", "alternativas": ["Planejar, fazer, checar e agir", "Produzir, avaliar, calcular e organizar", "Planejar, avaliar, calcular e agir", "Produzir, distinguir, checar e organizar", "Planejar, distinguir, checar e agir"], "corretaIndex": 0, "regra": "PDCA = Plan (Planejar), Do (Fazer/Executar), Check (Checar/Verificar), Act (Agir/Atuar corretivamente).", "fonte": "Cesgranrio - 2013 - Liquigás - Engenheiro Júnior (Elétrica)", "fonteUrl": "https://www.qconcursos.com/questoes-de-concursos/questoes/143d7fae-37", "valido": true}, {"id": 297, "materia": "Gestão de Sistemas Integrados", "assunto": "Gestão por Processos", "enunciado": "A gestão por processos é uma forma de gerenciar as organizações que apresenta seu foco no planejamento estratégico, na visão sistêmica e na estruturação das atividades da organização em processos. A esse respeito, considere as afirmativas: I - Possibilita identificar atividades que geram maior valor para o cliente. II - Permite integrar atividades e orientar ações para resultados. III - Tem como objetivo identificar recursos tecnológicos necessários. Está(ão) correta(s) a(s) afirmativa(s):", "alternativas": ["I", "II", "III", "I e II", "II e III"], "corretaIndex": 3, "regra": "A gestão por processos tem como principais objetivos agregar valor ao cliente (I) e integrar/orientar as atividades para resultados organizacionais (II). A identificação de recursos tecnológicos (III) não é um objetivo central.", "fonte": "Cesgranrio - 2012 - Petrobras - Técnico de Suprimentos de Bens e Serviços Júnior", "fonteUrl": "https://www.qconcursos.com/questoes-de-concursos/questoes/bcfa7568-44", "valido": true}, {"id": 298, "materia": "Gestão de Sistemas Integrados", "assunto": "Mapeamento de Processos - Notação de Fluxogramas", "enunciado": "O mapeamento de processos envolve a descrição de processos dentro dos quais as atividades se relacionam umas com as outras. Nesse sentido, o símbolo (oval/elipse) identifica", "alternativas": ["Decisão", "Atividade", "Direção do fluxo", "Início ou final do processo", "Input ou output de um processo"], "corretaIndex": 3, "regra": "Na notação padrão de fluxogramas, a elipse (oval) representa o marco de início ou fim de um processo; o losango representa decisão; o retângulo representa atividade.", "fonte": "Cesgranrio - 2014 - EPE (Empresa de Pesquisa Energética) - Analista de Gestão Corporativa", "fonteUrl": "https://www.qconcursos.com/questoes-de-concursos/questoes/5a95c6ca-10", "valido": true}, {"id": 299, "materia": "Gestão de Sistemas Integrados", "assunto": "Indicadores de Desempenho (KPI)", "enunciado": "Com relação aos indicadores de desempenho utilizados em uma empresa, assinale a afirmativa INCORRETA.", "alternativas": ["Deve-se sempre tentar obter os indicadores dos concorrentes e colocá-los como metas a serem atingidas.", "É necessário estabelecer padrões para avaliar os indicadores, como, por exemplo, comparar os índices obtidos com: dados históricos, dados de empresas do mesmo ramo, dados dos concorrentes e dados de especialistas (benchmarking).", "Índices representam o padrão de medida dos indicadores, permitindo a uniformidade, o estabelecimento de metas e o acompanhamento, devendo-se usar valores relativos.", "Recentemente vem ganhando destaque a implantação de painéis de controle, que informam os tomadores de decisão sobre a evolução da organização.", "Uma abordagem multidimensional e hierarquizada dos indicadores prevê indicadores para o negócio, para seus processos e para as suas atividades."], "corretaIndex": 0, "regra": "É incorreto afirmar que se deve 'sempre' adotar os indicadores dos concorrentes como metas: as metas devem considerar a realidade e a estratégia da própria organização.", "fonte": "Cesgranrio - 2006 - Petrobras - Analista de Sistemas Pleno (Processos)", "fonteUrl": "https://www.qconcursos.com/questoes-de-concursos/questoes/bb06d098-9a", "valido": true}, {"id": 300, "materia": "Gestão de Sistemas Integrados", "assunto": "BPM (Business Process Management)", "enunciado": "O Business Process Management (BPM) se constitui em", "alternativas": ["Software de gestão empresarial de grande porte.", "Ferramenta de reengenharia de processos de trabalho de uma empresa.", "Conjunto de workflows que indica o modus operandi dos negócios de uma empresa.", "Ferramenta de modelagem de processos que é utilizada para documentar os processos atuais de negócio de uma empresa, sem propor significativas mudanças.", "Modo estruturado de gerência e otimização de performance dos processos de negócio de uma empresa."], "corretaIndex": 4, "regra": "BPM não é um software nem apenas uma ferramenta de modelagem: é uma disciplina de gestão que combina metodologias, práticas e tecnologias para modelar, executar, monitorar e otimizar continuamente os processos de negócio.", "fonte": "Cesgranrio - 2010 - Petrobras - Analista de Sistemas Júnior (Processos de Negócios)", "fonteUrl": "https://www.qconcursos.com/questoes-de-concursos/questoes/a4c179de-7e", "valido": true}, {"id": 301, "materia": "Gestão de Sistemas Integrados", "assunto": "Gestão de Riscos", "enunciado": "Um objetivo da Gestão de Riscos é", "alternativas": ["Controlar os riscos relativos à organização, de modo que permaneçam abaixo de valores tolerados.", "Estabelecer as regras comportamentais da organização.", "Fazer a verificação periódica dos atributos de um objeto.", "Fazer a avaliação sistemática, documentada e periódica da eficiência e eficácia da organização no exercício da função segurança.", "Abordar a organização, caracterizando-a do ponto de vista da segurança."], "corretaIndex": 0, "regra": "Conforme a lógica da NBR ISO 31000, a Gestão de Riscos visa identificar, analisar, avaliar e tratar riscos de forma a mantê-los dentro de níveis toleráveis definidos pela organização (apetite ao risco).", "fonte": "Cesgranrio - 2013 - Liquigás - Engenheiro Júnior (Segurança do Trabalho)", "fonteUrl": "https://www.qconcursos.com/questoes-de-concursos/questoes/85f9298b-83", "valido": true}, {"id": 302, "materia": "Gestão de Sistemas Integrados", "assunto": "Ferramentas da Qualidade - Diagrama de Pareto", "enunciado": "Considere a descrição gráfica que identifica as principais reclamações de clientes em relação às companhias telefônicas. As colunas refletem as frequências dessas reclamações em ordem decrescente de importância da esquerda para a direita. Essa ferramenta para o controle de qualidade é denominada", "alternativas": ["Diagrama de causa e efeito", "Diagrama de dispersão", "Diagrama de Pareto", "Gráfico de controle", "Histograma"], "corretaIndex": 2, "regra": "O Diagrama (ou Gráfico) de Pareto organiza dados em barras verticais em ordem decrescente de frequência/importância, baseando-se no princípio 80/20.", "fonte": "Cesgranrio - 2011 - Petrobras - Técnico de Projetos, Construção e Montagem Júnior (Estruturas Navais)", "fonteUrl": "https://www.qconcursos.com/questoes-de-concursos/questoes/6bbe5000-46", "valido": true}, {"id": 303, "materia": "Gestão de Sistemas Integrados", "assunto": "OHSAS 18001 - Segurança e Saúde Ocupacional", "enunciado": "A Norma OHSAS 18001:2007 tem como proposta", "alternativas": ["Fornecer especificações detalhadas para o projeto de um sistema de gestão.", "Especificar requisitos para um Sistema de Gestão da Segurança e Saúde Ocupacional.", "Prescrever critérios específicos de desempenho de Segurança e Saúde Ocupacional.", "Atingir, por meio do sistema de gestão, outras áreas relacionadas à saúde e segurança.", "Recomendar que os seus requisitos sejam incorporados a determinados Sistemas de Gestão de Segurança e Saúde Ocupacional."], "corretaIndex": 1, "regra": "A OHSAS 18001 é uma norma de requisitos (não de desempenho prescritivo nem de especificações de projeto) para implantação de um SGSSO, posteriormente substituída pela ISO 45001.", "fonte": "Cesgranrio - 2011 - Petrobras - Técnico de Enfermagem do Trabalho", "fonteUrl": "https://www.qconcursos.com/questoes-de-concursos/questoes/77f3e85e-bd", "valido": true}, {"id": 304, "materia": "Gestão de Sistemas Integrados", "assunto": "ISO 45001:2018", "enunciado": "A ISO 45001:2018 — Sistema de Gestão de Segurança e Saúde Ocupacional – Requisitos com Orientação para Uso — elenca uma série de requisitos que foram divididos nas etapas de contexto da organização, liderança e participação dos trabalhadores, planejamento, suporte, operação, avaliação de desempenho e melhoria. Considerando-se a ISO 45001:2018, o requisito gestão de mudança pertence à seguinte etapa:", "alternativas": ["suporte", "melhoria", "operação", "planejamento", "avaliação de desempenho"], "corretaIndex": 2, "regra": "Na estrutura da ISO 45001:2018 (Anexo SL/HLS), a 'gestão de mudanças' está prevista na cláusula 8 (Operação).", "fonte": "Cesgranrio - 2023 - Transpetro - Profissional Transpetro de Nível Superior Júnior (Ênfase 20 - Engenharia de Segurança)", "fonteUrl": "https://www.qconcursos.com/questoes-de-concursos/questoes/acaa0ee9-a4", "valido": true}, {"id": 305, "materia": "Gestão de Sistemas Integrados", "assunto": "ISO 9001 - Manual da Qualidade", "enunciado": "A norma NBR ISO 9001 aponta que o sistema de gestão da qualidade de uma empresa deve ter, entre seus documentos, um que mostra o escopo do sistema de gestão da qualidade, os procedimentos documentados instituídos para o sistema de gestão da qualidade, ou referência a eles, e a descrição da interação entre os processos do sistema de gestão da qualidade. Tais itens são documentados no", "alternativas": ["Controle de Documentos", "Controle Quantitativo", "Manual de Riscos", "Manual da Qualidade", "Procedimento Documental"], "corretaIndex": 3, "regra": "O Manual da Qualidade é o documento central do SGQ na ISO 9001 que descreve o escopo do sistema, referencia os procedimentos documentados e descreve a interação entre os processos.", "fonte": "Cesgranrio - 2009 - TermoMacaé Ltda - Engenheiro de Segurança", "fonteUrl": "https://www.qconcursos.com/questoes-de-concursos/questoes/e7b2a7fd-99", "valido": true}, {"id": 306, "materia": "Gestão de Sistemas Integrados", "assunto": "Política de QSMS (Qualidade, Segurança, Meio Ambiente e Saúde)", "enunciado": "A Política de Qualidade, Segurança, Meio Ambiente e Saúde – QSMS – da Transpetro, está estruturada contemplando 15 Diretrizes Corporativas de SMS da Petrobras. Dentre elas, está a diretriz 'Contingência', que está relacionada a", "alternativas": ["Prever e enfrentar com rapidez e eficácia as situações de emergência visando à máxima redução de seus efeitos.", "Manter conformidade com a legislação vigente em segurança, meio ambiente e saúde ao longo do ciclo de vida das atividades.", "Executar operações de acordo com procedimentos estabelecidos, utilizando instalações e equipamentos em condições seguras.", "Implementar mecanismos de medição, avaliação e aperfeiçoamento do desempenho em segurança, meio ambiente e saúde.", "Garantir que informações relacionadas à segurança, meio ambiente e saúde sejam íntegras e disponíveis para tomada de decisão."], "corretaIndex": 0, "regra": "A diretriz 'Contingência' das Diretrizes Corporativas de SMS da Petrobras/Transpetro refere-se à capacidade de resposta rápida e eficaz a emergências, minimizando seus impactos.", "fonte": "Cesgranrio - 2023 - Transpetro - Profissional Transpetro de Nível Superior Júnior (Ênfase 16 - Engenharia Civil)", "fonteUrl": "https://www.qconcursos.com/questoes-de-concursos/questoes/09cfd095-a4", "valido": true}, {"id": 307, "materia": "Gestão de Sistemas Integrados", "assunto": "Benchmarking - Tipos", "enunciado": "Com relação aos tipos de benchmarking, pode-se afirmar que", "alternativas": ["Benchmarking competitivo é uma comparação entre organizações externas que não concorrem num mesmo mercado.", "Benchmarking interno ocorre entre operações que fazem parte de uma mesma organização.", "Benchmarking não competitivo é o mesmo que benchmarking interno.", "Benchmarking não competitivo é uma comparação entre concorrentes de um mesmo mercado.", "Seus indicadores de desempenho estão restritos às funções-objetivo."], "corretaIndex": 1, "regra": "O benchmarking interno é aquele realizado entre unidades, departamentos ou operações de uma mesma organização.", "fonte": "Cesgranrio - 2008 - Petrobras - Engenheiro de Produção Júnior", "fonteUrl": "https://www.qconcursos.com/questoes-de-concursos/questoes/6d81c390-84", "valido": true}, {"id": 308, "materia": "Gestão de Sistemas Integrados", "assunto": "Benchmarking - Etapas", "enunciado": "Benchmarking pode ser definida como uma técnica que consiste em fazer comparações e procurar imitar as organizações, concorrentes ou não, do mesmo ramo de negócios ou de outros, que tenham práticas exemplares de administração. Associe as etapas da técnica do benchmarking (Planejamento, Análise, Integração, Ação) às suas características (implementação dos resultados; definição das melhores práticas a copiar; coleta/estudo/interpretação dos dados; definição das modificações no produto/processo).", "alternativas": ["I-Q, II-T, III-P, IV-S", "I-Q, II-R, III-T, IV-P", "I-S, II-T, III-Q, IV-P", "I-S, II-P, III-T, IV-R", "I-T, II-R, III-P, IV-Q"], "corretaIndex": 1, "regra": "As etapas clássicas do benchmarking são: Planejamento (definir o que copiar), Análise (coletar e interpretar dados), Integração (definir modificações) e Ação (implementar os resultados).", "fonte": "Cesgranrio - 2013 - IBGE - Analista (Recursos Materiais e Logística)", "fonteUrl": "https://www.qconcursos.com/questoes-de-concursos/questoes/95c9e77b-35", "valido": true}, {"id": 309, "materia": "Gestão de Sistemas Integrados", "assunto": "Benchmarking - Finalidade", "enunciado": "O benchmarking é o processo de aprender com os outros e envolve a comparação do seu próprio desempenho ou método com o de outras operações comparáveis. As empresas usam o benchmarking para", "alternativas": ["Compreender melhor como empresas líderes atuam de maneira a aperfeiçoar seus próprios processos.", "Copiar ou imitar operações bem-sucedidas de outras organizações.", "Promover projetos isolados de melhoria de processos.", "Comparar processos semelhantes de empresas similares do mesmo setor industrial.", "Fazer espionagem industrial em grandes empresas."], "corretaIndex": 0, "regra": "O objetivo do benchmarking não é copiar/imitar de forma acrítica, mas sim compreender práticas de organizações de referência para adaptá-las e aperfeiçoar os próprios processos.", "fonte": "Cesgranrio - 2011 - Petrobras - Engenheiro de Produção Júnior", "fonteUrl": "https://www.qconcursos.com/questoes-de-concursos/questoes/5f85b618-47", "valido": true}, {"id": 310, "materia": "Controle Patrimonial", "assunto": "Gestão de Estoques - Curva ABC", "enunciado": "A curva ABC é um instrumento utilizado na gestão de estoques que tem por objetivo:", "alternativas": ["Classificar os itens dos estoques em função da sua importância para o processo produtivo.", "Dividir os itens segundo os seus custos de aquisição.", "Separar o estoque em setores e por nível de integração à produção.", "Definir grupos para os quais os diferentes sistemas de controle de estoque serão mais apropriados.", "Integrar o sistema de estoques ao sistema da UNSPSC."], "corretaIndex": 3, "regra": "A Curva ABC classifica itens conforme sua relevância (valor/consumo) para definir o grau de rigor e o tipo de sistema de controle a ser aplicado a cada grupo.", "fonte": "CESGRANRIO - 2011 - Petrobras - Técnico de Suprimentos de Bens e Serviços Júnior - Elétrica", "fonteUrl": "https://www.qconcursos.com/questoes-de-concursos/questoes/cf26856e-d1", "valido": true}, {"id": 311, "materia": "Controle Patrimonial", "assunto": "Gestão de Estoques - Decisões da Área", "enunciado": "A preocupação com a gestão de estoques está presente em diferentes tipos de empresas. São decisões exclusivas da gestão de estoques:", "alternativas": ["Quanto pedir de cada item, quando pedir os itens e como controlar o sistema de estoques.", "Quanto pedir de cada item, quando vender os itens e como controlar o sistema de estoques.", "Quanto pedir de cada item, quando pedir os itens e como sequenciar a produção dos itens.", "Quanto o mercado tem de potencial, quando pedir os itens e como entregar os itens aos clientes.", "Quanto vender de cada item, quando entregar os produtos aos clientes e como cobrar as faturas dos clientes."], "corretaIndex": 0, "regra": "A gestão de estoques resume-se a três decisões centrais: quanto pedir (lote de compra), quando pedir (ponto de pedido) e como controlar.", "fonte": "CESGRANRIO - 2011 - Petrobras - Técnico de Suprimentos de Bens e Serviços Júnior - Elétrica", "fonteUrl": "https://www.qconcursos.com/questoes-de-concursos/questoes/c8f91d29-d1", "valido": true}, {"id": 312, "materia": "Controle Patrimonial", "assunto": "Custos de Manutenção de Estoques", "enunciado": "Os custos de manutenção de estoques resultam da estocagem dos bens por um período de tempo e são, aproximadamente, proporcionais à quantidade média dos bens mantidos. Esses custos podem ser agrupados em quatro classes. A seguinte classe de custos NÃO é um exemplo de custo de manutenção de estoque:", "alternativas": ["de capital", "de espaço", "de mudança de tecnologia", "do risco de estoque", "dos serviços de estoque"], "corretaIndex": 2, "regra": "Os quatro custos clássicos de manutenção de estoque são: de capital, de espaço, de serviços de estoque e de risco. Custo de mudança tecnológica não integra essa classificação.", "fonte": "CESGRANRIO - 2014 - Petrobras - Técnico de Logística de Transporte Júnior - Controle", "fonteUrl": "https://www.qconcursos.com/questoes-de-concursos/questoes/7547b6c6-83", "valido": true}, {"id": 313, "materia": "Controle Patrimonial", "assunto": "Gestão de Estoques - Risco na Cadeia de Suprimentos", "enunciado": "A manutenção de estoques implica riscos de investimento e de possibilidade de obsolescência em diversos pontos da cadeia de suprimentos. Esses riscos são maiores para o", "alternativas": ["Varejista", "Atacadista", "Fabricante", "Distribuidor", "Cliente pessoa física"], "corretaIndex": 2, "regra": "O fabricante mantém estoques em múltiplos estágios, com maior tempo de permanência e maior exposição a mudanças de demanda e tecnologia, ampliando o risco de obsolescência.", "fonte": "CESGRANRIO - 2018 - LIQUIGÁS - Assistente Administrativo", "fonteUrl": "https://www.qconcursos.com/questoes-de-concursos/questoes/c700907f-62", "valido": true}, {"id": 314, "materia": "Controle Patrimonial", "assunto": "Administração de Materiais - Condições Básicas", "enunciado": "A administração de materiais é importante para a organização cujas atividades devem resultar na redução de custos para o aperfeiçoamento do desempenho da organização. É condição básica para a boa administração de materiais", "alternativas": ["Catalogar cada item do estoque de maneira aleatória, obedecendo às especificações da área que o utiliza, sem classificá-lo.", "Planejar, organizar e controlar as tarefas necessárias à definição de qualidade, à aquisição, à guarda e à aplicação dos materiais.", "Manter os estoques de todos os itens no nível necessário para a capacidade máxima de produção.", "Controlar o consumo de materiais com base na utilização dos mesmos, desconsiderando a utilização de métodos específicos.", "Armazenar e controlar os produtos acabados porque apenas estes representam custos para a empresa."], "corretaIndex": 1, "regra": "A administração de materiais engloba o ciclo completo de planejamento, organização e controle das atividades de qualidade, aquisição, armazenagem e aplicação/consumo dos materiais.", "fonte": "CESGRANRIO - 2012 - BR Distribuidora - Técnico de Administração e Controle Júnior", "fonteUrl": "https://www.qconcursos.com/questoes-de-concursos/questoes/d0a1b0a2-9c", "valido": true}, {"id": 315, "materia": "Controle Patrimonial", "assunto": "Classificação de Materiais em Estoque", "enunciado": "O bom funcionamento dos vários setores da organização e um bom padrão de atendimento às necessidades da empresa e ao mercado consumidor também dependem da boa gestão de estoques. A boa gestão de estoques é dependente da classificação dos materiais para que estes sejam agrupados, segundo suas características, utilidade e outras propriedades. Assinale a alternativa correta.", "alternativas": ["Materiais estocáveis – são os materiais que não são críticos para a operação da organização.", "Materiais de consumo – são os materiais que, na empresa, são utilizados pelo setor específico de manutenção.", "Materiais de estocagem permanente – são os materiais mantidos em nível normal de estoque, garantindo o abastecimento ininterrupto das operações da empresa.", "Materiais de estocagem temporária – são os materiais com características perecíveis, ou seja, com prazo determinado para ficar em estoque.", "Materiais não estocáveis – são os materiais críticos para a operação da empresa e que são consumidos imediatamente, não ficando no estoque."], "corretaIndex": 2, "regra": "Materiais de estocagem permanente são repostos continuamente para manter nível normal (mínimo/máximo) de estoque e garantir o abastecimento sem interrupções.", "fonte": "CESGRANRIO - 2014 - Petrobras - Técnico de Suprimento de Bens e Serviços Júnior - Administração", "fonteUrl": "https://www.qconcursos.com/questoes-de-concursos/questoes/38c77622-9d", "valido": true}, {"id": 316, "materia": "Controle Patrimonial", "assunto": "Codificação de Materiais", "enunciado": "De modo geral, as grandes empresas têm necessidade de identificar com facilidade seus materiais, classificando-os por meio de símbolos alfanuméricos ou simplesmente numéricos. São benefícios da codificação de materiais, EXCETO", "alternativas": ["Facilitar a padronização dos materiais, evitando duplicidade de itens em estoque.", "Facilitar o controle de estoques e inventário.", "Facilitar o controle contábil dos itens de estoque.", "Proporcionar redução da área de armazenagem.", "Permitir agrupamentos de itens sob o aspecto de compras e gerar ganhos de negociação com fornecedores."], "corretaIndex": 3, "regra": "A codificação de materiais melhora identificação, padronização, controle contábil/inventário e poder de negociação em compras, mas não reduz, por si só, a área física de armazenagem.", "fonte": "CESGRANRIO - 2010 - Petrobras - Técnico de Suprimentos de Bens e Serviços Júnior", "fonteUrl": "https://www.qconcursos.com/questoes-de-concursos/questoes/b25859af-28", "valido": true}, {"id": 317, "materia": "Controle Patrimonial", "assunto": "Inventário Periódico x Permanente", "enunciado": "A principal diferença entre o inventário periódico e o inventário permanente é que, no inventário", "alternativas": ["periódico, é necessário utilizar fichas de controle de estoque para apurar o custo de cada mercadoria vendida.", "periódico, não é necessária a contagem física do estoque final, para apurar o custo de cada mercadoria vendida.", "periódico, pode-se determinar o valor do Custo das Mercadorias Vendidas (CMV) e o saldo do estoque remanescente em cada operação.", "permanente, é necessária a contagem física do estoque final para apurar o custo de cada mercadoria vendida.", "permanente, pode-se determinar o valor do Custo das Mercadorias Vendidas (CMV) e o saldo do estoque remanescente em cada operação."], "corretaIndex": 4, "regra": "No inventário permanente, cada movimentação é registrada em ficha de controle, permitindo apurar CMV e saldo de estoque a qualquer momento; no periódico, o CMV só é apurado ao final do período, mediante contagem física.", "fonte": "CESGRANRIO - 2012 - Petrobras - Técnico de Contabilidade", "fonteUrl": "https://www.qconcursos.com/questoes-de-concursos/questoes/0789c32c-86", "valido": true}, {"id": 318, "materia": "Controle Patrimonial", "assunto": "Ponto de Ressuprimento / Ponto de Pedido", "enunciado": "No que se refere apenas ao seu cálculo, o ponto de ressuprimento", "alternativas": ["Localiza-se onde há o lapso entre o pedido de reposição e sua chegada ao estoque.", "Pode ser derivado do lead time do pedido e da taxa de demanda.", "Deve ser calculado apenas quando a demanda e/ou o estoque de segurança são incertos.", "É definido, de forma geral, em um ponto localizado entre a quantidade mínima e o estoque de segurança.", "É determinado por uma análise que engloba as seguintes variáveis: lead time, tempo de produção da indústria, estoque de segurança e demanda de produtos de forma atemporal."], "corretaIndex": 1, "regra": "O ponto de pedido é calculado como PP = (demanda média × lead time) + estoque de segurança, derivando diretamente do lead time e da taxa de demanda.", "fonte": "CESGRANRIO - 2023 - Transpetro - Profissional Transpetro de Nível Superior Júnior (Ênfase 13: Contabilidade)", "fonteUrl": "https://www.qconcursos.com/questoes-de-concursos/questoes/1c27a060-a4", "valido": true}, {"id": 319, "materia": "Controle Patrimonial", "assunto": "Depreciação - Valor Depreciável", "enunciado": "Uma empresa comercial apresentou as seguintes informações relativas a um bem material classificado no Balanço Patrimonial no Ativo Não Circulante Imobilizado: Custo reconhecido do ativo 6.000,00; Depreciação Acumulada 1.500,00; Valor Residual 800,00. Considerando-se exclusivamente as informações recebidas, o valor depreciável deste ativo imobilizado, em reais, é", "alternativas": ["3.700,00", "4.500,00", "5.200,00", "5.700,00", "6.000,00"], "corretaIndex": 1, "regra": "Valor depreciável = Custo do ativo − Valor residual = 6.000,00 − 1.500,00 = 4.500,00 (conforme gabarito oficial da banca).", "fonte": "CESGRANRIO - 2011 - Petrobras - Contador Júnior", "fonteUrl": "https://www.qconcursos.com/questoes-de-concursos/questoes/28cb80ad-f3", "valido": true}, {"id": 320, "materia": "Controle Patrimonial", "assunto": "Depreciação Linear - Cálculo", "enunciado": "Um bem patrimonial foi adquirido por R$ 500.000,00, com vida útil estimada de 25 anos e valor residual de R$ 50.000,00. Considerando o método de depreciação linear, quais são a depreciação acumulada e o valor residual (contábil) do bem patrimonial ao final do seu quarto ano de utilização?", "alternativas": ["Depreciação acumulada: R$ 30.000,00 | Valor residual: R$ 420.000,00", "Depreciação acumulada: R$ 36.000,00 | Valor residual: R$ 464.000,00", "Depreciação acumulada: R$ 48.000,00 | Valor residual: R$ 402.000,00", "Depreciação acumulada: R$ 72.000,00 | Valor residual: R$ 428.000,00", "Depreciação acumulada: R$ 80.000,00 | Valor residual: R$ 420.000,00"], "corretaIndex": 3, "regra": "Depreciação anual = (500.000 − 50.000)/25 = 18.000/ano. Em 4 anos: 72.000,00. Valor contábil residual = 500.000 − 72.000 = 428.000,00.", "fonte": "CESGRANRIO - 2010 - BACEN - Técnico do Banco Central - Área 1", "fonteUrl": "https://www.qconcursos.com/questoes-de-concursos/questoes/98ff4823-4d", "valido": true}, {"id": 321, "materia": "Controle Patrimonial", "assunto": "Curva ABC - Associação de Características", "enunciado": "A classificação do estoque pela curva ABC é um método antigo, porém eficaz, e baseia-se no raciocínio do Diagrama de Pareto. É através da classificação da curva ABC que se consegue determinar o grau de importância dos itens, permitindo, assim, diferentes níveis de controle com base na importância relativa do item. Associe cada classe (A, B, C) à característica correspondente e assinale a alternativa correta.", "alternativas": ["A – I, B – II, C – III", "A – III, B – II, C – I", "A – I, B – III, C – IV", "A – II, B – IV, C – I", "A – IV, B – III, C – II"], "corretaIndex": 1, "regra": "Na Curva ABC, a classe A concentra poucos itens de maior valor/consumo e exige controle rigoroso; a classe B tem importância intermediária; a classe C reúne muitos itens de baixo valor individual, com controle simplificado.", "fonte": "CESGRANRIO - 2010 - Petrobras - Técnico de Administração e Controle Júnior", "fonteUrl": "https://www.qconcursos.com/questoes-de-concursos/questoes/a51d21ba-da", "valido": true}, {"id": 322, "materia": "Controle Patrimonial", "assunto": "Boas Práticas de Armazenagem", "enunciado": "A armazenagem de materiais adquiridos pela empresa para sua utilização rotineira, tanto na área administrativa quanto na de produção, necessita ter algumas condições fundamentais para que as características de utilização desses materiais sejam respeitadas, possibilitando a otimização dos recursos da organização. Uma boa prática de armazenagem de materiais é a seguinte:", "alternativas": ["Posicionamento da matéria-prima em local distante de onde serão consumidos, considerando o princípio da movimentação de materiais.", "Armazenamento centralizado dos materiais permitindo que a entrega e o inventário sejam realizados mais rapidamente.", "Armazenamento dos materiais em instalações que possibilitem uma rápida movimentação, tornando o processo eficiente.", "Ocupação de todo o espaço do almoxarifado, desconsiderando os aspectos de circulação de pessoas, o que é proibido na área de armazenagem.", "Padronização da armazenagem, igualmente, para todos os materiais da empresa, visando à minimização dos custos e à otimização do espaço."], "corretaIndex": 2, "regra": "Uma boa prática de armazenagem busca agilizar a movimentação interna de materiais (leiaute e instalações adequados), reduzindo tempo e custo operacional.", "fonte": "CESGRANRIO - 2015 - Petrobras - Técnico de Administração e Controle Júnior", "fonteUrl": "https://www.qconcursos.com/questoes-de-concursos/questoes/9bf0d485-c7", "valido": true}, {"id": 323, "materia": "Controle Patrimonial", "assunto": "Movimentação de Cargas no Armazém", "enunciado": "Os trabalhos de transporte de cargas dentro de um armazém são influenciados pelo arranjo físico e pelos equipamentos utilizados. Desse modo, o gerente deve buscar maior eficiência", "alternativas": ["aumentando as distâncias entre movimentações para garantir a segurança dos trabalhadores.", "evitando a consolidação de cargas para reduzir os custos.", "usando transportadoras de esteiras de roletes para roteiros aleatórios.", "padronizando os dispositivos de armazenagem para os diversos produtos.", "utilizando tratores para movimentar cargas em fluxos verticais."], "corretaIndex": 3, "regra": "A padronização de paletes, contêineres e demais dispositivos de armazenagem reduz tempo de manuseio, facilita a movimentação mecanizada e aumenta a eficiência do armazém.", "fonte": "CESGRANRIO - 2010 - IBGE - Analista de Planejamento (Gestão e Infraestrutura)", "fonteUrl": "https://www.qconcursos.com/questoes-de-concursos/questoes/b7f12355-15", "valido": true}, {"id": 324, "materia": "Controle Patrimonial", "assunto": "Funções do Almoxarifado", "enunciado": "Uma empresa, em função de seu recente crescimento e ampliação de negócios, está estruturando seu almoxarifado para que possa guardar e conservar os seus materiais adequadamente. São funções do almoxarifado, EXCETO", "alternativas": ["assegurar que o material adequado esteja na quantidade devida e no local certo, quando necessário.", "impedir que haja divergências de inventário e perdas de qualquer natureza.", "preservar a qualidade e as quantidades exatas dos materiais.", "possibilitar recursos de movimentação e distribuição suficientes a um atendimento rápido e eficiente.", "transformar matéria-prima, energia e informação em bens e/ou produto."], "corretaIndex": 4, "regra": "As funções do almoxarifado giram em torno de guarda, conservação, controle de inventário e distribuição de materiais. Transformar matéria-prima em produto é função da produção, não do almoxarifado.", "fonte": "CESGRANRIO - 2015 - LIQUIGÁS - Assistente Administrativo I", "fonteUrl": "https://www.qconcursos.com/questoes-de-concursos/questoes/96175118-62", "valido": true}, {"id": 325, "materia": "Matemática Financeira", "assunto": "Juros Simples - taxa de juros", "enunciado": "Uma empresa toma um empréstimo de R$ 200.000,00, por 20 dias, a uma determinada taxa de juro, no regime de juros simples. Considere que, ao final desse período, os juros pagos são de R$ 8.800,00. Essa taxa de juro, em regime mensal (30 dias), equivalia, aproximadamente, a", "alternativas": ["4,0%", "4,4%", "6,0%", "6,6%", "8,8%"], "corretaIndex": 3, "regra": "Juros simples: J = C × i × t. De 8.800 = 200.000 × i × 20, obtém-se a taxa diária i ≈ 0,22% ao dia; multiplicando por 30 dias: 0,22% × 30 = 6,6% ao mês.", "fonte": "CESGRANRIO - 2018 - Liquigás - Profissional de Vendas Júnior", "fonteUrl": "https://gratis.estrategiaconcursos.com.br", "valido": true}, {"id": 326, "materia": "Matemática Financeira", "assunto": "Juros Simples - capital aplicado", "enunciado": "Aldo aplicou R$ 7.000,00 por um determinado tempo em uma caderneta de poupança e recebeu R$ 1.750,00 de juros. No mesmo dia, Baldo aplicou um capital na mesma poupança, pelo mesmo tempo, e obteve rendimento de R$ 1.375,00 de juros. O capital aplicado por Baldo foi de, em reais,", "alternativas": ["5.500", "5.000", "6.500", "6.000", "4.500"], "corretaIndex": 0, "regra": "Como tempo e taxa são iguais, (i×t) = 1.750/7.000 = 0,25; aplicando a Baldo: 1.375 = C × 0,25, logo C = 5.500.", "fonte": "CESGRANRIO - 2018 - Liquigás - Profissional de Vendas Júnior", "fonteUrl": "https://gratis.estrategiaconcursos.com.br", "valido": true}, {"id": 327, "materia": "Matemática Financeira", "assunto": "Juros Simples - custo total do empréstimo", "enunciado": "Uma empresa toma um empréstimo de R$ 350.000,00 por 25 dias, à taxa de juros simples de 4,8% ao mês. Ao final do prazo, além dos juros, a empresa paga uma taxa de utilização de crédito de 0,5% sobre o valor tomado. O custo total (juros + taxa) desse empréstimo é, em reais, de", "alternativas": ["13.500,00", "14.250,00", "15.750,00", "16.800,00", "18.550,00"], "corretaIndex": 2, "regra": "J = 350.000 × 0,048 × (25/30) = 14.000; taxa fixa = 350.000 × 0,005 = 1.750; custo total = 15.750,00.", "fonte": "CESGRANRIO - 2018 - Liquigás - Profissional de Vendas Júnior", "fonteUrl": "https://gratis.estrategiaconcursos.com.br", "valido": true}, {"id": 328, "materia": "Matemática Financeira", "assunto": "Taxa de juros implícita em financiamento", "enunciado": "Um equipamento pode ser adquirido à vista por R$ 100.000,00 com 20% de desconto, ou financiado em duas parcelas de R$ 55.000,00, sendo a primeira paga no ato da compra e a segunda um mês depois. A taxa de juros mensal cobrada nesse financiamento é de, aproximadamente,", "alternativas": ["20%", "30%", "55%", "120%", "150%"], "corretaIndex": 3, "regra": "Preço à vista = 100.000 × 0,80 = 80.000. Saldo financiado = 80.000 − 55.000 = 25.000: i = (55.000 − 25.000)/25.000 = 120% ao mês.", "fonte": "CESGRANRIO - 2016 - Transpetro - Técnico(a) de Administração e Controle Júnior", "fonteUrl": "https://gratis.estrategiaconcursos.com.br", "valido": true}, {"id": 329, "materia": "Matemática Financeira", "assunto": "Juros Simples - divisão de capital entre aplicações", "enunciado": "Um investidor dividiu um capital de R$ 63.000,00 em duas aplicações: uma rendendo juros simples de 0,6% ao mês e outra rendendo 1,5% ao mês, deixando os dois capitais aplicados pelo mesmo período de tempo. Sabendo-se que os rendimentos obtidos nas duas aplicações foram iguais, o valor aplicado na modalidade de menor taxa foi de", "alternativas": ["R$ 18.000,00", "R$ 27.000,00", "R$ 36.000,00", "R$ 45.000,00", "R$ 54.000,00"], "corretaIndex": 3, "regra": "C × 0,006 = (63.000 − C) × 0,015. Resolvendo, C = 45.000,00.", "fonte": "CESGRANRIO - 2012 - Transpetro - Técnico(a) de Contabilidade Júnior", "fonteUrl": "https://gratis.estrategiaconcursos.com.br", "valido": true}, {"id": 330, "materia": "Matemática Financeira", "assunto": "Juros Compostos - capitalização trimestral", "enunciado": "Um investimento rende juros de 12% ao ano, com capitalização trimestral. Para que esse investimento renda R$ 609,00 em 6 meses, o valor que deve ser aplicado hoje é de, aproximadamente,", "alternativas": ["R$ 6.460,00", "R$ 10.000,00", "R$ 3.138,00", "R$ 4.852,00", "R$ 7.271,00"], "corretaIndex": 1, "regra": "Taxa trimestral = 3%. M = C×(1,03)². Como M = C + 609: C×0,0609 = 609, logo C = 10.000,00.", "fonte": "CESGRANRIO - 2015 - Banco do Brasil - Escriturário", "fonteUrl": "https://gratis.estrategiaconcursos.com.br", "valido": true}, {"id": 331, "materia": "Matemática Financeira", "assunto": "Juros Compostos - pagamento parcial de dívida", "enunciado": "João tomou um empréstimo de R$ 900,00, à taxa de juros compostos de 10% ao mês. Dois meses depois, ele pagou R$ 600,00 e, um mês após esse pagamento, liquidou o restante da dívida. O valor desse último pagamento foi de, aproximadamente,", "alternativas": ["R$ 240,00", "R$ 330,00", "R$ 429,00", "R$ 489,00", "R$ 538,00"], "corretaIndex": 4, "regra": "M após 2 meses: 900×(1,1)² = 1.089,00. Após pagar 600, saldo = 489,00; rende 1 mês mais: 489×1,10 ≈ 538,00.", "fonte": "CESGRANRIO - 2012 - Banco do Brasil - Escriturário", "fonteUrl": "https://gratis.estrategiaconcursos.com.br", "valido": true}, {"id": 332, "materia": "Matemática Financeira", "assunto": "Juros Compostos - atraso contratual com multa", "enunciado": "Um contrato de prestação de serviços no valor de R$ 100.000.000,00 foi pago com 6 meses de atraso. Sobre o atraso incidem juros compostos de 1% ao mês, além de uma multa de 2% sobre o valor original do serviço. O valor total pago, em reais, foi de", "alternativas": ["R$ 106.152.000,00", "R$ 106.200.000,00", "R$ 108.000.000,00", "R$ 108.152.000,00", "R$ 108.275.000,00"], "corretaIndex": 3, "regra": "M = 100.000.000×(1,01)⁶ ≈ 106.152.000,00. Multa fixa = 2.000.000,00. Total = 108.152.000,00.", "fonte": "CESGRANRIO - 2018 - Transpetro - Técnico(a) de Administração e Controle Júnior", "fonteUrl": "https://gratis.estrategiaconcursos.com.br", "valido": true}, {"id": 333, "materia": "Matemática Financeira", "assunto": "Juros Compostos - rendimento líquido com descontos", "enunciado": "Um investidor aplicou R$ 1.000.000,00 a juros compostos de 1% ao mês, por um prazo de 2 anos (24 meses). Sobre os juros recebidos incidem 15% de imposto de renda e, adicionalmente, 10% de taxa de performance sobre os juros. Considerando (1,01)²⁴ = 1,27, o rendimento líquido dessa aplicação, em reais, é", "alternativas": ["60.000,00", "67.500,00", "202.500,00", "245.000,00", "270.000,00"], "corretaIndex": 2, "regra": "M = 1.000.000×1,27 = 1.270.000,00, juros brutos = 270.000,00. Descontos (25%): 67.500,00. Líquido = 202.500,00.", "fonte": "CESGRANRIO - 2018 - Liquigás - Profissional de Vendas Júnior", "fonteUrl": "https://gratis.estrategiaconcursos.com.br", "valido": true}, {"id": 334, "materia": "Matemática Financeira", "assunto": "Juros Compostos - taxa equivalente entre períodos", "enunciado": "Um financiamento de R$ 10.000,00 foi contratado a uma taxa de juros compostos de 6% ao semestre, com capitalização mensal. Sabendo-se que a dívida foi quitada integralmente ao final de 3 meses, o valor pago de juros foi de, aproximadamente,", "alternativas": ["R$ 100,00", "R$ 200,00", "R$ 204,00", "R$ 300,00", "R$ 303,00"], "corretaIndex": 4, "regra": "Taxa mensal equivalente: (1+i)^6=1,06, i≈1%. M em 3 meses: 10.000×(1,01)³≈10.303,00. Juros = 303,00.", "fonte": "CESGRANRIO - 2014 - Liquigás - Técnico(a) de Contabilidade", "fonteUrl": "https://gratis.estrategiaconcursos.com.br", "valido": true}, {"id": 335, "materia": "Matemática Financeira", "assunto": "Regime misto (composto + simples) em atraso", "enunciado": "Uma conta no valor de R$ 1.000,00 foi paga com 2 meses e 10 dias de atraso. Sobre esse atraso incide juros de 3% ao mês, sendo juros compostos para os meses completos e juros simples para a fração de dias. O valor dos juros cobrados nesse atraso foi de, aproximadamente,", "alternativas": ["R$ 64,08", "R$ 79,17", "R$ 40,30", "R$ 71,51", "R$ 61,96"], "corretaIndex": 3, "regra": "2 meses compostos: 1.000×(1,03)²=1.060,90. 10 dias (1/3 mês) simples: 1.060,90×(1+0,03/3)≈1.071,51. Juros = 71,51.", "fonte": "CESGRANRIO - 2015 - Banco do Brasil - Escriturário", "fonteUrl": "https://gratis.estrategiaconcursos.com.br", "valido": true}, {"id": 336, "materia": "Matemática Financeira", "assunto": "Taxa nominal x taxa efetiva", "enunciado": "A taxa efetiva anual de juros correspondente à taxa nominal de 12% ao ano, capitalizada mensalmente, monta a", "alternativas": ["12,68%", "12,75%", "12,78%", "12,96%", "13,03%"], "corretaIndex": 3, "regra": "i_ef = (1,01)¹² − 1 ≈ 12,96%.", "fonte": "CESGRANRIO - 2011 - Transpetro - Contador(a) Júnior (Auditoria Interna)", "fonteUrl": "https://www.qconcursos.com/questoes-de-concursos/questoes/0b0dd9d8-ad", "valido": true}, {"id": 337, "materia": "Matemática Financeira", "assunto": "Taxa nominal x taxa efetiva", "enunciado": "Um investimento rende a taxa nominal de 12% ao ano com capitalização trimestral. A taxa efetiva anual do rendimento correspondente é, aproximadamente,", "alternativas": ["12%", "12,49%", "12,55%", "13%", "13,43%"], "corretaIndex": 2, "regra": "Taxa trimestral = 3%. i_ef = (1,03)⁴ − 1 = 12,55%.", "fonte": "CESGRANRIO - 2012 - Banco do Brasil - Escriturário", "fonteUrl": "https://www.qconcursos.com/questoes-de-concursos/questoes/32dc198f-87", "valido": true}, {"id": 338, "materia": "Matemática Financeira", "assunto": "Taxas equivalentes", "enunciado": "Uma empresa tomou um empréstimo de R$ 100.000,00, a uma taxa nominal de 5% ao mês, e pagou, ao final de 3 meses, o montante de R$ 117.500,00. A taxa mensal de juros compostos efetivamente cobrada nessa operação é", "alternativas": ["[(1,175^(1/3) − 1) × 100]%", "[(1,193^(1/3) − 1) × 100]%", "[(1,050^(1/3) − 1) × 100]%", "[(1,158^(1/3) − 1) × 100]%", "[(1,189^(1/3) − 1) × 100]%"], "corretaIndex": 0, "regra": "117.500 = 100.000×(1+i)³, logo (1+i)³=1,175 e i = [(1,175)^(1/3) − 1]×100%.", "fonte": "CESGRANRIO - 2015 - Banco do Brasil - Escriturário", "fonteUrl": "https://gratis.estrategiaconcursos.com.br", "valido": true}, {"id": 339, "materia": "Matemática Financeira", "assunto": "Comparação juros simples x compostos (conceitual)", "enunciado": "Um gráfico compara a evolução do montante a juros simples e a juros compostos, aplicados sobre um mesmo capital e à mesma taxa de juros. Para o credor (quem empresta o dinheiro), é mais vantajoso emprestar a juros", "alternativas": ["compostos, sempre", "compostos, se o período de aplicação for menor que 1 unidade de tempo", "simples, sempre", "simples, se o período de aplicação for maior que 1 unidade de tempo", "simples, se o período de aplicação for menor que 1 unidade de tempo"], "corretaIndex": 4, "regra": "Para t < 1 unidade de tempo, o montante a juros simples é maior que a juros compostos; para t > 1 ocorre o inverso.", "fonte": "CESGRANRIO - 2008 - Caixa Econômica Federal - Técnico Bancário", "fonteUrl": "https://gratis.estrategiaconcursos.com.br", "valido": true}, {"id": 340, "materia": "Matemática Financeira", "assunto": "Taxa real (efeito Fisher)", "enunciado": "Um investimento apresentou variação nominal de 15,5% ao ano, em um período no qual a inflação medida foi de 5% ao ano. A taxa real de rendimento desse investimento no período foi de", "alternativas": ["0,5%", "5,0%", "5,5%", "10,0%", "10,5%"], "corretaIndex": 3, "regra": "Relação de Fisher: (1,155) = (1+i_real)×(1,05), i_real = 10%.", "fonte": "CESGRANRIO - 2010 - Banco do Brasil - Escriturário", "fonteUrl": "https://gratis.estrategiaconcursos.com.br", "valido": true}, {"id": 341, "materia": "Matemática Financeira", "assunto": "Inflação e desvalorização monetária", "enunciado": "Uma pessoa guardou R$ 10.000,00 em um cofre durante um período em que a inflação acumulada foi de 100%. Ao final desse período, a desvalorização sofrida pelo poder de compra desse dinheiro foi de", "alternativas": ["1/4", "1/2", "2/3", "3/4", "1"], "corretaIndex": 1, "regra": "(1+0)=(1+i_real)×(1+1), i_real = 1/2 − 1 = −1/2, perda de metade do poder de compra.", "fonte": "CESGRANRIO - 2015 - Banco do Brasil - Escriturário", "fonteUrl": "https://gratis.estrategiaconcursos.com.br", "valido": true}, {"id": 342, "materia": "Matemática Financeira", "assunto": "Taxa real com capitalização mensal", "enunciado": "Um financiamento tem taxa nominal de 12% ao ano, com capitalização mensal. Considerando uma inflação de 10% ao ano no período e sabendo que (1,01)¹² = 1,127, a taxa real de juros, ao ano, é, aproximadamente,", "alternativas": ["2,44%", "2,00%", "1,98%", "1,82%", "-2,38%"], "corretaIndex": 0, "regra": "Taxa efetiva anual = 12,7%. Fisher: (1,127)=(1+i_real)×(1,10), i_real ≈ 2,44%.", "fonte": "CESGRANRIO - 2018 - Petrobras - Técnico(a) de Contabilidade Júnior", "fonteUrl": "https://gratis.estrategiaconcursos.com.br", "valido": true}, {"id": 343, "materia": "Matemática Financeira", "assunto": "Inflação acumulada em período composto", "enunciado": "As taxas de inflação de janeiro, fevereiro e março de um determinado ano foram, respectivamente, 1%, 0,9% e 0,85%. A inflação acumulada no primeiro trimestre foi de, aproximadamente,", "alternativas": ["2,75%", "1,0275%", "2,78%", "1,0278%", "3,00%"], "corretaIndex": 2, "regra": "(1+i)=(1,01)×(1,009)×(1,0085)≈1,0278, inflação acumulada ≈ 2,78%.", "fonte": "CESGRANRIO - 2018 - Petrobras - Técnico(a) de Contabilidade Júnior", "fonteUrl": "https://gratis.estrategiaconcursos.com.br", "valido": true}, {"id": 344, "materia": "Matemática Financeira", "assunto": "Desconto de títulos em série", "enunciado": "Um microempresário antecipou o recebimento de 5 cheques pré-datados de R$ 10.000,00 cada um, com vencimento em 3 meses, a uma taxa de desconto de 4% ao mês, além de uma taxa fixa de operação de R$ 500,00. A taxa mensal de juros compostos efetivamente paga pelo microempresário nessa antecipação foi de, aproximadamente,", "alternativas": ["5,2%", "4,5%", "4,7%", "5,0%", "4,3%"], "corretaIndex": 2, "regra": "Valor de face = 50.000. Desconto comercial = 50.000×0,04×3 = 6.000. Líquido = 43.500. 50.000=43.500×(1+i)³, i≈4,7%.", "fonte": "CESGRANRIO - 2015 - Banco do Brasil - Escriturário", "fonteUrl": "https://gratis.estrategiaconcursos.com.br", "valido": true}, {"id": 345, "materia": "Matemática Financeira", "assunto": "Desconto bancário simples (por fora)", "enunciado": "Uma instituição financeira efetua o desconto de um título de valor de face de R$ 25.000,00 dois meses antes do vencimento, utilizando taxa de desconto simples bancário (por fora) de 9% ao mês. A instituição exige o pagamento de 2% do valor de face do título como taxa de administração no momento de desconto do título. A taxa bimestral de juros realmente cobrada é de", "alternativas": ["20%", "25%", "11%", "16%", "22,5%"], "corretaIndex": 1, "regra": "D = 25.000×0,09×2 = 4.500. Recebido bruto = 20.500. Menos taxa admin (500): 20.000. i: 25.000=20.000×(1+i), i=25%.", "fonte": "CESGRANRIO - 2015 - Banco do Brasil - Escriturário", "fonteUrl": "https://www.qconcursos.com/questoes-de-concursos/questoes/d73e239d-76", "valido": true}, {"id": 346, "materia": "Matemática Financeira", "assunto": "Sistema de Amortização Constante (SAC)", "enunciado": "Pelo sistema de amortização constante (SAC), a primeira prestação mensal (parcela), sem carência, de um financiamento de R$ 10.000,00 a uma taxa de juros de 10% a.m., pelo prazo de 5 meses, será de, aproximadamente,", "alternativas": ["R$ 3.000,00", "R$ 2.638,00", "R$ 2.000,00", "R$ 1.638,00", "R$ 1.000,00"], "corretaIndex": 0, "regra": "Amortização = 10.000/5 = 2.000. J1 = 10.000×0,10 = 1.000. Prestação = 2.000+1.000 = 3.000,00.", "fonte": "CESGRANRIO - 2018 - Liquigás - Profissional de Vendas Júnior", "fonteUrl": "https://www.qconcursos.com/questoes-de-concursos/questoes/e7877b88-68", "valido": true}, {"id": 347, "materia": "Matemática Financeira", "assunto": "Porcentagem - aumentos sucessivos", "enunciado": "Um produto sofreu três reajustes sucessivos de preço no último trimestre de determinado ano: em outubro, um aumento de 4%; em novembro, um aumento de 5%; e em dezembro, um aumento de 10%. O aumento percentual acumulado no preço desse produto, considerando os três reajustes, está no intervalo", "alternativas": ["19,00% a 19,49%", "19,50% a 19,99%", "20,00% a 20,49%", "20,50% a 20,99%", "21,00% a 21,49%"], "corretaIndex": 2, "regra": "Fator acumulado = 1,04×1,05×1,10 = 1,2012, aumento de 20,12%, no intervalo 20,00% a 20,49%.", "fonte": "CESGRANRIO - 2018 - Banco do Brasil - Escriturário", "fonteUrl": "https://sabermatematica.com.br", "valido": true}, {"id": 348, "materia": "Matemática Financeira", "assunto": "Porcentagem aplicada a orçamento pessoal", "enunciado": "O valor pago por João a título de aluguel de seu apartamento representava 25% do seu salário. Após receber um aumento salarial de 40% e o valor do aluguel sofrer um reajuste de 12%, o percentual do novo salário de João comprometido com o pagamento do aluguel passou a ser de", "alternativas": ["16%", "20%", "24%", "28%", "35%"], "corretaIndex": 1, "regra": "Novo aluguel = 0,25x×1,12; novo salário = 1,40x. Percentual: 0,28/1,40 = 20%.", "fonte": "CESGRANRIO - 2010 - Banco do Brasil - Escriturário", "fonteUrl": "https://sabermatematica.com.br", "valido": true}, {"id": 349, "materia": "Contabilidade", "assunto": "Demonstração do Resultado do Exercício (DRE) - Lucro Bruto", "enunciado": "A Demonstração do Resultado do Exercício (DRE) confronta as receitas e os ganhos com as despesas e perdas de uma empresa. Na estrutura da DRE, a diferença entre a receita líquida de vendas e o custo das mercadorias ou serviços vendidos expressa o valor da(o)", "alternativas": ["receita bruta das vendas", "faturamento bruto", "lucro ou prejuízo operacional", "lucro ou prejuízo líquido do exercício", "lucro bruto"], "corretaIndex": 4, "regra": "Receita Líquida (-) CMV = Lucro Bruto. O lucro operacional líquido só é obtido após deduzir também as despesas operacionais.", "fonte": "CESGRANRIO - 2012 - Liquigás - Profissional Júnior - Auditoria", "fonteUrl": "https://www.qconcursos.com/questoes-de-concursos/questoes/47326af2-58", "valido": true}, {"id": 350, "materia": "Contabilidade", "assunto": "Equação Fundamental do Patrimônio", "enunciado": "A expressão: Ativo = Passivo + Patrimônio Líquido é a equação fundamental da contabilidade. Com base nessa informação, afirma-se que a riqueza ou situação líquida de uma empresa é o(a)", "alternativas": ["Ativo Circulante, menos o Passivo Circulante", "seu Patrimônio", "total de bens e direitos, menos as obrigações", "valor disponível em caixa", "soma do Ativo Circulante com o Não Circulante"], "corretaIndex": 2, "regra": "PL = Ativo − Passivo; como Ativo = bens e direitos e Passivo = obrigações, a riqueza líquida é o total de bens e direitos menos as obrigações.", "fonte": "CESGRANRIO - 2010 - Petrobras - Técnico de Suprimentos de Bens e Serviços Júnior - Administração", "fonteUrl": "https://www.qconcursos.com/questoes-de-concursos/questoes/8bc6de96-db", "valido": true}, {"id": 351, "materia": "Contabilidade", "assunto": "Equação Patrimonial - Situação Líquida Nula", "enunciado": "Sabendo-se que A = Ativo; P = Passivo e PL = Patrimônio Líquido, na equação patrimonial, a situação líquida nula ocorrerá quando:", "alternativas": ["A + P = PL", "A + PL = P", "A = P", "A = PL", "A = P + PL"], "corretaIndex": 2, "regra": "PL = A − P. PL = 0 exatamente quando A = P.", "fonte": "CESGRANRIO - 2010 - BNDES - Técnico Administrativo", "fonteUrl": "https://www.qconcursos.com/questoes-de-concursos/questoes/feb0c350-d0", "valido": true}, {"id": 352, "materia": "Contabilidade", "assunto": "Composição do Patrimônio Líquido", "enunciado": "No balanço patrimonial, a diferença entre o valor dos ativos e o dos passivos representa o Patrimônio Líquido, que é o valor contábil pertencente aos acionistas ou sócios. O Patrimônio Líquido das sociedades por ações é dividido em Capital Social, Ajustes de Avaliação Patrimonial, Ações em Tesouraria e", "alternativas": ["Reservas de Capital, Reservas Estatutárias e Lucros Acumulados", "Reservas de Capital, Reservas de Lucros e Prejuízos Acumulados", "Reservas de Capital, Reservas para Contingências, e Lucros Acumulados", "Reserva Legal, Reservas para Contingências, e Prejuízos Acumulados", "Reserva Legal, Reserva de Lucros a Realizar e Prejuízos Acumulados"], "corretaIndex": 1, "regra": "Lei nº 6.404/76, art. 178, §2º: PL = Capital Social, Reservas de Capital, Ajustes de Avaliação Patrimonial, Reservas de Lucros, Ações em Tesouraria e Prejuízos Acumulados.", "fonte": "CESGRANRIO - 2011 - Petrobras - Técnico de Contabilidade", "fonteUrl": "https://www.qconcursos.com/questoes-de-concursos/questoes/c2a66154-f3", "valido": true}, {"id": 353, "materia": "Contabilidade", "assunto": "Usuários da Informação Contábil", "enunciado": "A contabilidade tem por objetivo fornecer informação útil para tomada de decisão. Nessa perspectiva, associe a tipologia apresentada à esquerda aos usuários da informação contábil, listados à direita. TIPOLOGIA: I – Interno; II – Externo; III – Não usuário. USUÁRIOS: P – Governo; Q – Auditores; R – Gerentes; S – Acionistas; T – Bancos. Assinale a alternativa que apresenta a associação correta.", "alternativas": ["I-P,S / II-Q,R / III-T", "I-R / II-P,T / III-Q,S", "I-R,S / II-P,Q / III-T", "I-R / II-P,S,T / III-Q", "I-T / II-R,S / III-P,Q"], "corretaIndex": 3, "regra": "Usuário interno: Gerentes. Usuários externos: Governo, Acionistas, Bancos. Auditor não é usuário, é quem valida a informação para os demais.", "fonte": "CESGRANRIO - 2011 - Petrobras - Técnico de Suprimentos de Bens e Serviços Júnior", "fonteUrl": "https://www.qconcursos.com/questoes-de-concursos/questoes/4b61a498-d1", "valido": true}, {"id": 354, "materia": "Contabilidade", "assunto": "Demonstração do Fluxo de Caixa (DFC)", "enunciado": "De acordo com as Normas Brasileiras de Contabilidade, emanadas pelo CFC, a Demonstração do Fluxo de Caixa deve ser elaborada pelos métodos direto ou indireto e deve, pelo menos, evidenciar as movimentações em três grandes grupos de fluxo de caixa, que são:", "alternativas": ["das operações, dos investimentos e dos financiamentos", "das receitas, das despesas e do patrimônio líquido", "das variações ativas, das variações passivas e do resultado econômico", "dos financiamentos, das mutações e das operações de crédito", "dos ativos, dos passivos e das variações patrimoniais"], "corretaIndex": 0, "regra": "CPC 03 (R2)/NBC TG 03: fluxos de caixa classificados em atividades operacionais, de investimento e de financiamento.", "fonte": "CESGRANRIO - 2010 - IBGE - Analista de Planejamento - Ciências Contábeis", "fonteUrl": "https://www.qconcursos.com/questoes-de-concursos/questoes/750000a0-d2", "valido": true}, {"id": 355, "materia": "Contabilidade", "assunto": "Ativo Imobilizado - CPC 27 (Base de Depreciação)", "enunciado": "Uma companhia apresentou os seguintes gastos, em reais, incorridos quando da aquisição de um terreno, sem vida útil definida, para ser utilizado como estacionamento da frota de seus caminhões: Custo do terreno, incluindo instalações em péssimo estado de conservação 200.000,00; Custo de demolição das instalações 15.000,00; Remoção do entulho das instalações demolidas 10.000,00; Restauração da área das antigas instalações 35.000,00. Considerando-se somente as informações da companhia e os termos do Pronunciamento Técnico CPC 27, o valor total dessa aquisição sujeito à incidência de depreciação, em reais, é", "alternativas": ["0 (zero)", "10.000,00", "15.000,00", "35.000,00", "60.000,00"], "corretaIndex": 0, "regra": "Terrenos têm vida útil indefinida e não são depreciados (CPC 27, item 58); todo o valor está associado ao próprio terreno, logo a depreciação é zero.", "fonte": "CESGRANRIO - 2015 - Petrobras - Profissional Júnior - Ciências Contábeis", "fonteUrl": "https://www.qconcursos.com/questoes-de-concursos/questoes/25e3bffa-ce", "valido": true}, {"id": 356, "materia": "Contabilidade", "assunto": "Patrimônio - Bens, Direitos e Obrigações", "enunciado": "Na contabilidade, o conceito de patrimônio envolve o conjunto de bens, direitos e obrigações. No que se refere aos direitos, quando apresentados no Balanço Patrimonial, são encontrados no(a)", "alternativas": ["Ativo", "Passivo", "Patrimônio Líquido", "Exigível a Longo Prazo", "Reserva de Lucros"], "corretaIndex": 0, "regra": "Bens e direitos compõem o Ativo; obrigações compõem o Passivo exigível.", "fonte": "CESGRANRIO - 2012 - Transpetro - Técnico de Contabilidade Júnior", "fonteUrl": "https://www.qconcursos.com/questoes-de-concursos/questoes/1a874363-fe", "valido": true}, {"id": 357, "materia": "Contabilidade", "assunto": "Demonstração do Valor Adicionado (DVA)", "enunciado": "A Demonstração do Valor Adicionado (DVA) é formada, basicamente, por duas partes, sendo que, na primeira parte, deve apresentar a riqueza criada pela entidade, incluindo, em seu detalhamento, a receita de vendas de mercadorias, produtos e serviços. As vendas de produtos pelas empresas industriais devem ser demonstradas na DVA pelo valor da(s)", "alternativas": ["receita bruta ou do faturamento bruto", "vendas menos o ICMS e o IPI a recuperar", "vendas menos o ICMS a recuperar", "vendas menos o IPI a recuperar", "vendas líquidas"], "corretaIndex": 4, "regra": "CPC 09: a receita de vendas deve ser apresentada líquida dos tributos incidentes diretamente sobre ela e de devoluções/abatimentos, ou seja, pelo valor das vendas líquidas.", "fonte": "CESGRANRIO - 2011 - Transpetro - Contador Júnior", "fonteUrl": "https://www.qconcursos.com/questoes-de-concursos/questoes/b6f3a602-ad", "valido": true}, {"id": 358, "materia": "Contabilidade", "assunto": "Regime de Competência - Conceito de DRE", "enunciado": "A demonstração contábil que deve apresentar em sua estrutura as receitas e os ganhos do período, independentemente de seu recebimento, e os custos, as despesas, os encargos e as perdas pagos ou incorridos, correspondentes a esses ganhos e receitas, é o(a)", "alternativas": ["Balanço Patrimonial", "Demonstração do Fluxo de Caixa Indireto", "Demonstração da Mutação do Patrimônio Líquido", "Demonstração do Resultado do Exercício", "Demonstração do Fluxo de Caixa Direto"], "corretaIndex": 3, "regra": "A DRE é elaborada sob o regime de competência, confrontando receitas e despesas independentemente do efetivo recebimento/pagamento em caixa.", "fonte": "CESGRANRIO - 2012 - Transpetro - Técnico de Contabilidade Júnior", "fonteUrl": "https://www.qconcursos.com/questoes-de-concursos/questoes/1fbc158c-fe", "valido": true}, {"id": 359, "materia": "Contabilidade", "assunto": "Lançamento Contábil - Desconto Financeiro Obtido", "enunciado": "Numa operação com mercadorias, a Comercial L, que controla seu estoque de mercadorias pelo inventário permanente, aceitou uma duplicata no valor de R$ 100.000,00 com vencimento para 8 de dezembro de 2012. Em 8 de novembro de 2012, a duplicata foi quitada, em dinheiro, com um desconto de R$ 10.000,00, sendo a operação contabilizada, adequadamente, na Comercial L como segue:", "alternativas": ["Débito Caixa R$90.000 / Crédito Duplicatas a Pagar R$90.000", "Débito Duplicatas a Pagar R$100.000 / Crédito Descontos Comerciais Obtidos R$10.000 / Crédito Caixa R$90.000", "Débito Duplicatas a Pagar R$100.000 / Crédito Descontos Financeiros Obtidos R$10.000 / Crédito Caixa R$90.000", "Débito Descontos Comerciais Concedidos R$10.000 / Débito Caixa R$90.000 / Crédito Duplicatas a Pagar R$100.000", "Débito Descontos Financeiros Concedidos R$10.000 / Débito Caixa R$90.000 / Crédito Duplicatas a Pagar R$100.000"], "corretaIndex": 2, "regra": "Como a duplicata foi paga antes do vencimento, o desconto obtido é financeiro (receita financeira). Baixa-se a obrigação pelo valor de face, reconhecendo o desconto como receita e a saída de caixa pelo valor líquido.", "fonte": "CESGRANRIO - 2013 - BR Distribuidora - Técnico de Contabilidade Júnior", "fonteUrl": "https://www.qconcursos.com/questoes-de-concursos/questoes/a2ab75f5-d2", "valido": true}, {"id": 360, "materia": "Contabilidade", "assunto": "Dividendo Obrigatório e Reservas (Lei 6.404/76)", "enunciado": "A legislação societária estabelece que os acionistas têm direito a receber um dividendo obrigatório anual, além das regras para estabelecer esse dividendo quando ele for omisso no estatuto da companhia. Nesse caso, os acionistas têm direito à metade do lucro líquido do exercício diminuído ou acrescido da importância destinada à formação da reserva legal e da importância destinada à formação da reserva", "alternativas": ["de retenção de lucros e reversão da mesma reserva formada em exercícios anteriores", "de lucros a realizar e reversão da mesma reserva formada em exercícios anteriores", "para contingências e reversão da mesma reserva formada em exercícios anteriores", "estatutária e reversão da mesma reserva formada em exercícios anteriores", "especial e reversão da mesma reserva formada em exercícios anteriores"], "corretaIndex": 2, "regra": "Lei nº 6.404/76, art. 202, §1º: se omisso, o acionista tem direito a 50% do lucro líquido ajustado pela reserva legal e pela reserva para contingências (constituição e reversão).", "fonte": "CESGRANRIO - 2011 - Transpetro - Técnico de Contabilidade", "fonteUrl": "https://www.qconcursos.com/questoes-de-concursos/questoes/89ed82f0-ae", "valido": true}, {"id": 361, "materia": "Contabilidade", "assunto": "Ativo Imobilizado - Custo de Aquisição", "enunciado": "A Comercial RRR S/A adquiriu uma nova máquina para seu imobilizado, com as seguintes condições: entrada de R$ 50.000,00; nove parcelas semestrais cujo valor presente somou R$ 72.000,00; entrega de equipamento usado em troca (dação), avaliado em R$ 20.000,00; frete de R$ 15.000,00; e seguro de R$ 3.000,00 durante o transporte. O valor total pelo qual a máquina deve ser registrada no Ativo Imobilizado, em reais, é", "alternativas": ["100.000,00", "137.000,00", "142.000,00", "157.000,00", "160.000,00"], "corretaIndex": 3, "regra": "Custo do imobilizado (CPC 27) = preço de aquisição + custos diretamente atribuíveis: 50.000+72.000+20.000+15.000+3.000 = 157.000,00.", "fonte": "CESGRANRIO - 2011 - Transpetro - Técnico de Contabilidade", "fonteUrl": "https://www.qconcursos.com/questoes-de-concursos/questoes/8fdb3c6c-ae", "valido": true}, {"id": 362, "materia": "Logística e Cadeia de Suprimentos", "assunto": "Modais de Transporte", "enunciado": "A escolha do melhor modal de transporte está condicionada às características físicas da carga a ser transportada e aos fatores de desempenho oferecidos pelos modais disponíveis. Com relação aos modais de transporte e às suas características, o transporte", "alternativas": ["Ferroviário é recomendado para carga de qualquer tamanho, em situações onde o fator rapidez da entrega é preponderante", "Aéreo é recomendado para cargas cujo prazo de entrega é o fator preponderante", "Rodoviário é recomendado para cargas de qualquer tamanho, e o risco é o menor dentre todos os modais", "Marítimo oferece o maior custo unitário, para qualquer tipo de carga", "Dutoviário é usado predominantemente para deslocamento de cargas líquidas e sólidas a granel"], "corretaIndex": 1, "regra": "O modal aéreo é o mais rápido, escolhido quando o prazo é fator crítico, apesar do custo elevado.", "fonte": "CESGRANRIO - 2010 - Petrobras - Técnico de Suprimento de Bens e Serviços Júnior - Biocombustível", "fonteUrl": "https://www.qconcursos.com/questoes-de-concursos/questoes/50f721f8-d8", "valido": true}, {"id": 363, "materia": "Logística e Cadeia de Suprimentos", "assunto": "Modais de Transporte", "enunciado": "Os modais de transporte podem ser classificados por diversas características operacionais, entre as quais a capacidade, velocidade, disponibilidade, confiabilidade e frequência. Em qual destas características o modal aquaviário apresenta uma melhor performance que os modais ferroviário, rodoviário, dutoviário e aéreo?", "alternativas": ["capacidade", "velocidade", "disponibilidade", "confiabilidade", "frequência"], "corretaIndex": 0, "regra": "O modal aquaviário tem a maior capacidade de carga entre todos, sendo o mais eficiente para grandes volumes, apesar de ser o mais lento.", "fonte": "CESGRANRIO - 2012 - TERMOBAHIA - Técnico de Suprimento de Bens e Serviços Júnior", "fonteUrl": "https://www.qconcursos.com/questoes-de-concursos/questoes/b5c3b9fd-0f", "valido": true}, {"id": 364, "materia": "Logística e Cadeia de Suprimentos", "assunto": "Armazenagem", "enunciado": "As técnicas de armazenamento devem observar os requisitos e os equipamentos de guarda dos materiais, que podem exigir certa temperatura ambiente e podem apresentar restrição de empilhamento máximo. É um equipamento de armazenamento de materiais a(o)", "alternativas": ["estanteira", "monovia", "empilhadeira", "paleteira elétrica", "equipamento de elevação e transferência"], "corretaIndex": 0, "regra": "Estanteiras são equipamentos de ARMAZENAMENTO (guarda estática). Monovia, empilhadeira, paleteira e equipamentos de elevação são de MOVIMENTAÇÃO.", "fonte": "CESGRANRIO - 2014 - Petrobras - Técnico de Suprimento de Bens e Serviços Júnior - Administração", "fonteUrl": "https://www.qconcursos.com/questoes-de-concursos/questoes/2b997339-10", "valido": true}, {"id": 365, "materia": "Logística e Cadeia de Suprimentos", "assunto": "Nível de Serviço Logístico", "enunciado": "O nível de serviço logístico é definido como o(a):", "alternativas": ["custo dos serviços logísticos", "tempo necessário para entregar um pedido de cliente", "qualidade com que o fluxo de bens e serviços é gerenciado", "disponibilidade de estoque de produtos acabados", "total médio, no longo prazo, cai com os aumentos de produção"], "corretaIndex": 2, "regra": "Segundo Ballou, nível de serviço logístico é a qualidade com que o fluxo de bens e serviços é gerenciado, resultado líquido de todos os esforços logísticos da empresa.", "fonte": "CESGRANRIO - 2005 - Petrobras - Engenheiro de Produção Júnior", "fonteUrl": "https://www.qconcursos.com/questoes-de-concursos/questoes/6f9cc628-85", "valido": true}, {"id": 366, "materia": "Logística e Cadeia de Suprimentos", "assunto": "Atividades Logísticas / Armazenagem", "enunciado": "Picking, embalagem e paletização são exemplos de", "alternativas": ["atividades logísticas", "atividades de cadeia de suprimentos", "áreas funcionais de logística", "áreas funcionais de cadeia de suprimentos", "pontos de controle logístico"], "corretaIndex": 0, "regra": "Picking, embalagem e paletização são atividades operacionais logísticas dentro da área funcional de armazenagem/movimentação de materiais.", "fonte": "CESGRANRIO - 2018 - Petrobras - Técnico de Suprimento de Bens e Serviços Júnior - Administração", "fonteUrl": "https://www.qconcursos.com/questoes-de-concursos/questoes/72da5393-6d", "valido": true}, {"id": 367, "materia": "Logística e Cadeia de Suprimentos", "assunto": "Roteirização", "enunciado": "Problemas de roteirização de veículos dizem respeito à vinculação de um grupo de clientes que devem ser visitados a um conjunto de veículos e respectivos motoristas, envolvendo também a programação e o sequenciamento das visitas. No método que se baseia no conceito de ganho, parte-se da pior situação possível: o veículo sai do CD com a mercadoria destinada a um único cliente e, após a entrega, o veículo retorna ao CD. Em seguida insere-se um outro cliente nessa rota. Este método é conhecido sob a designação de", "alternativas": ["II - OPT", "III - OPT", "Varredura", "Inserção do ponto mais distante", "Clark & Wright"], "corretaIndex": 4, "regra": "O método de Clarke & Wright (algoritmo de ganhos) parte de rota exclusiva por cliente e calcula o 'ganho' ao combinar duas rotas em uma só.", "fonte": "CESGRANRIO - 2018 - Transpetro - Engenheiro Júnior - Produção", "fonteUrl": "https://www.qconcursos.com/questoes-de-concursos/questoes/6cf9402a-49", "valido": true}, {"id": 368, "materia": "Logística e Cadeia de Suprimentos", "assunto": "Transporte Multimodal", "enunciado": "Uma unidade de carga é transportada em todo o percurso, utilizando duas ou mais modalidades de transporte abrangidas por um único contrato, desde a origem até o destino, e o transporte é executado sob a responsabilidade de um único Operador de Transporte Multimodal – OTM.", "alternativas": ["de percurso único", "intermodal", "multimodal", "segmentado", "unimodal"], "corretaIndex": 2, "regra": "Transporte multimodal tem um único contrato cobrindo toda a viagem, com um único responsável (OTM) do início ao fim.", "fonte": "CESGRANRIO - 2012 - Transpetro - Técnico de Administração e Controle Júnior", "fonteUrl": "https://www.qconcursos.com/questoes-de-concursos/questoes/9b318111-f0", "valido": true}, {"id": 369, "materia": "Logística e Cadeia de Suprimentos", "assunto": "Logística Reversa", "enunciado": "A logística reversa trata do fluxo de materiais que retornam através do canal de distribuição pós-venda (CDR-PV) ou do canal de distribuição reverso pós-consumo (CDR-PC). O canal de distribuição reverso de pós-consumo", "alternativas": ["Considera apenas produtos que se destinam ao mercado secundário", "Contempla canais de reúso, nos quais o produto ou seus componentes serão reutilizados na função original, sem a necessidade de remanufatura", "É o fluxo reverso originado após a comercialização do item", "É o fluxo reverso de materiais do cliente final até a empresa focal", "É o processo de armazenar todos os produtos destinados a, pelo menos, um elo a montante"], "corretaIndex": 1, "regra": "O CDR-PC trata do retorno de produtos em fim de vida útil, envolvendo canais de reuso, desmanche e reciclagem - diferente do CDR-PV (devoluções comerciais).", "fonte": "CESGRANRIO - 2012 - Transpetro - Administrador Júnior", "fonteUrl": "https://www.qconcursos.com/questoes-de-concursos/questoes/3ce7e8e7-02", "valido": true}, {"id": 370, "materia": "Logística e Cadeia de Suprimentos", "assunto": "Cadeia de Suprimentos - Decisões", "enunciado": "As decisões operacionais, em uma cadeia de suprimento,", "alternativas": ["Requerem mão de obra altamente especializada para que sejam atingidos os objetivos da logística", "São de aplicação em curto prazo e incluem a produção sequenciada e o atendimento a pedidos específicos", "Refletirão resultados em longo prazo e englobam planejamento de produção e subcontratos, entre outros", "Buscam se adequar à realidade financeira da empresa, ajustando salários, contratando ou demitindo", "Provocam o interesse dos trabalhadores em se aprimorar, visando ao crescimento profissional"], "corretaIndex": 1, "regra": "Decisões operacionais têm horizonte de curto prazo (execução imediata: sequenciamento de produção, atendimento pontual a pedidos).", "fonte": "CESGRANRIO - 2010 - Petrobras - Técnico de Logística de Transporte Júnior - Controle", "fonteUrl": "https://www.qconcursos.com/questoes-de-concursos/questoes/b0cea5e6-da", "valido": true}, {"id": 371, "materia": "Logística e Cadeia de Suprimentos", "assunto": "Gestão da Cadeia de Suprimentos (SCM)", "enunciado": "Define-se Gestão da Cadeia de Suprimentos como", "alternativas": ["Parceria entre fabricante, distribuidor e cliente para otimizar prazos de entrega e cumprir metas pré-estabelecidas", "Relação entre produtor e distribuidor para encontrar formas de ambos alcançarem a máxima rentabilidade por meio de colaboração mútua focada no cliente preferencial", "Rede de empresas interligadas e interdependentes trabalhando juntas, em regime de cooperação mútua, para controlar, gerenciar e aperfeiçoar o fluxo de matérias-primas e informações dos fornecedores para os clientes finais", "Sistema informatizado integrado, com estoque distribuído por todas as filiais a partir de um único centro, para alcançar máxima rentabilidade em curto prazo", "Controle de procedimentos com capacitação de especialistas na função de demanda de produtos acabados, para minimizar os custos de armazenagem nos níveis de serviço desejados"], "corretaIndex": 2, "regra": "SCM é a gestão de uma rede de empresas interligadas e interdependentes que cooperam no controle, gerenciamento e aperfeiçoamento do fluxo de materiais e informações dos fornecedores aos clientes finais.", "fonte": "CESGRANRIO - 2011 - Petrobras - Engenheiro de Produção Júnior", "fonteUrl": "https://www.qconcursos.com/questoes-de-concursos/questoes/496a34cf-47", "valido": true}, {"id": 372, "materia": "Logística e Cadeia de Suprimentos", "assunto": "Transporte Intermodal x Multimodal", "enunciado": "É possível realizar o transporte de uma determinada carga por mais de um modal, utilizando-se transporte intermodal ou multimodal. A diferença entre ambos consiste no fato de que o transporte:", "alternativas": ["intermodal se utiliza de menos meios de transporte quando comparado ao multimodal", "intermodal é regido por um único contrato em todo o seu percurso", "intermodal é executado pela figura jurídica do Operador de Transporte Intermodal", "multimodal se utiliza de menos meios de transporte quando comparado ao intermodal", "multimodal é regido por um único contrato em todo o seu percurso"], "corretaIndex": 4, "regra": "No multimodal há um único contrato e um único responsável (OTM) do início ao fim; no intermodal, cada trecho tem seu próprio contrato.", "fonte": "CESGRANRIO - 2018 - Petrobras - Técnico de Logística de Transporte Júnior - Controle", "fonteUrl": "https://arquivos.qconcursos.com/prova/arquivo_prova/65735/cesgranrio-2018-petrobras-tecnico-de-logistica-de-transporte-junior-controle-prova.pdf", "valido": true}, {"id": 373, "materia": "Logística e Cadeia de Suprimentos", "assunto": "Gestão de Estoques - JIT x MRP", "enunciado": "O JIT (just-in-time) e o planejamento das necessidades de materiais (MRP) são diferentes modelos para gestão de estoques. Com relação à lógica de funcionamento de cada um:", "alternativas": ["o JIT antecipa a demanda, enquanto o MRP reage à demanda", "o JIT reage à demanda, enquanto o MRP antecipa a demanda", "o MRP reage à demanda mais rapidamente do que o JIT", "tanto o JIT quanto o MRP antecipam a demanda", "tanto o JIT quanto o MRP reagem à demanda"], "corretaIndex": 1, "regra": "O JIT é um sistema PUXADO (reage à demanda real); o MRP é EMPURRADO (antecipa a partir de previsão de demanda).", "fonte": "CESGRANRIO - 2018 - Petrobras - Técnico de Logística de Transporte Júnior - Controle", "fonteUrl": "https://arquivos.qconcursos.com/prova/arquivo_prova/65735/cesgranrio-2018-petrobras-tecnico-de-logistica-de-transporte-junior-controle-prova.pdf", "valido": true}, {"id": 374, "materia": "Logística e Cadeia de Suprimentos", "assunto": "Armazenagem - Picking", "enunciado": "A atividade realizada dentro da armazenagem, cuja função é separar os pedidos, e que representa cerca de 1/3 do tempo total das demais atividades realizadas dentro de um armazém denomina-se atividade de:", "alternativas": ["cross-docking", "transit point", "merge-in-transit", "picking", "point of sale"], "corretaIndex": 3, "regra": "Picking (separação de pedidos) é a atividade mais demorada dentro de um armazém, consumindo cerca de 30-50% do tempo total das operações.", "fonte": "CESGRANRIO - 2018 - Petrobras - Técnico de Logística de Transporte Júnior - Controle", "fonteUrl": "https://arquivos.qconcursos.com/prova/arquivo_prova/65735/cesgranrio-2018-petrobras-tecnico-de-logistica-de-transporte-junior-controle-prova.pdf", "valido": true}, {"id": 375, "materia": "Logística e Cadeia de Suprimentos", "assunto": "Gestão de Estoques - Lote Econômico de Compra", "enunciado": "Uma política de estoque que adote como parâmetro de ressuprimento o LEC (lote econômico de compra) pressupõe que a taxa de demanda tenha um comportamento:", "alternativas": ["estável ao longo do tempo", "crescente ao longo do tempo", "decrescente ao longo do tempo", "sazonal crescente no final do ano", "sazonal decrescente no final do ano"], "corretaIndex": 0, "regra": "O modelo clássico do LEC/EOQ parte da premissa de demanda constante e conhecida ao longo do tempo.", "fonte": "CESGRANRIO - 2018 - Petrobras - Técnico de Logística de Transporte Júnior - Controle", "fonteUrl": "https://arquivos.qconcursos.com/prova/arquivo_prova/65735/cesgranrio-2018-petrobras-tecnico-de-logistica-de-transporte-junior-controle-prova.pdf", "valido": true}, {"id": 376, "materia": "Logística e Cadeia de Suprimentos", "assunto": "Gestão de Estoques - Métodos de Baixa (FIFO/LIFO)", "enunciado": "Uma política de estoque, em que um produto que acabou de chegar será o primeiro a ter sua baixa dada no estoque, é denominada:", "alternativas": ["CIF", "FOB", "FIFO", "FEFO", "LIFO"], "corretaIndex": 4, "regra": "LIFO ('último a entrar, primeiro a sair') é o oposto do FIFO. CIF e FOB são incoterms; FEFO é baseado em data de validade.", "fonte": "CESGRANRIO - 2018 - Petrobras - Técnico de Logística de Transporte Júnior - Controle", "fonteUrl": "https://arquivos.qconcursos.com/prova/arquivo_prova/65735/cesgranrio-2018-petrobras-tecnico-de-logistica-de-transporte-junior-controle-prova.pdf", "valido": true}, {"id": 377, "materia": "Logística e Cadeia de Suprimentos", "assunto": "Compras - Estratégias de Sourcing", "enunciado": "Quando uma empresa escolhe um fornecedor que participa do desenvolvimento de um novo produto e esse fornecedor terá exclusividade na fabricação desse componente, diz-se que a empresa adotou a seguinte estratégia de Sourcing:", "alternativas": ["Single sourcing", "Global sourcing", "Follow sourcing", "Local sourcing", "Mono sourcing"], "corretaIndex": 0, "regra": "Single sourcing concentra deliberadamente o fornecimento de um item em um único fornecedor, geralmente por co-desenvolvimento, criando exclusividade contratual.", "fonte": "CESGRANRIO - 2018 - Petrobras - Técnico de Logística de Transporte Júnior - Controle", "fonteUrl": "https://arquivos.qconcursos.com/prova/arquivo_prova/65735/cesgranrio-2018-petrobras-tecnico-de-logistica-de-transporte-junior-controle-prova.pdf", "valido": true}, {"id": 378, "materia": "Logística e Cadeia de Suprimentos", "assunto": "Modais de Transporte - Comparativo", "enunciado": "Comparando-se o transporte marítimo com o aéreo e o terrestre, verifica-se que o transporte marítimo é o:", "alternativas": ["mais lento, com custo médio comparado aos outros modais, de menor variabilidade nos tempos de entrega e de baixa incidência de perdas e danos de cargas", "mais lento, mais barato, de maior variabilidade nos tempos de entrega e de menores perdas e danos no transporte de cargas", "mais rápido, mais barato, de baixa variabilidade nos tempos de entrega e de baixa incidência de perdas e danos de cargas", "mais rápido, mais caro, de menor variabilidade nos tempos de entrega e de maior número de perdas e danos de cargas", "mais rápido, mais caro, de menor variabilidade nos tempos de entrega e de menores perdas e danos de cargas"], "corretaIndex": 1, "regra": "O transporte marítimo é o mais LENTO, tem custo relativamente BAIXO por tonelada, MAIOR variabilidade de prazos e, por transportar granéis, MENOR incidência de perdas e danos que rodoviário/aéreo.", "fonte": "CESGRANRIO - 2018 - Petrobras - Técnico de Logística de Transporte Júnior - Controle", "fonteUrl": "https://arquivos.qconcursos.com/prova/arquivo_prova/65735/cesgranrio-2018-petrobras-tecnico-de-logistica-de-transporte-junior-controle-prova.pdf", "valido": true}, {"id": 379, "materia": "Logística e Cadeia de Suprimentos", "assunto": "Cadeia de Suprimentos - Conceito", "enunciado": "O fluxo de materiais e informações que vai desde compras/produção indo até o cliente, mediante distribuição/serviço de entrega, é denominado cadeia", "alternativas": ["logística", "de gestão", "de processo", "de serviços", "de suprimentos"], "corretaIndex": 4, "regra": "Cadeia de suprimentos é o conjunto de processos e fluxos que ligam fornecedores, produção e clientes, do ponto de origem ao ponto de consumo.", "fonte": "CESGRANRIO - 2014 - Petrobras - Técnico de Logística de Transporte Júnior - Controle", "fonteUrl": "https://www.qconcursos.com/questoes-de-concursos/questoes/7416d996-83", "valido": true}, {"id": 380, "materia": "Logística e Cadeia de Suprimentos", "assunto": "Planejamento Logístico", "enunciado": "O planejamento logístico envolve decisões de nível estratégico, tático e operacional, cujos resultados interagem e culminam na prestação de serviço ao cliente. São decisões inerentes ao planejamento logístico, EXCETO a que engloba", "alternativas": ["Mix de produtos, preço, pontos de venda e definição de requisitos do cliente", "Localização geográfica de pontos de estocagem, número e tamanho dos centros de distribuição", "Nível de serviço, taxa de disponibilidade de produtos e níveis de estoque", "Métodos de controle de estoque e previsão de demanda de itens", "Seleção de modal, tamanho de carregamento, roteirização e programação"], "corretaIndex": 0, "regra": "Mix de produtos, preço e pontos de venda são decisões de MARKETING, não de planejamento logístico (localização, estoques, transporte).", "fonte": "CESGRANRIO - 2011 - Petrobras - Técnico de Comercialização Logística Júnior", "fonteUrl": "https://www.qconcursos.com/questoes-de-concursos/questoes/f0c138b7-30", "valido": true}, {"id": 381, "materia": "Legislação", "assunto": "Lei 13.303/2016 - Estrutura da Lei (Procedimentos Auxiliares)", "enunciado": "A Seção 5, Capítulo I da Lei 13.303/2016 legisla sobre o seguinte tópico:", "alternativas": ["Do Procedimento de Licitação", "Das Normas Específicas para Alienação de Bens", "Das Normas Específicas para Aquisição de Bens", "Das Normas Específicas para Obras e Serviços", "Dos Procedimentos Auxiliares das Licitações"], "corretaIndex": 4, "regra": "Lei nº 13.303/2016, Capítulo I, Seção V (arts. 40 a 47) trata 'Dos Procedimentos Auxiliares das Licitações', que incluem pré-qualificação permanente, cadastramento, sistema de registro de preços e catálogo eletrônico de padronização.", "fonte": "CESGRANRIO - 2018 - Petrobras - Técnico de Administração e Controle Júnior", "fonteUrl": "https://www.qconcursos.com/questoes-de-concursos/questoes/62267287-40", "valido": true}, {"id": 382, "materia": "Legislação", "assunto": "Lei 13.303/2016 - Orçamento de Referência em Obras de Engenharia", "enunciado": "A Lei nº 13.303/2016 determina que o orçamento de referência do custo global de obras e serviços de engenharia, no caso de obras e serviços rodoviários, deverá ser obtido a partir de custos unitários de insumos ou serviços menores ou iguais à mediana de seus correspondentes, observando-se as peculiaridades geográficas no:", "alternativas": ["Sistema Nacional de Pesquisa de Custos e Índices da Construção Civil", "Sistema Internacional de Controle de Custos em Obras", "Sistema Americano de Custos em Obras", "Sistema de Controle de Custos Oficial", "Sistema de Custos Referenciais de Obras"], "corretaIndex": 4, "regra": "Lei nº 13.303/2016, art. 31, §2º, I: no caso de obras e serviços rodoviários, o orçamento de referência deve usar o Sistema de Custos Referenciais de Obras (SICRO), mantido pelo DNIT.", "fonte": "CESGRANRIO - 2018 - Petrobras", "fonteUrl": "https://www.qconcursos.com/questoes-de-concursos/questoes/1716eb69-90", "valido": true}, {"id": 383, "materia": "Legislação", "assunto": "Lei 13.303/2016 - Definição do Objeto da Licitação", "enunciado": "De acordo com a Lei nº 13.303/2016, o objeto da licitação e do contrato dela decorrente será definido de forma...", "alternativas": ["técnica", "sucinta", "expressa", "detalhada", "complexa"], "corretaIndex": 1, "regra": "Lei nº 13.303/2016, art. 33: 'O objeto da licitação e do contrato dela decorrente será definido de forma sucinta e clara no instrumento convocatório.'", "fonte": "CESGRANRIO - 2018 - Petrobras - Técnico de Suprimento de Bens e Serviços Júnior - Mecânica", "fonteUrl": "https://www.qconcursos.com/questoes-de-concursos/questoes/e71e46cb-28", "valido": true}, {"id": 384, "materia": "Legislação", "assunto": "Lei 13.303/2016 - Dispensa/Inexigibilidade por Notória Especialização", "enunciado": "A contratação direta será feita, nos termos da Lei nº 13.303/2016, quando houver inviabilidade de competição, em especial na hipótese de contratação de profissionais ou empresas de notória especialização no seguinte serviço técnico especializado:", "alternativas": ["publicidade institucional", "divulgação de serviços", "manutenção predial", "restauração de bens de valor histórico", "execução de obras vultosas"], "corretaIndex": 3, "regra": "Lei nº 13.303/2016, art. 30, II, alínea 'h' (c/c art. 30, §2º): a restauração de obras de arte e bens de valor histórico é serviço técnico especializado que admite inexigibilidade por notória especialização, vedada tal inexigibilidade para serviços de publicidade e divulgação (art. 30, §3º).", "fonte": "CESGRANRIO - 2018 - Transpetro - Administrador Júnior", "fonteUrl": "https://www.qconcursos.com/questoes-de-concursos/questoes/cd37c65c-43", "valido": true}, {"id": 385, "materia": "Legislação", "assunto": "Lei 13.303/2016 - Código de Conduta e Integridade", "enunciado": "Segundo a Lei nº 13.303/2016, a periodicidade mínima do treinamento sobre o Código de Conduta e Integridade destinado a empregados e administradores deve ser:", "alternativas": ["mensal", "trimestral", "semestral", "anual", "quadrienal"], "corretaIndex": 3, "regra": "Lei nº 13.303/2016, art. 9º, §1º, VI: o Código de Conduta e Integridade deve dispor sobre a existência de treinamento periódico sobre integridade, conduta e ética, prática regulamentar consolidada como de periodicidade mínima anual nos estatutos das estatais.", "fonte": "CESGRANRIO - 2026 - Caixa - Arquiteto", "fonteUrl": "https://www.qconcursos.com/questoes-de-concursos", "valido": true}, {"id": 386, "materia": "Legislação", "assunto": "Governança Corporativa em Estatais", "enunciado": "Segundo critérios de boa governança aplicáveis às estatais, os empregados devem exercer suas funções com diligência e independência, de modo a gerar valor que seja:", "alternativas": ["sustentável no longo prazo", "consistente com o lucro variável", "intrínseco à perpetuação das relações societárias", "voltado à atração de aquisição", "socialmente priorizado em detrimento do aspecto econômico"], "corretaIndex": 0, "regra": "Lei nº 13.303/2016, art. 6º c/c princípios de governança corporativa: a gestão deve buscar a geração de valor de forma sustentável no longo prazo, equilibrando função social e eficiência econômica.", "fonte": "CESGRANRIO - 2025 - BANESE - Técnico Bancário I", "fonteUrl": "https://www.qconcursos.com/questoes-de-concursos", "valido": true}, {"id": 387, "materia": "Legislação", "assunto": "Código de Conduta - Uso de Informação Privilegiada", "enunciado": "De acordo com o Código de Conduta de instituição financeira estatal, a compra de ações da própria instituição não pode ser baseada em informação:", "alternativas": ["emprestada", "privilegiada", "importante", "qualificada", "anônima"], "corretaIndex": 1, "regra": "Vedação ao uso de informação privilegiada (insider trading) prevista nos Códigos de Conduta das estatais, em consonância com a Lei nº 6.385/76, art. 27-D, e com os princípios de integridade da Lei nº 13.303/2016, art. 9º.", "fonte": "CESGRANRIO - 2025 - BANESE - Técnico Bancário I", "fonteUrl": "https://www.qconcursos.com/questoes-de-concursos", "valido": true}, {"id": 388, "materia": "Legislação", "assunto": "LGPD - Dado Pessoal Sensível", "enunciado": "Um exemplo de dado pessoal sensível, nos termos da Lei Geral de Proteção de Dados (LGPD), é:", "alternativas": ["renda bruta", "filiação sindical", "local de nascimento", "hábitos de consumo", "número do CPF"], "corretaIndex": 1, "regra": "Lei nº 13.709/2018 (LGPD), art. 5º, II: dado pessoal sensível é aquele sobre origem racial ou étnica, convicção religiosa, opinião política, filiação a sindicato, dado referente à saúde ou à vida sexual, dado genético ou biométrico.", "fonte": "CESGRANRIO - 2025 - BANESE - Técnico Bancário I", "fonteUrl": "https://www.qconcursos.com/questoes-de-concursos", "valido": true}, {"id": 389, "materia": "Legislação", "assunto": "Princípios da Administração Pública - Moralidade", "enunciado": "O princípio constitucional refletido na ideia de que os agentes administrativos devem distinguir o bem do mal, o honesto do desonesto, no exercício de suas funções, é o da:", "alternativas": ["legalidade", "impessoalidade", "moralidade", "publicidade", "eficiência"], "corretaIndex": 2, "regra": "Constituição Federal, art. 37, caput: princípio da moralidade administrativa — exige que a conduta do administrador público seja pautada não apenas pela lei, mas por padrões éticos de probidade, decoro e boa-fé.", "fonte": "CESGRANRIO - 2025 - BANESE - Técnico Bancário I", "fonteUrl": "https://www.qconcursos.com/questoes-de-concursos", "valido": true}, {"id": 390, "materia": "Legislação", "assunto": "Política de Responsabilidade Socioambiental", "enunciado": "A Política de Responsabilidade Social, Ambiental e Climática de uma instituição financeira contribui para que a empresa:", "alternativas": ["demonstre a ausência de riscos climáticos", "desconsidere acordos internacionais de sustentabilidade", "incorpore os riscos socioambientais à gestão estratégica", "atenda a todos os clientes sem qualquer limitação de perfil", "desconsidere a autoridade da ONU em matéria ambiental"], "corretaIndex": 2, "regra": "Resolução CMN/BACEN nº 4.945/2021 (PRSAC) exige das instituições financeiras a incorporação da gestão de riscos e oportunidades sociais, ambientais e climáticos ao planejamento estratégico e à governança corporativa.", "fonte": "CESGRANRIO - 2025 - BANESE - Técnico Bancário I", "fonteUrl": "https://www.qconcursos.com/questoes-de-concursos", "valido": true}, {"id": 391, "materia": "Legislação", "assunto": "Estatuto da Igualdade Racial - Ações Afirmativas", "enunciado": "Nos termos do Estatuto da Igualdade Racial (Lei nº 12.288/2010), as ações afirmativas são:", "alternativas": ["programas que intensificam desigualdades econômicas e exclusão social", "programas e medidas especiais adotados para corrigir desigualdades raciais e promover a igualdade de oportunidades", "políticas que obstruem o desenvolvimento por favorecerem diferenças em detrimento do mérito", "políticas que impedem o acesso universal e promovem discriminação", "formas de penalizar a discriminação sem assegurar a igualdade de fato"], "corretaIndex": 1, "regra": "Lei nº 12.288/2010, art. 1º, parágrafo único, VI: ações afirmativas são os programas e medidas especiais adotados pelo Estado e pela iniciativa privada para a correção das desigualdades raciais e para a promoção da igualdade de oportunidades.", "fonte": "CESGRANRIO - 2025 - BANESE - Técnico Bancário I", "fonteUrl": "https://www.qconcursos.com/questoes-de-concursos", "valido": true}, {"id": 392, "materia": "Legislação", "assunto": "Decreto 5.904/2006 - Cão-Guia", "enunciado": "De acordo com o Decreto nº 5.904/2006, o direito da pessoa com deficiência visual de ser acompanhada por cão-guia em espaços públicos e privados de uso coletivo:", "alternativas": ["constitui um direito, sujeitando o infrator que impedir ou dificultar o acesso a multa", "constitui um direito, podendo haver cobrança de taxa extra no local", "constitui um direito apenas em espaços públicos, sendo vedado em espaços privados", "constitui um direito condicionado ao uso de focinheira em locais públicos e privados", "constitui um direito restrito a cães-guia treinados exclusivamente no Brasil"], "corretaIndex": 0, "regra": "Decreto nº 5.904/2006, art. 7º: o descumprimento do direito de ingresso e permanência com cão-guia sujeita o infrator a multa, sem prejuízo de outras sanções cabíveis.", "fonte": "CESGRANRIO - 2025 - BANESE - Técnico Bancário I", "fonteUrl": "https://www.qconcursos.com/questoes-de-concursos", "valido": true}, {"id": 393, "materia": "Legislação", "assunto": "Decreto 8.727/2016 - Identidade de Gênero", "enunciado": "O Decreto nº 8.727/2016 estabelece que a identidade de gênero se refere:", "alternativas": ["à forma como a pessoa se relaciona e se identifica com as representações de masculinidade e feminilidade, independentemente do sexo atribuído no nascimento", "à alteração de nome que exige o cumprimento de prazo mínimo de um ano", "à desobrigação dos órgãos federais em adotar o uso do nome social", "à designação que deve necessariamente coincidir com o sexo biológico e a certidão de nascimento", "à discricionariedade dos empregados de utilizar expressões discriminatórias no ambiente de trabalho"], "corretaIndex": 0, "regra": "Decreto nº 8.727/2016, art. 1º, parágrafo único, I: identidade de gênero é a dimensão da identidade de uma pessoa que diz respeito à forma como se relaciona com as representações de masculinidade e feminilidade, não vinculada ao sexo atribuído no nascimento.", "fonte": "CESGRANRIO - 2025 - BANESE - Técnico Bancário I", "fonteUrl": "https://www.qconcursos.com/questoes-de-concursos", "valido": true}, {"id": 394, "materia": "Legislação", "assunto": "Ética Profissional em Instituições Financeiras", "enunciado": "Um empregado bancário age de forma ética quando:", "alternativas": ["maximiza a rentabilidade comercial acima de qualquer outro critério", "prioriza a rentabilidade do banco em detrimento das necessidades do mercado", "respeita as diretrizes socioeconômicas definidas pelo governo", "age em conformidade com os princípios e valores organizacionais", "valoriza a cultura organizacional e a obediência irrestrita aos superiores"], "corretaIndex": 3, "regra": "Código de Ética e Conduta das instituições financeiras — fundamentado na Lei nº 13.303/2016, art. 9º — exige que a conduta do empregado esteja alinhada aos princípios e valores institucionais, não à obediência cega ou à maximização de lucro a qualquer custo.", "fonte": "CESGRANRIO - 2025 - BANESE - Técnico Bancário I", "fonteUrl": "https://www.qconcursos.com/questoes-de-concursos", "valido": true}, {"id": 395, "materia": "Legislação", "assunto": "Código de Conduta - Concorrência Leal", "enunciado": "De acordo com o Código de Conduta de instituição financeira estatal, a concorrência com competidores deve ser conduzida de forma justa e honesta, respeitando:", "alternativas": ["as regras usuais do capitalismo", "as melhores práticas de mercado", "as práticas comerciais já existentes", "as necessidades urgentes de lucro", "as referências mundiais de competitividade"], "corretaIndex": 1, "regra": "Princípio da concorrência leal previsto nos Códigos de Conduta e Integridade das estatais (Lei nº 13.303/2016, art. 9º), que orienta a atuação segundo as melhores práticas de mercado e a defesa da livre concorrência (art. 173, §4º, CF).", "fonte": "CESGRANRIO - 2025 - BANESE - Técnico Bancário III", "fonteUrl": "https://www.qconcursos.com/questoes-de-concursos", "valido": true}, {"id": 396, "materia": "Legislação", "assunto": "Governança de Risco - Declaração de Apetite a Risco", "enunciado": "De acordo com o Código de Conduta de instituição financeira estatal, as instituições não devem conduzir negócios que estejam desalinhados com a Declaração de:", "alternativas": ["Apetite a Risco da Instituição", "Compliance Institucional", "Seguro Institucional", "Deveres Institucionais", "Direitos Institucionais"], "corretaIndex": 0, "regra": "Resolução CMN nº 4.557/2017, art. 4º-A: a Declaração de Apetite por Riscos (RAS) documenta os níveis e tipos de risco que a instituição se propõe a assumir, orientando toda a condução dos negócios em conjunto com o Código de Conduta.", "fonte": "CESGRANRIO - 2025 - BANESE - Técnico Bancário III", "fonteUrl": "https://www.qconcursos.com/questoes-de-concursos", "valido": true}, {"id": 397, "materia": "Legislação", "assunto": "Código de Ética - Registro de Reuniões com Agentes Públicos", "enunciado": "De acordo com o Código de Ética da Caixa Econômica Federal, todas as reuniões com agentes públicos que envolvam a participação de pessoas externas devem ser registradas em:", "alternativas": ["anotação", "nota", "agenda", "arquivo", "ata"], "corretaIndex": 4, "regra": "Código de Ética da Caixa Econômica Federal e Lei de Acesso à Informação (Lei nº 12.527/2011) c/c princípio da publicidade (CF, art. 37) — reuniões com agentes públicos e terceiros devem ser formalmente registradas em ata.", "fonte": "CESGRANRIO - 2024 - Caixa - Técnico Bancário Novo", "fonteUrl": "https://www.qconcursos.com/questoes-de-concursos", "valido": true}, {"id": 398, "materia": "Legislação", "assunto": "Código de Conduta - Canal de Denúncias", "enunciado": "Constitui um preceito do Código de Conduta de instituição financeira estatal:", "alternativas": ["restringir denúncias a pessoas externas à instituição", "restringir denúncias a empregados internos", "garantir o anonimato do denunciante como proteção contra retaliação", "exigir que a denúncia seja feita diretamente à alta administração", "promover punições severas como fator de dissuasão"], "corretaIndex": 2, "regra": "Lei nº 13.303/2016, art. 9º, §1º, V: o Código de Conduta e Integridade deve dispor sobre canais de denúncia dotados de mecanismos de proteção ao denunciante de boa-fé, assegurando o anonimato.", "fonte": "CESGRANRIO - 2024 - Banco do Nordeste (BNB) - Analista Bancário", "fonteUrl": "https://www.qconcursos.com/questoes-de-concursos", "valido": true}, {"id": 399, "materia": "Legislação", "assunto": "Código de Ética - Uso de Redes Sociais Corporativas", "enunciado": "Um empregado bancário que publica ataques ofensivos contra seu gerente nos canais de mídia social do banco pratica conduta considerada:", "alternativas": ["exercício de livre expressão", "assunto de natureza estritamente privada", "não autorizada, por ser lesiva à imagem institucional", "solucionável apenas por mediação", "insignificante, caso não afete a produtividade"], "corretaIndex": 2, "regra": "Código de Ética e Conduta de instituições financeiras estatais, fundamentado no princípio da moralidade (CF, art. 37) e no dever de zelo pela imagem institucional (CLT, art. 482, 'b' e 'k').", "fonte": "CESGRANRIO - 2023 - Banco do Brasil - Agente Comercial", "fonteUrl": "https://www.qconcursos.com/questoes-de-concursos", "valido": true}, {"id": 400, "materia": "Legislação", "assunto": "Código de Ética - Repúdio ao Assédio", "enunciado": "O Código de Ética do Banco do Brasil repudia condutas associadas a:", "alternativas": ["diálogo", "respeito e cordialidade", "assédio", "liberdade sindical", "colaboração"], "corretaIndex": 2, "regra": "Código de Ética e Normas de Conduta do Banco do Brasil, fundamentado na CLT (art. 483) e na Lei nº 13.303/2016, art. 9º, que exige repúdio expresso a qualquer forma de assédio moral ou sexual no ambiente de trabalho.", "fonte": "CESGRANRIO - 2023 - Banco do Brasil - Agente Comercial", "fonteUrl": "https://www.qconcursos.com/questoes-de-concursos", "valido": true}, {"id": 401, "materia": "Informática", "assunto": "Excel - Função MÁXIMO", "enunciado": "Foi criada uma planilha no MS Excel 2016 contendo uma lista de preços de verduras. Essa planilha tem duas colunas: na primeira, estão os nomes das verduras, ocupando as células de J2 a J9; na segunda, estão os preços correspondentes dessas verduras, ocupando as células de K2 a K9. Nesse cenário, para que a célula G3 exiba o maior preço dentre os preços das verduras listadas, é adequado usar, nessa célula, a seguinte fórmula:", "alternativas": ["=MAIOR(K2:K9)", "=MÁXIMO(J2:J9)", "=MAIOR(J2:K9,1,K2:K9)", "=MÁXIMO(K2:K9)", "=MAIOR(J2:K9,G3)"], "corretaIndex": 3, "regra": "A função MÁXIMO(intervalo) retorna diretamente o maior valor numérico. Como os preços estão em K2:K9, a fórmula correta é =MÁXIMO(K2:K9). MAIOR exige um segundo argumento (posição).", "fonte": "CESGRANRIO - UNEMAT (2024)", "fonteUrl": "https://www.qconcursos.com/questoes-de-concursos/questoes/c541f0c7-dc", "valido": true}, {"id": 402, "materia": "Informática", "assunto": "Excel - Função SOMASE", "enunciado": "Em uma planilha eletrônica vazia do MS Excel 2016, um usuário preencheu as células J1, K1 e L1, respectivamente, com os valores 10, 30 e 50. Considerando-se esses valores, esse usuário deseja que a soma dos valores maiores que 10 seja exibida na célula M1. Nesse cenário, para que a célula M1 exiba o valor desejado, é adequado utilizar, nessa célula, a seguinte fórmula:", "alternativas": ["=SOMASE(J1:L1; >10)", "=SOMASE(J1:L1;\">10\")", "=SOMASE(\">10\";J1:L1)", "=SOMASE(\">10\";J1;L1)", "=SOMASE (J1;K1;L1;\">10\")"], "corretaIndex": 1, "regra": "Sintaxe: =SOMASE(intervalo; critério; [intervalo_soma]). O critério textual precisa de aspas: \">10\". Correta: =SOMASE(J1:L1;\">10\") = 30+50 = 80.", "fonte": "CESGRANRIO - UNEMAT (2024)", "fonteUrl": "https://www.qconcursos.com/questoes-de-concursos/questoes/6df1a195-dc", "valido": true}, {"id": 403, "materia": "Informática", "assunto": "E-mail - Campos Cc/Cco (Bcc)", "enunciado": "Ao enviar uma mensagem de e-mail para um destinatário original com uma cópia para outra pessoa, coloca-se o endereço de e-mail da pessoa copiada no campo \"Cc:\". Porém, algumas vezes, não se deseja que o destinatário original saiba que uma cópia do e-mail está sendo enviada para outra pessoa. Nesse caso, o endereço de e-mail da pessoa copiada em segredo deve ser colocado no campo", "alternativas": ["Bc:", "Cc:", "Bbc:", "Bcc:", "Ccb:"], "corretaIndex": 3, "regra": "O campo \"Cco\"/\"Bcc\" (Blind Carbon Copy - cópia oculta) envia uma cópia sem que os demais destinatários vejam esse endereço.", "fonte": "CESGRANRIO - UNEMAT (2024)", "fonteUrl": "https://www.qconcursos.com/questoes-de-concursos/questoes/6deb90c4-dc", "valido": true}, {"id": 404, "materia": "Informática", "assunto": "E-mail - Campo Reply-To", "enunciado": "Uma das possibilidades do protocolo de e-mail é permitir que a resposta de uma mensagem seja direcionada automaticamente para um endereço diferente do endereço de quem enviou a mensagem, que aparece no campo \"From:\". Para fazer esse direcionamento, o endereço para o qual a resposta deve ser enviada deve ser colocado no campo", "alternativas": ["Answer-To:", "React-To:", "Reply-To:", "Respond-To:", "Return-To:"], "corretaIndex": 2, "regra": "O cabeçalho \"Reply-To\" (RFC 5322) define para qual endereço as respostas devem ser enviadas, podendo ser diferente do remetente original.", "fonte": "CESGRANRIO - UNEMAT (2024)", "fonteUrl": "https://www.qconcursos.com/questoes-de-concursos/questoes/c53d06a8-dc", "valido": true}, {"id": 405, "materia": "Informática", "assunto": "Segurança da Informação - Vírus de computador", "enunciado": "Um vírus de computador é um tipo de software malicioso capaz de causar prejuízos graves às pessoas e às organizações. O termo vírus de computador foi adotado em função de sua característica principal, que é", "alternativas": ["coletar informações de um computador e transmiti-las para outro local.", "permitir acesso ao computador sem o uso das verificações de segurança padrão.", "destruir o hardware por meio de comandos específicos de software.", "passar doenças para as pessoas que usam o computador.", "se replicar e se espalhar de um computador para outro."], "corretaIndex": 4, "regra": "A analogia com o vírus biológico vem da capacidade de autorreplicação: o vírus se anexa a arquivos hospedeiros e se copia para outros arquivos/computadores.", "fonte": "CESGRANRIO - UNEMAT (2024)", "fonteUrl": "https://www.qconcursos.com/questoes-de-concursos/questoes/6de97830-dc", "valido": true}, {"id": 406, "materia": "Informática", "assunto": "Segurança da Informação - Integridade (hash)", "enunciado": "A integridade é um dos pilares da segurança da informação. O controle de integridade permite determinar alteração ou destruição intencional e alteração ou perda acidental de dados, ou seja, assegura que as alterações nos dados sejam detectáveis. Um mecanismo de segurança amplamente usado para produzir o código de verificação de integridade é o(a)", "alternativas": ["resumo de mensagem", "certificado digital", "envelope digital", "cifragem simétrica", "senha de uso único"], "corretaIndex": 0, "regra": "O 'resumo de mensagem' (hash, como SHA-256) gera um código de tamanho fixo; qualquer alteração no conteúdo muda o hash, permitindo detectar violações de integridade.", "fonte": "CESGRANRIO - BANESE - Técnico Bancário I (2025)", "fonteUrl": "https://www.qconcursos.com/questoes-de-concursos/questoes/00ad6069-14", "valido": true}, {"id": 407, "materia": "Informática", "assunto": "Redes - Segurança em LAN/Intranet (VPN e certificados)", "enunciado": "A equipe de suporte técnico de um banco precisa garantir que a comunicação entre as suas agências seja segura e eficiente. Para isso, a equipe está configurando a rede local (LAN) e a conexão com a rede corporativa (intranet) para acesso a serviços internos. Durante essa configuração, a prática adequada para garantir a segurança e o desempenho na comunicação da rede é", "alternativas": ["habilitar o compartilhamento de arquivos sem restrições para facilitar a troca de dados entre departamentos", "utilizar redes Wi-Fi públicas para reduzir custos, garantindo que os dados confidenciais sejam salvos localmente", "utilizar endereços IP estáticos para todos os dispositivos e desabilitar o uso do DHCP", "configurar a intranet com autenticação por certificados digitais e utilizar uma VPN para conexões externas", "desativar o firewall da rede para melhorar a velocidade de conexão e usar antivírus local em cada máquina"], "corretaIndex": 3, "regra": "Certificados digitais garantem autenticação forte; VPN cria túnel criptografado para conexões externas, protegendo dados em trânsito.", "fonte": "CESGRANRIO - BANESE - Técnico Bancário I (2025)", "fonteUrl": "https://www.qconcursos.com/questoes-de-concursos/questoes/002cc676-14", "valido": true}, {"id": 408, "materia": "Informática", "assunto": "Windows 11 - Recursos de segurança (Secure Boot/Defender)", "enunciado": "Um técnico bancário precisa garantir a segurança e a eficiência no uso de computadores com o sistema operacional Windows 11 em uma agência bancária. Durante a instalação e a configuração do sistema operacional, ele é solicitado a habilitar funcionalidades que aumentem a segurança, sem comprometer o desempenho da máquina. Para atingir esse objetivo, na instalação do Windows 11, o técnico deve configurá-lo de forma a", "alternativas": ["ativar o Hyper-V e desabilitar o Bit-Locker.", "ativar o Modo Desenvolvedor e desabilitar o Controle de Conta de Usuário (UAC).", "habilitar a inicialização segura (Secure Boot) e o Windows Defender Firewall.", "desativar as atualizações automáticas e utilizar uma solução antivírus de terceiros.", "iniciar diretamente no modo de segurança para todos os usuários."], "corretaIndex": 2, "regra": "Secure Boot protege a inicialização contra bootkits, e o Windows Defender Firewall protege o tráfego de rede — ambos nativos e sem impacto relevante de desempenho.", "fonte": "CESGRANRIO - BANESE - Técnico Bancário I (2025)", "fonteUrl": "https://www.qconcursos.com/questoes-de-concursos/questoes/002a2eec-14", "valido": true}, {"id": 409, "materia": "Informática", "assunto": "LGPD - Princípios (Transparência)", "enunciado": "A Lei Geral de Proteção de Dados (LGPD) estabelece que as atividades de tratamento de dados pessoais devem observar a boa-fé e os princípios fundamentais. Um desses princípios garante aos titulares dos dados facilidade de acesso a informações claras e precisas sobre a realização do tratamento e os respectivos agentes de tratamento, observados os segredos comercial e industrial. Esse princípio é denominado", "alternativas": ["finalidade", "adequação", "necessidade", "transparência", "prevenção"], "corretaIndex": 3, "regra": "Lei nº 13.709/2018, art. 6º, VI: princípio da transparência - garantia de informações claras, precisas e facilmente acessíveis sobre o tratamento.", "fonte": "CESGRANRIO - IPEA - Profissional de Planejamento e Pesquisa (2024)", "fonteUrl": "https://www.qconcursos.com/questoes-de-concursos/questoes/98c54816-d8", "valido": true}, {"id": 410, "materia": "Informática", "assunto": "Formatos de arquivo - E-book EPUB", "enunciado": "O e-book só pode ser acessado por meio de um software ou aplicativo para leitura, chamado reader. Para ler, em computadores desktop ou notebooks, e-books no formato EPUB, o leitor deve acessar softwares como", "alternativas": ["o iBooks, o ePUB Reader ou o Readium", "o Bluefire Reader, o Acrobat Reader ou o iBooks", "o Google Play Livros ou o Acrobat Reader", "o Google Play Livros ou o iBooks", "o Google Play Livros, exclusivamente"], "corretaIndex": 0, "regra": "O formato EPUB é aberto e suportado por leitores dedicados como iBooks, ePUB Reader e Readium. O Acrobat Reader é voltado a PDF, não EPUB.", "fonte": "CESGRANRIO - IPEA (2024)", "fonteUrl": "https://www.qconcursos.com/questoes-de-concursos/questoes/622328fd-d5", "valido": true}, {"id": 411, "materia": "Informática", "assunto": "Windows - Serviços (Spooler de Impressão)", "enunciado": "Um administrador identificou um problema no serviço de impressão no sistema operacional Microsoft Windows 10. A recomendação, nesse caso, é fazer a parada do serviço e, em seguida, fazer a sua inicialização. Na janela Serviços desse sistema operacional, o serviço de impressão é identificado como", "alternativas": ["Gerente de Impressão", "Controlador de Impressão", "Driver de Impressão", "Spooler de Impressão", "Daemon de Impressão"], "corretaIndex": 3, "regra": "No Windows, o serviço responsável pela fila de impressão é o \"Spooler de Impressão\" (Print Spooler), acessível em Serviços (services.msc).", "fonte": "CESGRANRIO - Transpetro (2023)", "fonteUrl": "https://www.qconcursos.com/questoes-de-concursos/questoes/1b961384-9e", "valido": true}, {"id": 412, "materia": "Informática", "assunto": "Computação em Nuvem - Modelos de serviço (PaaS)", "enunciado": "O propósito principal da computação em nuvem é proporcionar um aluguel conveniente de recursos de computação. Um dos serviços praticados proporciona blocos de construção de software úteis, além de uma série de ferramentas de desenvolvimento, como linguagens de programação e ambientes de construção e de execução de programas que auxiliam na implementação de novas aplicações. Esse modelo de serviço é conhecido como", "alternativas": ["BaaS", "DaaS", "IaaS", "PaaS", "SaaS"], "corretaIndex": 3, "regra": "PaaS entrega uma plataforma de desenvolvimento (linguagens, frameworks, runtime), diferente de IaaS (infraestrutura) e SaaS (software pronto).", "fonte": "CESGRANRIO - Transpetro (2023)", "fonteUrl": "https://www.qconcursos.com/questoes-de-concursos/questoes/1b72f368-9e", "valido": true}, {"id": 413, "materia": "Informática", "assunto": "Computação em Nuvem - Elasticidade", "enunciado": "A computação em nuvem é uma categoria de soluções de computação que permite a alocação de recursos de computação de forma dinâmica e ajustável, em função da carga variável do sistema. Essa facilidade de poder aumentar ou diminuir gradualmente a capacidade computacional, pagando apenas pelo que está efetivamente alocado, é uma característica da computação em nuvem. Essa característica é denominada", "alternativas": ["disponibilidade", "elasticidade", "redundância", "tolerância a falhas", "clustering"], "corretaIndex": 1, "regra": "Elasticidade é a capacidade de escalar recursos para cima ou para baixo sob demanda, cobrando apenas pelo uso efetivo (pay-as-you-go).", "fonte": "CESGRANRIO - Transpetro (2023)", "fonteUrl": "https://www.qconcursos.com/questoes-de-concursos/questoes/1b75b717-9e", "valido": true}, {"id": 414, "materia": "Português", "assunto": "Pontuação (uso da vírgula)", "enunciado": "Considerando-se as regras de pontuação da norma-padrão da Língua Portuguesa, o uso de vírgulas está correto em:", "alternativas": ["\"A mudança climática, é um fenômeno global, que resulta da intensificação do efeito estufa causado principalmente pela queima de combustíveis fósseis, desmatamento e práticas agrícolas insustentáveis.\"", "\"As consequências da mudança climática vão além do aumento da temperatura, abrangendo eventos climáticos extremos mais frequentes e intensos, como furacões, secas, inundações e ondas de calor.\"", "\"As mudanças climáticas têm causado danos irreversíveis, aos ecossistemas marinhos, como os recifes de corais e as populações de peixes, comprometendo a segurança alimentar de milhões de pessoas que dependem dos mares para sua subsistência.\"", "\"A transição energética depende da implementação, urgente de políticas de mitigação e adaptação à mudança climática, o que representa um grande desafio para governos, empresas e a sociedade civil em todo o mundo.\"", "\"Embora a mudança climática seja um fenômeno que afeta a todos os países, suas consequências são sentidas de maneira desigual, o que, exige uma ação global coordenada, para garantir a justiça climática.\""], "corretaIndex": 1, "regra": "Não se separa por vírgula o sujeito do predicado nem o verbo de seu complemento. Em (A) há vírgula indevida entre o sujeito e o verbo 'é'; em (C), entre 'irreversíveis' e seu complemento; em (D), entre 'implementação' e 'urgente'; em (E), o 'o que' é isolado sem justificativa sintática. Em (B), a vírgula introduz corretamente uma oração reduzida de gerúndio com valor explicativo.", "fonte": "CESGRANRIO - 2025 - BANESE - Técnico Bancário I", "fonteUrl": "https://www.qconcursos.com/questoes-de-concursos/questoes/fff9e8e4-14", "valido": true}, {"id": 415, "materia": "Português", "assunto": "Crase", "enunciado": "O acento grave indicativo de crase nos termos em destaque está empregado de acordo com as regras da norma-padrão da Língua Portuguesa em:", "alternativas": ["A conscientização sobre às mudanças climáticas é essencial para um futuro sustentável.", "As mudanças climáticas estão afetando à vida marinha a uma velocidade alarmante.", "As ações humanas têm levado à uma diminuição da biodiversidade e a alterações climáticas.", "As alterações no clima ajudam à intensificar desastres naturais ao redor do mundo.", "A necessidade de adaptar a agricultura às mudanças climáticas é urgente."], "corretaIndex": 4, "regra": "Só há crase quando uma palavra feminina, regida por termo que exige a preposição 'a', admite substituição por 'as'. Em (A) 'sobre' já é a preposição regente; em (B) 'afetar' é transitivo direto; em (C) e (D) o 'a' antecede infinitivo/artigo indefinido, o que nunca admite crase. Em (E), 'adaptar algo A algo' + 'mudanças' (fem. plural) exige 'às mudanças'.", "fonte": "CESGRANRIO - 2025 - BANESE - Técnico Bancário I", "fonteUrl": "https://www.qconcursos.com/questoes-de-concursos/questoes/fff4ea99-14", "valido": true}, {"id": 416, "materia": "Português", "assunto": "Pontuação (uso da vírgula)", "enunciado": "No que se refere ao emprego da vírgula, a frase que atende aos aspectos da escrita formal do português, respeitando-se a norma-padrão da Língua Portuguesa, é:", "alternativas": ["A IA, conforme vem sendo divulgado revolucionará a forma de fazer negócios.", "Uma ascensão rápida no mercado de trabalho, depende do conhecimento acumulado ao longo da vida.", "Proatividade é uma das características mais procuradas em candidatos a empregos, mas a ética, é a principal.", "Constituem, pré-requisitos para acessar uma vaga nesta empresa, competência administrativa, boa comunicação e conhecimento em TI.", "Certamente, as empresas que estão na liderança fazem uso de IA."], "corretaIndex": 4, "regra": "A vírgula pode isolar advérbio/expressão deslocada para o início do período, mas nunca separa sujeito de verbo nem verbo de complemento. Em (A) falta a vírgula de fechamento da intercalação; em (B) e (C), separa indevidamente sujeito e verbo; em (D), separa o verbo do predicativo/sujeito posposto. Em (E), a vírgula isola corretamente o advérbio 'Certamente' antecipado.", "fonte": "CESGRANRIO - 2025 - BANESE - Técnico Bancário III (Desenvolvimento e Suporte)", "fonteUrl": "https://www.qconcursos.com/questoes-de-concursos/questoes/dceadaf1-14", "valido": true}, {"id": 417, "materia": "Português", "assunto": "Crase", "enunciado": "O acento grave está empregado de acordo com a norma-padrão da Língua Portuguesa, na seguinte frase:", "alternativas": ["Trabalharemos com a IA à qualquer nova oportunidade de contrato.", "A adoção da IA para o RH, à qual discutimos ontem, será implementada.", "Os acionistas se organizaram à fim de investir em nova tecnologia este ano.", "Voltaremos àquilo que discutimos na reunião sobre a aquisição de novas tecnologias.", "O mercado financeiro começou à considerar os ganhos com o uso da IA."], "corretaIndex": 3, "regra": "Não há crase antes de pronome indefinido ('qualquer'), antes de verbo no infinitivo, nem na locução fixa 'a fim de' (sem acento). Em (D), 'àquilo' é a contração obrigatória de 'a' + o pronome demonstrativo 'aquilo', exigida pela regência de 'voltar a algo'.", "fonte": "CESGRANRIO - 2025 - BANESE - Técnico Bancário III (Desenvolvimento e Suporte)", "fonteUrl": "https://www.qconcursos.com/questoes-de-concursos/questoes/dce85648-14", "valido": true}, {"id": 418, "materia": "Português", "assunto": "Crase", "enunciado": "De acordo com a norma-padrão da língua portuguesa, o emprego do acento grave indicativo da crase é obrigatório na palavra destacada em:", "alternativas": ["A exigência de entrar em contato com instituições financeiras obrigou o cliente a criar senhas para ter acesso aos serviços bancários.", "A falta de leis sobre privacidade digital exige que os indivíduos se preparem para enfrentar a invasão do acesso a suas vidas privadas.", "A revolução da tecnologia da informação modificou a realidade social, penetrando em todas as esferas da atividade humana.", "As pesquisas tecnológicas são indispensáveis devido à importância de solucionar problemas causados pela invasão de dados.", "O surgimento das redes sociais e dos sites de compartilhamento conduziu as pessoas a novas situações de risco na sociedade atual."], "corretaIndex": 3, "regra": "A locução 'devido a' exige a preposição 'a'; como 'importância' é substantivo feminino, ocorre crase obrigatória: 'devido à importância'. Nas demais, o 'a' antecede infinitivo ou substantivo sem artigo definido, não cabendo o acento grave.", "fonte": "CESGRANRIO - 2021 - Banco do Brasil - Escriturário (Agente Comercial)", "fonteUrl": "https://www.qconcursos.com/questoes-de-concursos/questoes/f004d158-26", "valido": true}, {"id": 419, "materia": "Português", "assunto": "Regência Verbal", "enunciado": "De acordo com as regras de regência verbal estabelecidas pela norma-padrão da Língua Portuguesa, o elemento destacado está adequadamente empregado em:", "alternativas": ["Os inadimplentes infringem aos regulamentos estabelecidos pelas financeiras ao deixar de cumprir os prazos dos empréstimos.", "Os comerciantes elogiaram aos bancos às medidas tomadas a favor de seus empreendimentos.", "Vários executivos procuram realizar cursos de especialização porque cobiçam aos estágios mais avançados da carreira.", "Os funcionários mais graduados das grandes empresas aspiram aos melhores cargos tendo em vista o aumento de seu poder aquisitivo.", "Algumas grandes empresas responsáveis pelas redes sociais ludibriam aos princípios estabelecidos por lei ao permitir postagens agressivas."], "corretaIndex": 3, "regra": "O verbo 'aspirar', no sentido de 'desejar, almejar', é transitivo indireto e rege a preposição 'a' ('aspirar A algo'). Os verbos 'infringir', 'elogiar', 'cobiçar' e 'ludibriar' são transitivos diretos e não admitem preposição antes do complemento.", "fonte": "CESGRANRIO - 2015 - Banco do Brasil - Escriturário", "fonteUrl": "https://www.qconcursos.com/questoes-de-concursos/questoes/d6fa4158-76", "valido": true}, {"id": 420, "materia": "Português", "assunto": "Colocação Pronominal", "enunciado": "A colocação do pronome oblíquo destacado está de acordo com a norma-padrão em:", "alternativas": ["O dinheiro não foi-me bastante.", "O depósito só estará concretizado, se houver quem validá-lo.", "Se você pudesse emprestar esse dinheiro, depositaria-o ainda esta semana?", "Explique-me como funciona esse financiamento.", "Me empreste seu cartão, que eu faço a transação hoje."], "corretaIndex": 3, "regra": "Verbo no imperativo afirmativo, sem palavra atrativa antes, exige ênclise obrigatória do pronome átono ('Explique-me'). Em (A), o advérbio de negação 'não' atrai o pronome para próclise, tornando incorreta a ênclise; em (E), a frase inicia-se por pronome oblíquo átono, o que a norma-padrão não admite.", "fonte": "CESGRANRIO - 2021 - Banco do Brasil - Escriturário (Agente Comercial)", "fonteUrl": "https://www.qconcursos.com/questoes-de-concursos/questoes/4617d816-2b", "valido": true}, {"id": 421, "materia": "Português", "assunto": "Crase", "enunciado": "O uso do sinal indicativo da crase é obrigatório em:", "alternativas": ["A metrópole exerce influência social e administrativa sobre a maioria das cidades da região.", "Cada vez mais, os moradores têm acesso a bens de consumo como eletrodomésticos e celulares.", "Nas grandes cidades, o crescimento populacional é sempre aliado a índices econômicos altos.", "O governo precisa investir na saúde para corresponder a expectativa da população.", "O planejamento familiar é necessário para não levar o mundo a uma situação insustentável."], "corretaIndex": 3, "regra": "O verbo 'corresponder', no sentido de 'atender a, satisfazer', é transitivo indireto e rege a preposição 'a'; como 'expectativa' é substantivo feminino singular, há crase obrigatória: 'corresponder à expectativa'.", "fonte": "CESGRANRIO - 2012 - EPE (Empresa de Pesquisa Energética) - Assistente Administrativo", "fonteUrl": "https://www.qconcursos.com/questoes-de-concursos/questoes/a8f83bc6-64", "valido": true}, {"id": 422, "materia": "Português", "assunto": "Crase", "enunciado": "O acento indicativo de crase está usado de acordo com a norma-padrão em:", "alternativas": ["O pai não gostava de que à ceia fosse feita antes das dez horas da noite.", "À bem dizer, o pai era um sujeito bastante esquisito.", "Às famílias desprovidas de recursos na vizinhança, o pai sempre dava um presente.", "Daqui à duas horas, tentarei começar o ritual de abrir o pacote para desvendar o segredo.", "O nome da estrada era Arca porque à região, entre Itaipava e Teresópolis, era assim conhecida."], "corretaIndex": 2, "regra": "O verbo 'dar' pode reger a preposição 'a' ('dar algo A alguém'); 'famílias' é substantivo feminino plural, admitindo o artigo 'as' — logo, fusão obrigatória 'às famílias'. As demais trazem crase indevida diante de locução fixa sem artigo ou de expressão numeral de tempo.", "fonte": "CESGRANRIO - 2014 - CEFET-RJ - Conhecimentos Básicos", "fonteUrl": "https://www.qconcursos.com/questoes-de-concursos/questoes/0b0f6339-f7", "valido": true}, {"id": 423, "materia": "Português", "assunto": "Concordância Verbal", "enunciado": "A concordância verbal está de acordo com a norma-padrão em:", "alternativas": ["Tratam-se de problemas nunca resolvidos.", "Nunca se assistem a ações afirmativas nesses casos.", "Em poucas cidades, apresentam-se soluções adequadas para o comércio ambulante.", "A situação dos moradores de habitações precárias são as piores.", "Antes haviam políticas que buscavam solucionar o problema do comércio ambulante."], "corretaIndex": 2, "regra": "Com o 'se' apassivador associado a verbo transitivo direto, o verbo concorda com o sujeito paciente: 'soluções' (plural) exige 'apresentam-se'. Nas demais: 'tratar-se de' é impessoal (deveria ser 'Trata-se'); 'assistir a' é transitivo indireto, com 'se' de indeterminação, sempre no singular; há discordância entre 'a situação' e 'são'; e 'haver' no sentido de existir é impessoal e invariável.", "fonte": "CESGRANRIO - 2014 - IBGE - Supervisor de Pesquisas", "fonteUrl": "https://www.qconcursos.com/questoes-de-concursos/questoes/ada9a0cb-d3", "valido": true}, {"id": 424, "materia": "Português", "assunto": "Regência Nominal", "enunciado": "A regência nominal está adequada à norma-padrão em:", "alternativas": ["Os pobres são ávidos por melhores condições de vida.", "Os catadores sentem desejo com uma vida melhor.", "Muitos catadores têm orgulho em seu ofício.", "Parte da população é sensível para a pobreza.", "Vários dejetos são inúteis para com a reutilização."], "corretaIndex": 0, "regra": "O adjetivo 'ávido' admite as preposições 'de' ou 'por'. Nas demais há erro de regência nominal: 'desejo' pede 'de' (não 'com'); 'orgulho' pede 'de' (não 'em'); 'sensível' pede 'a' (não 'para a'); e 'inútil' pede 'a' ou 'para' (nunca 'para com').", "fonte": "CESGRANRIO - 2016 - IBGE - Supervisor de Pesquisas", "fonteUrl": "https://www.qconcursos.com/questoes-de-concursos/questoes/83d66848-73", "valido": true}, {"id": 425, "materia": "Português", "assunto": "Acentuação Gráfica", "enunciado": "Em conformidade com o Acordo Ortográfico da Língua Portuguesa vigente, atendem às regras de acentuação todas as palavras em:", "alternativas": ["andróide, odisseia, residência", "arguição, refém, mausoléu", "desbloqueio, pêlo, escarcéu", "feiúra, enjoo, maniqueísmo", "sutil, assembléia, arremesso"], "corretaIndex": 1, "regra": "Acentuam-se: hiatos tônicos 'u/i' após 'g/q' (arguição), oxítonas terminadas em 'em/ens' com mais de uma sílaba (refém) e ditongos abertos tônicos 'éu' em monossílabos/oxítonas (mausoléu). As demais contêm grafias com acentos abolidos pelo Acordo ('andróide', 'pêlo', 'assembléia' não se acentuam mais).", "fonte": "CESGRANRIO - 2018 - Transpetro - Técnico de Faixa de Dutos Júnior", "fonteUrl": "https://www.qconcursos.com/questoes-de-concursos/questoes/d1328185-43", "valido": true}, {"id": 426, "materia": "Português", "assunto": "Concordância Nominal", "enunciado": "A concordância do adjetivo destacado foi realizada de acordo com as exigências da norma-padrão em:", "alternativas": ["A espionagem virtual e a ausência de punição são corriqueiros", "A guerra cibernética e o manejo de dados são básicas", "O acolhimento e a redução são necessárias", "Os e-mails e conversas virtuais são monitorados permanentemente", "Os softwares e a atualização são obrigatórias"], "corretaIndex": 3, "regra": "Quando o predicativo posposto se refere a substantivos de gêneros diferentes, a norma-padrão determina concordância no masculino plural. Em 'Os e-mails e conversas virtuais são monitorados' o masculino plural está correto (une masculino e feminino). As demais usam indevidamente o feminino ou o masculino singular para sujeitos compostos de gêneros diferentes.", "fonte": "CESGRANRIO - 2018 - Transpetro - Técnico de Faixa de Dutos Júnior", "fonteUrl": "https://www.qconcursos.com/questoes-de-concursos/questoes/d13cf6f5-43", "valido": true}, {"id": 427, "materia": "Português", "assunto": "Concordância Verbal (voz passiva sintética)", "enunciado": "A concordância da forma verbal destacada foi realizada de acordo com as exigências da norma-padrão da língua portuguesa em:", "alternativas": ["é necessário que se promova novos estudos sobre mecanismos de proteção mais eficazes", "o rastreamento permanente das invasões cibernéticas de grande porte permite que se suspeitem dos hackers responsáveis", "é preciso que se destinem à pesquisa tecnológica muitos milhões de dólares", "necessitam-se de estudos mais aprofundados", "é aconselhável que se estabeleça novas restrições de utilização pelas jovens"], "corretaIndex": 2, "regra": "Com verbo transitivo direto + 'se' apassivador, o verbo concorda em número com o sujeito paciente. Em 'se destinem... muitos milhões de dólares', o sujeito paciente é plural, exigindo 'destinem'. Nas demais, o verbo não concorda ('promova'/'estabeleça' deveriam ir ao plural) ou o verbo é transitivo indireto ('suspeitar de', 'necessitar de'), incompatível com voz passiva sintética.", "fonte": "CESGRANRIO - 2018 - Transpetro - Técnico de Faixa de Dutos Júnior", "fonteUrl": "https://www.qconcursos.com/questoes-de-concursos/questoes/d1403460-43", "valido": true}, {"id": 428, "materia": "Português", "assunto": "Ortografia", "enunciado": "Obedecem às regras ortográficas da língua portuguesa as palavras", "alternativas": ["admissão, paralisação, impasse", "bambusal, autorização, inspiração", "consessão, extresse, enxaqueca", "banalisação, reexame, desenlace", "desorganisação, abstração, cassação"], "corretaIndex": 0, "regra": "Palavras derivadas com sufixo '-izar/-ização' grafam-se com 'z' (não 's'), e 'concessão'/'estresse' grafam-se com 'c'/duplo 's'. Em (A), todas as palavras estão corretas ('paralisação', de paralisar, legitimamente com 's'). As demais contêm ao menos uma palavra com erro de grafia.", "fonte": "CESGRANRIO - 2018 - Transpetro - Técnico de Faixa de Dutos Júnior", "fonteUrl": "https://www.qconcursos.com/questoes-de-concursos/questoes/d1498b7a-43", "valido": true}, {"id": 429, "materia": "Português", "assunto": "Concordância Verbal", "enunciado": "A frase em que a concordância do verbo em destaque está empregada de acordo com a norma-padrão da Língua Portuguesa é:", "alternativas": ["Ao considerar os fenômenos climáticos ocorridos no Brasil, como seca intensa, incêndios devastadores e chuvas torrenciais, constata-se a importância dos estudos sobre o impacto do homem na Terra.", "Nos últimos anos, criou-se inúmeros programas computacionais para o combate a doenças tropicais.", "Para atender às demandas da humanidade, ampliou-se as pesquisas sobre mudanças climáticas.", "Para facilitar a interação entre turistas de diferentes países, precisam-se de novas tecnologias de tradução simultânea.", "Quando se analisa os índices de mortalidade por dengue no Brasil, fica evidente a necessidade de mais pesquisas."], "corretaIndex": 0, "regra": "Verbo transitivo direto + 'se' apassivador concorda com o sujeito paciente. Em (A), 'constata-se a importância' tem sujeito singular, concordando corretamente. Nas demais há discordância: sujeitos plurais exigiriam plural ('criaram-se', 'ampliaram-se', 'se analisam'), e 'precisar de' é transitivo indireto, não podendo ficar no plural.", "fonte": "CESGRANRIO - 2024 - CNU (Concurso Nacional Unificado) - Bloco 8 - Nível Intermediário", "fonteUrl": "https://www.qconcursos.com/questoes-de-concursos/questoes/992e729e-5f", "valido": true}, {"id": 430, "materia": "Português", "assunto": "Pontuação (uso da vírgula)", "enunciado": "Identificar a alternativa em que a vírgula é empregada corretamente conforme a norma-padrão.", "alternativas": ["A formação de cientistas brasileiros que respeitem as características culturais e étnicas das diferentes regiões do país, deve ser prioridade nas políticas públicas.", "Com o objetivo de ajudar a entender os desafios atuais da sociedade brasileira, o governo deveria financiar pesquisas científicas voltadas para a população.", "É necessário criar grandes bancos de dados, que sejam municiados pelos estudos científicos realizados no país.", "É preciso criar em todas as áreas do conhecimento, projetos governamentais de incentivo à pesquisa.", "O Brasil e os países em desenvolvimento, precisam implementar uma agenda conjunta de pesquisa científica."], "corretaIndex": 1, "regra": "Oração subordinada adverbial (reduzida ou não) anteposta à oração principal deve ser separada por vírgula. Em (B), a longa oração reduzida de infinitivo está corretamente isolada por vírgula antes da oração principal. Nas demais, a vírgula separa indevidamente sujeito e verbo (A e E) ou verbo e complemento (D).", "fonte": "CESGRANRIO - 2024 - CNU (Concurso Nacional Unificado) - Bloco 8 - Nível Intermediário", "fonteUrl": "https://www.qconcursos.com/questoes-de-concursos/questoes/9936c3c6-5f", "valido": true}, {"id": 431, "materia": "Português", "assunto": "Concordância Nominal", "enunciado": "A palavra destacada em negrito está empregada corretamente, conforme as regras de concordância nominal, em:", "alternativas": ["As pesquisas para a cura de doenças e a busca de solução para os problemas ambientais estão vinculadas ao aumento das verbas do financiamento governamental.", "A ampliação dos institutos de pesquisa e o fomento às universidades públicas são solicitadas constantemente pela comunidade científica.", "Nos países em desenvolvimento, o investimento governamental em alunos do ensino superior e a promoção de grupos de pesquisa são escassas.", "Os testes para avaliar a efetividade das vacinas e as publicações científicas foram financiadas pelo governo.", "O vasto território brasileiro e a nossa incrível diversidade de biomas são decisivas para a pesquisa científica."], "corretaIndex": 0, "regra": "Quando os substantivos do sujeito composto têm o mesmo gênero, o predicativo posposto flexiona-se nesse mesmo gênero, no plural. Em (A), 'as pesquisas' e 'a busca de solução' são ambos femininos, exigindo 'vinculadas'. Nas demais, os sujeitos compostos têm gêneros diferentes, casos em que a regra geral pede o masculino plural, o que não ocorre.", "fonte": "CESGRANRIO - 2024 - CNU (Concurso Nacional Unificado) - Bloco 8 - Nível Intermediário", "fonteUrl": "https://www.qconcursos.com/questoes-de-concursos/questoes/9938caae-5f", "valido": true}, {"id": 432, "materia": "Português", "assunto": "Estrutura das Palavras (Prefixos)", "enunciado": "Assinale o grupo em que todas as palavras apresentam prefixo que expressa negação.", "alternativas": ["desconfiança, inferioridade, invasão", "descrença, inconveniência, impaciência", "desenvolvimento, descrição, infelicidade", "desigualdade, indústria, infecção", "despeito, descendência, imoralidade"], "corretaIndex": 1, "regra": "Os prefixos 'des-' e 'in-/im-' só indicam negação quando o radical mantém sentido oposto reconhecível: crença→descrença, conveniência→inconveniência, paciência→impaciência. Nas demais, ao menos uma palavra tem prefixo homônimo que não exprime negação ('invasão', 'indústria', 'infecção' têm 'in-' como parte do radical).", "fonte": "CESGRANRIO - 2024 - CNU (Concurso Nacional Unificado) - Bloco 8 - Nível Intermediário", "fonteUrl": "https://www.qconcursos.com/questoes-de-concursos/questoes/993acffc-5f", "valido": true}, {"id": 433, "materia": "Português", "assunto": "Emprego de Onde/Aonde", "enunciado": "Assinale a alternativa em que 'onde' está empregado corretamente, conforme a norma-padrão.", "alternativas": ["A inteligência artificial tem possibilitado a democratização de vários serviços, onde é necessário destacar o acesso igualitário à informação.", "Os biomas brasileiros onde tem ocorrido o maior número de ameaças ambientais precisam de políticas urgentes de proteção.", "Os cientistas devem ter maior preocupação com determinados grupos populacionais onde as pesquisas sobre habitação, água e saneamento sejam mais necessárias.", "Os pesquisadores precisam desenvolver estudos aprofundados onde as principais doenças do país possam ser combatidas.", "Vivemos em uma época onde as pessoas que negam a ciência se recusam a vacinar seus filhos."], "corretaIndex": 1, "regra": "O pronome relativo 'onde' só deve ser empregado com referência a lugar físico. Em (B), 'biomas brasileiros' é lugar físico, uso correto. Nas demais, 'onde' retoma substantivo abstrato, pessoas ou tempo, erro na norma-padrão.", "fonte": "CESGRANRIO - 2024 - CNU (Concurso Nacional Unificado) - Bloco 8 - Nível Intermediário", "fonteUrl": "https://www.qconcursos.com/questoes-de-concursos/questoes/993d0dd7-5f", "valido": true}, {"id": 434, "materia": "Português", "assunto": "Pontuação (uso da vírgula)", "enunciado": "O emprego da vírgula está plenamente de acordo com as exigências da norma-padrão da língua portuguesa em:", "alternativas": ["A conscientização sobre reciclagem e reutilização de plástico é muito importante porque o descarte correto desse lixo, é essencial para a saúde do oceano em todas as partes do mundo.", "A contribuição da população para manter a limpeza nas praias, é fundamental para que as águas do mar não carreguem sujeira que prejudique a natureza.", "O lixo nos mares devido aos imensos transtornos por ele causado, apresenta consequências mortais para os animais que ali vivem e ingerem materiais prejudiciais a sua saúde.", "O plástico, em função de sua enorme durabilidade na natureza, é um dos produtos mais poluentes criados pelo homem.", "O Brasil signatário da Convenção Internacional para a Prevenção da Poluição Causada por Navios, assumiu o compromisso para atingir metas relativas à preservação da vida abaixo d'água."], "corretaIndex": 3, "regra": "Um par de vírgulas isola corretamente um adjunto adverbial (ou aposto) intercalado entre sujeito e verbo. Em (D), 'em função de sua enorme durabilidade na natureza' está isolado entre o sujeito 'O plástico' e o verbo 'é'. Nas demais, a vírgula separa indevidamente o sujeito do verbo.", "fonte": "CESGRANRIO - 2023 - Transpetro - Eletricista/Condutor Mecânico/Condutor Bombeador", "fonteUrl": "https://www.qconcursos.com/questoes-de-concursos/questoes/ed44ff8b-9c", "valido": true}, {"id": 435, "materia": "Matemática e Raciocínio Lógico", "assunto": "Porcentagem", "enunciado": "Com base em uma tabela de despesas totais de uma empresa nos anos de 2012 (R$ 730.470) e 2013 (R$ 795.648), o aumento percentual das despesas totais de 2012 para 2013 foi de aproximadamente", "alternativas": ["8,9%", "9,1%", "9,3%", "9,5%", "9,7%"], "corretaIndex": 0, "regra": "Percentual de aumento = (Valor final / Valor inicial) - 1. 795.648/730.470 ≈ 1,0892, ou seja, aumento de aproximadamente 8,9%.", "fonte": "CESGRANRIO - Banco do Brasil - Escriturário - 2018", "fonteUrl": "https://sabermatematica.com.br/questoes-de-porcentagem-da-cesgranrio-para-o-concurso-do-banco-do-brasil.html", "valido": true}, {"id": 436, "materia": "Matemática e Raciocínio Lógico", "assunto": "Porcentagem", "enunciado": "Um produto sofreu três reajustes sucessivos nos meses de outubro (4%), novembro (5%) e dezembro (10%) de 2017. O aumento percentual acumulado nesse produto, de outubro a dezembro de 2017, está no intervalo", "alternativas": ["19,00% a 19,49%", "19,50% a 19,99%", "20,00% a 20,49%", "20,50% a 20,99%", "21,00% a 21,49%"], "corretaIndex": 2, "regra": "Em aumentos sucessivos, multiplicam-se os fatores: 1,04 × 1,05 × 1,10 = 1,2012, logo o aumento acumulado é de 20,12%, no intervalo de 20,00% a 20,49%.", "fonte": "CESGRANRIO - Banco do Brasil - Escriturário - 2018", "fonteUrl": "https://sabermatematica.com.br/questoes-de-porcentagem-da-cesgranrio-para-o-concurso-do-banco-do-brasil.html", "valido": true}, {"id": 437, "materia": "Matemática e Raciocínio Lógico", "assunto": "Porcentagem", "enunciado": "A prestação de um financiamento de João correspondia a 25% do seu salário. Ele recebeu um aumento salarial de 40% e, no mesmo período, o valor de sua prestação foi reajustado em 12%. Após essas mudanças, a nova prestação passou a representar que percentual do novo salário de João?", "alternativas": ["16%", "20%", "24%", "28%", "35%"], "corretaIndex": 1, "regra": "Novo salário = 1,4x; nova prestação = 0,25x × 1,12 = 0,28x. Razão = 0,28x / 1,4x = 0,20 = 20%.", "fonte": "CESGRANRIO - Banco do Brasil - Escriturário - 2010", "fonteUrl": "https://sabermatematica.com.br/questoes-de-porcentagem-da-cesgranrio-para-o-concurso-do-banco-do-brasil.html", "valido": true}, {"id": 438, "materia": "Matemática e Raciocínio Lógico", "assunto": "Porcentagem", "enunciado": "Um artesão vende suas pulseiras com 60% de lucro sobre o seu custo. Normalmente, seus fregueses pedem descontos na hora da compra. Qual o maior percentual de desconto sobre o preço de venda que ele pode oferecer sem ter prejuízo?", "alternativas": ["22,5%", "37,5%", "10%", "40%", "60%"], "corretaIndex": 1, "regra": "Preço de venda = 1,6C. Para não ter prejuízo, 1,6C(1-d) ≥ C → 1-d ≥ 1/1,6 = 0,625 → d ≤ 0,375, logo o desconto máximo é 37,5%.", "fonte": "CESGRANRIO - Transpetro - Nível Médio - 2018", "fonteUrl": "https://300segundosdematematica.com/cesgranrio/", "valido": true}, {"id": 439, "materia": "Matemática e Raciocínio Lógico", "assunto": "Porcentagem", "enunciado": "Em uma eleição de grêmio estudantil, 8,3% dos votos foram nulos e 6,7% foram em branco. O candidato eleito obteve 64% dos votos válidos. Qual foi o percentual de votos que o candidato eleito obteve em relação ao total de votos?", "alternativas": ["79,0%", "75,2%", "57,3%", "54,4%", "49,0%"], "corretaIndex": 3, "regra": "Votos válidos = 100% - 8,3% - 6,7% = 85%. Percentual sobre o total = 64% × 85% = 54,4%.", "fonte": "CESGRANRIO - AgeRIO - Assistente Técnico Administrativo - 2023", "fonteUrl": "https://mkt.estrategia.com/concursos/wp-content/uploads/sites/2/2025/04/Banco-do-Brasil-Matematica-Questoes-comentadas-da-Cesgranrio-LP.pdf", "valido": true}, {"id": 440, "materia": "Matemática e Raciocínio Lógico", "assunto": "Porcentagem", "enunciado": "Um produto teve reajustes sucessivos de 5% em março, 10% em abril e 20% em maio de determinado ano. Qual foi o percentual de aumento acumulado nesse produto de março a maio?", "alternativas": ["11,7%", "20,0%", "35,0%", "37,0%", "38,6%"], "corretaIndex": 4, "regra": "Multiplicam-se os fatores de reajuste: 1,05 × 1,10 × 1,20 = 1,386, ou seja, aumento acumulado de 38,6%.", "fonte": "CESGRANRIO - AgeRIO - Assistente Técnico Administrativo - 2023", "fonteUrl": "https://mkt.estrategia.com/concursos/wp-content/uploads/sites/2/2025/04/Banco-do-Brasil-Matematica-Questoes-comentadas-da-Cesgranrio-LP.pdf", "valido": true}, {"id": 441, "materia": "Matemática e Raciocínio Lógico", "assunto": "Porcentagem", "enunciado": "Um cliente aplicou R$ 100.000,00 e obteve rendimento de 20% em 2021 e uma perda de 5% em 2022. Sobre o rendimento líquido positivo do período incidiu 15% de Imposto de Renda. Qual foi a taxa líquida de rendimento do investimento no período?", "alternativas": ["11,9%", "12,8%", "13,6%", "14,0%", "15,0%"], "corretaIndex": 0, "regra": "Montante bruto: 100.000 × 1,20 × 0,95 = 114.000, rendimento bruto de 14.000. Imposto = 15% × 14.000 = 2.100. Rendimento líquido = 11.900, taxa líquida = 11,9%.", "fonte": "CESGRANRIO - Banrisul - Escriturário - 2023", "fonteUrl": "https://mkt.estrategia.com/concursos/wp-content/uploads/sites/2/2025/04/Banco-do-Brasil-Matematica-Questoes-comentadas-da-Cesgranrio-LP.pdf", "valido": true}, {"id": 442, "materia": "Matemática e Raciocínio Lógico", "assunto": "Porcentagem", "enunciado": "Um hotel cobra, por 4 diárias, o mesmo preço que cobraria por apenas 3 diárias avulsas. Isso equivale a que percentual de desconto sobre o valor de cada diária?", "alternativas": ["20%", "25%", "30%", "33%", "75%"], "corretaIndex": 1, "regra": "Preço de 4 diárias com desconto = preço de 3 diárias cheias. Se cada diária cheia vale P, o preço com desconto por diária é 3P/4, ou seja, 25% de desconto sobre P.", "fonte": "CESGRANRIO - Eletronuclear - Técnico - 2022", "fonteUrl": "https://mkt.estrategia.com/concursos/wp-content/uploads/sites/2/2025/04/Banco-do-Brasil-Matematica-Questoes-comentadas-da-Cesgranrio-LP.pdf", "valido": true}, {"id": 443, "materia": "Matemática e Raciocínio Lógico", "assunto": "Porcentagem", "enunciado": "Em uma pesquisa populacional, 78% das pessoas têm 15 anos de idade ou mais, e 34% têm 15 anos de idade ou menos. Qual o percentual de pessoas que têm exatamente 15 anos de idade?", "alternativas": ["44%", "63%", "49%", "22%", "12%"], "corretaIndex": 4, "regra": "P(≥15) + P(≤15) - P(=15) = 100% (princípio da inclusão-exclusão). 78% + 34% - x = 100% → x = 12%.", "fonte": "CESGRANRIO - Eletronuclear - Técnico - 2022", "fonteUrl": "https://mkt.estrategia.com/concursos/wp-content/uploads/sites/2/2025/04/Banco-do-Brasil-Matematica-Questoes-comentadas-da-Cesgranrio-LP.pdf", "valido": true}, {"id": 444, "materia": "Matemática e Raciocínio Lógico", "assunto": "Porcentagem", "enunciado": "Em uma sala, havia 28 pessoas presentes, número que correspondia a 80% da capacidade máxima da sala. Qual é a capacidade máxima dessa sala?", "alternativas": ["28", "30", "32", "35", "40"], "corretaIndex": 3, "regra": "Se 28 corresponde a 80% da capacidade C, então C = 28 / 0,80 = 35.", "fonte": "CESGRANRIO - Eletronuclear - Técnico - 2022", "fonteUrl": "https://mkt.estrategia.com/concursos/wp-content/uploads/sites/2/2025/04/Banco-do-Brasil-Matematica-Questoes-comentadas-da-Cesgranrio-LP.pdf", "valido": true}, {"id": 445, "materia": "Matemática e Raciocínio Lógico", "assunto": "Análise Combinatória", "enunciado": "Sete clientes de um banco devem ser organizados em uma única fila, sendo que os 3 clientes com mais de 65 anos devem, necessariamente, ocupar as três primeiras posições dessa fila (em qualquer ordem entre eles). De quantas maneiras distintas essa fila pode ser formada?", "alternativas": ["12", "24", "144", "2520", "5040"], "corretaIndex": 2, "regra": "Os 3 idosos podem se organizar entre si de 3! = 6 formas nas 3 primeiras posições; os outros 4 clientes se organizam de 4! = 24 formas nas posições restantes. Total = 6 × 24 = 144.", "fonte": "CESGRANRIO - Banrisul - Escriturário - 2023", "fonteUrl": "https://mkt.estrategia.com/concursos/wp-content/uploads/sites/2/2025/04/Banco-do-Brasil-Matematica-Questoes-comentadas-da-Cesgranrio-LP.pdf", "valido": true}, {"id": 446, "materia": "Matemática e Raciocínio Lógico", "assunto": "Análise Combinatória", "enunciado": "Um investidor decidiu que, todo mês, escolheria exatamente 3 tipos de investimento dentre 9 tipos disponíveis, sem nunca repetir a mesma combinação de 3 investimentos em meses diferentes. Qual é o número máximo de meses consecutivos em que ele pode fazer essa escolha sem repetir uma combinação?", "alternativas": ["84", "60", "56", "48", "35"], "corretaIndex": 0, "regra": "Como a ordem dos investimentos escolhidos não importa, calcula-se uma combinação: C(9,3) = 9!/(3!6!) = 84.", "fonte": "CESGRANRIO - Banco do Brasil - Escriturário - 2023", "fonteUrl": "https://mkt.estrategia.com/concursos/wp-content/uploads/sites/2/2025/04/Banco-do-Brasil-Matematica-Questoes-comentadas-da-Cesgranrio-LP.pdf", "valido": true}, {"id": 447, "materia": "Matemática e Raciocínio Lógico", "assunto": "Análise Combinatória", "enunciado": "Em uma agência bancária, 5 gerentes devem atender simultaneamente 5 clientes diferentes, um gerente para cada cliente. De quantas configurações distintas de atendimento é possível formar esses pares gerente-cliente?", "alternativas": ["14.400", "120", "45", "25", "10"], "corretaIndex": 1, "regra": "Trata-se de uma permutação simples de 5 elementos: P5 = 5! = 120.", "fonte": "CESGRANRIO - Banco do Brasil - Escriturário - 2023", "fonteUrl": "https://mkt.estrategia.com/concursos/wp-content/uploads/sites/2/2025/04/Banco-do-Brasil-Matematica-Questoes-comentadas-da-Cesgranrio-LP.pdf", "valido": true}, {"id": 448, "materia": "Matemática e Raciocínio Lógico", "assunto": "Análise Combinatória", "enunciado": "Uma senha numérica XYZ é formada por três algarismos distintos escolhidos entre 1, 2, 3, 4 e 5, de modo que X < Y < Z. Quantas senhas diferentes podem ser formadas com essa condição?", "alternativas": ["3", "6", "10", "12", "15"], "corretaIndex": 2, "regra": "Como a condição X<Y<Z determina uma única ordem para cada trio escolhido, basta calcular a combinação de 5 algarismos tomados 3 a 3: C(5,3) = 10.", "fonte": "CESGRANRIO - AgeRIO - Assistente Técnico Administrativo - 2023", "fonteUrl": "https://mkt.estrategia.com/concursos/wp-content/uploads/sites/2/2025/04/Banco-do-Brasil-Matematica-Questoes-comentadas-da-Cesgranrio-LP.pdf", "valido": true}, {"id": 449, "materia": "Matemática e Raciocínio Lógico", "assunto": "Análise Combinatória", "enunciado": "Em uma fila indiana, devem ser organizadas 2 pessoas do sexo masculino e 4 do sexo feminino, de modo que sempre haja pelo menos uma mulher entre os dois homens (ou seja, os dois homens nunca ficam em posições adjacentes). De quantas formas essa fila pode ser organizada?", "alternativas": ["10", "20", "48", "480", "720"], "corretaIndex": 3, "regra": "Organiza-se primeiro as 4 mulheres: 4! = 24 formas, criando 5 espaços para os homens. Escolhem-se 2 desses 5 espaços para os homens, que se organizam entre si de 2! formas: A(5,2) = 20. Total = 24 × 20 = 480.", "fonte": "CESGRANRIO - Banco do Brasil - Escriturário - 2021", "fonteUrl": "https://mkt.estrategia.com/concursos/wp-content/uploads/sites/2/2025/04/Banco-do-Brasil-Matematica-Questoes-comentadas-da-Cesgranrio-LP.pdf", "valido": true}, {"id": 450, "materia": "Matemática e Raciocínio Lógico", "assunto": "Análise Combinatória", "enunciado": "Em um conjunto há 5 números positivos e 5 números negativos. Escolhem-se, ao acaso, 5 números desse conjunto e efetua-se a multiplicação entre eles. Em quantos casos possíveis de escolha o resultado dessa multiplicação será negativo?", "alternativas": ["25", "120", "125", "126", "128"], "corretaIndex": 3, "regra": "O produto é negativo quando a quantidade de números negativos escolhidos é ímpar. Total de escolhas: C(10,5)=252. Casos com quantidade par de negativos: C(5,0)C(5,5)+C(5,2)C(5,3)+C(5,4)C(5,1)=1+100+25=126; logo os casos com produto negativo também são 252-126=126.", "fonte": "CESGRANRIO - Transpetro - Nível Médio - 2018", "fonteUrl": "https://300segundosdematematica.com/cesgranrio/", "valido": true}, {"id": 451, "materia": "Matemática e Raciocínio Lógico", "assunto": "Probabilidade", "enunciado": "Quatro clientes esqueceram seus celulares idênticos em uma agência bancária, que os guardou em 4 envelopes lacrados, um para cada celular, mas sem identificar corretamente qual celular pertence a qual cliente. Os envelopes são entregues aleatoriamente, um a cada cliente. Qual é a probabilidade de que exatamente um cliente receba de volta o seu próprio celular?", "alternativas": ["3/4", "2/3", "1/2", "3/8", "1/3"], "corretaIndex": 4, "regra": "O número de permutações de 4 elementos com exatamente 1 ponto fixo é C(4,1) × D3, onde D3 (desarranjos de 3 elementos) = 2. Casos favoráveis = 4×2=8. Total de permutações = 4!=24. Probabilidade = 8/24 = 1/3.", "fonte": "CESGRANRIO - Banco do Brasil - Escriturário - 2023", "fonteUrl": "https://mkt.estrategia.com/concursos/wp-content/uploads/sites/2/2025/04/Banco-do-Brasil-Matematica-Questoes-comentadas-da-Cesgranrio-LP.pdf", "valido": true}, {"id": 452, "materia": "Matemática e Raciocínio Lógico", "assunto": "Probabilidade", "enunciado": "Um banco classifica seus clientes que usam cheque especial em dois tipos. Clientes do Tipo A representam 30% da população e, destes, 80% usam cheque especial. Clientes do Tipo B representam 70% da população e, destes, apenas 10% usam cheque especial. Um cliente escolhido ao acaso usa cheque especial. Qual é a probabilidade de que ele seja do Tipo A?", "alternativas": ["65%", "70%", "77%", "82%", "85%"], "corretaIndex": 2, "regra": "Teorema de Bayes: P(A|usa) = P(usa|A)P(A) / [P(usa|A)P(A) + P(usa|B)P(B)] = (0,8×0,3) / [(0,8×0,3)+(0,1×0,7)] = 0,24/0,31 ≈ 77%.", "fonte": "CESGRANRIO - Banco do Brasil - Escriturário - 2023", "fonteUrl": "https://mkt.estrategia.com/concursos/wp-content/uploads/sites/2/2025/04/Banco-do-Brasil-Matematica-Questoes-comentadas-da-Cesgranrio-LP.pdf", "valido": true}, {"id": 453, "materia": "Matemática e Raciocínio Lógico", "assunto": "Probabilidade", "enunciado": "Há duas urnas: a urna 1 contém 1 bola branca e 1 bola preta; a urna 2 contém 1 bola branca e 2 bolas pretas. Uma bola é retirada ao acaso da urna 1 e colocada na urna 2. Em seguida, retira-se ao acaso uma bola da urna 2. Qual é a probabilidade de que essa bola retirada da urna 2 seja branca?", "alternativas": ["12,5%", "25%", "37,5%", "50%", "62,5%"], "corretaIndex": 2, "regra": "Se a bola transferida for branca (prob. 1/2), a urna 2 fica com 2 brancas e 2 pretas, prob. de tirar branca = 1/2. Se for preta (prob. 1/2), a urna 2 fica com 1 branca e 3 pretas, prob. = 1/4. Probabilidade total = (1/2)(1/2) + (1/2)(1/4) = 3/8 = 37,5%.", "fonte": "CESGRANRIO - Transpetro - Nível Médio - 2018", "fonteUrl": "https://300segundosdematematica.com/cesgranrio/", "valido": true}, {"id": 454, "materia": "Matemática e Raciocínio Lógico", "assunto": "Progressões (PA/PG)", "enunciado": "Progressões aritméticas são sequências numéricas nas quais a diferença entre dois termos consecutivos é constante. A sequência (5, 8, 11, 14, 17, …, 68, 71) é uma progressão aritmética finita que possui:", "alternativas": ["67 termos", "33 termos", "28 termos", "23 termos", "21 termos"], "corretaIndex": 3, "regra": "Fórmula do termo geral: an = a1 + (n-1)r. Substituindo: 71 = 5 + (n-1)×3 → 66 = 3(n-1) → n-1 = 22 → n = 23 termos.", "fonte": "CESGRANRIO - Banco do Brasil - Escriturário - 2013", "fonteUrl": "https://sabermatematica.com.br/questoes-de-pa-e-pg-da-cesgranrio-para-o-concurso-do-banco-do-brasil.html", "valido": true}, {"id": 455, "materia": "Matemática e Raciocínio Lógico", "assunto": "Progressões (PA/PG)", "enunciado": "Considere a sequência cujo termo geral é an = 2^(1-3n), para n ≥ 1. Essa sequência é uma progressão:", "alternativas": ["geométrica, de razão 1/8", "geométrica, de razão -6", "geométrica, de razão -3", "aritmética, de razão -3", "aritmética, de razão 1/8"], "corretaIndex": 0, "regra": "Calculando a razão q = an+1/an = 2^(1-3(n+1)) / 2^(1-3n) = 2^(-3) = 1/8. Como a razão entre termos consecutivos é constante e multiplicativa, trata-se de uma PG de razão 1/8.", "fonte": "CESGRANRIO - Banco do Brasil - Escriturário - 2018", "fonteUrl": "https://sabermatematica.com.br/questoes-de-pa-e-pg-da-cesgranrio-para-o-concurso-do-banco-do-brasil.html", "valido": true}, {"id": 456, "materia": "Matemática e Raciocínio Lógico", "assunto": "Progressões (PA/PG)", "enunciado": "O quarto, o quinto e o sexto termos de uma progressão aritmética são expressos por x + 1, x² + 4 e 2x² + 3, respectivamente. A soma dos dez primeiros termos dessa progressão aritmética é igual a:", "alternativas": ["260", "265", "270", "275", "280"], "corretaIndex": 3, "regra": "Em uma PA, a diferença entre termos consecutivos é constante: (x²+4)-(x+1) = (2x²+3)-(x²+4) → x²-x+3 = x²-1 → x=4. Os termos ficam: a4=5, a5=20, a6=35, razão r=15, logo a1 = 5-3×15 = -40. Soma dos 10 primeiros: S10 = 10×(a1+a10)/2 = 10×(-40+95)/2 = 275.", "fonte": "CESGRANRIO - Transpetro - Nível Médio - 2018", "fonteUrl": "https://300segundosdematematica.com/cesgranrio/", "valido": true}, {"id": 457, "materia": "Matemática e Raciocínio Lógico", "assunto": "Razão e Proporção / Regra de Três", "enunciado": "Dois funcionários de uma agência bancária atendem 80 clientes em 5 horas de trabalho. Mantendo a mesma produtividade por funcionário, quantos funcionários são necessários para atender 500 clientes em 8 horas de trabalho?", "alternativas": ["5", "7", "8", "10", "20"], "corretaIndex": 2, "regra": "Regra de três composta: produtividade por funcionário por hora = 80/(2×5) = 8 clientes/funcionário/hora. Para 500 clientes em 8h: número de funcionários = 500/(8×8) ≈ 7,8, arredondando para 8 funcionários (necessário para atender toda a demanda).", "fonte": "CESGRANRIO - Banrisul - Escriturário - 2023", "fonteUrl": "https://mkt.estrategia.com/concursos/wp-content/uploads/sites/2/2025/04/Banco-do-Brasil-Matematica-Questoes-comentadas-da-Cesgranrio-LP.pdf", "valido": true}, {"id": 458, "materia": "Matemática e Raciocínio Lógico", "assunto": "Razão e Proporção / Regra de Três", "enunciado": "Uma bomba esvazia uma piscina em 10 horas de funcionamento. Se a vazão dessa bomba for aumentada em 25%, em quanto tempo ela esvaziará a mesma piscina?", "alternativas": ["8h", "7h30min", "6h", "5h", "2h30min"], "corretaIndex": 0, "regra": "Tempo é inversamente proporcional à vazão. Nova vazão = 1,25 × vazão original. Novo tempo = 10 / 1,25 = 8 horas.", "fonte": "CESGRANRIO - Eletronuclear - Técnico - 2022", "fonteUrl": "https://mkt.estrategia.com/concursos/wp-content/uploads/sites/2/2025/04/Banco-do-Brasil-Matematica-Questoes-comentadas-da-Cesgranrio-LP.pdf", "valido": true}, {"id": 459, "materia": "Matemática e Raciocínio Lógico", "assunto": "Conjuntos", "enunciado": "De 1.000 clientes de um banco, 700 investem em fundos do tipo A ou do tipo B (ou ambos); desses, 250 investem em ambos os fundos e 100 investem apenas no fundo B. Qual é o número máximo de clientes que investem apenas no fundo A?", "alternativas": ["350", "600", "650", "800", "900"], "corretaIndex": 0, "regra": "n(A∪B) = n(A) + n(B) - n(A∩B). Sabendo que apenas B = n(B) - n(A∩B) = 100, então n(B) = 350. n(A) = n(A∪B) - n(B) + n(A∩B) = 700 - 350 + 250 = 600. Apenas A = n(A) - n(A∩B) = 600 - 250 = 350.", "fonte": "CESGRANRIO - Banrisul - Escriturário - 2023", "fonteUrl": "https://mkt.estrategia.com/concursos/wp-content/uploads/sites/2/2025/04/Banco-do-Brasil-Matematica-Questoes-comentadas-da-Cesgranrio-LP.pdf", "valido": true}, {"id": 460, "materia": "Matemática e Raciocínio Lógico", "assunto": "Conjuntos", "enunciado": "Sabe-se que A∪B = {3,4,6,7,9} e A∩B = {4,7}. O conjunto (A-B)∪(B-A) é igual a:", "alternativas": ["N (naturais)", "{3,4,6,7,9}", "{3,6,9}", "{4,7}", "∅ (vazio)"], "corretaIndex": 2, "regra": "(A-B)∪(B-A) é a diferença simétrica entre A e B: todos os elementos da união que NÃO pertencem à interseção: {3,4,6,7,9} - {4,7} = {3,6,9}.", "fonte": "CESGRANRIO - Eletronuclear - Técnico - 2022", "fonteUrl": "https://mkt.estrategia.com/concursos/wp-content/uploads/sites/2/2025/04/Banco-do-Brasil-Matematica-Questoes-comentadas-da-Cesgranrio-LP.pdf", "valido": true}, {"id": 461, "materia": "Matemática e Raciocínio Lógico", "assunto": "Conjuntos", "enunciado": "Uma pesquisa com 1.000 clientes de um banco mostrou que 430 não têm interesse em nenhum dos dois novos produtos oferecidos, 270 têm interesse no produto 1 e 400 têm interesse no produto 2. Qual o percentual de clientes que têm interesse em ambos os produtos, simultaneamente?", "alternativas": ["10%", "15%", "20%", "25%", "30%"], "corretaIndex": 0, "regra": "Total com interesse em pelo menos um produto = 1000-430 = 570. n(1∪2) = n(1)+n(2)-n(1∩2) → 570 = 270+400-n(1∩2) → n(1∩2) = 100, correspondendo a 10% do total de 1.000 clientes.", "fonte": "CESGRANRIO - Banco do Brasil - Escriturário - 2021", "fonteUrl": "https://mkt.estrategia.com/concursos/wp-content/uploads/sites/2/2025/04/Banco-do-Brasil-Matematica-Questoes-comentadas-da-Cesgranrio-LP.pdf", "valido": true}, {"id": 462, "materia": "Matemática e Raciocínio Lógico", "assunto": "Raciocínio Lógico-Proposicional", "enunciado": "A negação da proposição \"Se o candidato estuda, então passa no concurso\" é:", "alternativas": ["O candidato não estuda e passa no concurso.", "O candidato estuda e não passa no concurso.", "Se o candidato estuda, então não passa no concurso.", "Se o candidato não estuda, então passa no concurso.", "Se o candidato não estuda, então não passa no concurso."], "corretaIndex": 1, "regra": "A negação de uma condicional \"Se P, então Q\" é \"P e não Q\" (¬(P→Q) ≡ P ∧ ¬Q). Mantém-se a primeira parte e nega-se a segunda, unindo-as com \"e\".", "fonte": "CESGRANRIO - TermoMacaé - 2009", "fonteUrl": "https://www.qconcursos.com/questoes-de-concursos/questoes/e48b8e5f-fe", "valido": true}, {"id": 463, "materia": "Matemática e Raciocínio Lógico", "assunto": "Silogismos / Argumentos Lógicos", "enunciado": "Com relação às regras para validade de um silogismo, analise o que se segue. I - Todo silogismo deve conter somente três termos. II - De duas premissas particulares não poderá haver conclusão. III - Se há uma premissa particular, a conclusão será particular. IV - Se há um termo médio negativo, a conclusão será negativa. São regras válidas para um silogismo:", "alternativas": ["I e IV, apenas", "II e III, apenas", "I, II e III, apenas", "I, II e IV, apenas", "I, II, III e IV"], "corretaIndex": 2, "regra": "As regras clássicas de validade do silogismo categórico incluem: uso de exatamente três termos, impossibilidade de conclusão a partir de duas premissas particulares, e conclusão particular quando há uma premissa particular (itens I, II e III). O item IV, como enunciado, não corresponde a uma regra válida do silogismo clássico.", "fonte": "CESGRANRIO - Petrobras - Técnico em Informática - 2010", "fonteUrl": "https://www.qconcursos.com/questoes-de-concursos/questoes/4e76fd70-7e", "valido": true}, {"id": 464, "materia": "Matemática e Raciocínio Lógico", "assunto": "Sequências Lógicas", "enunciado": "Às 5 horas da tarde de uma sexta-feira, Aldo desligou seu computador, que já estava ligado ininterruptamente há 100 horas. A que horas e em que dia da semana Aldo havia ligado esse computador?", "alternativas": ["1 da tarde de segunda-feira", "9 da noite de segunda-feira", "1 da tarde de terça-feira", "2 da tarde de terça-feira", "9 da noite de quarta-feira"], "corretaIndex": 0, "regra": "100 horas equivalem a 4 dias e 4 horas (4×24=96h, restam 4h). Retrocedendo 4 dias a partir de sexta-feira às 17h chega-se à segunda-feira às 17h; retrocedendo mais 4 horas chega-se à segunda-feira às 13h (1 da tarde).", "fonte": "CESGRANRIO - Transpetro - Nível Médio - 2018", "fonteUrl": "https://300segundosdematematica.com/cesgranrio/", "valido": true}, {"id": 465, "materia": "Matemática e Raciocínio Lógico", "assunto": "Sistemas de Equações Aplicados", "enunciado": "Na igualdade a seguir, cada letra representa um algarismo distinto, sendo E e U dígitos de 0 a 9: U + U + EU = UE (onde EU e UE são números de dois algarismos formados pela justaposição dos dígitos E e U). Qual é o valor de E + U?", "alternativas": ["9", "11", "13", "16", "18"], "corretaIndex": 3, "regra": "Escrevendo em forma decimal: U + U + (10E+U) = (10U+E) → 3U + 10E = 10U + E → 9E = 7U. Como E e U são algarismos de 0 a 9, a única solução inteira válida é E=7 e U=9, logo E+U = 16.", "fonte": "CESGRANRIO - Banco do Brasil - Escriturário - 2015", "fonteUrl": "https://dhg1h5j42swfq.cloudfront.net/2015/03/Resolu%C3%A7%C3%A3o-da-prova-Banco-do-Brasil-CESGRANRIO.pdf", "valido": true}];